/* GENERATED curriculum (USACO Guide + Competitive Programmer's Handbook + cp-algorithms; problems verified against the Codeforces problemset). Rebuild from the curriculum JSON — do not edit by hand. */
export const CURRICULUM: unknown[] = [{"area":"basics","topics":[{"id":"implementation","name":"Implementation & Simulation","cfTags":["implementation","math"],"subtopics":[{"id":"impl-basics","name":"Implementation fundamentals","tier":800,"order":1,"prereq":[],"summary":"Turning a statement directly into correct code: reading input fast, choosing the right integer type and handling every edge case. Almost every Div 2/3/4 A problem is pure implementation; the difficulty is precision, not ideas.","learn":["Fast I/O: ios::sync_with_stdio(false); cin.tie(nullptr); never mix with printf/scanf after that","Know the limits: int ~2.1e9, long long ~9.2e18; use long long whenever a product or sum can exceed 2e9","Multi-test input (t test cases): reset all global arrays/counters per test, and respect 'sum of n over all tests' bounds","Read the statement twice; write down the exact output format (YES/NO case, spaces, -1 cases) before coding","Test on the samples plus hand-made edge cases: n=1, all equal elements, maximum values","Prefer simple, direct code over clever code; off-by-one errors are the main source of WA"],"resources":[{"title":"USACO Guide: Data Types","url":"https://usaco.guide/general/data-types","kind":"usaco","where":"USACO Guide General","minutes":10},{"title":"USACO Guide: Fast Input and Output","url":"https://usaco.guide/general/fast-io","kind":"usaco","where":"USACO Guide General","minutes":10},{"title":"CPH: Input and output","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 1.2 (p. 4)","minutes":10},{"title":"CPH: Working with numbers","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 1.3 (p. 6)","minutes":15}],"problems":[{"id":"4A","src":"cf","name":"Watermelon","rating":800,"from":"usaco-guide"},{"id":"71A","src":"cf","name":"Way Too Long Words","rating":800,"from":"curated"},{"id":"231A","src":"cf","name":"Team","rating":800,"from":"usaco-guide"},{"id":"1352A","src":"cf","name":"Sum of Round Numbers","rating":800,"from":"curated"},{"id":"1676A","src":"cf","name":"Lucky?","rating":800,"from":"curated"},{"id":"1829B","src":"cf","name":"Blank Space","rating":800,"from":"curated"},{"id":"1760A","src":"cf","name":"Medium Number","rating":800,"from":"curated"},{"id":"1512A","src":"cf","name":"Spy Detected!","rating":800,"from":"curated"},{"id":"1873C","src":"cf","name":"Target Practice","rating":800,"from":"curated"},{"id":"1950A","src":"cf","name":"Stair, Peak, or Neither?","rating":800,"from":"curated"},{"id":"1722B","src":"cf","name":"Colourblindness","rating":800,"from":"curated"},{"id":"1433A","src":"cf","name":"Boring Apartments","rating":800,"from":"curated"},{"id":"cses-1068","src":"cses","name":"Weird Algorithm","from":"usaco-guide"},{"id":"cses-1083","src":"cses","name":"Missing Number","from":"curated"},{"id":"cses-1069","src":"cses","name":"Repetitions","from":"curated"},{"id":"cses-1094","src":"cses","name":"Increasing Array","from":"curated"}]},{"id":"impl-complexity","name":"Time complexity & constraint estimation","tier":900,"order":2,"prereq":["impl-basics"],"summary":"Estimating the running time of an idea from the constraints before coding it: roughly 1e8 simple operations per second. Reading n <= 2e5 should immediately suggest O(n log n), n <= 20 suggests 2^n, and so on.","learn":["Big-O rules: loops multiply, sequential parts add, keep the dominant term","Constraint table: n<=10 -> O(n!), n<=20 -> O(2^n), n<=500 -> O(n^3), n<=5000 -> O(n^2), n<=2e5 -> O(n log n), n<=1e18 -> O(log n) or O(sqrt) on a smaller quantity","Iterate divisors up to sqrt(n): O(sqrt n) instead of O(n)","Bounded search: if the answer or a variable is at most cube-root/sqrt of the limit, brute-force over it","Watch hidden costs: string concatenation, erasing from vector front, endl flushing, copying containers into functions","Amortized analysis: a pointer that only moves forward costs O(n) total"],"resources":[{"title":"USACO Guide: Time Complexity","url":"https://usaco.guide/bronze/time-comp","kind":"usaco","where":"USACO Guide Bronze","minutes":20},{"title":"CPH: Time complexity","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 2 (p. 17)","minutes":20},{"title":"CPH: Estimating efficiency","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 2.3 (p. 21)","minutes":5}],"problems":[{"id":"1520B","src":"cf","name":"Ordinary Numbers","rating":800,"from":"curated"},{"id":"1475B","src":"cf","name":"New Year's Number","rating":900,"from":"curated"},{"id":"1490C","src":"cf","name":"Sum of Cubes","rating":1100,"from":"curated"},{"id":"1213C","src":"cf","name":"Book Reading","rating":1200,"from":"curated"},{"id":"1360D","src":"cf","name":"Buying Shovels","rating":1300,"from":"curated"},{"id":"1203C","src":"cf","name":"Common Divisors","rating":1300,"from":"curated"},{"id":"1294C","src":"cf","name":"Product of Three Numbers","rating":1300,"from":"curated"},{"id":"cses-1071","src":"cses","name":"Number Spiral","from":"curated"},{"id":"cses-1618","src":"cses","name":"Trailing Zeros","from":"curated"}]},{"id":"impl-simulation","name":"Simulation","tier":1000,"order":3,"prereq":["impl-basics"],"summary":"Doing exactly what the statement describes, step by step, with the right data structures. Harder versions require noticing that the process repeats (cycle/period) or that only a bounded number of steps matter, so it can be fast-forwarded.","learn":["Model the state explicitly (positions, grid, queue) and update it one step at a time","Use deque/stack/set when the simulation adds/removes from ends or needs ordered access","Grids: direction arrays dx/dy, boundary checks, and simulating gravity/rotations carefully","If the number of steps is huge, find a period (state repeats) or a point after which nothing changes, then jump ahead with arithmetic","Bound the number of 'interesting' steps (e.g. values shrink quickly, last digit cycles) and simulate only those","Write the simulation as a function and test it on the sample before optimising"],"resources":[{"title":"USACO Guide: Simulation","url":"https://usaco.guide/bronze/simulation","kind":"usaco","where":"USACO Guide Bronze","minutes":25}],"problems":[{"id":"1791B","src":"cf","name":"Following Directions","rating":800,"from":"curated"},{"id":"1907B","src":"cf","name":"YetnotherrokenKeoard","rating":1000,"from":"curated"},{"id":"1669G","src":"cf","name":"Fall Down","rating":1200,"from":"curated"},{"id":"1294B","src":"cf","name":"Collecting Packages","rating":1200,"from":"curated"},{"id":"1703E","src":"cf","name":"Mirror Grid","rating":1200,"from":"curated"},{"id":"1234B2","src":"cf","name":"Social Network (hard version)","rating":1300,"from":"curated"},{"id":"1352D","src":"cf","name":"Alice, Bob and Candies","rating":1300,"from":"curated"},{"id":"1714E","src":"cf","name":"Add Modulo 10","rating":1400,"from":"curated"},{"id":"cses-2162","src":"cses","name":"Josephus Problem I","from":"curated"}]},{"id":"impl-casework","name":"Casework","tier":1000,"order":4,"prereq":["impl-basics"],"summary":"Splitting the input space into a few cases that are each easy to solve. Typical when the answer is a small number (0/1/2/-1) or depends on parity, signs or which of a few configurations occurs.","learn":["Enumerate cases systematically (e.g. by sign, parity, which element is the maximum) so none are missed","Prove the answer is always small (e.g. at most 2 operations) and then check 0, 1, 2 separately","Brute-force small inputs to validate your case analysis","Handle degenerate cases first: n=1, all equal, already sorted, zero","When cases multiply, try to reduce them by symmetry (swap a,b; reverse the array)"],"resources":[{"title":"USACO Guide: Casework","url":"https://usaco.guide/bronze/casework","kind":"usaco","where":"USACO Guide Bronze","minutes":20}],"problems":[{"id":"1294A","src":"cf","name":"Collecting Coins","rating":800,"from":"curated"},{"id":"1716A","src":"cf","name":"2-3 Moves","rating":800,"from":"curated"},{"id":"1374B","src":"cf","name":"Multiply by 2, divide by 6","rating":900,"from":"curated"},{"id":"1342A","src":"cf","name":"Road To Zero","rating":1000,"from":"curated"},{"id":"1409B","src":"cf","name":"Minimum Product","rating":1100,"from":"curated"},{"id":"1352B","src":"cf","name":"Same Parity Summands","rating":1200,"from":"curated"},{"id":"1371B","src":"cf","name":"Magical Calendar","rating":1200,"from":"curated"},{"id":"581D","src":"cf","name":"Three Logos","rating":1700,"from":"usaco-guide"}]}]},{"id":"complete-search","name":"Complete Search","cfTags":["brute force","bitmasks","meet-in-the-middle"],"subtopics":[{"id":"search-iterate","name":"Brute force by iterating","tier":800,"order":1,"prereq":["impl-complexity"],"summary":"Trying every candidate answer or every combination of a few variables with nested loops. Works whenever the search space, after bounding it smartly, fits in about 1e8 operations.","learn":["Identify what to enumerate: the answer itself, a pair (i, j), a small parameter (k, a digit, a divisor)","Bound the search space with an observation (answer <= 60, only sqrt(n) divisors, only 2 distinct values matter)","Fix one variable and compute the rest greedily or with a formula","Check the total complexity across all test cases before coding","Brute force is also your testing tool: write it to validate a faster solution on random small inputs"],"resources":[{"title":"USACO Guide: Basic Complete Search","url":"https://usaco.guide/bronze/intro-complete","kind":"usaco","where":"USACO Guide Bronze","minutes":20},{"title":"CPH: Complete search","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 5 (p. 47)","minutes":10}],"problems":[{"id":"1873B","src":"cf","name":"Good Kid","rating":800,"from":"curated"},{"id":"2009A","src":"cf","name":"Minimize!","rating":800,"from":"curated"},{"id":"1985B","src":"cf","name":"Maximum Multiple Sum","rating":800,"from":"curated"},{"id":"1881A","src":"cf","name":"Don't Try to Count","rating":800,"from":"curated"},{"id":"1380A","src":"cf","name":"Three Indices","rating":900,"from":"curated"},{"id":"1791D","src":"cf","name":"Distinct Split","rating":1000,"from":"curated"},{"id":"1676H1","src":"cf","name":"Maximum Crossings (Easy Version)","rating":1400,"from":"curated"},{"id":"1285C","src":"cf","name":"Fadi and LCM","rating":1400,"from":"curated"},{"id":"1759D","src":"cf","name":"Make It Round","rating":1400,"from":"curated"},{"id":"1352E","src":"cf","name":"Special Elements","rating":1500,"from":"curated"},{"id":"1213D1","src":"cf","name":"Equalizing by Division (easy version)","rating":1500,"from":"curated"},{"id":"1920C","src":"cf","name":"Partitioning the Array","rating":1600,"from":"curated"}]},{"id":"search-recursion","name":"Recursion & generating candidates","tier":1000,"order":2,"prereq":["search-iterate"],"summary":"Writing a recursive function that explores choices or divides a problem into self-similar halves. Used to generate all numbers of a special form, to check divide-and-conquer structures, or to try both options at each step.","learn":["Define the state passed to the recursion and the base case first","Generate special numbers (e.g. made only of digits 4/7) recursively instead of looping over all integers","Divide and conquer on halves: solve(l, r) splits into solve(l, mid) and solve(mid+1, r)","Count the recursion tree size to estimate complexity (branching^depth)","Watch the recursion depth (default stack ~ 1e5-1e6 frames); convert to iteration if needed"],"resources":[{"title":"USACO Guide: Complete Search with Recursion","url":"https://usaco.guide/bronze/complete-rec","kind":"usaco","where":"USACO Guide Bronze","minutes":30},{"title":"CPH: Generating subsets (recursive method)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 5.1 (p. 47)","minutes":10}],"problems":[{"id":"1829D","src":"cf","name":"Gold Rush","rating":1000,"from":"curated"},{"id":"727A","src":"cf","name":"Transformation: from A to B","rating":1000,"from":"curated"},{"id":"535B","src":"cf","name":"Tavas and SaDDas","rating":1100,"from":"curated"},{"id":"1490D","src":"cf","name":"Permutation Transformation","rating":1200,"from":"curated"},{"id":"1741D","src":"cf","name":"Masha and a Beautiful Tree","rating":1300,"from":"curated"},{"id":"653B","src":"cf","name":"Bear and Compressing","rating":1300,"from":"curated"},{"id":"1385D","src":"cf","name":"a-Good String","rating":1500,"from":"curated"},{"id":"1036C","src":"cf","name":"Classy Numbers","rating":1900,"from":"curated"},{"id":"cses-2165","src":"cses","name":"Tower of Hanoi","from":"curated"}]},{"id":"search-subsets","name":"Generating subsets (bitmask enumeration)","tier":1200,"order":3,"prereq":["search-recursion","bit-basics"],"summary":"Enumerating all 2^n subsets of a small set, usually with an integer mask from 0 to 2^n - 1. Appears when n <= 20 or when the choice per element is binary and few elements matter.","learn":["Loop mask from 0 to (1<<n)-1; element i is chosen iff (mask>>i)&1","Recursive alternative: at each index either take or skip the element","Iterate all submasks of a mask: for (s = m; s; s = (s-1) & m) — total 3^n over all masks","Enumerate over a small 'type' set (e.g. which of 26 letters are allowed, which corners are filled) even when n itself is large","Complexity O(2^n * n); for n around 40 switch to meet-in-the-middle"],"resources":[{"title":"USACO Guide: Complete Search with Recursion (Subsets)","url":"https://usaco.guide/bronze/complete-rec","kind":"usaco","where":"USACO Guide Bronze","minutes":20},{"title":"CPH: Generating subsets","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 5.1 (p. 47)","minutes":10},{"title":"CPH: Representing sets","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 10.3 (p. 98)","minutes":10},{"title":"cp-algorithms: Enumerating submasks of a bitmask","url":"https://cp-algorithms.com/algebra/all-submasks.html","kind":"cpalgo","where":"cp-algorithms.com","minutes":10}],"problems":[{"id":"1097B","src":"cf","name":"Petr and a Combination Lock","rating":1200,"from":"curated"},{"id":"1553C","src":"cf","name":"Penalty","rating":1200,"from":"curated"},{"id":"1362B","src":"cf","name":"Johnny and His Hobbies","rating":1200,"from":"curated"},{"id":"1882B","src":"cf","name":"Sets and Union","rating":1300,"from":"curated"},{"id":"550B","src":"cf","name":"Preparing Olympiad","rating":1400,"from":"curated"},{"id":"1494B","src":"cf","name":"Berland Crossword","rating":1400,"from":"curated"},{"id":"1778C","src":"cf","name":"Flexible String","rating":1600,"from":"curated"},{"id":"1017D","src":"cf","name":"The Wu","rating":1900,"from":"usaco-guide"},{"id":"cses-1623","src":"cses","name":"Apple Division","from":"usaco-guide"}]},{"id":"search-permutations","name":"Generating permutations","tier":1200,"order":4,"prereq":["search-recursion"],"summary":"Trying all n! orderings with next_permutation or recursion when n <= 8-10. Also used to enumerate all digit orders or all assignments of distinct roles.","learn":["Sort first, then do { ... } while (next_permutation(a.begin(), a.end())) to visit each permutation once (handles duplicates)","Recursive generation with a used[] array when you need pruning","n! grows fast: 8! = 40320, 10! ~ 3.6e6, 11! ~ 4e7 — check limits","Often you permute a small 'pattern' (digit positions, 5 people, 3 rectangles) rather than the whole input","Combine with a cheap evaluation per permutation; total cost is n! times evaluation"],"resources":[{"title":"USACO Guide: Complete Search with Recursion (Permutations)","url":"https://usaco.guide/bronze/complete-rec","kind":"usaco","where":"USACO Guide Bronze","minutes":15},{"title":"CPH: Generating permutations","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 5.2 (p. 49)","minutes":10},{"title":"cp-algorithms: Generating all K-combinations","url":"https://cp-algorithms.com/combinatorics/generating_combinations.html","kind":"cpalgo","where":"cp-algorithms.com","minutes":10}],"problems":[{"id":"1999B","src":"cf","name":"Card Game","rating":1000,"from":"curated"},{"id":"47B","src":"cf","name":"Coins","rating":1200,"from":"curated"},{"id":"431B","src":"cf","name":"Shower Line","rating":1200,"from":"curated"},{"id":"124B","src":"cf","name":"Permutations","rating":1400,"from":"curated"},{"id":"513B1","src":"cf","name":"Permutations","rating":1400,"from":"curated"},{"id":"685A","src":"cf","name":"Robbers' watch","rating":1700,"from":"curated"},{"id":"cses-1622","src":"cses","name":"Creating Strings","from":"usaco-guide"}]},{"id":"search-backtracking","name":"Backtracking & pruning","tier":1500,"order":5,"prereq":["search-recursion"],"summary":"Building a solution incrementally and abandoning a partial solution as soon as it cannot lead to a valid answer. Pruning (and memoization) turns an exponential search into something fast enough in practice.","learn":["Template: place(i): if i==n record answer; for each choice c valid at i: apply c, place(i+1), undo c","Prune early: check constraints as soon as a choice is made, not only at the end","Prune by bounds: stop if the current partial cost already exceeds the best answer","Symmetry breaking: fix the first choice to cut identical branches","When the same state repeats, memoize it — this is the bridge to dynamic programming","Classic examples: n-queens, grid path counting with dead-end detection, generating numbers with digit constraints"],"resources":[{"title":"USACO Guide: Complete Search with Recursion (Backtracking)","url":"https://usaco.guide/bronze/complete-rec","kind":"usaco","where":"USACO Guide Bronze","minutes":20},{"title":"CPH: Backtracking","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 5.3 (p. 50)","minutes":10},{"title":"CPH: Pruning the search","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 5.4 (p. 51)","minutes":15}],"problems":[{"id":"9C","src":"cf","name":"Hexadecimal's Numbers","rating":1200,"from":"curated"},{"id":"96B","src":"cf","name":"Lucky Numbers (easy)","rating":1300,"from":"curated"},{"id":"244B","src":"cf","name":"Undoubtedly Lucky Numbers","rating":1600,"from":"curated"},{"id":"1575D","src":"cf","name":"Divisible by Twenty-Five","rating":1800,"from":"curated"},{"id":"263C","src":"cf","name":"Circle of Numbers","rating":2000,"from":"curated"},{"id":"1593F","src":"cf","name":"Red-Black Number","rating":2100,"from":"curated"},{"id":"448E","src":"cf","name":"Divisors","rating":2200,"from":"curated"},{"id":"cses-1624","src":"cses","name":"Chessboard and Queens","from":"usaco-guide"},{"id":"cses-1625","src":"cses","name":"Grid Paths","from":"curated"}]},{"id":"search-mitm","name":"Meet in the middle","tier":1800,"order":6,"prereq":["search-subsets","bs-sorted"],"summary":"Split the input into two halves, enumerate all 2^(n/2) possibilities for each half, and combine the halves with sorting + binary search, two pointers, or a hash map. Reduces 2^40 to about 2^20 * 20.","learn":["Recognise it: n around 35-45 with subset-like choices, or a path whose two halves can be enumerated separately","Enumerate left-half sums into a sorted vector; for each right-half sum binary search / two-pointer the complement","For counting, use a hash map (or sorted + equal_range) of left-half values","Paths in a grid: enumerate from the start to the anti-diagonal and from the end back to it, meet on the diagonal","Mind memory: 2^20 values per half is fine; 2^23 of pairs can be tight","Modular / XOR variants combine with the same idea (sorted + lower_bound for 'max (a+b) mod m')"],"resources":[{"title":"USACO Guide: Meet In The Middle","url":"https://usaco.guide/gold/meet-in-the-middle","kind":"usaco","where":"USACO Guide Gold","minutes":25},{"title":"CPH: Meet in the middle","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 5.5 (p. 54)","minutes":10}],"problems":[{"id":"888E","src":"cf","name":"Maximum Subsequence","rating":1800,"from":"usaco-guide"},{"id":"1006F","src":"cf","name":"Xor-Paths","rating":2100,"from":"usaco-guide"},{"id":"525E","src":"cf","name":"Anya and Cubes","rating":2100,"from":"curated"},{"id":"1105E","src":"cf","name":"Helping Hiasat ","rating":2200,"from":"curated"},{"id":"585D","src":"cf","name":"Lizard Era: Beginning","rating":2300,"from":"usaco-guide"},{"id":"912E","src":"cf","name":"Prime Gift","rating":2400,"from":"usaco-guide"},{"id":"1257F","src":"cf","name":"Make Them Similar","rating":2400,"from":"curated"},{"id":"cses-1628","src":"cses","name":"Meet in the Middle","from":"usaco-guide"},{"id":"cses-1642","src":"cses","name":"Sum of Four Values","from":"usaco-guide"}]}]},{"id":"sorting","name":"Sorting","cfTags":["sortings"],"subtopics":[{"id":"sort-basics","name":"Sorting & using sorted order","tier":800,"order":1,"prereq":["impl-basics"],"summary":"Sorting makes equal values adjacent, puts extremes at the ends and enables greedy and two-pointer reasoning. Many easy problems become trivial once you realise the order of elements does not matter and you may sort.","learn":["std::sort is O(n log n); sort(a.rbegin(), a.rend()) for descending","After sorting: count distinct values, find duplicates, take k largest/smallest, pair smallest with largest","Ask 'does the input order matter?' — if not, sort first","Sort pairs/tuples to sort by several keys lexicographically; keep original indices in the pair if you must output them","unique + erase to deduplicate a sorted vector"],"resources":[{"title":"USACO Guide: Introduction to Sorting","url":"https://usaco.guide/bronze/intro-sorting","kind":"usaco","where":"USACO Guide Bronze","minutes":20},{"title":"CPH: Sorting theory","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 3.1 (p. 25)","minutes":15},{"title":"CPH: Sorting in C++","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 3.2 (p. 29)","minutes":10}],"problems":[{"id":"1399A","src":"cf","name":"Remove Smallest","rating":800,"from":"curated"},{"id":"1360B","src":"cf","name":"Honest Coach","rating":800,"from":"curated"},{"id":"1353B","src":"cf","name":"Two Arrays And Swaps","rating":800,"from":"curated"},{"id":"1669B","src":"cf","name":"Triple","rating":800,"from":"curated"},{"id":"1742B","src":"cf","name":"Increasing","rating":800,"from":"curated"},{"id":"1971A","src":"cf","name":"My First Sorting Problem","rating":800,"from":"curated"},{"id":"1312B","src":"cf","name":"Bogosort","rating":1000,"from":"curated"},{"id":"1808B","src":"cf","name":"Playing in a Casino","rating":1200,"from":"usaco-guide"},{"id":"1857C","src":"cf","name":"Assembly via Minimums","rating":1200,"from":"curated"},{"id":"1810C","src":"cf","name":"Make It Permutation","rating":1300,"from":"curated"},{"id":"863B","src":"cf","name":"Kayaking","rating":1500,"from":"usaco-guide"},{"id":"cses-1621","src":"cses","name":"Distinct Numbers","from":"usaco-guide"}]},{"id":"sort-comparator","name":"Custom comparators & sorting by key","tier":1200,"order":2,"prereq":["sort-basics"],"summary":"Sorting objects by a custom rule: by a derived key (a_i - b_i, remainder, value/weight), by several criteria, or by a rule that compares two items directly. Must define a strict weak ordering.","learn":["Lambda comparator: sort(v.begin(), v.end(), [](const T& x, const T& y){ return x.key < y.key; })","Comparator must be strict: use <, never <=, or std::sort may crash","Sort by several criteria with tie-breakers, e.g. by score desc then index asc (or compare tuples)","Sort indices instead of objects (iota + sort by a[i]) to keep original positions","Derived keys: sort by a_i - b_i, by a_i mod k, by the result of a function","Avoid floating keys when a cross-multiplied integer comparison works"],"resources":[{"title":"USACO Guide: Custom Comparators and Coordinate Compression","url":"https://usaco.guide/silver/sorting-custom","kind":"usaco","where":"USACO Guide Silver","minutes":30},{"title":"CPH: Sorting in C++ (comparison functions)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 3.2 (p. 29)","minutes":10}],"problems":[{"id":"1850B","src":"cf","name":"Ten Words of Wisdom","rating":800,"from":"curated"},{"id":"1849B","src":"cf","name":"Monsters","rating":1000,"from":"curated"},{"id":"1857D","src":"cf","name":"Strong Vertices","rating":1300,"from":"curated"},{"id":"1551C","src":"cf","name":"Interesting Story","rating":1500,"from":"curated"},{"id":"1478C","src":"cf","name":"Nezzar and Symmetric Array","rating":1700,"from":"usaco-guide"},{"id":"1472E","src":"cf","name":"Correct Placement","rating":1700,"from":"usaco-guide"}]},{"id":"sort-compress-events","name":"Coordinate compression & event sorting","tier":1500,"order":3,"prereq":["sort-comparator","bs-sorted"],"summary":"Coordinate compression maps large or sparse values to 0..k-1 while keeping their order, so they can index arrays or BITs. Event sorting (a basic sweep line) turns intervals into +1/-1 events processed in sorted order.","learn":["Compression: copy, sort, unique, then index = lower_bound(vals, x) - vals.begin()","Intervals [l, r]: events (l, +1) and (r+1, -1) (or (r, -1) with a tie-break) sorted by coordinate","Sweep through events keeping a running count to find maximum overlap or coverage lengths","Decide tie-breaking explicitly: do closings come before openings at the same coordinate?","Compression + Fenwick tree for counting inversions or 'number of earlier elements smaller than x'","A std::map can replace compression when only ordered iteration is needed"],"resources":[{"title":"USACO Guide: Coordinate Compression","url":"https://usaco.guide/silver/sorting-custom","kind":"usaco","where":"USACO Guide Silver","minutes":15},{"title":"CPH: Sweep line algorithms","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 30 (p. 275)","minutes":15}],"problems":[{"id":"2014D","src":"cf","name":"Robert Hood and Mrs Hood","rating":1400,"from":"curated"},{"id":"1915F","src":"cf","name":"Greetings","rating":1500,"from":"curated"},{"id":"1000C","src":"cf","name":"Covered Points Count","rating":1700,"from":"usaco-guide"},{"id":"1579E2","src":"cf","name":"Array Optimization by Deque","rating":1700,"from":"curated"},{"id":"1420D","src":"cf","name":"Rescue Nibel!","rating":1800,"from":"curated"},{"id":"1042D","src":"cf","name":"Petya and Array","rating":1800,"from":"curated"},{"id":"1311F","src":"cf","name":"Moving Points","rating":1900,"from":"curated"},{"id":"cses-1619","src":"cses","name":"Restaurant Customers","from":"usaco-guide"},{"id":"cses-1144","src":"cses","name":"Salary Queries","from":"usaco-guide"}]}]},{"id":"prefix-sums","name":"Prefix Sums & Difference Arrays","cfTags":["implementation","data structures","dp"],"subtopics":[{"id":"prefix-1d","name":"1D prefix sums","tier":1000,"order":1,"prereq":["impl-basics"],"summary":"Precompute p[i] = a[1] + ... + a[i] so any range sum is p[r] - p[l-1] in O(1). The standard tool when a problem asks many range-sum queries or iterates over all subarrays.","learn":["Use 1-indexed p with p[0] = 0 to avoid special cases","Range sum [l, r] = p[r] - p[l-1]; use long long","Prefix counts: keep a prefix array per character/property (e.g. count of 'a' in s[1..i])","Combine prefix and suffix arrays to evaluate 'remove one element' or 'split into two parts' options in O(1) each","Prefix sums of a boolean array answer 'how many good positions in [l, r]'"],"resources":[{"title":"USACO Guide: Introduction to Prefix Sums","url":"https://usaco.guide/silver/prefix-sums","kind":"usaco","where":"USACO Guide Silver","minutes":20},{"title":"CPH: Static array queries (sum queries)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 9.1 (p. 84)","minutes":10}],"problems":[{"id":"1807D","src":"cf","name":"Odd Queries","rating":900,"from":"curated"},{"id":"313B","src":"cf","name":"Ilya and Queries","rating":1100,"from":"curated"},{"id":"1832B","src":"cf","name":"Maximum Sum","rating":1100,"from":"curated"},{"id":"1311C","src":"cf","name":"Perform the Combo","rating":1300,"from":"curated"},{"id":"1555C","src":"cf","name":"Coin Rows","rating":1300,"from":"curated"},{"id":"2008E","src":"cf","name":"Alternating String","rating":1500,"from":"usaco-guide"},{"id":"1826D","src":"cf","name":"Running Miles","rating":1700,"from":"usaco-guide"},{"id":"466C","src":"cf","name":"Number of Ways","rating":1700,"from":"curated"},{"id":"2026D","src":"cf","name":"Sums of Segments","rating":1900,"from":"usaco-guide"},{"id":"cses-1646","src":"cses","name":"Static Range Sum Queries","from":"curated"}]},{"id":"prefix-counting","name":"Counting subarrays with prefix sums + hashing","tier":1300,"order":2,"prereq":["prefix-1d"],"summary":"Counting or detecting subarrays with a given sum/property by looking up earlier prefix values in a map: sum(l..r) = k iff p[r] - p[l-1] = k. Works with transformed arrays (a_i - 1, +1/-1, values mod m).","learn":["For each r, add cnt[p[r] - k] to the answer, then increment cnt[p[r]]; start with cnt[0] = 1","Transform the array so the condition becomes 'sum equals 0' (e.g. a_i - 1 for sum = length, +1/-1 for balanced)","Divisibility: count pairs of equal p[i] mod m (normalise negatives with ((x % m) + m) % m)","Zero-sum subarray exists iff some prefix value repeats; greedy cut when a prefix repeats to break all zero-sum segments","Use std::map or a hashed unordered_map with a custom hash to avoid anti-hash tests"],"resources":[{"title":"USACO Guide: Introduction to Prefix Sums","url":"https://usaco.guide/silver/prefix-sums","kind":"usaco","where":"USACO Guide Silver","minutes":15},{"title":"CPH: Static array queries","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 9.1 (p. 84)","minutes":10}],"problems":[{"id":"1520D","src":"cf","name":"Same Differences","rating":1200,"from":"curated"},{"id":"1915E","src":"cf","name":"Romantic Glasses","rating":1300,"from":"curated"},{"id":"2033D","src":"cf","name":"Kousuke's Assignment","rating":1300,"from":"curated"},{"id":"1426D","src":"cf","name":"Non-zero Segments","rating":1500,"from":"curated"},{"id":"1398C","src":"cf","name":"Good Subarrays","rating":1600,"from":"usaco-guide"},{"id":"1748C","src":"cf","name":"Zero-Sum Prefixes","rating":1600,"from":"curated"},{"id":"cses-1661","src":"cses","name":"Subarray Sums II","from":"usaco-guide"},{"id":"cses-1662","src":"cses","name":"Subarray Divisibility","from":"usaco-guide"}]},{"id":"prefix-max-subarray","name":"Maximum subarray sum (Kadane)","tier":1200,"order":3,"prereq":["prefix-1d"],"summary":"Finding the best contiguous segment: best ending at i is max(a[i], best ending at i-1 + a[i]), or equivalently p[r] - min prefix before r. Variants add constraints such as a forced modification, a segment that must be proper, or multiplying one segment.","learn":["Kadane: cur = max(a[i], cur + a[i]); ans = max(ans, cur)","Equivalent view: answer = max over r of p[r] - min_{l<r} p[l]","Variant 'apply an operation to one subarray': track gain array and run Kadane on it","Variant with states (before / inside / after the modified segment) is a tiny DP","Decide whether the empty subarray is allowed","Length-bounded windows need sliding-window minimum of prefixes"],"resources":[{"title":"USACO Guide: More on Prefix Sums (Max Subarray Sum)","url":"https://usaco.guide/silver/more-prefix-sums","kind":"usaco","where":"USACO Guide Silver","minutes":15},{"title":"CPH: Maximum subarray sum","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 2.4 (p. 21)","minutes":10},{"title":"cp-algorithms: Search the subarray with the maximum/minimum sum","url":"https://cp-algorithms.com/others/maximum_average_segment.html","kind":"cpalgo","where":"cp-algorithms.com","minutes":15}],"problems":[{"id":"1899C","src":"cf","name":"Yarik and Array","rating":1100,"from":"curated"},{"id":"1946B","src":"cf","name":"Maximum Sum","rating":1100,"from":"curated"},{"id":"1285B","src":"cf","name":"Just Eat It!","rating":1300,"from":"curated"},{"id":"1373D","src":"cf","name":"Maximum Sum on Even Positions","rating":1600,"from":"curated"},{"id":"33C","src":"cf","name":"Wonderful Randomized Sum","rating":1800,"from":"curated"},{"id":"1155D","src":"cf","name":"Beautiful Array","rating":1900,"from":"curated"},{"id":"cses-1643","src":"cses","name":"Maximum Subarray Sum","from":"usaco-guide"}]},{"id":"prefix-difference","name":"Difference arrays (range updates)","tier":1300,"order":4,"prereq":["prefix-1d"],"summary":"Applying many 'add x to [l, r]' updates offline: d[l] += x, d[r+1] -= x, then take the prefix sum of d. Also used to count how many intervals cover each point.","learn":["Range add in O(1): d[l] += x; d[r+1] -= x; final value a[i] = prefix of d up to i","Counting coverage: each interval adds 1; after the prefix pass you know how many intervals cover each point","Can be nested: count how many times each operation is applied with one difference array, then apply operations with another","Combine with sorting: count how often each position is queried, then pair biggest counts with biggest values","Second-order differences handle adding arithmetic progressions to a range"],"resources":[{"title":"USACO Guide: More on Prefix Sums (Difference Arrays)","url":"https://usaco.guide/silver/more-prefix-sums","kind":"usaco","where":"USACO Guide Silver","minutes":15},{"title":"CPH: Additional techniques (difference arrays)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 9.4 (p. 93)","minutes":5}],"problems":[{"id":"295A","src":"cf","name":"Greg and Array","rating":1400,"from":"usaco-guide"},{"id":"816B","src":"cf","name":"Karen and Coffee","rating":1400,"from":"usaco-guide"},{"id":"276C","src":"cf","name":"Little Girl and Maximum Sum","rating":1500,"from":"usaco-guide"},{"id":"1795C","src":"cf","name":"Tea Tasting","rating":1500,"from":"curated"},{"id":"1132C","src":"cf","name":"Painting the Fence","rating":1700,"from":"curated"},{"id":"2030D","src":"cf","name":"QED's Favorite Permutation","rating":1700,"from":"usaco-guide"}]},{"id":"prefix-2d","name":"2D prefix sums","tier":1400,"order":5,"prereq":["prefix-1d"],"summary":"Precomputing P[i][j] = sum of the rectangle (1,1)-(i,j) so any sub-rectangle sum is an O(1) inclusion-exclusion. Also extends to 2D difference arrays and to higher dimensions.","learn":["Build: P[i][j] = a[i][j] + P[i-1][j] + P[i][j-1] - P[i-1][j-1]","Query (r1,c1)-(r2,c2): P[r2][c2] - P[r1-1][c2] - P[r2][c1-1] + P[r1-1][c1-1]","2D difference array: four corner updates, then a 2D prefix pass","Add a third dimension when values are small (e.g. one prefix table per brightness or per value)","Combine with binary search on the side length of a square","Weighted prefix sums (sum of i*a[i]) let you compute more complex aggregates in O(1)"],"resources":[{"title":"USACO Guide: More on Prefix Sums (2D Prefix Sums)","url":"https://usaco.guide/silver/more-prefix-sums","kind":"usaco","where":"USACO Guide Silver","minutes":15},{"title":"CPH: Static array queries (2D)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 9.1 (p. 84)","minutes":5}],"problems":[{"id":"1722E","src":"cf","name":"Counting Rectangles","rating":1600,"from":"usaco-guide"},{"id":"835C","src":"cf","name":"Star sky","rating":1600,"from":"curated"},{"id":"1731D","src":"cf","name":"Valiant's New Map","rating":1700,"from":"curated"},{"id":"245H","src":"cf","name":"Queries for Number of Palindromes","rating":1800,"from":"usaco-guide"},{"id":"2044H","src":"cf","name":"Hard Demon Problem","rating":2100,"from":"curated"},{"id":"1301E","src":"cf","name":"Nanosoft","rating":2500,"from":"curated"},{"id":"cses-1652","src":"cses","name":"Forest Queries","from":"usaco-guide"}]},{"id":"prefix-other-ops","name":"Prefix/suffix aggregates (xor, max, min, intersection)","tier":1400,"order":6,"prereq":["prefix-1d","bit-xor"],"summary":"Prefix and suffix arrays work for any associative operation: prefix XOR gives range XOR in O(1); prefix/suffix max/min/gcd/intersection let you evaluate 'everything except element i' or 'split point' questions quickly.","learn":["Prefix XOR: xor(l..r) = px[r] ^ px[l-1] (XOR is its own inverse)","Prefix/suffix combination: value without element i = op(pre[i-1], suf[i+1])","Max/min/gcd are not invertible, so use prefix + suffix (or a sparse table) instead of subtraction","Interval intersection of all but one segment: prefix/suffix max of l and min of r","Counting subarrays with given XOR uses the same hash-map trick as sums"],"resources":[{"title":"USACO Guide: More on Prefix Sums","url":"https://usaco.guide/silver/more-prefix-sums","kind":"usaco","where":"USACO Guide Silver","minutes":10},{"title":"CPH: Static array queries","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 9.1 (p. 84)","minutes":10}],"problems":[{"id":"2123C","src":"cf","name":"Prefix Min and Suffix Max","rating":1000,"from":"curated"},{"id":"1847C","src":"cf","name":"Vampiric Powers, anyone?","rating":1400,"from":"curated"},{"id":"1516B","src":"cf","name":"AGAGA XOOORRR","rating":1500,"from":"curated"},{"id":"1272D","src":"cf","name":"Remove One Element","rating":1500,"from":"curated"},{"id":"1029C","src":"cf","name":"Maximal Intersection","rating":1600,"from":"curated"},{"id":"1349A","src":"cf","name":"Orac and LCM","rating":1600,"from":"usaco-guide"},{"id":"1968F","src":"cf","name":"Equal XOR Segments","rating":1800,"from":"curated"}]}]},{"id":"two-pointers","name":"Two Pointers & Sliding Window","cfTags":["two pointers"],"subtopics":[{"id":"tp-basics","name":"Two pointers on sorted arrays","tier":1100,"order":1,"prereq":["sort-basics"],"summary":"Two indices moving monotonically through one or two sorted arrays: pair-sum search from both ends, merging two sorted lists, counting pairs with sum in a range. Total movement is O(n), so the whole scan is linear.","learn":["Opposite ends: l = 0, r = n-1; if a[l] + a[r] > target then r-- else l++","Count pairs with sum <= x: for each l move r down while a[l] + a[r] > x","Pairs with sum in [L, R] = count(<= R) - count(<= L-1)","Merge-like scan over two sorted arrays (matching applicants to apartments, people to boats)","Prove why moving a pointer never skips the optimum (monotonicity)","Three values: fix one, two-pointer the other two in O(n^2)"],"resources":[{"title":"USACO Guide: Two Pointers","url":"https://usaco.guide/silver/two-pointers","kind":"usaco","where":"USACO Guide Silver","minutes":25},{"title":"CPH: Two pointers method","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 8.1 (p. 77)","minutes":10},{"title":"Codeforces EDU: Two Pointers Method","url":"https://codeforces.com/edu/course/2/lesson/9","kind":"cf-edu","where":"Codeforces EDU (ITMO Academy pilot course)","minutes":60}],"problems":[{"id":"1462A","src":"cf","name":"Favorite Sequence","rating":800,"from":"curated"},{"id":"1791C","src":"cf","name":"Prepend and Append","rating":800,"from":"curated"},{"id":"1399C","src":"cf","name":"Boats Competition","rating":1200,"from":"curated"},{"id":"1729D","src":"cf","name":"Friends and the Restaurant","rating":1200,"from":"curated"},{"id":"2051D","src":"cf","name":"Counting Pairs","rating":1200,"from":"curated"},{"id":"1538C","src":"cf","name":"Number of Pairs","rating":1300,"from":"curated"},{"id":"1324D","src":"cf","name":"Pair of Topics","rating":1400,"from":"curated"},{"id":"1883G1","src":"cf","name":"Dances (Easy version)","rating":1400,"from":"curated"},{"id":"cses-1640","src":"cses","name":"Sum of Two Values","from":"usaco-guide"},{"id":"cses-1641","src":"cses","name":"Sum of Three Values","from":"usaco-guide"},{"id":"cses-1084","src":"cses","name":"Apartments","from":"usaco-guide"},{"id":"cses-1090","src":"cses","name":"Ferris Wheel","from":"usaco-guide"}]},{"id":"tp-window","name":"Variable-size sliding window","tier":1300,"order":2,"prereq":["tp-basics"],"summary":"Maintaining a window [l, r] that expands to the right and shrinks from the left while a monotone condition holds (sum <= k, at most k distinct values, at most k zeros). Finds longest/shortest good subarrays or counts them in O(n).","learn":["Requirement: if [l, r] is good then every sub-window is good (or every super-window is) — monotonicity","For each r, advance l while the window is bad; then [l, r] is the longest good window ending at r","Counting good subarrays: add (r - l + 1) for each r","Maintain window state incrementally: sum, frequency map, number of distinct values","'Exactly k' = 'at most k' - 'at most k-1'","Cyclic arrays: double the array and limit the window length to n"],"resources":[{"title":"USACO Guide: Two Pointers (Sliding Window)","url":"https://usaco.guide/silver/two-pointers","kind":"usaco","where":"USACO Guide Silver","minutes":15},{"title":"USACO Guide: Sliding Window (With Two Pointers)","url":"https://usaco.guide/gold/sliding-window","kind":"usaco","where":"USACO Guide Gold","minutes":15},{"title":"Codeforces EDU: Two Pointers Method","url":"https://codeforces.com/edu/course/2/lesson/9","kind":"cf-edu","where":"Codeforces EDU (ITMO Academy pilot course)","minutes":60}],"problems":[{"id":"1692E","src":"cf","name":"Binary Deque","rating":1200,"from":"curated"},{"id":"1354B","src":"cf","name":"Ternary String","rating":1200,"from":"curated"},{"id":"279B","src":"cf","name":"Books","rating":1400,"from":"usaco-guide"},{"id":"701C","src":"cf","name":"They Are Everywhere","rating":1500,"from":"usaco-guide"},{"id":"660C","src":"cf","name":"Hard Process","rating":1600,"from":"curated"},{"id":"616D","src":"cf","name":"Longest k-Good Segment","rating":1600,"from":"usaco-guide"},{"id":"814C","src":"cf","name":"An impassioned circulation of affection","rating":1600,"from":"usaco-guide"},{"id":"1777C","src":"cf","name":"Quiz Master","rating":1700,"from":"usaco-guide"},{"id":"1611F","src":"cf","name":"ATM and Students","rating":1800,"from":"curated"},{"id":"1744F","src":"cf","name":"MEX vs MED","rating":2000,"from":"usaco-guide"},{"id":"cses-1660","src":"cses","name":"Subarray Sums I","from":"usaco-guide"},{"id":"cses-1141","src":"cses","name":"Playlist","from":"usaco-guide"},{"id":"cses-2428","src":"cses","name":"Subarray Distinct Values","from":"usaco-guide"}]},{"id":"tp-fixed-window","name":"Fixed-size window & sliding min/max (monotonic deque)","tier":1600,"order":3,"prereq":["tp-window"],"summary":"Processing every window of length k: add the new element, remove the old one. For window minimum/maximum use a monotonic deque (amortised O(1)); for medians/costs use two multisets. Frequently used to speed up DP transitions over a range.","learn":["Fixed window: update aggregate with a[r] in and a[r-k] out instead of recomputing","Monotonic deque: pop back while back is worse than the new element, pop front when it leaves the window","Alternative: queue implemented with two stacks storing running minima","Sliding median / sliding cost: two balanced multisets (lower and upper half)","DP optimisation: dp[i] = min(dp[j]) + c over j in [i-k, i-1] becomes O(n) with the deque","Maximum subarray sum with length in [a, b]: prefix sums + sliding window minimum"],"resources":[{"title":"USACO Guide: Sliding Window","url":"https://usaco.guide/gold/sliding-window","kind":"usaco","where":"USACO Guide Gold","minutes":25},{"title":"CPH: Sliding window minimum","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 8.3 (p. 81)","minutes":10},{"title":"cp-algorithms: Minimum stack / Minimum queue","url":"https://cp-algorithms.com/data_structures/stack_queue_modification.html","kind":"cpalgo","where":"cp-algorithms.com","minutes":15}],"problems":[{"id":"1690D","src":"cf","name":"Black and White Stripe","rating":1000,"from":"curated"},{"id":"1196D2","src":"cf","name":"RGB Substring (hard version)","rating":1600,"from":"curated"},{"id":"1941E","src":"cf","name":"Rudolf and k Bridges","rating":1600,"from":"curated"},{"id":"2009G1","src":"cf","name":"Yunli's Subarray Queries (easy version)","rating":1900,"from":"curated"},{"id":"940E","src":"cf","name":"Cashback","rating":2000,"from":"curated"},{"id":"487B","src":"cf","name":"Strip","rating":2000,"from":"curated"},{"id":"cses-1644","src":"cses","name":"Maximum Subarray Sum II","from":"usaco-guide"},{"id":"cses-1076","src":"cses","name":"Sliding Median","from":"usaco-guide"},{"id":"cses-1077","src":"cses","name":"Sliding Cost","from":"usaco-guide"}]}]},{"id":"binary-search","name":"Binary Search","cfTags":["binary search"],"subtopics":[{"id":"bs-sorted","name":"Binary search on a sorted array","tier":1100,"order":1,"prereq":["sort-basics"],"summary":"Finding positions in a sorted array in O(log n): first element >= x, number of elements <= x, elements in a value range. The C++ tools are lower_bound and upper_bound.","learn":["lower_bound(a.begin(), a.end(), x) -> first >= x; upper_bound -> first > x","Count of values in [L, R] = upper_bound(R) - lower_bound(L)","Answer many queries offline: sort once, binary search per query","Binary search over prefix sums / prefix maxima (they are monotone) to answer 'how far can I go' queries","std::set / multiset have their own .lower_bound — use the member function, not std::lower_bound (which is O(n) there)"],"resources":[{"title":"USACO Guide: Binary Search on a Sorted Array","url":"https://usaco.guide/silver/binary-search-sorted-array","kind":"usaco","where":"USACO Guide Silver","minutes":15},{"title":"CPH: Binary search","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 3.3 (p. 31)","minutes":10},{"title":"cp-algorithms: Binary search","url":"https://cp-algorithms.com/num_methods/binary_search.html","kind":"cpalgo","where":"cp-algorithms.com","minutes":20},{"title":"Codeforces EDU: Binary Search","url":"https://codeforces.com/edu/course/2/lesson/6","kind":"cf-edu","where":"Codeforces EDU (ITMO Academy pilot course)","minutes":60}],"problems":[{"id":"706B","src":"cf","name":"Interesting drink","rating":1100,"from":"curated"},{"id":"1676E","src":"cf","name":"Eating Queries","rating":1100,"from":"curated"},{"id":"474B","src":"cf","name":"Worms","rating":1200,"from":"curated"},{"id":"1742E","src":"cf","name":"Scuza","rating":1200,"from":"curated"},{"id":"600B","src":"cf","name":"Queries about less or equal elements","rating":1300,"from":"curated"},{"id":"702C","src":"cf","name":"Cellular Network","rating":1500,"from":"usaco-guide"},{"id":"1971E","src":"cf","name":"Find the Car","rating":1500,"from":"curated"},{"id":"cses-1091","src":"cses","name":"Concert Tickets","from":"usaco-guide"}]},{"id":"bs-answer","name":"Binary search on the answer","tier":1300,"order":2,"prereq":["bs-sorted"],"summary":"If a yes/no predicate check(x) is monotone in x (false...false true...true), binary search for the boundary using O(log range) calls to check. Typical for 'minimise the maximum', 'maximise the minimum', or 'minimum time to finish'.","learn":["Spot it: answers like 'minimum possible maximum' or 'largest x such that ...' with an easy feasibility check","Write check(x) first (often greedy), prove monotonicity, then binary search","Invariant template: lo always bad, hi always good; while (hi - lo > 1) { mid = lo + (hi - lo)/2; ... }","Choose bounds carefully (0 to 2e18 for time-type answers) and guard overflow inside check","Total complexity O(check * log(range))","Off-by-one: decide whether you search the first true or the last true"],"resources":[{"title":"USACO Guide: Binary Search","url":"https://usaco.guide/silver/binary-search","kind":"usaco","where":"USACO Guide Silver","minutes":30},{"title":"CPH: Binary search (finding optimal solutions)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 3.3 (p. 31)","minutes":10},{"title":"Codeforces EDU: Binary Search","url":"https://codeforces.com/edu/course/2/lesson/6","kind":"cf-edu","where":"Codeforces EDU (ITMO Academy pilot course)","minutes":60}],"problems":[{"id":"1873E","src":"cf","name":"Building an Aquarium","rating":1100,"from":"usaco-guide"},{"id":"1613C","src":"cf","name":"Poisoned Dagger","rating":1200,"from":"curated"},{"id":"1352C","src":"cf","name":"K-th Not Divisible by n","rating":1200,"from":"curated"},{"id":"1612C","src":"cf","name":"Chat Ban","rating":1300,"from":"curated"},{"id":"1201C","src":"cf","name":"Maximum Median","rating":1400,"from":"usaco-guide"},{"id":"1840D","src":"cf","name":"Wooden Toy Festival","rating":1400,"from":"curated"},{"id":"1907D","src":"cf","name":"Jumping Through Segments","rating":1400,"from":"curated"},{"id":"1985F","src":"cf","name":"Final Boss","rating":1500,"from":"curated"},{"id":"1760F","src":"cf","name":"Quests","rating":1500,"from":"curated"},{"id":"1623C","src":"cf","name":"Balanced Stone Heaps","rating":1600,"from":"curated"},{"id":"1856C","src":"cf","name":"To Become Max","rating":1600,"from":"usaco-guide"},{"id":"1661C","src":"cf","name":"Water the Trees","rating":1700,"from":"curated"},{"id":"cses-1620","src":"cses","name":"Factory Machines","from":"usaco-guide"},{"id":"cses-1085","src":"cses","name":"Array Division","from":"usaco-guide"}]},{"id":"bs-real","name":"Binary search on real numbers & averages","tier":1500,"order":3,"prereq":["bs-answer"],"summary":"Binary searching a real-valued answer (time, radius, power, ratio) when the feasibility check is monotone. Also covers 'maximise the average/ratio' problems: average >= x iff sum(a_i - x) >= 0, so binary search x (fractional programming).","learn":["Iterate a fixed number of times (60-100) instead of comparing with an epsilon; print with enough decimals (setprecision(10))","Pick safe bounds: lo surely feasible, hi surely infeasible (or vice versa); use long double when values reach 1e9+","Maximise average of a chosen subset/subarray: binary search x, subtract x from every element, check whether a valid choice has sum >= 0","Maximise a ratio sum(a)/sum(b): check whether max of sum(a_i - x*b_i) >= 0","Time-based checks: 'can everything be done/met by time t' with a simulation or geometry formula","If a closed formula exists, prefer it; otherwise binary search avoids fragile algebra"],"resources":[{"title":"cp-algorithms: Binary search (search on real numbers)","url":"https://cp-algorithms.com/num_methods/binary_search.html","kind":"cpalgo","where":"cp-algorithms.com","minutes":15},{"title":"Codeforces EDU: Binary Search (real-valued answers and averages)","url":"https://codeforces.com/edu/course/2/lesson/6","kind":"cf-edu","where":"Codeforces EDU (ITMO Academy pilot course)","minutes":60},{"title":"USACO Guide: Binary Search","url":"https://usaco.guide/silver/binary-search","kind":"usaco","where":"USACO Guide Silver","minutes":10}],"problems":[{"id":"1886B","src":"cf","name":"Fear of the Dark","rating":1200,"from":"curated"},{"id":"1354C1","src":"cf","name":"Simple Polygon Embedding","rating":1400,"from":"curated"},{"id":"1408C","src":"cf","name":"Discrete Acceleration","rating":1500,"from":"curated"},{"id":"1730B","src":"cf","name":"Meeting on the Line","rating":1600,"from":"curated"},{"id":"1359C","src":"cf","name":"Mixing Water","rating":1700,"from":"usaco-guide"},{"id":"1059D","src":"cf","name":"Nature Reserve","rating":2200,"from":"curated"}]},{"id":"bs-kth-median","name":"k-th value & median binary search","tier":1800,"order":4,"prereq":["bs-answer","prefix-1d"],"summary":"Finding the k-th smallest value of a huge implicit multiset by binary searching the value x and counting how many elements are <= x. The same idea gives the 'median >= x' trick: map elements to +1/-1 relative to x so a median condition becomes a sum condition.","learn":["k-th smallest: smallest x with count(<= x) >= k; count(<= x) must be computable quickly (formula, two pointers, sorted arrays)","Multiplication table: count(<= x) = sum over rows i of min(m, x / i)","Median >= x trick: b_i = (a_i >= x ? +1 : -1); median of a segment is >= x iff its b-sum is > 0 (adjust for the exact median definition)","Subarray with length >= k and positive b-sum: prefix sums + running minimum of p[j] for j <= i - k","Threshold binary search: find the value v such that taking every gain >= v uses about k operations, then fix up ties","Maximising the median of a construction: binary search the median, check greedily with the +1/-1 view"],"resources":[{"title":"Codeforces EDU: Binary Search (k-th element)","url":"https://codeforces.com/edu/course/2/lesson/6","kind":"cf-edu","where":"Codeforces EDU (ITMO Academy pilot course)","minutes":60},{"title":"cp-algorithms: Binary search","url":"https://cp-algorithms.com/num_methods/binary_search.html","kind":"cpalgo","where":"cp-algorithms.com","minutes":10},{"title":"USACO Guide: Binary Search","url":"https://usaco.guide/silver/binary-search","kind":"usaco","where":"USACO Guide Silver","minutes":10}],"problems":[{"id":"2103C","src":"cf","name":"Median Splits","rating":1600,"from":"curated"},{"id":"448D","src":"cf","name":"Multiplication Table","rating":1800,"from":"curated"},{"id":"1251D","src":"cf","name":"Salary Changing","rating":1900,"from":"usaco-guide"},{"id":"1996F","src":"cf","name":"Bomb","rating":1900,"from":"curated"},{"id":"2128E1","src":"cf","name":"Submedians (Easy Version)","rating":1900,"from":"curated"},{"id":"1486D","src":"cf","name":"Max Median","rating":2100,"from":"usaco-guide"},{"id":"1993D","src":"cf","name":"Med-imize","rating":2200,"from":"curated"},{"id":"cses-2422","src":"cses","name":"Multiplication Table","from":"usaco-guide"}]},{"id":"bs-advanced","name":"Binary search with complex checks","tier":1800,"order":5,"prereq":["bs-answer"],"summary":"Binary search on the answer where the feasibility check is itself a non-trivial algorithm: a greedy over the whole array, a DP, a simulation in time, or a two-dimensional reachability condition.","learn":["Write and test check(x) as a standalone function before adding the binary search","Check may be DP or greedy over the whole array; total cost is O(check * log range)","Binary search on time with a movement/coverage simulation check (packmen, ships, robots)","Alternating constraints (odd/even positions) are checked greedily by trying both roles","Binary search on min and on max separately when minimising max - min","Watch overflow inside check (cap sums at the target)"],"resources":[{"title":"USACO Guide: Binary Search","url":"https://usaco.guide/silver/binary-search","kind":"usaco","where":"USACO Guide Silver","minutes":15},{"title":"Codeforces EDU: Binary Search","url":"https://codeforces.com/edu/course/2/lesson/6","kind":"cf-edu","where":"Codeforces EDU (ITMO Academy pilot course)","minutes":60},{"title":"cp-algorithms: Binary search","url":"https://cp-algorithms.com/num_methods/binary_search.html","kind":"cpalgo","where":"cp-algorithms.com","minutes":10}],"problems":[{"id":"847E","src":"cf","name":"Packmen","rating":1800,"from":"usaco-guide"},{"id":"1117C","src":"cf","name":"Magic Ship","rating":1900,"from":"usaco-guide"},{"id":"2013D","src":"cf","name":"Minimize the Difference","rating":1900,"from":"curated"},{"id":"1370D","src":"cf","name":"Odd-Even Subsequence","rating":2000,"from":"curated"},{"id":"1866G","src":"cf","name":"Grouped Carriages","rating":2100,"from":"usaco-guide"},{"id":"818F","src":"cf","name":"Level Generation","rating":2100,"from":"usaco-guide"}]}]},{"id":"ternary-search","name":"Ternary Search & Unimodal Optimisation","cfTags":["ternary search"],"subtopics":[{"id":"ternary-search","name":"Ternary search on unimodal functions","tier":1700,"order":1,"prereq":["bs-answer"],"summary":"Finding the minimum/maximum of a function that strictly decreases then increases (unimodal or convex). Ternary search narrows [l, r] by comparing f(m1) and f(m2); for integer convex functions, binary search on f(x+1) - f(x) is cleaner.","learn":["Real version: m1 = l + (r-l)/3, m2 = r - (r-l)/3; drop the worse third; ~100-200 iterations","Integer version: binary search for the first x with f(x+1) - f(x) >= 0, or ternary until r - l < 3 then brute force","Requires strict unimodality — plateaus break it; sums of convex functions are convex","Classic sources: total distance/cost as a function of a meeting point or a target height, number of operations k vs cost","When f is convex in one variable and you iterate the other, nest the searches","Prove convexity (or test it with brute force) before relying on it"],"resources":[{"title":"USACO Guide: Optimizing Unimodal Functions","url":"https://usaco.guide/gold/ternary-search","kind":"usaco","where":"USACO Guide Gold","minutes":25},{"title":"cp-algorithms: Ternary search","url":"https://cp-algorithms.com/num_methods/ternary_search.html","kind":"cpalgo","where":"cp-algorithms.com","minutes":15}],"problems":[{"id":"2009E","src":"cf","name":"Klee's SUPER DUPER LARGE Array!!!","rating":1400,"from":"curated"},{"id":"1933E","src":"cf","name":"Turtle vs. Rabbit Race: Optimal Trainings","rating":1500,"from":"curated"},{"id":"439D","src":"cf","name":"Devu and his Brother","rating":1700,"from":"curated"},{"id":"1928D","src":"cf","name":"Lonely Mountain Dungeons","rating":1900,"from":"curated"},{"id":"427E","src":"cf","name":"Police Patrol","rating":2000,"from":"usaco-guide"},{"id":"2063D","src":"cf","name":"Game With Triangles","rating":2000,"from":"usaco-guide"},{"id":"1355E","src":"cf","name":"Restorer Distance","rating":2100,"from":"usaco-guide"},{"id":"1538G","src":"cf","name":"Gift Set","rating":2100,"from":"curated"},{"id":"1848D","src":"cf","name":"Vika and Bonuses","rating":2200,"from":"curated"},{"id":"626E","src":"cf","name":"Simple Skewness","rating":2400,"from":"usaco-guide"}]}]},{"id":"bit-manipulation","name":"Bit Manipulation","cfTags":["bitmasks"],"subtopics":[{"id":"bit-basics","name":"Bitwise operations & binary representation","tier":900,"order":1,"prereq":["impl-basics"],"summary":"Working with the binary form of integers using &, |, ^, ~, << and >>. Needed for subset masks, parity tricks and every problem that mentions AND/OR/XOR.","learn":["Check bit i: (x >> i) & 1; set: x | (1 << i); clear: x & ~(1 << i); toggle: x ^ (1 << i)","Use 1LL << i for i >= 31; __builtin_popcount(ll), __builtin_ctz, __lg / 63 - __builtin_clzll for highest bit","x & (x - 1) removes the lowest set bit; x & -x isolates it; x is a power of two iff x && !(x & (x-1))","a & b <= min(a, b) <= max(a, b) <= a | b","Binary representation of n has floor(log2 n) + 1 bits; any number is a sum of distinct powers of two","Operator precedence: & | ^ bind weaker than == — always parenthesise"],"resources":[{"title":"USACO Guide: Intro to Bitwise Operators","url":"https://usaco.guide/silver/intro-bitwise","kind":"usaco","where":"USACO Guide Silver","minutes":25},{"title":"CPH: Bit representation","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 10.1 (p. 95)","minutes":5},{"title":"CPH: Bit operations","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 10.2 (p. 96)","minutes":10},{"title":"Bitwise operations for beginners (Errichto)","url":"https://codeforces.com/blog/entry/73490","kind":"cf-blog","where":"Codeforces blog","minutes":20},{"title":"cp-algorithms: Bit manipulation","url":"https://cp-algorithms.com/algebra/bit-manipulation.html","kind":"cpalgo","where":"cp-algorithms.com","minutes":15}],"problems":[{"id":"1527A","src":"cf","name":"And Then There Were K","rating":800,"from":"curated"},{"id":"1421A","src":"cf","name":"XORwice","rating":800,"from":"curated"},{"id":"1688A","src":"cf","name":"Cirno's Perfect Bitmasks Classroom","rating":800,"from":"curated"},{"id":"1635A","src":"cf","name":"Min Or Sum","rating":800,"from":"curated"},{"id":"1829C","src":"cf","name":"Mr. Perfectly Fine","rating":800,"from":"curated"},{"id":"1559A","src":"cf","name":"Mocha and Math","rating":900,"from":"curated"},{"id":"1594B","src":"cf","name":"Special Numbers","rating":1100,"from":"curated"},{"id":"1842B","src":"cf","name":"Tenzing and Books","rating":1100,"from":"curated"},{"id":"cses-2205","src":"cses","name":"Gray Code","from":"curated"}]},{"id":"bit-xor","name":"XOR properties & identities","tier":1200,"order":2,"prereq":["bit-basics"],"summary":"XOR is addition without carry: x ^ x = 0, x ^ 0 = x, it is associative and commutative and self-inverse. Many problems reduce to parity of bits, prefix XOR, or identities like a + b = (a ^ b) + 2(a & b).","learn":["x ^ x = 0 lets you cancel pairs; XOR of a whole array is invariant under swapping","Prefix XOR: xor(l..r) = px[r] ^ px[l-1]","a + b = (a ^ b) + 2 * (a & b); a ^ b <= a + b; a ^ b and a + b have the same parity","If a ^ b = c then a ^ c = b — solve for the unknown by XOR-ing","Splitting into >= 2 parts with equal XOR: if the total XOR is 0 any split into two works; otherwise the number of parts must be odd and three parts (each equal to the total) suffice, since any three adjacent equal parts merge into one","Consecutive XOR 0 ^ 1 ^ ... ^ n has a period-4 closed form"],"resources":[{"title":"USACO Guide: Intro to Bitwise Operators (XOR)","url":"https://usaco.guide/silver/intro-bitwise","kind":"usaco","where":"USACO Guide Silver","minutes":15},{"title":"CPH: Bit operations","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 10.2 (p. 96)","minutes":10},{"title":"Bitwise operations for beginners (Errichto)","url":"https://codeforces.com/blog/entry/73490","kind":"cf-blog","where":"Codeforces blog","minutes":15}],"problems":[{"id":"1805A","src":"cf","name":"We Need the Zero","rating":800,"from":"curated"},{"id":"1698A","src":"cf","name":"XOR Mixup","rating":800,"from":"curated"},{"id":"1979B","src":"cf","name":"XOR Sequences","rating":1000,"from":"curated"},{"id":"2039C1","src":"cf","name":"Shohag Loves XOR (Easy Version)","rating":1200,"from":"curated"},{"id":"1790E","src":"cf","name":"Vlad and a Pair of Numbers","rating":1400,"from":"curated"},{"id":"1722G","src":"cf","name":"Even-Odd XOR","rating":1500,"from":"curated"},{"id":"1872E","src":"cf","name":"Data Structures Fan","rating":1500,"from":"usaco-guide"},{"id":"1325D","src":"cf","name":"Ehab the Xorcist","rating":1700,"from":"curated"},{"id":"1851F","src":"cf","name":"Lisa and the Martians","rating":1800,"from":"usaco-guide"}]},{"id":"bit-contribution","name":"Per-bit independence & contribution counting","tier":1500,"order":3,"prereq":["bit-basics","prefix-1d"],"summary":"Bitwise operations act on each bit independently, so you can solve the problem separately for each of the ~30 bits and add up contributions (bit b contributes 2^b times the number of pairs/subarrays where it is set). Also: counting how often each bit is set across numbers.","learn":["Sum over pairs of (a_i ^ a_j): for each bit, count ones c1 and zeros c0, add c1 * c0 * 2^b","Sum of AND/OR over subarrays: per bit, count subarrays that are all ones / contain a one","Operations that preserve the multiset of bits per position (AND/OR swaps) — reason with per-bit counts","Highest-bit grouping: a_i & a_j >= a_i ^ a_j iff they share the same highest bit","Counting ones in bit b among 1..n has a closed form (period 2^(b+1))","Use per-bit prefix counts to answer range AND/OR queries"],"resources":[{"title":"USACO Guide: Intro to Bitwise Operators","url":"https://usaco.guide/silver/intro-bitwise","kind":"usaco","where":"USACO Guide Silver","minutes":10},{"title":"Bitwise operations 2: popcount & bitsets (Errichto)","url":"https://codeforces.com/blog/entry/73558","kind":"cf-blog","where":"Codeforces blog","minutes":20},{"title":"CPH: Bit operations","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 10.2 (p. 96)","minutes":10}],"problems":[{"id":"1420B","src":"cf","name":"Rock and Lever","rating":1200,"from":"curated"},{"id":"1514B","src":"cf","name":"AND 0, Sum Big","rating":1200,"from":"curated"},{"id":"1601A","src":"cf","name":"Array Elimination","rating":1300,"from":"curated"},{"id":"1362C","src":"cf","name":"Johnny and Another Rating Drop","rating":1400,"from":"curated"},{"id":"2020C","src":"cf","name":"Bitwise Balancing","rating":1400,"from":"curated"},{"id":"1775C","src":"cf","name":"Interesting Sequence","rating":1600,"from":"curated"},{"id":"1368D","src":"cf","name":"AND, OR and square sum","rating":1700,"from":"usaco-guide"},{"id":"1879D","src":"cf","name":"Sum of XOR Functions","rating":1700,"from":"usaco-guide"},{"id":"1957D","src":"cf","name":"A BIT of an Inequality","rating":1900,"from":"curated"},{"id":"cses-1146","src":"cses","name":"Counting Bits","from":"curated"}]},{"id":"bit-greedy","name":"Greedy bit-by-bit & AND/OR monotonicity","tier":1600,"order":4,"prereq":["bit-contribution"],"summary":"Building an answer from the highest bit down: a higher bit is worth more than all lower bits together, so fix bits greedily and check feasibility. Also uses the fact that prefix AND only decreases and prefix OR only increases, changing at most ~30 times.","learn":["Greedy from the top bit: try to set bit b in the answer; keep it if the remaining budget/check allows","2^b > 2^(b-1) + ... + 1 justifies the greedy","AND over a growing range is non-increasing, OR is non-decreasing — binary search or two pointers apply","For a fixed right end there are at most log(maxA) distinct OR (or AND) values over left ends","Combine with masks: candidate answer mask must be a submask/supermask of chosen numbers","Powers of two: splitting/merging (like binary carries) handled bit by bit"],"resources":[{"title":"USACO Guide: Intro to Bitwise Operators","url":"https://usaco.guide/silver/intro-bitwise","kind":"usaco","where":"USACO Guide Silver","minutes":10},{"title":"CPH: Representing sets","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 10.3 (p. 98)","minutes":10}],"problems":[{"id":"1669H","src":"cf","name":"Maximal AND","rating":1300,"from":"curated"},{"id":"1918C","src":"cf","name":"XOR-distance","rating":1400,"from":"curated"},{"id":"1878E","src":"cf","name":"Iva & Pav","rating":1400,"from":"curated"},{"id":"243A","src":"cf","name":"The Brand New Function","rating":1600,"from":"curated"},{"id":"1903D1","src":"cf","name":"Maximum And Queries (easy version)","rating":1700,"from":"curated"},{"id":"1732C1","src":"cf","name":"Sheikh (Easy version)","rating":1800,"from":"usaco-guide"},{"id":"1303D","src":"cf","name":"Fill The Bag","rating":1900,"from":"curated"},{"id":"1946D","src":"cf","name":"Birthday Gift","rating":1900,"from":"curated"},{"id":"1934D1","src":"cf","name":"XOR Break --- Solo Version","rating":2100,"from":"curated"}]}]},{"id":"ad-hoc","name":"Ad Hoc & Observation","cfTags":["math","greedy","implementation"],"subtopics":[{"id":"adhoc-observation","name":"Observations & small-case patterns","tier":1000,"order":1,"prereq":["search-iterate"],"summary":"Problems with no standard algorithm: the solution is a key observation about the structure (what the answer can be, what never changes, what is always achievable). The skill is to experiment on small cases until the pattern appears, then prove it.","learn":["Work small examples by hand or brute force n <= 8 and print the answers to spot a pattern","Ask: what is the answer at most? (often 0/1/2) What is a trivial lower/upper bound — is it always achievable?","Look at extremes: the maximum, the minimum, the first and last elements","Reformulate: what does one operation really change? What is the final state forced to look like?","Prove the observation (or at least stress-test it) before submitting","Keep a personal list of recurring tricks (sum/max conditions, endpoints matter, answer independent of order)"],"resources":[{"title":"USACO Guide: Ad Hoc Problems","url":"https://usaco.guide/bronze/ad-hoc","kind":"usaco","where":"USACO Guide Bronze","minutes":20}],"problems":[{"id":"1405B","src":"cf","name":"Array Cancellation","rating":1000,"from":"curated"},{"id":"1257B","src":"cf","name":"Magic Stick","rating":1000,"from":"curated"},{"id":"1327A","src":"cf","name":"Sum of Odd Integers","rating":1100,"from":"curated"},{"id":"1288B","src":"cf","name":"Yet Another Meme Problem","rating":1100,"from":"curated"},{"id":"1496B","src":"cf","name":"Max and Mex","rating":1100,"from":"curated"},{"id":"1859C","src":"cf","name":"Another Permutation Problem","rating":1200,"from":"curated"},{"id":"1373C","src":"cf","name":"Pluses and Minuses","rating":1300,"from":"curated"},{"id":"1375C","src":"cf","name":"Element Extermination","rating":1400,"from":"curated"},{"id":"1380B","src":"cf","name":"Universal Solution","rating":1400,"from":"curated"},{"id":"1358C","src":"cf","name":"Celex Update","rating":1600,"from":"curated"},{"id":"1554B","src":"cf","name":"Cobb","rating":1700,"from":"curated"},{"id":"1763C","src":"cf","name":"Another Array Problem","rating":2000,"from":"curated"}]},{"id":"adhoc-parity-invariants","name":"Parity, invariants & monovariants","tier":1200,"order":2,"prereq":["adhoc-observation"],"summary":"An invariant is a quantity that operations never change (sum mod 2, XOR, multiset of values at even positions); a monovariant only moves one way. Comparing invariants of the start and target states proves impossibility, and often also tells you exactly when it is possible.","learn":["Find what an operation preserves: parity of the sum, sum mod k, total XOR, relative order of some elements","Parity of positions: swaps of distance 2 keep elements on positions of the same parity","Sum and max conditions: pairs can be removed iff sum is even and max <= sum - max","Monovariants (strictly decreasing potential) prove termination and bound the number of steps","If the invariant matches, usually build the transformation explicitly (connects to constructive)","Coloring arguments on grids (chessboard coloring) are invariants too"],"resources":[{"title":"USACO Guide: Ad Hoc Problems","url":"https://usaco.guide/bronze/ad-hoc","kind":"usaco","where":"USACO Guide Bronze","minutes":15}],"problems":[{"id":"1851B","src":"cf","name":"Parity Sort","rating":800,"from":"curated"},{"id":"1367B","src":"cf","name":"Even Array","rating":800,"from":"curated"},{"id":"1365B","src":"cf","name":"Trouble Sort","rating":1300,"from":"curated"},{"id":"1733C","src":"cf","name":"Parity Shuffle Sorting","rating":1300,"from":"curated"},{"id":"1201B","src":"cf","name":"Zero Array","rating":1500,"from":"curated"},{"id":"1442A","src":"cf","name":"Extreme Subtraction","rating":1800,"from":"curated"},{"id":"1365F","src":"cf","name":"Swaps Again","rating":2100,"from":"curated"},{"id":"cses-1754","src":"cses","name":"Coin Piles","from":"curated"}]},{"id":"adhoc-mex","name":"MEX problems","tier":1100,"order":3,"prereq":["adhoc-observation"],"summary":"MEX (minimum excluded non-negative integer) appears constantly in Div 2/3 problems. The key facts: MEX = k requires all of 0..k-1 to be present and k absent, only small values matter, and large or duplicate values can be reused freely.","learn":["MEX of n numbers is at most n; values > n never change it","To get MEX >= k you need each of 0..k-1 at least once; extra copies are 'free' resources","Splitting into two sets: each value needs two copies to count for both sets (mex(A) + mex(B))","Operations that add x to an element: group values by remainder mod x and greedily fill 0, 1, 2, ...","Prefix MEX is non-decreasing; maintain it in O(n) total by advancing a pointer over a 'present' array","Games with MEX: count how often each small value appears (values appearing once are vulnerable)"],"resources":[{"title":"Mex (mathematics)","url":"https://en.wikipedia.org/wiki/Mex_(mathematics)","kind":"other","where":"Wikipedia","minutes":5},{"title":"USACO Guide: Ad Hoc Problems","url":"https://usaco.guide/bronze/ad-hoc","kind":"usaco","where":"USACO Guide Bronze","minutes":10}],"problems":[{"id":"1497A","src":"cf","name":"Meximization","rating":800,"from":"curated"},{"id":"1566B","src":"cf","name":"MIN-MEX Cut","rating":800,"from":"usaco-guide"},{"id":"1406A","src":"cf","name":"Subset Mex","rating":900,"from":"curated"},{"id":"1806B","src":"cf","name":"Mex Master","rating":900,"from":"curated"},{"id":"1567B","src":"cf","name":"MEXor Mixup","rating":1000,"from":"curated"},{"id":"2021B","src":"cf","name":"Maximize Mex","rating":1200,"from":"curated"},{"id":"1943A","src":"cf","name":"MEX Game 1","rating":1300,"from":"curated"},{"id":"1628A","src":"cf","name":"Meximum Array","rating":1400,"from":"curated"},{"id":"1294D","src":"cf","name":"MEX maximizing","rating":1600,"from":"curated"},{"id":"1619E","src":"cf","name":"MEX and Increments","rating":1700,"from":"curated"},{"id":"1375D","src":"cf","name":"Replace by MEX","rating":1900,"from":"curated"}]},{"id":"adhoc-pigeonhole","name":"Pigeonhole & bounding the answer","tier":1500,"order":4,"prereq":["adhoc-observation"],"summary":"If n items go into fewer than n boxes, two share a box. In contests this turns large inputs into trivial cases (n > m means two equal remainders, so the answer is immediate) and proves that the answer or the search is small, so brute force on the remaining cases is fast.","learn":["n > m values mod m: two have equal remainder, so a difference (or a prefix-sum segment) is divisible by m","Among n + 1 prefix sums mod n, two coincide: some non-empty segment has sum divisible by n","Bounded number of distinct pair sums: brute force over pairs stops early because a collision must appear quickly","Answer is small because something grows fast (lcm of 1..k, doubling, factorial) — iterate only up to that bound","Combine: handle the large case with pigeonhole, the small case with brute force or DP"],"resources":[{"title":"Pigeonhole principle","url":"https://en.wikipedia.org/wiki/Pigeonhole_principle","kind":"other","where":"Wikipedia","minutes":10},{"title":"USACO Guide: Ad Hoc Problems","url":"https://usaco.guide/bronze/ad-hoc","kind":"usaco","where":"USACO Guide Bronze","minutes":10}],"problems":[{"id":"1855B","src":"cf","name":"Longest Divisors Interval","rating":900,"from":"curated"},{"id":"2067C","src":"cf","name":"Devyatkino","rating":1500,"from":"curated"},{"id":"1305C","src":"cf","name":"Kuroni and Impossible Calculation","rating":1600,"from":"curated"},{"id":"1500A","src":"cf","name":"Going Home","rating":1800,"from":"curated"},{"id":"577B","src":"cf","name":"Modulo Sum","rating":1900,"from":"curated"},{"id":"1270G","src":"cf","name":"Subset with Zero Sum","rating":2700,"from":"curated"}]},{"id":"adhoc-perm-cycles","name":"Permutation cycles, swaps & inversion parity","tier":1300,"order":5,"prereq":["adhoc-parity-invariants"],"summary":"A permutation splits into disjoint cycles (i -> p_i). Sorting by swaps needs n - (number of cycles) swaps, each swap changes the number of inversions by an odd amount, and 3-cycles preserve parity. These facts answer 'minimum swaps', 'is it reachable' and 'what is reachable from i' questions.","learn":["Find cycles by following i -> p_i with a visited array; elements on a cycle share everything 'reachable' from them","Minimum swaps to sort a permutation = n - (number of cycles)","One swap changes the number of cycles by exactly +-1 and flips the parity of the permutation","Parity of a permutation = parity of inversions = parity of (n - cycles); 3-cycles are even, so they only reach same-parity permutations","Duplicates in the array give free parity flips (swap equal elements)","Bubble sort swaps = number of inversions; adjacent-swap distance between arrays = inversions"],"resources":[{"title":"USACO Guide: Functional Graphs (cycles)","url":"https://usaco.guide/silver/func-graphs","kind":"usaco","where":"USACO Guide Silver","minutes":15},{"title":"CPH: Sorting theory (inversions)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 3.1 (p. 25)","minutes":10},{"title":"Parity of a permutation","url":"https://en.wikipedia.org/wiki/Parity_of_a_permutation","kind":"other","where":"Wikipedia","minutes":10}],"problems":[{"id":"1249B1","src":"cf","name":"Books Exchange (easy version)","rating":1000,"from":"curated"},{"id":"2008D","src":"cf","name":"Sakurako's Hobby","rating":1100,"from":"curated"},{"id":"1249B2","src":"cf","name":"Books Exchange (hard version)","rating":1300,"from":"curated"},{"id":"2033E","src":"cf","name":"Sakurako, Kosuke, and the Permutation","rating":1400,"from":"curated"},{"id":"1983D","src":"cf","name":"Swap Dilemma","rating":1700,"from":"curated"},{"id":"1768D","src":"cf","name":"Lucky Permutation","rating":1800,"from":"curated"},{"id":"1585D","src":"cf","name":"Yet Another Sorting Problem","rating":1900,"from":"curated"}]}]},{"id":"constructive","name":"Constructive Algorithms","cfTags":["constructive algorithms"],"subtopics":[{"id":"cons-basics","name":"Constructive basics","tier":900,"order":1,"prereq":["adhoc-observation"],"summary":"Instead of computing a number you output any object (array, string, permutation) with the required property. Start from the simplest pattern that might work, check it on edge cases, and output -1 exactly when an invariant forbids a solution.","learn":["Try trivial constructions first: all equal, 1..n, alternating, sorted/reversed","Decide when the answer is impossible (parity, small n) and handle those cases explicitly","Build a solution for small n by hand and generalise (often by parity of n or n mod 4)","Write a checker that validates your output on random tests","Any valid answer is accepted — avoid over-engineering for optimality that is not asked"],"resources":[{"title":"USACO Guide: Ad Hoc Problems","url":"https://usaco.guide/bronze/ad-hoc","kind":"usaco","where":"USACO Guide Bronze","minutes":15}],"problems":[{"id":"1890A","src":"cf","name":"Doremy's Paint 3","rating":800,"from":"curated"},{"id":"1343B","src":"cf","name":"Balanced Array","rating":800,"from":"curated"},{"id":"1837A","src":"cf","name":"Grasshopper on a Line","rating":800,"from":"curated"},{"id":"1878B","src":"cf","name":"Aleksa and Stack","rating":800,"from":"curated"},{"id":"1831A","src":"cf","name":"Twin Permutations","rating":800,"from":"curated"},{"id":"1335B","src":"cf","name":"Construct the String","rating":900,"from":"curated"},{"id":"1869A","src":"cf","name":"Make It Zero","rating":900,"from":"curated"},{"id":"1520C","src":"cf","name":"Not Adjacent Matrix","rating":1000,"from":"curated"},{"id":"cses-1092","src":"cses","name":"Two Sets","from":"curated"}]},{"id":"cons-permutations","name":"Constructing permutations & arrays","tier":1200,"order":2,"prereq":["cons-basics"],"summary":"Building permutations or arrays with constraints on adjacent differences, prefix values, fixed points, MEX or inversions. Common patterns: reverse blocks, interleave halves, shift by one, place large and small alternately.","learn":["Cyclic shift (2, 3, ..., n, 1) removes all fixed points","Even numbers then odd numbers (2 4 6 ... 1 3 5 ...) keeps every adjacent difference >= 2 for n >= 4 (n = 2, 3 are impossible)","Fill positions greedily with the smallest/largest unused value (keep a set of unused values)","Reverse a suffix/prefix to adjust inversions or a target sum","Use prefix-max/MEX constraints to decide where a value is forced and fill the rest freely","Check small n (1, 2, 3) separately — they are often impossible"],"resources":[{"title":"USACO Guide: Ad Hoc Problems","url":"https://usaco.guide/bronze/ad-hoc","kind":"usaco","where":"USACO Guide Bronze","minutes":10}],"problems":[{"id":"1454A","src":"cf","name":"Special Permutation","rating":800,"from":"curated"},{"id":"1992C","src":"cf","name":"Gorilla and Permutation","rating":900,"from":"curated"},{"id":"1506E","src":"cf","name":"Restoring the Permutation","rating":1500,"from":"curated"},{"id":"1473C","src":"cf","name":"No More Inversions","rating":1500,"from":"curated"},{"id":"1352G","src":"cf","name":"Special Permutation","rating":1600,"from":"curated"},{"id":"1364C","src":"cf","name":"Ehab and Prefix MEXs","rating":1600,"from":"curated"},{"id":"1658C","src":"cf","name":"Shinju and the Lost Permutation","rating":1700,"from":"curated"},{"id":"2123F","src":"cf","name":"Minimize Fixed Points","rating":1700,"from":"curated"},{"id":"cses-1070","src":"cses","name":"Permutations","from":"curated"}]},{"id":"cons-grids-strings","name":"Constructing grids & strings","tier":1300,"order":3,"prereq":["cons-basics"],"summary":"Filling a grid or writing a string that satisfies local constraints (no equal neighbours, given row/column sums, avoided substrings). Patterns: chessboard colourings, cyclic shifts of rows, block repetition, periodic strings.","learn":["Chessboard / striped colourings satisfy many 'adjacent cells differ' constraints","Shift each row cyclically by a constant to spread ones evenly (row/column count constraints)","Build a large grid from repeated small blocks (2x2 or 4x4) with offsets","Strings: periodic constructions (abcabc...) and trying all permutations of a few letters","Make a local change to an existing valid grid (change one cell per block) to satisfy an extra rule"],"resources":[{"title":"USACO Guide: Ad Hoc Problems","url":"https://usaco.guide/bronze/ad-hoc","kind":"usaco","where":"USACO Guide Bronze","minutes":10}],"problems":[{"id":"1699B","src":"cf","name":"Almost Ternary Matrix","rating":900,"from":"curated"},{"id":"1335D","src":"cf","name":"Anti-Sudoku","rating":1300,"from":"curated"},{"id":"1863D","src":"cf","name":"Two-Colored Dominoes","rating":1400,"from":"curated"},{"id":"1968E","src":"cf","name":"Cells Arrangement","rating":1600,"from":"curated"},{"id":"1208C","src":"cf","name":"Magic Grid","rating":1800,"from":"curated"},{"id":"1554D","src":"cf","name":"Diane","rating":1800,"from":"curated"},{"id":"1360G","src":"cf","name":"A/B Matrix","rating":1900,"from":"curated"},{"id":"1213E","src":"cf","name":"Two Small Strings","rating":1900,"from":"curated"},{"id":"cses-1755","src":"cses","name":"Palindrome Reorder","from":"curated"}]},{"id":"cons-operations","name":"Constructing sequences of operations","tier":1400,"order":4,"prereq":["cons-basics","adhoc-parity-invariants"],"summary":"Outputting a list of at most K operations (flip a prefix, swap, apply XOR, reverse) that transforms the input into a target. The limit K hints at the construction: n ops = fix one position per op, 2n ops = two ops per position, 3 ops = a clever fixed recipe.","learn":["Read the operation limit as a hint about the per-element budget","Fix positions one by one from the end (or the start) so that later operations do not disturb them","Reduce to a canonical form (e.g. all zeros) from both start and target, then reverse the second sequence","Invariants decide feasibility; the construction must reach every state the invariant allows","Simulate your operations in the code to double-check the final state"],"resources":[{"title":"USACO Guide: Ad Hoc Problems","url":"https://usaco.guide/bronze/ad-hoc","kind":"usaco","where":"USACO Guide Bronze","minutes":10}],"problems":[{"id":"1381A1","src":"cf","name":"Prefix Flip (Easy Version)","rating":1300,"from":"curated"},{"id":"1839C","src":"cf","name":"Insert Zero and Invert Prefix","rating":1300,"from":"curated"},{"id":"1750C","src":"cf","name":"Complementary XOR","rating":1400,"from":"curated"},{"id":"1421C","src":"cf","name":"Palindromifier","rating":1400,"from":"curated"},{"id":"1327C","src":"cf","name":"Game with Chips","rating":1600,"from":"curated"},{"id":"1381A2","src":"cf","name":"Prefix Flip (Hard Version)","rating":1700,"from":"curated"},{"id":"1438D","src":"cf","name":"Powerful Ksenia","rating":2200,"from":"curated"}]},{"id":"cons-math","name":"Arithmetic & number constructions","tier":1300,"order":5,"prereq":["cons-basics"],"summary":"Constructing numbers or arrays with gcd/lcm/divisibility/sum constraints: split n into k parts with a given lcm, find numbers with prescribed remainders, choose values to make a sum vanish. Usually relies on parity or a simple divisor argument.","learn":["Use 1s and 2s as fillers; handle n odd / n even / n mod 4 separately","gcd(x, x+1) = 1; lcm of (k, k, ...) patterns; divisibility by building from the previous term","Pairs (a, -b) and (b, -a) cancel: pair up elements to make a weighted sum zero","Choose numbers as multiples of a large base to control remainders","Verify with a brute-force checker on all small inputs"],"resources":[{"title":"USACO Guide: Ad Hoc Problems","url":"https://usaco.guide/bronze/ad-hoc","kind":"usaco","where":"USACO Guide Bronze","minutes":10}],"problems":[{"id":"1968C","src":"cf","name":"Assembly via Remainders","rating":1000,"from":"curated"},{"id":"1708B","src":"cf","name":"Difference of GCDs","rating":1100,"from":"curated"},{"id":"1497C1","src":"cf","name":"k-LCM (easy version)","rating":1200,"from":"curated"},{"id":"1562C","src":"cf","name":"Rings","rating":1500,"from":"curated"},{"id":"1497C2","src":"cf","name":"k-LCM (hard version)","rating":1600,"from":"curated"},{"id":"1582D","src":"cf","name":"Vupsen, Pupsen and 0","rating":1600,"from":"curated"},{"id":"1316C","src":"cf","name":"Primitive Primes","rating":1800,"from":"curated"},{"id":"1656D","src":"cf","name":"K-good","rating":1900,"from":"curated"},{"id":"1366D","src":"cf","name":"Two Divisors","rating":2000,"from":"curated"}]},{"id":"cons-bitwise","name":"Bitwise constructions (XOR/AND/OR)","tier":1300,"order":6,"prereq":["cons-basics","bit-xor"],"summary":"Constructing numbers, pairs or permutations with a prescribed XOR/AND/OR value. Work bit by bit, use complements (x ^ (2^k - 1)) and powers of two as building blocks, and reserve one or two 'free' elements to fix the final XOR.","learn":["Complement pairing: x and (2^k - 1) ^ x have AND 0 and OR 2^k - 1","Fix the XOR at the end: choose n - 1 elements freely, set the last to the XOR you still need (check distinctness/bounds)","Use large distinct high bits (2^29, 2^30) to make values distinct without disturbing low bits","Maximising OR under a sum: put 2^b - 1 (all low bits) in one element and the remainder in another","Permutations maximising alternating AND/OR: place the elements that hold the top bits at the end","Handle small n and targets of the form 2^m - 1 separately (they often need a special pattern)"],"resources":[{"title":"USACO Guide: Intro to Bitwise Operators","url":"https://usaco.guide/silver/intro-bitwise","kind":"usaco","where":"USACO Guide Silver","minutes":15},{"title":"Bitwise operations for beginners (Errichto)","url":"https://codeforces.com/blog/entry/73490","kind":"cf-blog","where":"Codeforces blog","minutes":15}],"problems":[{"id":"1758B","src":"cf","name":"XOR = Average","rating":900,"from":"curated"},{"id":"1632B","src":"cf","name":"Roof Construction","rating":1000,"from":"curated"},{"id":"1957B","src":"cf","name":"A BIT of a Construction","rating":1100,"from":"curated"},{"id":"1988C","src":"cf","name":"Increasing Sequence with Fixed OR","rating":1300,"from":"curated"},{"id":"2035C","src":"cf","name":"Alya and Permutation","rating":1400,"from":"curated"},{"id":"1630A","src":"cf","name":"And Matching","rating":1500,"from":"curated"},{"id":"1332D","src":"cf","name":"Walk on Matrix","rating":1700,"from":"curated"}]}]},{"id":"greedy","name":"Greedy Algorithms","cfTags":["greedy"],"subtopics":[{"id":"greedy-basics","name":"Greedy basics","tier":800,"order":1,"prereq":["impl-basics"],"summary":"Making the locally best choice at each step (take the largest, use the cheapest, act as late as possible) when it can be shown never to hurt. The hard part is knowing when greedy fails; always try to find a counterexample first.","learn":["State the greedy rule precisely, then try to break it with a small counterexample","Classic failure: coin change with arbitrary denominations — that needs DP","Proof idea 'stays ahead': after each step greedy is at least as good as any other solution","Moving everything to the median minimises total absolute distance","When greedy is unclear, brute-force small cases and compare"],"resources":[{"title":"USACO Guide: Introduction to Greedy Algorithms","url":"https://usaco.guide/bronze/intro-greedy","kind":"usaco","where":"USACO Guide Bronze","minutes":20},{"title":"CPH: Coin problem","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 6.1 (p. 57)","minutes":5}],"problems":[{"id":"1551A","src":"cf","name":"Polycarp and Coins","rating":800,"from":"curated"},{"id":"1399B","src":"cf","name":"Gifts Fixing","rating":800,"from":"curated"},{"id":"1807B","src":"cf","name":"Grab the Candies","rating":800,"from":"curated"},{"id":"1675B","src":"cf","name":"Make It Increasing","rating":900,"from":"curated"},{"id":"1374C","src":"cf","name":"Move Brackets","rating":1000,"from":"curated"},{"id":"1914C","src":"cf","name":"Quests","rating":1100,"from":"usaco-guide"},{"id":"1520E","src":"cf","name":"Arranging The Sheep","rating":1400,"from":"curated"}]},{"id":"greedy-sorting","name":"Greedy with sorting","tier":1100,"order":2,"prereq":["greedy-basics","sort-basics"],"summary":"Sort the items by the right key first, then a simple greedy pass becomes optimal: take cheapest items first, pair biggest with smallest, process tasks by deadline. Most Div 2 B/C greedy problems look like this.","learn":["Find the processing order (by value, by deadline, by cost) and argue why it is optimal","Take-as-many-as-possible: sort ascending and add while the budget allows","Pairing: smallest with largest (two pointers) or adjacent after sorting","Prefix of the sorted order is often optimal — combine with prefix sums to try every count k","Minimising sum of |a_i - x|: choose x = median"],"resources":[{"title":"USACO Guide: Greedy Algorithms with Sorting","url":"https://usaco.guide/silver/greedy-sorting","kind":"usaco","where":"USACO Guide Silver","minutes":25},{"title":"CPH: Minimizing sums","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 6.4 (p. 61)","minutes":5}],"problems":[{"id":"1791G1","src":"cf","name":"Teleporters (Easy Version)","rating":1100,"from":"curated"},{"id":"1238B","src":"cf","name":"Kill `Em All","rating":1300,"from":"curated"},{"id":"1418B","src":"cf","name":"Negative Prefixes","rating":1300,"from":"curated"},{"id":"762B","src":"cf","name":"USB vs. PS/2","rating":1400,"from":"usaco-guide"},{"id":"1203E","src":"cf","name":"Boxers","rating":1500,"from":"curated"},{"id":"1158A","src":"cf","name":"The Party and Sweets","rating":1500,"from":"usaco-guide"},{"id":"1296D","src":"cf","name":"Fight with Monsters","rating":1500,"from":"curated"},{"id":"1783C","src":"cf","name":"Yet Another Tournament","rating":1700,"from":"usaco-guide"},{"id":"321B","src":"cf","name":"Ciel and Duel","rating":1900,"from":"usaco-guide"},{"id":"cses-1074","src":"cses","name":"Stick Lengths","from":"usaco-guide"},{"id":"cses-2183","src":"cses","name":"Missing Coin Sum","from":"curated"}]},{"id":"greedy-intervals","name":"Interval scheduling & covering","tier":1400,"order":3,"prereq":["greedy-sorting","sort-compress-events"],"summary":"Classic interval greedies: choose the maximum number of disjoint intervals (sort by right end), stab all intervals with the fewest points, cover a segment with the fewest intervals, remove the fewest intervals so no point is over-covered.","learn":["Max disjoint intervals: sort by right endpoint, take each interval that starts after the last chosen end","Min points to stab all intervals: sort by right end; place a point at r when the interval is not yet stabbed","Cover [0, L] with fewest intervals: repeatedly take the interval reaching furthest among those starting <= current end","Too many covering intervals at a point: drop the one that extends furthest right (set/priority queue)","Assigning values/rooms to intervals: sweep by left end, priority queue by right end","Nested segments: sort by l ascending and r descending"],"resources":[{"title":"USACO Guide: Greedy Algorithms with Sorting (Scheduling)","url":"https://usaco.guide/silver/greedy-sorting","kind":"usaco","where":"USACO Guide Silver","minutes":15},{"title":"CPH: Scheduling","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 6.2 (p. 58)","minutes":10}],"problems":[{"id":"976C","src":"cf","name":"Nested Segments","rating":1500,"from":"curated"},{"id":"1462F","src":"cf","name":"The Treasure of The Segments","rating":1800,"from":"curated"},{"id":"1249D1","src":"cf","name":"Too Many Segments (easy version)","rating":1800,"from":"curated"},{"id":"1249D2","src":"cf","name":"Too Many Segments (hard version)","rating":1800,"from":"curated"},{"id":"22D","src":"cf","name":"Segments","rating":1900,"from":"curated"},{"id":"1701D","src":"cf","name":"Permutation Restoration","rating":1900,"from":"curated"},{"id":"cses-1629","src":"cses","name":"Movie Festival","from":"usaco-guide"},{"id":"cses-1632","src":"cses","name":"Movie Festival II","from":"usaco-guide"},{"id":"cses-1164","src":"cses","name":"Room Allocation","from":"usaco-guide"}]},{"id":"greedy-exchange","name":"Exchange argument","tier":1500,"order":4,"prereq":["greedy-sorting","sort-comparator"],"summary":"Proving a greedy order by showing that swapping two adjacent items that violate the order never makes the answer better. The comparison of the two orders usually yields the comparator itself (a_i * b_j < a_j * b_i, s + t < t + s).","learn":["Take two adjacent items i, j; write cost(i then j) and cost(j then i); the sign of the difference is your comparator","Classic results: shortest processing time first, sort strings by s + t < t + s, sort by ratio a/b via cross-multiplication","Projects that raise and lower a resource: positives by requirement ascending, negatives by (requirement + change) descending","Check the comparator is transitive (strict weak order)","If no adjacent-swap argument works, the problem probably needs DP on top of the order"],"resources":[{"title":"USACO Guide: Greedy Algorithms with Sorting","url":"https://usaco.guide/silver/greedy-sorting","kind":"usaco","where":"USACO Guide Silver","minutes":10},{"title":"CPH: Tasks and deadlines","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 6.3 (p. 60)","minutes":5},{"title":"cp-algorithms: Scheduling jobs on one machine","url":"https://cp-algorithms.com/schedules/schedule_one_machine.html","kind":"cpalgo","where":"cp-algorithms.com","minutes":15},{"title":"cp-algorithms: Scheduling jobs on two machines","url":"https://cp-algorithms.com/schedules/schedule_two_machines.html","kind":"cpalgo","where":"cp-algorithms.com","minutes":15}],"problems":[{"id":"1607D","src":"cf","name":"Blue-Red Permutation","rating":1300,"from":"curated"},{"id":"632C","src":"cf","name":"The Smallest String Concatenation","rating":1700,"from":"usaco-guide"},{"id":"922D","src":"cf","name":"Robot Vacuum Cleaner","rating":1800,"from":"curated"},{"id":"864E","src":"cf","name":"Fire","rating":2000,"from":"curated"},{"id":"1203F1","src":"cf","name":"Complete the Projects (easy version)","rating":2100,"from":"curated"},{"id":"1203F2","src":"cf","name":"Complete the Projects (hard version)","rating":2300,"from":"curated"},{"id":"cses-1630","src":"cses","name":"Tasks and Deadlines","from":"usaco-guide"},{"id":"cses-1631","src":"cses","name":"Reading Books","from":"usaco-guide"}]},{"id":"greedy-lexicographic","name":"Lexicographic & digit greedy","tier":1200,"order":5,"prereq":["greedy-basics"],"summary":"Making the lexicographically smallest/largest string or number: decide characters from left to right, choosing the best possible character that still allows a valid completion. A monotonic stack often implements the 'remove k characters' family.","learn":["Fix positions left to right; at each position pick the best character that keeps the rest feasible","Removing characters for the smallest result: monotonic stack, pop while top > current and removals remain","Merging two sequences while keeping internal order (e.g. by parity): two-pointer merge choosing the smaller head","First differing position decides — improve as early as possible","Digits: replace the first digit where improvement is possible, then keep improving while it helps"],"resources":[{"title":"USACO Guide: Introduction to Greedy Algorithms","url":"https://usaco.guide/bronze/intro-greedy","kind":"usaco","where":"USACO Guide Bronze","minutes":10}],"problems":[{"id":"1328C","src":"cf","name":"Ternary XOR","rating":1200,"from":"curated"},{"id":"1730C","src":"cf","name":"Minimum Notation","rating":1200,"from":"curated"},{"id":"1157B","src":"cf","name":"Long Number","rating":1300,"from":"curated"},{"id":"1905C","src":"cf","name":"Largest Subsequence","rating":1400,"from":"curated"},{"id":"1251C","src":"cf","name":"Minimize The Integer","rating":1600,"from":"curated"},{"id":"1886C","src":"cf","name":"Decreasing String","rating":1600,"from":"curated"}]},{"id":"greedy-pq","name":"Greedy with priority queue / multiset","tier":1500,"order":6,"prereq":["greedy-sorting"],"summary":"Greedy choices that need the current best among a changing set: always take the largest remaining value, assign the earliest free room, take the best k items in a prefix. A priority_queue or multiset gives each choice in O(log n).","learn":["Sweep in one order (time, position) and keep candidates in a heap keyed by another criterion","Best k elements of every prefix: min-heap of size k, pop the smallest when it overflows","Repeatedly take the max, modify it and push it back (marginal gains when splitting into parts)","multiset supports erase(find(x)) and lower_bound — use it when you need both ends or arbitrary removals","Concatenate sorting + heap: sort by one parameter, heap over the other (e.g. length vs beauty)","Merging greedy (Huffman): repeatedly merge the two smallest items; total cost = sum of merge costs is minimised"],"resources":[{"title":"USACO Guide: Priority Queues","url":"https://usaco.guide/silver/priority-queues","kind":"usaco","where":"USACO Guide Silver","minutes":20},{"title":"CPH: Other structures (priority queue)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 4.5 (p. 41)","minutes":10},{"title":"CPH: Data compression (Huffman coding)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 6.5 (p. 62)","minutes":10}],"problems":[{"id":"1579D","src":"cf","name":"Productive Meeting","rating":1400,"from":"curated"},{"id":"1140C","src":"cf","name":"Playlist","rating":1600,"from":"curated"},{"id":"1353D","src":"cf","name":"Constructing the Array","rating":1600,"from":"curated"},{"id":"1061D","src":"cf","name":"TV Shows","rating":2000,"from":"curated"},{"id":"2085D","src":"cf","name":"Serval and Kaitenzushi Buffet","rating":2000,"from":"usaco-guide"},{"id":"1428E","src":"cf","name":"Carrots for Rabbits","rating":2200,"from":"usaco-guide"},{"id":"cses-1161","src":"cses","name":"Stick Division","from":"usaco-guide"}]},{"id":"greedy-regret","name":"Regret greedy (undoable choices)","tier":2000,"order":7,"prereq":["greedy-pq"],"summary":"Greedily accept every choice, but keep enough information in a heap to undo the worst earlier choice when a better one arrives. Turns many seemingly DP problems (buy/sell stocks, drink potions, bracket costs) into O(n log n).","learn":["Take the item now; if the constraint breaks, remove the worst taken item (heap top)","Potions: drink everything, if health < 0 spit out the most negative potion drunk so far","Buy low sell high: push price twice so a sale can later be 'upgraded' to a later sale","Bracket sequence with costs: start with cheapest bracket, switch the best candidate when balance goes negative","Proof: the heap keeps the optimal solution for each prefix — think of it as exchange argument applied online"],"resources":[{"title":"USACO Guide: Priority Queues","url":"https://usaco.guide/silver/priority-queues","kind":"usaco","where":"USACO Guide Silver","minutes":10}],"problems":[{"id":"1526C1","src":"cf","name":"Potions (Easy Version)","rating":1500,"from":"curated"},{"id":"1526C2","src":"cf","name":"Potions (Hard Version)","rating":1600,"from":"curated"},{"id":"1974G","src":"cf","name":"Money Buys Less Happiness Now ","rating":2000,"from":"curated"},{"id":"1271D","src":"cf","name":"Portals","rating":2100,"from":"curated"},{"id":"865D","src":"cf","name":"Buy Low Sell High","rating":2400,"from":"curated"},{"id":"3D","src":"cf","name":"Least Cost Bracket Sequence","rating":2600,"from":"curated"},{"id":"436E","src":"cf","name":"Cardboard Box","rating":2600,"from":"curated"}]}]},{"id":"interactive","name":"Interactive Problems","cfTags":["interactive"],"subtopics":[{"id":"inter-basics","name":"Interactive protocol & query thinking","tier":1300,"order":1,"prereq":["impl-basics"],"summary":"In interactive problems your program talks to a judge: print a query, flush, read the response, and finish within a query limit. The query limit is the main hint about the intended strategy.","learn":["Flush after every query: cout << ... << endl (or cout.flush()); read the response immediately","Stop immediately on a -1 response to avoid Idleness/Wrong Answer confusion","Count the query budget: n queries, n/2, log n or 2 log n each suggest a different strategy","Write a local interactor (or simulate the judge in a function) to test","Adaptive judges may change the hidden answer consistently with previous responses — your strategy must work in the worst case","Use randomisation when the judge is not adaptive and an expected bound suffices"],"resources":[{"title":"Interactive Problems: Guide for Participants","url":"https://codeforces.com/blog/entry/45307","kind":"cf-blog","where":"Codeforces blog","minutes":15},{"title":"USACO Guide: Interactive and Communication Problems","url":"https://usaco.guide/adv/interactive","kind":"usaco","where":"USACO Guide Advanced","minutes":25}],"problems":[{"id":"2013C","src":"cf","name":"Password Cracking","rating":1400,"from":"curated"},{"id":"1407C","src":"cf","name":"Chocolate Bunny","rating":1600,"from":"curated"},{"id":"1797C","src":"cf","name":"Li Hua and Chess","rating":1600,"from":"curated"},{"id":"1729E","src":"cf","name":"Guess the Cycle Size","rating":1800,"from":"curated"},{"id":"1846F","src":"cf","name":"Rudolph and Mimic","rating":1800,"from":"curated"},{"id":"1534D","src":"cf","name":"Lost Tree","rating":1800,"from":"curated"},{"id":"1617D1","src":"cf","name":"Too Many Impostors (easy version)","rating":1800,"from":"curated"}]},{"id":"inter-binary-search","name":"Binary search in interactive problems","tier":1500,"order":2,"prereq":["inter-basics","bs-answer"],"summary":"The most common interactive pattern: the hidden object is found by halving the search space with each query. Variants use ternary splits, prefix queries, or need extra care to stay within ceil(log2 n) + c queries.","learn":["Query ranges/prefixes so each answer halves the candidate set","With 20 queries and n = 1e5..1e6, think binary search; with 2 log n think nested or two-phase search","Ternary split (two queries per step dividing by 3) when each query compares two points","Cache previous answers to avoid repeating queries across many sub-searches","Prove the invariant on the candidate interval just like offline binary search"],"resources":[{"title":"USACO Guide: Interactive Problems (Divide and Conquer)","url":"https://usaco.guide/adv/interactive","kind":"usaco","where":"USACO Guide Advanced","minutes":15},{"title":"Interactive Problems: Guide for Participants","url":"https://codeforces.com/blog/entry/45307","kind":"cf-blog","where":"Codeforces blog","minutes":10}],"problems":[{"id":"1807E","src":"cf","name":"Interview","rating":1300,"from":"curated"},{"id":"1999G1","src":"cf","name":"Ruler (easy version)","rating":1500,"from":"curated"},{"id":"1520F1","src":"cf","name":"Guess the K-th Zero (Easy version)","rating":1600,"from":"usaco-guide"},{"id":"1486C1","src":"cf","name":"Guessing the Greatest (easy version)","rating":1600,"from":"curated"},{"id":"1698D","src":"cf","name":"Fixed Point Guessing","rating":1600,"from":"curated"},{"id":"1999G2","src":"cf","name":"Ruler (hard version)","rating":1700,"from":"curated"},{"id":"1486C2","src":"cf","name":"Guessing the Greatest (hard version)","rating":1900,"from":"curated"},{"id":"1697D","src":"cf","name":"Guess The String","rating":1900,"from":"curated"},{"id":"1624F","src":"cf","name":"Interacdive Problem","rating":2000,"from":"curated"},{"id":"1856D","src":"cf","name":"More Wrong","rating":2100,"from":"curated"},{"id":"1363D","src":"cf","name":"Guess The Maximums","rating":2100,"from":"curated"},{"id":"1520F2","src":"cf","name":"Guess the K-th Zero (Hard version)","rating":2200,"from":"curated"}]},{"id":"inter-bits-pairs","name":"Interactive with bit, XOR/AND/OR & pairing queries","tier":1800,"order":3,"prereq":["inter-basics","bit-xor"],"summary":"Queries that return AND/OR/XOR/sum/gcd of hidden values. Typical tricks: a + b = (a ^ b) + 2(a & b) to recover sums, learn bits one by one, find a reference element (zero/max) and query everything against it, or process elements in pairs to save queries.","learn":["Recover a + b from (a & b) and (a | b): a + b = (a & b) + (a | b)","Learn three values from three pairwise sums, then the rest relative to one known value","Find a special element (0, maximum, position of n) first, then use it as a reference","Bit-by-bit queries determine each bit of a hidden number in ~log(max) queries","Pairing/elimination: compare elements in pairs to keep only candidates (tournament style)","Sum of query limits like n + O(1) tells you each element can be queried about once"],"resources":[{"title":"USACO Guide: Interactive and Communication Problems","url":"https://usaco.guide/adv/interactive","kind":"usaco","where":"USACO Guide Advanced","minutes":15},{"title":"Bitwise operations for beginners (Errichto)","url":"https://codeforces.com/blog/entry/73490","kind":"cf-blog","where":"Codeforces blog","minutes":10}],"problems":[{"id":"1543D1","src":"cf","name":"RPD and Rap Sheet (Easy Version)","rating":1700,"from":"curated"},{"id":"1556D","src":"cf","name":"Take a Guess","rating":1800,"from":"usaco-guide"},{"id":"1780D","src":"cf","name":"Bit Guessing Game","rating":1800,"from":"curated"},{"id":"1207E","src":"cf","name":"XOR Guessing","rating":1900,"from":"curated"},{"id":"1088D","src":"cf","name":"Ehab and another another xor problem","rating":2000,"from":"usaco-guide"},{"id":"1451E1","src":"cf","name":"Bitwise Queries (Easy Version)","rating":2000,"from":"curated"},{"id":"1521C","src":"cf","name":"Nastia and a Hidden Permutation","rating":2000,"from":"curated"},{"id":"1634D","src":"cf","name":"Finding Zero","rating":2000,"from":"curated"},{"id":"1762D","src":"cf","name":"GCD Queries ","rating":2100,"from":"curated"},{"id":"1451E2","src":"cf","name":"Bitwise Queries (Hard Version)","rating":2300,"from":"curated"}]}]}]},{"area":"math","topics":[{"id":"math-basics","name":"Math Fundamentals","cfTags":["math"],"subtopics":[{"id":"math-arith-basics","name":"Integer arithmetic, overflow & floor/ceil","tier":800,"order":1,"prereq":[],"summary":"The everyday arithmetic every Div 2/3/4 A-B problem relies on: integer division, remainders, ceiling division, parity and 64-bit overflow. Recognise it when a statement asks for a count or minimum that can be written as a closed formula of the inputs.","learn":["Use long long whenever a product or sum can exceed about 2*10^9; cast before multiplying (1LL*a*b).","Ceiling division for positives: (a+b-1)/b; in C++ '/' truncates toward zero and % can be negative for negative operands.","Parity reasoning: the sum of k odd numbers has the parity of k; many A problems reduce to an even/odd check.","Count multiples of k in [l,r] as r/k-(l-1)/k; the k-th number not divisible by n is a closed formula.","Avoid floating point for exact integer answers: compute integer sqrt with a correction loop, compare a*d vs c*b instead of a/b vs c/d.","Derive a formula on small cases by hand, then double-check edge cases (0, 1, equal values, maximum constraints)."],"resources":[{"title":"CPH: Working with numbers","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 1.3 (p. 6)","minutes":10},{"title":"CPH: Mathematics (sums, sets, logic, functions)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 1.5 (p. 10)","minutes":15}],"problems":[{"id":"1328A","src":"cf","name":"Divisibility Problem","rating":800,"from":"curated"},{"id":"1335A","src":"cf","name":"Candies and Two Sisters","rating":800,"from":"curated"},{"id":"2009A","src":"cf","name":"Minimize!","rating":800,"from":"curated"},{"id":"1374B","src":"cf","name":"Multiply by 2, divide by 6","rating":900,"from":"curated"},{"id":"1343A","src":"cf","name":"Candies","rating":900,"from":"curated"},{"id":"1607B","src":"cf","name":"Odd Grasshopper","rating":900,"from":"curated"},{"id":"1418A","src":"cf","name":"Buying Torches","rating":1000,"from":"curated"},{"id":"1463A","src":"cf","name":"Dungeon","rating":1100,"from":"curated"},{"id":"1352C","src":"cf","name":"K-th Not Divisible by n","rating":1200,"from":"curated"}]},{"id":"math-sums-formulas","name":"Sums, series & closed formulas","tier":1000,"order":2,"prereq":["math-arith-basics"],"summary":"Arithmetic and geometric series, sum of squares, and the habit of turning a loop over a huge range into an O(1) formula. Appears whenever n is up to 10^9-10^18 and the answer is a sum of a regular pattern.","learn":["1+2+...+n = n(n+1)/2; sum of the first k odd numbers is k^2; sum of squares n(n+1)(2n+1)/6.","Geometric series a(r^k-1)/(r-1); sum of powers of two 2^0+...+2^(k-1)=2^k-1.","Minimum/maximum sums of k distinct numbers from [1..n] are prefix/suffix arithmetic series, and every value in between is reachable.","Combine a monotone closed-form sum with binary search when you need the first k reaching a target.","Compute range sums of arithmetic sequences as (first+last)*count/2 and beware overflow of the intermediate product.","Telescoping and pairing tricks (Gauss pairing) simplify many 'sum over a pattern' tasks."],"resources":[{"title":"CPH: Mathematics: sum formulas","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 1.5 (p. 10)","minutes":15}],"problems":[{"id":"cses-3406","src":"cses","name":"Triangle Number Sums","from":"curated"},{"id":"1985B","src":"cf","name":"Maximum Multiple Sum","rating":800,"from":"curated"},{"id":"1878C","src":"cf","name":"Vasilije in Cacak","rating":900,"from":"curated"},{"id":"1353C","src":"cf","name":"Board Moves","rating":1000,"from":"curated"},{"id":"1327A","src":"cf","name":"Sum of Odd Integers","rating":1100,"from":"curated"},{"id":"1872D","src":"cf","name":"Plus Minus Permutation","rating":1200,"from":"curated"},{"id":"1612C","src":"cf","name":"Chat Ban","rating":1300,"from":"curated"},{"id":"1862D","src":"cf","name":"Ice Cream Balls","rating":1300,"from":"curated"}]},{"id":"math-digits-bases","name":"Digits & number bases","tier":1000,"order":3,"prereq":["math-arith-basics"],"summary":"Manipulating decimal digits and representations in base k (including binary): digit sums, round numbers, repunits, counting how digits change. Recognise it when a property is stated in terms of the decimal/binary representation of a number.","learn":["Extract digits with n%10 and n/=10; the number of digits of n is floor(log10 n)+1 but compute it with integer loops.","A number written in base k with digits 0/1 corresponds to a subset of powers of k (bitmask of the index).","Repunits 11...1 and 'numbers of identical digits' can be enumerated directly (only 9*18 such numbers below 10^18).","Large numbers of 11, 111, ... can be reduced: any representation only needs 11 and 111 (since 1111 = 11*101).","Count digit changes when incrementing from l to r by summing r/10^i - l/10^i over i.","Divisibility rules: by 3/9 via digit sum, by 2/5/10 via last digit, by 4/25 via last two digits."],"resources":[{"title":"CPH: Working with numbers","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 1.3 (p. 6)","minutes":10}],"problems":[{"id":"1352A","src":"cf","name":"Sum of Round Numbers","rating":800,"from":"curated"},{"id":"1520B","src":"cf","name":"Ordinary Numbers","rating":800,"from":"curated"},{"id":"1266A","src":"cf","name":"Competitive Programmer","rating":1000,"from":"curated"},{"id":"1594B","src":"cf","name":"Special Numbers","rating":1100,"from":"curated"},{"id":"1526B","src":"cf","name":"I Hate 1111","rating":1400,"from":"curated"},{"id":"1538F","src":"cf","name":"Interesting Function","rating":1500,"from":"curated"}]}]},{"id":"number-theory","name":"Number Theory","cfTags":["number theory","chinese remainder theorem","math"],"subtopics":[{"id":"nt-divisibility","name":"Divisibility & divisors in O(√n)","tier":1000,"order":1,"prereq":["math-arith-basics"],"summary":"Divisors come in pairs (d, n/d), so all divisors of n can be enumerated in O(√n). This is the first tool for problems like 'find the smallest/largest divisor', 'split n into factors' or 'minimum packages of equal size'.","learn":["Loop d from 1 while d*d<=n; if n%d==0 record d and n/d (avoid recording the square root twice).","The smallest divisor >1 of n is prime; the largest proper divisor is n / smallest prime factor.","A number has an odd divisor >1 iff it is not a power of two.","The number of divisors of n<=10^9 is at most 1344, of n<=10^18 at most 103680, so iterating over divisors is usually cheap.","To check divisibility of a product without overflow, reduce factors with gcd first.","Reconstruct n from its full divisor list: n = smallest * largest, then verify the list."],"resources":[{"title":"USACO Guide: Divisibility","url":"https://usaco.guide/gold/divisibility","kind":"usaco","where":"USACO Guide Gold","minutes":25},{"title":"CPH: Primes and factors","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 21.1 (p. 197)","minutes":15},{"title":"cp-algorithms: Number of divisors / sum of divisors","url":"https://cp-algorithms.com/algebra/divisors.html","kind":"cpalgo","where":"cp-algorithms","minutes":10}],"problems":[{"id":"cses-1713","src":"cses","name":"Counting Divisors","from":"usaco-guide"},{"id":"1475A","src":"cf","name":"Odd Divisor","rating":900,"from":"curated"},{"id":"1350A","src":"cf","name":"Orac and Factors","rating":900,"from":"curated"},{"id":"1916B","src":"cf","name":"Two Divisors","rating":1000,"from":"curated"},{"id":"1899B","src":"cf","name":"250 Thousand Tons of TNT","rating":1100,"from":"curated"},{"id":"1294C","src":"cf","name":"Product of Three Numbers","rating":1300,"from":"curated"},{"id":"1360D","src":"cf","name":"Buying Shovels","rating":1300,"from":"curated"},{"id":"1372B","src":"cf","name":"Omkar and Last Class of Math","rating":1300,"from":"curated"},{"id":"1203C","src":"cf","name":"Common Divisors","rating":1300,"from":"curated"},{"id":"1165D","src":"cf","name":"Almost All Divisors","rating":1600,"from":"curated"},{"id":"1920C","src":"cf","name":"Partitioning the Array","rating":1600,"from":"curated"},{"id":"1744E2","src":"cf","name":"Divisible Numbers (hard version)","rating":1900,"from":"curated"}]},{"id":"nt-gcd-lcm","name":"GCD, LCM & Euclid's algorithm","tier":1100,"order":2,"prereq":["nt-divisibility"],"summary":"gcd(a,b) via Euclid runs in O(log min(a,b)); lcm(a,b)=a/gcd(a,b)*b. Key identities like gcd(a,b)=gcd(a,b-a) and 'the gcd of a prefix changes at most log times' unlock many Div 2 B-D problems.","learn":["Euclid: gcd(a,b)=gcd(b,a mod b); std::gcd / std::lcm in C++17; compute lcm as a/gcd*b to avoid overflow.","gcd(a+x, b+x) = gcd(a+x, b-a): differences turn 'gcd of shifted array' into a fixed gcd of differences.","gcd(a1..an) can only decrease, and each decrease divides it by at least 2, so prefix gcds take O(log) distinct values.","Reduce ratios a:b by dividing by gcd to use them as hashable keys.","lcm grows fast: when lcm of a set exceeds a bound you can stop early.","gcd(a,b)=1 problems: consecutive integers are coprime; gcd(n, n+1)=1, gcd(n, 2n+1)=1.","Sparse table / segment tree over gcd answers range-gcd queries (gcd is idempotent)."],"resources":[{"title":"USACO Guide: Divisibility (GCD & LCM)","url":"https://usaco.guide/gold/divisibility","kind":"usaco","where":"USACO Guide Gold","minutes":25},{"title":"CPH: Primes and factors: Euclid's algorithm","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 21.1 (p. 197)","minutes":10},{"title":"cp-algorithms: Euclidean algorithm for GCD","url":"https://cp-algorithms.com/algebra/euclid-algorithm.html","kind":"cpalgo","where":"cp-algorithms","minutes":10}],"problems":[{"id":"cses-1081","src":"cses","name":"Common Divisors","from":"usaco-guide"},{"id":"1325A","src":"cf","name":"EhAb AnD gCd","rating":800,"from":"curated"},{"id":"1765M","src":"cf","name":"Minimum LCM","rating":1000,"from":"curated"},{"id":"1511B","src":"cf","name":"GCD Length","rating":1100,"from":"curated"},{"id":"1736B","src":"cf","name":"Playing with GCD","rating":1200,"from":"curated"},{"id":"1285C","src":"cf","name":"Fadi and LCM","rating":1400,"from":"curated"},{"id":"2007C","src":"cf","name":"Dora and C++","rating":1500,"from":"curated"},{"id":"1536C","src":"cf","name":"Diluc and Kaeya","rating":1500,"from":"usaco-guide"},{"id":"1458A","src":"cf","name":"Row GCD","rating":1600,"from":"curated"},{"id":"1349A","src":"cf","name":"Orac and LCM","rating":1600,"from":"usaco-guide"},{"id":"1542C","src":"cf","name":"Strange Function","rating":1600,"from":"curated"},{"id":"1034A","src":"cf","name":"Enlarge GCD","rating":1800,"from":"curated"},{"id":"1848C","src":"cf","name":"Vika and Price Tags","rating":1800,"from":"curated"},{"id":"1547F","src":"cf","name":"Array Stabilization (GCD version)","rating":1900,"from":"curated"},{"id":"1210C","src":"cf","name":"Kamil and Making a Stream","rating":2000,"from":"curated"},{"id":"1967B2","src":"cf","name":"Reverse Card (Hard Version)","rating":2200,"from":"curated"}]},{"id":"nt-primes-sieve","name":"Primes, primality & Sieve of Eratosthenes","tier":1200,"order":3,"prereq":["nt-divisibility"],"summary":"Trial division tests primality in O(√n); the Sieve of Eratosthenes marks all primes up to N in O(N log log N) and the linear sieve also produces smallest prime factors. Recognise it when many numbers up to 10^6-10^7 need prime information.","learn":["Sieve: for each prime p, mark multiples starting at p*p; memory as vector<bool> or bitset for N=10^7.","Linear sieve computes spf[i] (smallest prime factor) and multiplicative functions in O(N).","Prime gaps are small (<~300 below 10^9) so 'next prime >= x' is a short trial-division loop.","Every even number >2 is not prime; Goldbach-style facts (every even number is a sum of two primes in contest ranges) appear in constructive tasks.","Deterministic Miller-Rabin with fixed bases tests 64-bit primality in O(log n) multiplications.","Segmented sieve finds primes in a range [L,R] with R up to 10^12 and R-L up to 10^6."],"resources":[{"title":"USACO Guide: Divisibility (Prime Factorization)","url":"https://usaco.guide/gold/divisibility","kind":"usaco","where":"USACO Guide Gold","minutes":25},{"title":"CPH: Primes and factors: sieve of Eratosthenes","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 21.1 (p. 197)","minutes":15},{"title":"cp-algorithms: Sieve of Eratosthenes","url":"https://cp-algorithms.com/algebra/sieve-of-eratosthenes.html","kind":"cpalgo","where":"cp-algorithms","minutes":15},{"title":"cp-algorithms: Linear Sieve","url":"https://cp-algorithms.com/algebra/prime-sieve-linear.html","kind":"cpalgo","where":"cp-algorithms","minutes":10},{"title":"cp-algorithms: Primality tests (Miller-Rabin)","url":"https://cp-algorithms.com/algebra/primality_tests.html","kind":"cpalgo","where":"cp-algorithms","minutes":15}],"problems":[{"id":"cses-3396","src":"cses","name":"Next Prime","from":"curated"},{"id":"26A","src":"cf","name":"Almost Prime","rating":900,"from":"curated"},{"id":"1238A","src":"cf","name":"Prime Subtraction","rating":900,"from":"curated"},{"id":"1474B","src":"cf","name":"Different Divisors","rating":1000,"from":"curated"},{"id":"2093C","src":"cf","name":"Simple Repetition","rating":1000,"from":"curated"},{"id":"1872C","src":"cf","name":"Non-coprime Split","rating":1100,"from":"curated"},{"id":"1332B","src":"cf","name":"Composite Coloring","rating":1400,"from":"curated"},{"id":"1771C","src":"cf","name":"Hossam and Trainees","rating":1600,"from":"curated"},{"id":"1176D","src":"cf","name":"Recover it!","rating":1800,"from":"curated"},{"id":"1749D","src":"cf","name":"Counting Arrays","rating":1900,"from":"curated"}]},{"id":"nt-factorization","name":"Prime factorization & smallest-prime-factor sieve","tier":1300,"order":4,"prereq":["nt-primes-sieve"],"summary":"Write n = p1^e1 ... pk^ek by trial division (O(√n)) or in O(log n) per query using a precomputed smallest-prime-factor array. Exponent vectors turn products, perfect powers, squares and divisibility questions into simple per-prime arithmetic.","learn":["Trial division up to √n; whatever remains >1 is a prime factor.","With spf[] from a sieve, factorize any x<=N in O(log x) by repeated division.","a divides b iff every prime exponent of a is <= that of b; gcd/lcm take min/max exponents.","Perfect k-th power iff all exponents are divisible by k; reduce exponents mod k to get a canonical 'signature' (square-free part for k=2).","Legendre's formula: the exponent of p in n! is sum floor(n/p^i); trailing zeros of n! in base b use the limiting prime of b.","A number <=10^18 has at most 15 distinct prime factors; <=10^9 at most 9."],"resources":[{"title":"USACO Guide: Divisibility (Prime Factorization)","url":"https://usaco.guide/gold/divisibility","kind":"usaco","where":"USACO Guide Gold","minutes":25},{"title":"CPH: Primes and factors","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 21.1 (p. 197)","minutes":15},{"title":"cp-algorithms: Integer factorization","url":"https://cp-algorithms.com/algebra/factorization.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"1881D","src":"cf","name":"Divide and Equalize","rating":1300,"from":"curated"},{"id":"1444A","src":"cf","name":"Division","rating":1500,"from":"curated"},{"id":"1114C","src":"cf","name":"Trailing Loves (or L'oeufs?)","rating":1700,"from":"curated"},{"id":"1228C","src":"cf","name":"Primes and Multiplication","rating":1700,"from":"curated"},{"id":"1497E1","src":"cf","name":"Square-Free Division (easy version)","rating":1700,"from":"curated"},{"id":"1225D","src":"cf","name":"Power Products","rating":1800,"from":"usaco-guide"},{"id":"1470B","src":"cf","name":"Strange Definition","rating":1900,"from":"curated"},{"id":"1366D","src":"cf","name":"Two Divisors","rating":2000,"from":"curated"}]},{"id":"nt-modular-arithmetic","name":"Modular arithmetic","tier":1200,"order":5,"prereq":["math-arith-basics"],"summary":"Doing all arithmetic modulo m (usually 10^9+7 or 998244353) to keep numbers small, and reasoning about remainders (pairs whose sum is divisible by k, cycles of last digits). Recognise 'print the answer modulo ...' or conditions on divisibility of sums.","learn":["(a+b) mod m, (a-b+m) mod m, (a*b) mod m with 64-bit intermediates; never divide directly under a modulus.","Normalise negatives: ((x % m) + m) % m.","Group numbers by remainder: a+b divisible by k iff r_a + r_b ≡ 0 (mod k); count pairs with a map of remainders.","Pigeonhole: among m+1 numbers two share a remainder mod m, so if n>m the product of differences mod m is 0.","Last digits / remainders under repeated operations become periodic quickly; simulate until the cycle.","Algebraic tricks: multiply both sides by a factor to separate i and j (e.g. (a+b)(a^2+b^2) = (a^4-b^4)/(a-b))."],"resources":[{"title":"USACO Guide: Modular Arithmetic","url":"https://usaco.guide/gold/modular","kind":"usaco","where":"USACO Guide Gold","minutes":25},{"title":"CPH: Modular arithmetic","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 21.2 (p. 201)","minutes":15}],"problems":[{"id":"1931D","src":"cf","name":"Divisible Pairs","rating":1300,"from":"curated"},{"id":"1714E","src":"cf","name":"Add Modulo 10","rating":1400,"from":"curated"},{"id":"1305C","src":"cf","name":"Kuroni and Impossible Calculation","rating":1600,"from":"curated"},{"id":"1514C","src":"cf","name":"Product 1 Modulo N","rating":1600,"from":"usaco-guide"},{"id":"1344A","src":"cf","name":"Hilbert's Hotel","rating":1600,"from":"curated"},{"id":"2033F","src":"cf","name":"Kosuke's Sloth","rating":1800,"from":"curated"},{"id":"1389E","src":"cf","name":"Calendar Ambiguity","rating":2200,"from":"curated"},{"id":"1188B","src":"cf","name":"Count Pairs","rating":2300,"from":"curated"}]},{"id":"nt-binary-exponentiation","name":"Binary (fast) exponentiation","tier":1300,"order":6,"prereq":["nt-modular-arithmetic"],"summary":"Compute a^b mod m in O(log b) by repeated squaring. Needed for counting answers like 2^n or (2^m-1)^n, for modular inverses via Fermat, and as the core of matrix exponentiation.","learn":["Iterative pow: while(b){ if(b&1) r=r*a%m; a=a*a%m; b>>=1; }.","Reduce the base first (a%=m) and use 64-bit (or __int128 when m is ~10^18).","Counting independent binary choices gives powers of 2; choices per item with 'not all empty' give (2^m-1)^n.","The same doubling idea works for any associative operation (matrix multiply, function composition, binary lifting).","Exponent towers need Euler's theorem to reduce the exponent (see Euler phi).","Precompute powers in an array when you need many consecutive powers."],"resources":[{"title":"USACO Guide: Modular Arithmetic (Exponentiation)","url":"https://usaco.guide/gold/modular","kind":"usaco","where":"USACO Guide Gold","minutes":25},{"title":"CPH: Modular arithmetic: modular exponentiation","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 21.2 (p. 201)","minutes":10},{"title":"cp-algorithms: Binary Exponentiation","url":"https://cp-algorithms.com/algebra/binary-exp.html","kind":"cpalgo","where":"cp-algorithms","minutes":15}],"problems":[{"id":"cses-1095","src":"cses","name":"Exponentiation","from":"usaco-guide"},{"id":"185A","src":"cf","name":"Plant","rating":1300,"from":"curated"},{"id":"1594E1","src":"cf","name":"Rubik's Cube Coloring (easy version)","rating":1300,"from":"curated"},{"id":"1866B","src":"cf","name":"Battling with Numbers","rating":1400,"from":"curated"},{"id":"1236B","src":"cf","name":"Alice and the List of Presents","rating":1500,"from":"curated"},{"id":"1985G","src":"cf","name":"D-Function","rating":1600,"from":"curated"},{"id":"1557C","src":"cf","name":"Moamen and XOR","rating":1700,"from":"curated"},{"id":"1228C","src":"cf","name":"Primes and Multiplication","rating":1700,"from":"curated"}]},{"id":"nt-modular-inverse","name":"Modular inverse & division mod p","tier":1400,"order":7,"prereq":["nt-binary-exponentiation"],"summary":"x^{-1} mod p exists when gcd(x,p)=1; for prime p it equals x^{p-2} (Fermat). This is how fractions, expected values and binomial coefficients are output 'modulo 998244353'.","learn":["For prime p: inv(x)=pow(x,p-2,p); for general m use extended Euclid (requires gcd(x,m)=1).","A fraction P/Q is printed as P*Q^{-1} mod p; add/multiply fractions directly in modular form.","Inverses of 1..n in O(n): inv[i] = -(p/i) * inv[p%i] mod p.","Inverse factorials: invfact[n]=pow(fact[n],p-2), then invfact[i-1]=invfact[i]*i.","Never take the inverse of a value that may be ≡0 mod p (e.g. n>=p in n!).","Division by 2 mod p is multiplication by (p+1)/2."],"resources":[{"title":"USACO Guide: Modular Arithmetic (Modular Inverse)","url":"https://usaco.guide/gold/modular","kind":"usaco","where":"USACO Guide Gold","minutes":25},{"title":"CPH: Modular arithmetic: modular inverse","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 21.2 (p. 201)","minutes":10},{"title":"cp-algorithms: Modular Multiplicative Inverse","url":"https://cp-algorithms.com/algebra/module-inverse.html","kind":"cpalgo","where":"cp-algorithms","minutes":15}],"problems":[{"id":"2008F","src":"cf","name":"Sakurako's Box","rating":1400,"from":"curated"},{"id":"1569C","src":"cf","name":"Jury Meeting","rating":1500,"from":"curated"},{"id":"1452D","src":"cf","name":"Radio Towers","rating":1600,"from":"curated"},{"id":"1279D","src":"cf","name":"Santa's Bot","rating":1700,"from":"usaco-guide"},{"id":"1312D","src":"cf","name":"Count the Arrays","rating":1700,"from":"curated"}]},{"id":"nt-harmonic-sieve","name":"Harmonic loops over multiples (n/1+n/2+...)","tier":1600,"order":8,"prereq":["nt-divisibility"],"summary":"Iterating, for every d, over all multiples of d costs n/1+n/2+...+n/n = O(n log n). It powers 'for every value, look at its multiples/divisors' DP and gcd counting on value-indexed arrays.","learn":["for(d=1;d<=n;d++) for(m=d;m<=n;m+=d) ... runs in O(n log n); use it to build divisor lists for all numbers up to n.","Count, for each g, how many array values are multiples of g using a frequency array (cnt[g] = sum of freq of multiples).","Longest chain where each element divides the next: dp over values pushing to multiples.","'Is g achievable as a gcd of a subset?' check gcd of all present multiples of g equals g.","Combine with going from large g to small to subtract over-counting (preparation for Möbius).","Minimum lcm pair: for each g, take the two smallest present multiples of g."],"resources":[{"title":"USACO Guide: Divisibility","url":"https://usaco.guide/gold/divisibility","kind":"usaco","where":"USACO Guide Gold","minutes":25},{"title":"CPH: Primes and factors (sum of divisors, harmonic bounds)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 21.1 (p. 197)","minutes":10}],"problems":[{"id":"1350B","src":"cf","name":"Orac and Models","rating":1400,"from":"curated"},{"id":"1627D","src":"cf","name":"Not Adding","rating":1900,"from":"curated"},{"id":"1475G","src":"cf","name":"Strange Beauty","rating":1900,"from":"curated"},{"id":"1884D","src":"cf","name":"Counting Rhyme","rating":2100,"from":"curated"},{"id":"1154G","src":"cf","name":"Minimum Possible LCM","rating":2200,"from":"curated"},{"id":"1646E","src":"cf","name":"Power Board","rating":2200,"from":"curated"}]},{"id":"nt-divisor-functions","name":"Divisor functions & multiplicative functions","tier":1700,"order":9,"prereq":["nt-factorization","nt-harmonic-sieve"],"summary":"From n = ∏ p^e you get τ(n)=∏(e+1), σ(n)=∏(p^{e+1}-1)/(p-1) and the product of divisors. Multiplicative functions (f(ab)=f(a)f(b) for coprime a,b) can be sieved for all n<=N.","learn":["Number of divisors τ(n)=∏(e_i+1); sum of divisors σ(n)=∏(1+p+...+p^e).","Product of divisors = n^{τ(n)/2}; reduce the exponent mod p-1 when working modulo a prime p.","Multiplicative functions (τ, σ, φ, μ, ω-related) can be computed for all n<=N by the linear sieve.","Count distinct prime factors ω(n) for all n with a sieve; 2^{ω(n)} counts coprime ordered factor pairs.","Sum of τ(i) or σ(i) over i<=N via sum over d of floor(N/d) (and d*floor(N/d)).","DP over divisors of values (dp[d] over multiples) for maximizing sums of prefix gcds."],"resources":[{"title":"USACO Guide: Divisibility (Counting Divisors)","url":"https://usaco.guide/gold/divisibility","kind":"usaco","where":"USACO Guide Gold","minutes":25},{"title":"USACO Guide: Prefix Sums of Number-Theoretic Functions (Part 1)","url":"https://usaco.guide/adv/prefix-sums-nt-1","kind":"usaco","where":"USACO Guide Advanced","minutes":40},{"title":"CPH: Primes and factors: number and sum of factors","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 21.1 (p. 197)","minutes":10},{"title":"cp-algorithms: Number of divisors / sum of divisors","url":"https://cp-algorithms.com/algebra/divisors.html","kind":"cpalgo","where":"cp-algorithms","minutes":10}],"problems":[{"id":"cses-1082","src":"cses","name":"Sum of Divisors","from":"usaco-guide"},{"id":"cses-2182","src":"cses","name":"Divisor Analysis","from":"usaco-guide"},{"id":"236B","src":"cf","name":"Easy Number Challenge","rating":1300,"from":"curated"},{"id":"1528B","src":"cf","name":"Kavi on Pairing Duty","rating":1700,"from":"curated"},{"id":"1512G","src":"cf","name":"Short Task","rating":1700,"from":"curated"},{"id":"1499D","src":"cf","name":"The Number of Pairs","rating":2100,"from":"usaco-guide"},{"id":"1614D1","src":"cf","name":"Divan and Kostomuksha (easy version)","rating":2100,"from":"curated"},{"id":"1614D2","src":"cf","name":"Divan and Kostomuksha (hard version)","rating":2300,"from":"curated"},{"id":"1792E","src":"cf","name":"Divisors and Table","rating":2400,"from":"curated"}]},{"id":"nt-euler-phi","name":"Euler's totient, Fermat & Euler's theorem","tier":1700,"order":10,"prereq":["nt-factorization","nt-modular-inverse"],"summary":"φ(n) counts 1<=k<=n with gcd(k,n)=1, computed from the factorization as n∏(1-1/p). Euler's theorem a^φ(m) ≡ 1 (mod m) (Fermat for primes) lets you reduce huge exponents and explains periodicity of powers.","learn":["φ(n)=n∏(1-1/p) over distinct primes p|n; sieve φ for all n<=N in O(N log log N).","Number of k in [0,m) with gcd(a+k, m) = gcd(a,m) is φ(m/gcd(a,m)).","Fermat: a^{p-1} ≡ 1 mod p for prime p not dividing a, so exponents reduce mod p-1 (CSES Exponentiation II).","Generalised Euler: for e >= log2 m, a^e ≡ a^{(e mod φ(m)) + φ(m)} (mod m) even if gcd(a,m)≠1 (power towers).","Σ_{d|n} φ(d) = n, a frequent identity for gcd sums: Σ_i gcd(i,n) = Σ_{d|n} d·φ(n/d).","Exponents of a recurrence of products (f_n = f_{n-1}f_{n-2}...) live modulo p-1 and are found with matrix power."],"resources":[{"title":"USACO Guide: Divisibility (Euler's Totient Function)","url":"https://usaco.guide/gold/divisibility","kind":"usaco","where":"USACO Guide Gold","minutes":25},{"title":"CPH: Modular arithmetic: Euler's theorem","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 21.2 (p. 201)","minutes":10},{"title":"cp-algorithms: Euler's totient function","url":"https://cp-algorithms.com/algebra/phi-function.html","kind":"cpalgo","where":"cp-algorithms","minutes":15}],"problems":[{"id":"cses-1712","src":"cses","name":"Exponentiation II","from":"usaco-guide"},{"id":"1295D","src":"cf","name":"Same GCDs","rating":1800,"from":"curated"},{"id":"919E","src":"cf","name":"Congruence Equation","rating":2100,"from":"curated"},{"id":"776E","src":"cf","name":"The Holmes Children","rating":2100,"from":"curated"},{"id":"1717E","src":"cf","name":"Madoka and The Best University","rating":2200,"from":"curated"},{"id":"1182E","src":"cf","name":"Product Oriented Recurrence","rating":2300,"from":"curated"},{"id":"906D","src":"cf","name":"Power Tower","rating":2700,"from":"usaco-guide"}]},{"id":"nt-ext-euclid","name":"Extended Euclid & linear Diophantine equations","tier":1800,"order":11,"prereq":["nt-gcd-lcm"],"summary":"Extended Euclid finds x,y with ax+by=gcd(a,b). It solves ax+by=c (solvable iff gcd|c), gives modular inverses modulo non-primes, and solves linear congruences ax ≡ b (mod m).","learn":["Recursive ext_gcd returns g and (x,y); all solutions: x+k·b/g, y-k·a/g.","ax+by=c has integer solutions iff gcd(a,b) divides c; scale the base solution by c/g.","To find non-negative or minimal solutions, shift k so that x is in [0, b/g).","If x+y should be small with a,b positive, brute force over one variable up to the other coefficient (bounded by b/g).","Linear congruence ax ≡ b (mod m): divide by g=gcd(a,m) (needs g|b), then multiply by the inverse of a/g mod m/g.","Watch overflow: coefficients can reach ~10^18; use __int128 for products.","Frobenius / Chicken McNugget: for coprime a,b>0 every integer > ab-a-b is a non-negative combination of a and b; ab-a-b itself is not."],"resources":[{"title":"USACO Guide: Extended Euclidean Algorithm","url":"https://usaco.guide/adv/extend-euclid","kind":"usaco","where":"USACO Guide Advanced","minutes":30},{"title":"CPH: Solving equations: Diophantine equations","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 21.3 (p. 204)","minutes":10},{"title":"cp-algorithms: Extended Euclidean Algorithm","url":"https://cp-algorithms.com/algebra/extended-euclid-algorithm.html","kind":"cpalgo","where":"cp-algorithms","minutes":15},{"title":"cp-algorithms: Linear Diophantine Equation","url":"https://cp-algorithms.com/algebra/linear-diophantine-equation.html","kind":"cpalgo","where":"cp-algorithms","minutes":20},{"title":"cp-algorithms: Linear Congruence Equation","url":"https://cp-algorithms.com/algebra/linear_congruence_equation.html","kind":"cpalgo","where":"cp-algorithms","minutes":10}],"problems":[{"id":"633A","src":"cf","name":"Ebony and Ivory","rating":1100,"from":"curated"},{"id":"7C","src":"cf","name":"Line","rating":1800,"from":"curated"},{"id":"1244C","src":"cf","name":"The Football Season","rating":2000,"from":"curated"},{"id":"1748D","src":"cf","name":"ConstructOR","rating":2100,"from":"curated"},{"id":"982E","src":"cf","name":"Billiard","rating":2600,"from":"curated"}]},{"id":"nt-crt","name":"Chinese Remainder Theorem","tier":2000,"order":12,"prereq":["nt-ext-euclid"],"summary":"A system x ≡ a_i (mod m_i) with pairwise coprime moduli has a unique solution modulo ∏m_i; with general moduli it is merged pairwise via extended Euclid. Appears with periodic events, interactive 'guess x' tasks and with knowing x mod several small numbers.","learn":["Merge two congruences x≡a1 (mod m1), x≡a2 (mod m2): solvable iff a1≡a2 (mod gcd); new modulus lcm(m1,m2).","Knowing x mod m_i for all i determines x mod lcm(m_i); a modulus k is determined iff k | lcm(m_i).","Interactive: learn x modulo several small coprime numbers (e.g. via gcd queries) and combine.","Periodic coincidences of two cycles of lengths n and m repeat every lcm(n,m); count them per residue class with CRT.","Pigeonhole over small primes: if for prime p every residue class is used twice, no shift works (Koxia).","Garner's algorithm reconstructs big numbers from residues modulo several primes."],"resources":[{"title":"USACO Guide: Extended Euclidean Algorithm (Chinese Remainder Theorem)","url":"https://usaco.guide/adv/extend-euclid","kind":"usaco","where":"USACO Guide Advanced","minutes":30},{"title":"CPH: Solving equations: Chinese remainder theorem","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 21.3 (p. 204)","minutes":10},{"title":"cp-algorithms: Chinese Remainder Theorem","url":"https://cp-algorithms.com/algebra/chinese-remainder-theorem.html","kind":"cpalgo","where":"cp-algorithms","minutes":15}],"problems":[{"id":"1770C","src":"cf","name":"Koxia and Number Theory","rating":1700,"from":"curated"},{"id":"687B","src":"cf","name":"Remainders Game","rating":1800,"from":"curated"},{"id":"1665D","src":"cf","name":"GCD Guess","rating":2000,"from":"curated"},{"id":"919E","src":"cf","name":"Congruence Equation","rating":2100,"from":"curated"},{"id":"1500B","src":"cf","name":"Two chandeliers","rating":2200,"from":"curated"},{"id":"1993F1","src":"cf","name":"Dyn-scripted Robot (Easy Version)","rating":2400,"from":"curated"},{"id":"338D","src":"cf","name":"GCD Table","rating":2900,"from":"curated"}]},{"id":"nt-floor-blocks","name":"Floor-division blocks (O(√n) distinct quotients)","tier":1700,"order":13,"prereq":["nt-harmonic-sieve"],"summary":"floor(n/i) takes only O(√n) distinct values, and all i with the same quotient form a contiguous block [l, n/(n/l)]. This turns sums like Σ f(floor(n/i)) or Σ n mod i into O(√n) loops.","learn":["Iterate blocks: for(l=1;l<=n;l=r+1){ q=n/l; r=n/q; ... }.","n mod i = n - i·floor(n/i), so Σ n mod i is computed block by block with arithmetic series.","For a fixed quotient q, the i with floor(n/i)=q are in [n/(q+1)+1, n/q].","DP of the form dp[x] = Σ_z dp[floor(x/z)] is sped up by grouping equal quotients or by pushing contributions to multiples ranges.","Conditions like floor(a/b) = a mod b reduce to a = k(b+1) with k<b; count pairs with block sums.","Combine with Möbius prefix sums for Σ_{i<=n} Σ_{j<=m} [gcd(i,j)=1] (iterate blocks where both n/i and m/i are constant: r=min(n/(n/l), m/(m/l))).","Σ_{i<n} floor((a·i+b)/c) has an O(log) Euclid-like algorithm (floor_sum, as in AtCoder Library) for when even O(√n) is too slow."],"resources":[{"title":"USACO Guide: Prefix Sums of Number-Theoretic Functions (Part 1)","url":"https://usaco.guide/adv/prefix-sums-nt-1","kind":"usaco","where":"USACO Guide Advanced","minutes":40},{"title":"CPH: Primes and factors (sum of factors over ranges)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 21.1 (p. 197)","minutes":10}],"problems":[{"id":"1263C","src":"cf","name":"Everyone is a Winner!","rating":1400,"from":"curated"},{"id":"1485C","src":"cf","name":"Floor and Mod","rating":1700,"from":"curated"},{"id":"1558B","src":"cf","name":"Up the Strip","rating":1900,"from":"curated"},{"id":"616E","src":"cf","name":"Sum of Remainders","rating":2200,"from":"curated"},{"id":"1954E","src":"cf","name":"Chain Reaction","rating":2200,"from":"curated"},{"id":"830C","src":"cf","name":"Bamboo Partition","rating":2300,"from":"curated"},{"id":"1780E","src":"cf","name":"Josuke and Complete Graph","rating":2400,"from":"curated"},{"id":"1603D","src":"cf","name":"Artistic Partition","rating":3000,"from":"curated"}]},{"id":"nt-mobius","name":"Möbius function & inversion (gcd counting)","tier":2100,"order":14,"prereq":["nt-divisor-functions","comb-pie"],"summary":"μ(n) is 0 if n has a squared prime factor, otherwise (-1)^{#primes}. Σ_{d|n} μ(d) = [n=1] lets you count coprime pairs/subsets and pairs with gcd exactly g by inclusion–exclusion over divisors.","learn":["[gcd = 1] = Σ_{d | gcd} μ(d): count coprime pairs as Σ_d μ(d)·C(cnt_d, 2).","Number of non-empty subsets with gcd 1: Σ_d μ(d)(2^{cnt_d}-1) where cnt_d = number of multiples of d.","'Exactly g' from 'divisible by g': f(g) = F(g) - Σ_{k>=2} f(kg), computed from large to small (a Möbius inversion without μ).","Sieve μ with the linear sieve; only square-free d matter.","Möbius inversion: if F(n) = Σ_{d|n} f(d) then f(n) = Σ_{d|n} μ(d) F(n/d).","Dirichlet convolution view: μ * 1 = ε, φ * 1 = id; combine with floor blocks for large n.","For n up to 10^10-10^11, prefix sums of μ or φ come from Dirichlet hyperbola / Du's sieve in about O(n^{2/3}) (advanced)."],"resources":[{"title":"USACO Guide: Inclusion-Exclusion Principle (Möbius Function)","url":"https://usaco.guide/plat/PIE","kind":"usaco","where":"USACO Guide Platinum","minutes":30},{"title":"USACO Guide: Prefix Sums of Number-Theoretic Functions (Dirichlet convolution)","url":"https://usaco.guide/adv/prefix-sums-nt-1","kind":"usaco","where":"USACO Guide Advanced","minutes":40},{"title":"[Tutorial] Math note — Möbius inversion","url":"https://codeforces.com/blog/entry/53925","kind":"cf-blog","where":"Codeforces blog","minutes":30},{"title":"[Tutorial] Math note — Dirichlet convolution","url":"https://codeforces.com/blog/entry/54150","kind":"cf-blog","where":"Codeforces blog","minutes":30}],"problems":[{"id":"cses-2417","src":"cses","name":"Counting Coprime Pairs","from":"usaco-guide"},{"id":"803F","src":"cf","name":"Coprime Subsequences","rating":2000,"from":"curated"},{"id":"900D","src":"cf","name":"Unusual Sequences","rating":2000,"from":"curated"},{"id":"839D","src":"cf","name":"Winter is here","rating":2200,"from":"curated"},{"id":"1559E","src":"cf","name":"Mocha and Stars","rating":2200,"from":"curated"},{"id":"547C","src":"cf","name":"Mike and Foam","rating":2300,"from":"curated"},{"id":"915G","src":"cf","name":"Coprime Arrays","rating":2300,"from":"curated"},{"id":"1097F","src":"cf","name":"Alex and a TV Show","rating":2500,"from":"curated"}]},{"id":"nt-discrete-log","name":"Primitive roots & discrete logarithm (BSGS)","tier":2400,"order":15,"prereq":["nt-euler-phi","nt-ext-euclid"],"summary":"A primitive root g mod p generates all non-zero residues, so multiplication becomes addition of exponents. Baby-step giant-step solves a^x ≡ b (mod m) in O(√m). Rare but appears in recurrences of products and 'k-th root mod p' tasks.","learn":["Primitive root of prime p: test candidates g with g^{(p-1)/q} ≠ 1 for every prime q | p-1.","BSGS: write x = i·k - j with k≈√m, store a^j·b in a hash map, scan a^{ik}.","Taking logs base a primitive root converts x^k ≡ b into k·y ≡ log b (mod p-1), a linear congruence.","Multiplicative recurrences f_n = ∏ f_{n-i}^{c_i} become linear recurrences on exponents mod p-1 (matrix power).","Pollard's rho with Miller–Rabin factorizes 64-bit numbers in about O(n^{1/4}) when trial division is too slow.","Discrete root / Tonelli–Shanks for modular square roots are the same toolbox."],"resources":[{"title":"cp-algorithms: Discrete Logarithm","url":"https://cp-algorithms.com/algebra/discrete-log.html","kind":"cpalgo","where":"cp-algorithms","minutes":20},{"title":"cp-algorithms: Primitive Root","url":"https://cp-algorithms.com/algebra/primitive-root.html","kind":"cpalgo","where":"cp-algorithms","minutes":15},{"title":"cp-algorithms: Discrete Root","url":"https://cp-algorithms.com/algebra/discrete-root.html","kind":"cpalgo","where":"cp-algorithms","minutes":15},{"title":"CPH: Other results (Fermat, Wilson, ...)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 21.4 (p. 205)","minutes":5}],"problems":[{"id":"1182E","src":"cf","name":"Product Oriented Recurrence","rating":2300,"from":"curated"},{"id":"1106F","src":"cf","name":"Lunar New Year and a Recursive Sequence","rating":2400,"from":"curated"}]}]},{"id":"combinatorics","name":"Combinatorics","cfTags":["combinatorics","math"],"subtopics":[{"id":"comb-counting-basics","name":"Counting principles (sum & product rules)","tier":1000,"order":1,"prereq":["math-arith-basics"],"summary":"Rule of sum, rule of product, counting pairs with a frequency map, and complementary counting. Most early 'count the number of ...' problems need nothing more, but the counts must be organised to avoid O(n^2).","learn":["Product rule: independent choices multiply; sum rule: disjoint cases add.","Count pairs i<j with equal key as Σ C(cnt,2) using a map; pairs with different keys as total minus equal.","Complementary counting: count the bad configurations and subtract from all.","Count substrings of allowed characters as Σ len·(len+1)/2 over maximal blocks.","Count unordered pairs from two groups as |A|·|B| minus conflicting pairs (inclusion–exclusion lite).","Arranging n people in circles: divide by rotations (n-1)!/... for circular arrangements."],"resources":[{"title":"USACO Guide: Combinatorics","url":"https://usaco.guide/gold/combo","kind":"usaco","where":"USACO Guide Gold","minutes":30},{"title":"CPH: Combinatorics (introduction)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 22 (p. 207)","minutes":10}],"problems":[{"id":"1840B","src":"cf","name":"Binary Cafe","rating":1100,"from":"curated"},{"id":"1272C","src":"cf","name":"Yet Another Broken Keyboard","rating":1200,"from":"curated"},{"id":"1985E","src":"cf","name":"Secret Box","rating":1200,"from":"curated"},{"id":"1922B","src":"cf","name":"Forming Triangles","rating":1200,"from":"curated"},{"id":"1328B","src":"cf","name":"K-th Beautiful String","rating":1300,"from":"curated"},{"id":"1326C","src":"cf","name":"Permutation Partitions","rating":1300,"from":"curated"},{"id":"1433E","src":"cf","name":"Two Round Dances","rating":1300,"from":"curated"},{"id":"1475C","src":"cf","name":"Ball in Berland","rating":1400,"from":"curated"},{"id":"1215B","src":"cf","name":"The Number of Products","rating":1400,"from":"curated"}]},{"id":"comb-binomial","name":"Binomial coefficients & factorials mod p","tier":1400,"order":2,"prereq":["comb-counting-basics","nt-modular-inverse"],"summary":"C(n,k) counts k-subsets. Precompute factorials and inverse factorials mod p in O(n) to answer each C(n,k) in O(1); use Pascal's triangle for small n or non-prime modulus. Lucas's theorem handles C(n,k) mod a small prime.","learn":["Precompute fact[0..N], invfact[0..N] once; C(n,k)=fact[n]·invfact[k]·invfact[n-k], 0 if k<0 or k>n.","When n is huge but k is small, compute C(n,k) = n(n-1)...(n-k+1)/k! directly in O(k).","Pascal: C(n,k)=C(n-1,k-1)+C(n-1,k), O(n^2) table, works for any modulus.","Identities: Σ_k C(n,k)=2^n, hockey stick Σ_{i} C(i,k)=C(n+1,k+1), Vandermonde Σ C(a,i)C(b,k-i)=C(a+b,k).","Multinomial n!/(c1!c2!...) counts arrangements of a multiset (distinct strings from letters).","Fix the element in a special role (the median, the minimum) and choose the rest with binomials.","Lucas: C(n,k) mod p = ∏ C(n_i,k_i) over base-p digits; C(n,k) is odd iff k & n == k (Xor Pyramid)."],"resources":[{"title":"USACO Guide: Combinatorics (Binomial Coefficients)","url":"https://usaco.guide/gold/combo","kind":"usaco","where":"USACO Guide Gold","minutes":30},{"title":"CPH: Binomial coefficients","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 22.1 (p. 208)","minutes":15},{"title":"cp-algorithms: Binomial Coefficients","url":"https://cp-algorithms.com/combinatorics/binomial-coefficients.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"cses-1079","src":"cses","name":"Binomial Coefficients","from":"usaco-guide"},{"id":"cses-1715","src":"cses","name":"Creating Strings II","from":"usaco-guide"},{"id":"cses-2419","src":"cses","name":"Xor Pyramid Peak","from":"usaco-guide"},{"id":"cses-3194","src":"cses","name":"Xor Pyramid Diagonal","from":"curated"},{"id":"cses-3195","src":"cses","name":"Xor Pyramid Row","from":"curated"},{"id":"1081C","src":"cf","name":"Colorful Bricks","rating":1500,"from":"curated"},{"id":"1999F","src":"cf","name":"Expected Median","rating":1500,"from":"curated"},{"id":"553A","src":"cf","name":"Kyoya and Colored Balls","rating":1500,"from":"curated"},{"id":"1795D","src":"cf","name":"Triangle Coloring","rating":1600,"from":"curated"},{"id":"1475E","src":"cf","name":"Advertising Agency","rating":1600,"from":"curated"},{"id":"1462E2","src":"cf","name":"Close Tuples (hard version)","rating":1700,"from":"usaco-guide"},{"id":"1420D","src":"cf","name":"Rescue Nibel!","rating":1800,"from":"curated"},{"id":"1359E","src":"cf","name":"Modular Stability","rating":2000,"from":"curated"},{"id":"1696E","src":"cf","name":"Placing Jinas","rating":2000,"from":"curated"},{"id":"1334E","src":"cf","name":"Divisor Paths","rating":2200,"from":"curated"}]},{"id":"comb-stars-bars","name":"Stars and bars & distributions","tier":1600,"order":3,"prereq":["comb-binomial"],"summary":"The number of ways to write n as an ordered sum of k non-negative integers is C(n+k-1, k-1); with positive parts C(n-1,k-1). Also counts non-decreasing sequences and multisets.","learn":["n identical balls into k distinct boxes: C(n+k-1,k-1); each box >=1: C(n-1,k-1).","Non-decreasing sequences of length m with values in [1,n] are multisets: C(n+m-1,m).","Lower bounds: subtract them first; upper bounds: use inclusion–exclusion over violated boxes.","Group indistinguishable objects (pairs of adjacent pawns) and place them among free cells: C(free+groups, groups).","Combine two monotone arrays into one longer monotone sequence to reduce to a single stars-and-bars count.","Generating-function view: coefficient of x^n in (1-x)^{-k}."],"resources":[{"title":"USACO Guide: Combinatorics (Stars and Bars)","url":"https://usaco.guide/gold/combo","kind":"usaco","where":"USACO Guide Gold","minutes":30},{"title":"CPH: Binomial coefficients: boxes and balls","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 22.1 (p. 208)","minutes":10},{"title":"cp-algorithms: Stars and bars","url":"https://cp-algorithms.com/combinatorics/stars_and_bars.html","kind":"cpalgo","where":"cp-algorithms","minutes":10}],"problems":[{"id":"cses-1716","src":"cses","name":"Distributing Apples","from":"usaco-guide"},{"id":"1288C","src":"cf","name":"Two Arrays","rating":1600,"from":"curated"},{"id":"1545B","src":"cf","name":"AquaMoon and Chess","rating":1900,"from":"curated"},{"id":"1931G","src":"cf","name":"One-Dimensional Puzzle","rating":2000,"from":"curated"},{"id":"2060F","src":"cf","name":"Multiplicative Arrays","rating":2200,"from":"curated"},{"id":"1929F","src":"cf","name":"Sasha and the Wedding Binary Search Tree","rating":2300,"from":"usaco-guide"},{"id":"451E","src":"cf","name":"Devu and Flowers","rating":2300,"from":"curated"}]},{"id":"comb-contribution","name":"Contribution technique (sum over all pairs/subsets)","tier":1400,"order":4,"prereq":["comb-counting-basics"],"summary":"Instead of enumerating all subarrays, pairs, paths or subsets, compute how much each element (or edge, or bit) contributes to the total and sum those contributions. A core trick behind 'sum over all ...' problems.","learn":["Element a[i] lies in i·(n-i+1) subarrays (1-indexed); weight it accordingly.","Sum of |x_i - x_j| over pairs: sort and add x_i·(2i-n-1).","Edge (u,v) of a tree lies on size·(n-size) paths.","Bitwise sums: handle each bit separately and count pairs/subarrays where the bit is set.","Sorted-order arguments: after sorting, each element's role (max/min/median) is determined by its position.","Sum over all 2^n subsets: an element appears in 2^{n-1} of them."],"resources":[{"title":"USACO Guide: Combinatorics","url":"https://usaco.guide/gold/combo","kind":"usaco","where":"USACO Guide Gold","minutes":30},{"title":"CPH: Binomial coefficients (counting arguments)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 22.1 (p. 208)","minutes":10}],"problems":[{"id":"2000E","src":"cf","name":"Photoshoot for Gorillas","rating":1400,"from":"curated"},{"id":"1648A","src":"cf","name":"Weird Sum","rating":1400,"from":"curated"},{"id":"1996E","src":"cf","name":"Decode","rating":1600,"from":"curated"},{"id":"1879D","src":"cf","name":"Sum of XOR Functions","rating":1700,"from":"usaco-guide"},{"id":"1422C","src":"cf","name":"Bargain","rating":1700,"from":"curated"},{"id":"1401D","src":"cf","name":"Maximum Distributed Tree","rating":1800,"from":"curated"},{"id":"1327E","src":"cf","name":"Count The Blocks","rating":1800,"from":"curated"},{"id":"1400D","src":"cf","name":"Zigzags","rating":1900,"from":"curated"},{"id":"1444B","src":"cf","name":"Divide and Sum","rating":1900,"from":"curated"},{"id":"1009E","src":"cf","name":"Intercity Travelling","rating":2000,"from":"curated"},{"id":"1467D","src":"cf","name":"Sum of Paths","rating":2200,"from":"curated"}]},{"id":"comb-pie","name":"Inclusion–exclusion principle","tier":1800,"order":5,"prereq":["comb-binomial"],"summary":"|A1∪...∪An| = Σ|Ai| - Σ|Ai∩Aj| + ... . Used to count objects avoiding all 'bad' properties: integers coprime to a set of primes, permutations with no bad positions, grids with constraints in every row/column.","learn":["Iterate over subsets of the bad properties with sign (-1)^{|S|}; feasible when the number of properties is small (≤20) or symmetric.","Symmetric case: Σ_k (-1)^k C(m,k)·f(k) where f(k) counts objects violating k fixed properties.","Count numbers ≤n divisible by none of k primes with 2^k subsets of products (stop when the product exceeds n).","Upper bounds in stars and bars: subtract boxes that exceed their capacity via PIE.","Count gcd(b_i, b_{i-1}) constraints: factorize the ratio and use PIE over its distinct primes.","Grids with 'every row and column has a minimum': PIE over rows (and columns) that violate."],"resources":[{"title":"USACO Guide: Inclusion-Exclusion Principle","url":"https://usaco.guide/plat/PIE","kind":"usaco","where":"USACO Guide Platinum","minutes":30},{"title":"CPH: Inclusion-exclusion","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 22.3 (p. 212)","minutes":10},{"title":"cp-algorithms: The Inclusion-Exclusion Principle","url":"https://cp-algorithms.com/combinatorics/inclusion-exclusion.html","kind":"cpalgo","where":"cp-algorithms","minutes":30}],"problems":[{"id":"cses-2185","src":"cses","name":"Prime Multiples","from":"usaco-guide"},{"id":"cses-2421","src":"cses","name":"Counting Reorders","from":"usaco-guide"},{"id":"cses-2429","src":"cses","name":"Grid Completion","from":"usaco-guide"},{"id":"1207D","src":"cf","name":"Number Of Permutations","rating":1800,"from":"curated"},{"id":"1750D","src":"cf","name":"Count GCD","rating":1800,"from":"curated"},{"id":"1228E","src":"cf","name":"Another Filling the Grid","rating":2300,"from":"curated"},{"id":"1342E","src":"cf","name":"Placing Rooks","rating":2300,"from":"curated"},{"id":"451E","src":"cf","name":"Devu and Flowers","rating":2300,"from":"curated"},{"id":"997C","src":"cf","name":"Sky Full of Stars","rating":2500,"from":"curated"}]},{"id":"comb-permutations","name":"Counting permutations: cycles, derangements & involutions","tier":1600,"order":6,"prereq":["comb-binomial"],"summary":"Counting permutations by structure: derangements D(n)=(n-1)(D(n-1)+D(n-2)), cycle decompositions, involutions, permutations with few fixed points, and permutations constrained by prefix maxima or by where values must go.","learn":["Derangements: D(n)=n!Σ(-1)^k/k! or the recurrence (n-1)(D(n-1)+D(n-2)).","Permutation = disjoint cycles; the order of a permutation is the lcm of its cycle lengths.","Involutions (p(p(i))=i): I(n) = I(n-1) + (n-1)·I(n-2); each element is a fixed point or paired with another.","Place values from largest to smallest (or smallest to largest) and count free positions: products of (available slots) give the answer.","Prefix maxima / records: the maximum splits the permutation into independent left and right parts, combined with a binomial C(n-1, left size).","Count permutations with at most k misplaced elements: Σ C(n,i)·D(i)."],"resources":[{"title":"USACO Guide: Combinatorics (Derangements)","url":"https://usaco.guide/gold/combo","kind":"usaco","where":"USACO Guide Gold","minutes":30},{"title":"CPH: Inclusion-exclusion: derangements","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 22.3 (p. 212)","minutes":10}],"problems":[{"id":"cses-1717","src":"cses","name":"Christmas Party","from":"curated"},{"id":"cses-3397","src":"cses","name":"Permutation Order","from":"curated"},{"id":"cses-3398","src":"cses","name":"Permutation Rounds","from":"usaco-guide"},{"id":"1391C","src":"cf","name":"Cyclic Permutations","rating":1500,"from":"curated"},{"id":"888D","src":"cf","name":"Almost Identity Permutations","rating":1600,"from":"usaco-guide"},{"id":"1957C","src":"cf","name":"How Does the Rook Move?","rating":1600,"from":"curated"},{"id":"1699C","src":"cf","name":"The Third Problem","rating":1700,"from":"curated"},{"id":"1553E","src":"cf","name":"Permutation Shift","rating":2100,"from":"curated"},{"id":"1946E","src":"cf","name":"Girl Permutation","rating":2200,"from":"curated"},{"id":"1768E","src":"cf","name":"Partial Sorting","rating":2300,"from":"curated"}]},{"id":"comb-stirling","name":"Stirling numbers, set partitions & sums of powers","tier":2300,"order":7,"prereq":["comb-permutations","comb-pie"],"summary":"Stirling numbers of the second kind S(n,k) count partitions of n labelled items into k non-empty groups; those of the first kind count permutations with k cycles. Their main contest use is rewriting x^k as a combination of falling factorials, which turns sums of k-th powers over subsets or random variables into sums of binomials.","learn":["S(n,k) = S(n-1,k-1) + k·S(n-1,k); unsigned first kind c(n,k) = c(n-1,k-1) + (n-1)·c(n-1,k).","Surjections from n items onto k labelled boxes: k!·S(n,k) = Σ_i (-1)^i C(k,i)(k-i)^n (inclusion–exclusion), so one row S(n,·) is a single convolution.","x^k = Σ_j S(k,j)·x(x-1)...(x-j+1): turns Σ_{subsets} |S|^k into Σ_j S(k,j)·n!/(n-j)!·2^{n-j} in O(k^2).","E[X^k] for a binomial-like count X becomes Σ_j S(k,j)·j!·E[C(X,j)], and E[C(X,j)] is just a count of j-element subsets.","Bell numbers B(n) = Σ_k S(n,k) count all set partitions; Bell triangle or B(n+1) = Σ C(n,i)B(i).","Rook placements with exactly k attacking pairs, or n balls into k non-empty unlabelled boxes, are Stirling counts in disguise."],"resources":[{"title":"Wikipedia: Stirling numbers of the second kind","url":"https://en.wikipedia.org/wiki/Stirling_numbers_of_the_second_kind","kind":"other","where":"Wikipedia","minutes":15},{"title":"Wikipedia: Stirling numbers of the first kind","url":"https://en.wikipedia.org/wiki/Stirling_numbers_of_the_first_kind","kind":"other","where":"Wikipedia","minutes":10},{"title":"[Tutorial] Generating Functions in Competitive Programming (Part 1)","url":"https://codeforces.com/blog/entry/77468","kind":"cf-blog","where":"Codeforces blog","minutes":45},{"title":"CPH: Inclusion-exclusion (surjections)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 22.3 (p. 212)","minutes":10}],"problems":[{"id":"cses-2228","src":"cses","name":"Counting Sequences","from":"curated"},{"id":"1342E","src":"cf","name":"Placing Rooks","rating":2300,"from":"curated"},{"id":"932E","src":"cf","name":"Team Work","rating":2400,"from":"curated"},{"id":"1716F","src":"cf","name":"Bags with Balls","rating":2500,"from":"curated"},{"id":"1278F","src":"cf","name":"Cards","rating":2600,"from":"curated"},{"id":"961G","src":"cf","name":"Partitions","rating":2700,"from":"curated"},{"id":"960G","src":"cf","name":"Bandit Blues","rating":2900,"from":"curated"}]},{"id":"comb-catalan","name":"Catalan numbers, bracket sequences & reflection","tier":1900,"order":8,"prereq":["comb-binomial"],"summary":"C_n = C(2n,n)/(n+1) counts balanced bracket sequences, binary trees, Dyck paths, triangulations. The reflection principle counts lattice paths that never cross a line, giving C(n+m,m) - C(n+m,m-1)-type answers.","learn":["Catalan recurrence C_{n+1}=Σ C_i C_{n-i}; closed form C(2n,n)-C(2n,n+1).","Reflection: paths from (0,0) to (a,b) touching y=x+1 correspond bijectively to paths to a reflected endpoint.","Count bracket sequences with a fixed prefix: remaining opens/closes with the balance constraint via reflection.","Balanced sequences with forced matched intervals split into independent groups; multiply Catalan numbers per group.","Number of BSTs / binary trees with n nodes is C_n; with height constraints use DP on the Catalan recurrence.","Ballot problem / exceedance: the fraction of 'good' paths is often (a-b+1)/(a+1)."],"resources":[{"title":"USACO Guide: Catalan Numbers","url":"https://usaco.guide/adv/catalan","kind":"usaco","where":"USACO Guide Advanced","minutes":30},{"title":"CPH: Catalan numbers","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 22.2 (p. 210)","minutes":15},{"title":"cp-algorithms: Catalan Numbers","url":"https://cp-algorithms.com/combinatorics/catalan-numbers.html","kind":"cpalgo","where":"cp-algorithms","minutes":15},{"title":"cp-algorithms: Balanced bracket sequences","url":"https://cp-algorithms.com/combinatorics/bracket_sequences.html","kind":"cpalgo","where":"cp-algorithms","minutes":15}],"problems":[{"id":"cses-2064","src":"cses","name":"Bracket Sequences I","from":"usaco-guide"},{"id":"cses-2187","src":"cses","name":"Bracket Sequences II","from":"usaco-guide"},{"id":"9D","src":"cf","name":"How many trees?","rating":1900,"from":"curated"},{"id":"1976D","src":"cf","name":"Invertible Bracket Sequences","rating":2000,"from":"curated"},{"id":"1830C","src":"cf","name":"Hyperregular Bracket Strings","rating":2400,"from":"usaco-guide"},{"id":"1264D1","src":"cf","name":"Beautiful Bracket Sequence (easy version)","rating":2600,"from":"curated"},{"id":"1924D","src":"cf","name":"Balanced Subsequences","rating":2700,"from":"usaco-guide"}]},{"id":"comb-lattice-paths","name":"Lattice paths, obstacles & the reflection principle","tier":2200,"order":9,"prereq":["comb-catalan"],"summary":"Monotone paths on a grid from (0,0) to (a,b) number C(a+b,a). With forbidden cells, sort them and subtract paths through the first forbidden cell (an O(k^2) DP over obstacles); with a forbidden line, reflect the endpoint. Recognise 'count walks/sequences of +1/-1 steps with a constraint on prefix sums'.","learn":["Paths from (x1,y1) to (x2,y2) with right/up steps: C((x2-x1)+(y2-y1), x2-x1).","Obstacles: sort them, dp[i] = paths to obstacle i avoiding earlier obstacles = all paths − Σ_{j before i} dp[j]·paths(j→i); answer uses the target as the last 'obstacle'.","Reflection principle: paths that touch the line y = x + c are in bijection with paths to the endpoint reflected over that line.","Sequences of n (+1) and m (−1) with all prefix sums ≥ −k (or maximum prefix sum ≥ k) are counted by one reflection: C(n+m, m) − C(n+m, m−k−1) style formulas.","Expected / summed maximum prefix sum: Σ_k (number of sequences with max prefix ≥ k).","Probability that a queue never runs out of change (+10/−20 coins) is a ballot-type ratio of two binomials."],"resources":[{"title":"CPH: Catalan numbers (paths in a grid)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 22.2 (p. 210)","minutes":15},{"title":"cp-algorithms: Balanced bracket sequences","url":"https://cp-algorithms.com/combinatorics/bracket_sequences.html","kind":"cpalgo","where":"cp-algorithms","minutes":15},{"title":"Wikipedia: Bertrand's ballot theorem","url":"https://en.wikipedia.org/wiki/Bertrand%27s_ballot_theorem","kind":"other","where":"Wikipedia","minutes":10},{"title":"Wikipedia: Lattice path","url":"https://en.wikipedia.org/wiki/Lattice_path","kind":"other","where":"Wikipedia","minutes":10}],"problems":[{"id":"cses-1078","src":"cses","name":"Grid Paths II","from":"curated"},{"id":"559C","src":"cf","name":"Gerald and Giant Chess","rating":2200,"from":"curated"},{"id":"1204E","src":"cf","name":"Natasha, Sasha and the Prefix Sums","rating":2300,"from":"curated"},{"id":"26D","src":"cf","name":"Tickets","rating":2400,"from":"curated"},{"id":"722E","src":"cf","name":"Research Rover","rating":2900,"from":"curated"}]},{"id":"comb-cayley","name":"Counting trees: Cayley's formula & Prüfer codes","tier":2300,"order":10,"prereq":["comb-binomial"],"summary":"There are n^{n-2} labelled trees on n vertices (Cayley), proven via Prüfer sequences, where vertex v appears deg(v)-1 times. Generalisations count forests and ways to connect k components with sizes s_i: n^{k-2}∏s_i.","learn":["Prüfer sequence: length n-2, bijection with labelled trees; degree of v = occurrences + 1.","Trees with prescribed degrees: (n-2)!/∏(d_i-1)!.","Connecting k components of sizes s_1..s_k into a tree: n^{k-2}·∏ s_i.","Forests of k rooted trees containing fixed roots: k·n^{n-k-1}.","Counting trees where a given path has length k: choose the path's inner vertices, then use the forest formula.","Matrix-tree theorem (Kirchhoff) counts spanning trees of any graph via a determinant."],"resources":[{"title":"CPH: Cayley's formula","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 22.5 (p. 215)","minutes":10},{"title":"cp-algorithms: Counting labeled graphs","url":"https://cp-algorithms.com/combinatorics/counting_labeled_graphs.html","kind":"cpalgo","where":"cp-algorithms","minutes":10},{"title":"cp-algorithms: Kirchhoff's theorem","url":"https://cp-algorithms.com/graph/kirchhoff-theorem.html","kind":"cpalgo","where":"cp-algorithms","minutes":15},{"title":"cp-algorithms: Prüfer code","url":"https://cp-algorithms.com/graph/pruefer_code.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"1109D","src":"cf","name":"Sasha and Interesting Fact from Graph Theory","rating":2400,"from":"curated"},{"id":"156D","src":"cf","name":"Clues","rating":2500,"from":"curated"},{"id":"917D","src":"cf","name":"Stranger Trees","rating":2600,"from":"curated"},{"id":"1762E","src":"cf","name":"Tree Sum","rating":2600,"from":"curated"}]},{"id":"comb-burnside","name":"Burnside's lemma & Pólya counting","tier":2300,"order":11,"prereq":["comb-binomial","nt-gcd-lcm"],"summary":"Counts objects up to symmetry (rotations, reflections): the number of distinct objects equals the average number of configurations fixed by each symmetry. Classic use: necklaces and grid colourings up to rotation.","learn":["Burnside: #orbits = (1/|G|) Σ_{g∈G} fix(g).","Rotation by k of an n-bead necklace has gcd(k,n) cycles, so fix = m^{gcd(k,n)}.","Group sums by d=gcd: Σ_{d|n} φ(n/d)·m^d / n.","Pólya: fixed colourings of a permutation with c cycles is m^c.","For grids under 90° rotations, count cycles of each rotation on cells.","Divide by |G| using a modular inverse."],"resources":[{"title":"CPH: Burnside's lemma","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 22.4 (p. 214)","minutes":10},{"title":"cp-algorithms: Burnside's lemma / Pólya enumeration theorem","url":"https://cp-algorithms.com/combinatorics/burnside.html","kind":"cpalgo","where":"cp-algorithms","minutes":25}],"problems":[{"id":"cses-2209","src":"cses","name":"Counting Necklaces","from":"curated"},{"id":"cses-2210","src":"cses","name":"Counting Grids","from":"curated"},{"id":"1065E","src":"cf","name":"Side Transmutations","rating":2300,"from":"curated"}]},{"id":"comb-generating-functions","name":"Generating functions","tier":2300,"order":12,"prereq":["comb-binomial","comb-pie"],"summary":"Encode a sequence a_n as the polynomial/power series Σ a_n x^n; products of generating functions combine independent choices, so counting questions become coefficient extraction, often finished with PIE or FFT.","learn":["Ordinary GF of choosing 0..c items of a type: (1-x^{c+1})/(1-x); of unlimited items: 1/(1-x).","[x^n] (1-x)^{-k} = C(n+k-1, k-1); expand (1-x^{c+1}) products with PIE.","Exponential GFs (Σ a_n x^n/n!) handle labelled structures; products give binomial convolutions.","Products of many small polynomials are computed by divide & conquer with NTT.","Stirling numbers of the first kind are coefficients of x(x+1)...(x+n-1).","Catalan GF satisfies C(x)=1+xC(x)^2; solving needs polynomial sqrt/inverse."],"resources":[{"title":"[Tutorial] Generating Functions in Competitive Programming (Part 1)","url":"https://codeforces.com/blog/entry/77468","kind":"cf-blog","where":"Codeforces blog","minutes":45},{"title":"USACO Guide: More Complex Operations Using FFT","url":"https://usaco.guide/adv/fft-ext","kind":"usaco","where":"USACO Guide Advanced","minutes":30}],"problems":[{"id":"451E","src":"cf","name":"Devu and Flowers","rating":2300,"from":"curated"},{"id":"1251F","src":"cf","name":"Red-White Fence","rating":2500,"from":"curated"},{"id":"958F3","src":"cf","name":"Lightsabers (hard)","rating":2600,"from":"curated"},{"id":"1257G","src":"cf","name":"Divisor Set","rating":2600,"from":"curated"},{"id":"960G","src":"cf","name":"Bandit Blues","rating":2900,"from":"curated"},{"id":"438E","src":"cf","name":"The Child and Binary Tree","rating":3100,"from":"curated"}]}]},{"id":"probability","name":"Probability & Expected Value","cfTags":["probabilities","math"],"subtopics":[{"id":"prob-basics","name":"Probability basics & probabilities mod p","tier":1500,"order":1,"prereq":["comb-binomial","nt-modular-inverse"],"summary":"Probability = favourable/total for uniform outcomes, multiplication for independent events, conditioning by cases. Many CF problems ask for the probability or expectation as P·Q^{-1} mod 998244353.","learn":["Uniform outcomes: count favourable and total with combinatorics.","Independent events multiply; complementary event: P(at least one) = 1 - P(none).","Probability DP over steps: dp[state] = probability of reaching the state.","Print fractions mod p by multiplying with modular inverses; keep everything modular from the start.","Conditioning: P(A) = Σ P(A|B_i)P(B_i) over a partition of cases.","Double precision is fine when the output is a real number (CSES Dice Probability) — print enough digits."],"resources":[{"title":"CPH: Probability: calculation","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 24.1 (p. 225)","minutes":10},{"title":"CPH: Probability: events","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 24.2 (p. 226)","minutes":10},{"title":"USACO Guide: Combinatorics (Expected Value)","url":"https://usaco.guide/gold/combo","kind":"usaco","where":"USACO Guide Gold","minutes":30}],"problems":[{"id":"cses-1725","src":"cses","name":"Dice Probability","from":"curated"},{"id":"cses-1727","src":"cses","name":"Candy Lottery","from":"usaco-guide"},{"id":"cses-1728","src":"cses","name":"Inversion Probability","from":"curated"},{"id":"476B","src":"cf","name":"Dreamoon and WiFi","rating":1300,"from":"curated"},{"id":"312B","src":"cf","name":"Archer","rating":1300,"from":"curated"},{"id":"1461C","src":"cf","name":"Random Events","rating":1500,"from":"curated"},{"id":"518D","src":"cf","name":"Ilya and Escalator","rating":1700,"from":"curated"},{"id":"148D","src":"cf","name":"Bag of mice","rating":1800,"from":"curated"},{"id":"935D","src":"cf","name":"Fafa and Ancient Alphabet","rating":1900,"from":"curated"},{"id":"1543C","src":"cf","name":"Need for Pink Slips","rating":1900,"from":"curated"}]},{"id":"prob-linearity","name":"Expected value & linearity of expectation","tier":1800,"order":2,"prereq":["prob-basics"],"summary":"E[X+Y]=E[X]+E[Y] always, even for dependent variables. Write a complicated quantity as a sum of indicator variables and add their probabilities. The most frequent probability idea on Codeforces.","learn":["Indicator trick: E[#good things] = Σ P(thing i is good).","Expected depth-like sums: in a random removal order, vertex v is chosen directly with probability 1/depth(v).","Expected number of pairs/inversions: sum over pairs of the probability the pair is 'good'.","E[X^2] = Σ_{i,j} E[X_i X_j] (expected square via pairs); for XOR, split into bit pairs.","Symmetry: in a random permutation each relative order of k fixed elements is equally likely.","Expected sum over all equally likely configurations = total sum / number of configurations (and vice versa).","Tail-sum formula for non-negative integers: E[X] = Σ_{k≥1} P(X ≥ k); E[max] is computed via P(max < k) = ∏ P(X_i < k)."],"resources":[{"title":"USACO Guide: Combinatorics (Linearity of Expectation)","url":"https://usaco.guide/gold/combo","kind":"usaco","where":"USACO Guide Gold","minutes":30},{"title":"CPH: Random variables: expected value","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 24.3 (p. 228)","minutes":15},{"title":"Sums and Expected Value — part 1 (Errichto)","url":"https://codeforces.com/blog/entry/62690","kind":"cf-blog","where":"Codeforces blog","minutes":30}],"problems":[{"id":"cses-1726","src":"cses","name":"Moving Robots","from":"curated"},{"id":"1824B1","src":"cf","name":"LuoTianyi and the Floating Islands (Easy Version)","rating":1800,"from":"curated"},{"id":"1777D","src":"cf","name":"Score of a Tree","rating":1900,"from":"curated"},{"id":"1925D","src":"cf","name":"Good Trip","rating":1900,"from":"curated"},{"id":"2020E","src":"cf","name":"Expected Power","rating":2000,"from":"curated"},{"id":"280C","src":"cf","name":"Game on Tree","rating":2200,"from":"curated"},{"id":"1540B","src":"cf","name":"Tree Array","rating":2300,"from":"curated"},{"id":"1983E","src":"cf","name":"I Love Balls","rating":2300,"from":"curated"},{"id":"1418E","src":"cf","name":"Expected Damage","rating":2400,"from":"curated"}]},{"id":"prob-expected-dp","name":"Expected-value DP & Markov chains","tier":2000,"order":3,"prereq":["prob-linearity","@dp-probability"],"summary":"When a process repeats until a condition holds, write E[state] = cost + Σ p·E[next] and solve: by DP in topological order, by algebra when the state can return to itself (geometric distribution), or by Gaussian elimination for general Markov chains.","learn":["Self-loops: E = 1 + pE + ... gives E = (1 + ...)/(1-p); expected trials until success with probability p is 1/p.","Process states backwards from the absorbing state (dp over 'remaining work').","Expected steps over a chain of states: linear equations E_i = a_i + b_i·E_0 solved by expressing everything in terms of one unknown.","Multiplicative/number-theoretic states: dp over divisors of the current gcd or prime exponents.","Coupon collector: expected draws to see all n types is n·(1 + 1/2 + ... + 1/n); in general, sum the expected waiting times of each phase.","Markov chains: transition matrix powers give distributions after k steps; stationary distribution solves πP=π."],"resources":[{"title":"CPH: Markov chains","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 24.4 (p. 230)","minutes":10},{"title":"CPH: Random variables","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 24.3 (p. 228)","minutes":15},{"title":"Sums and Expected Value — part 1 (Errichto)","url":"https://codeforces.com/blog/entry/62690","kind":"cf-blog","where":"Codeforces blog","minutes":30}],"problems":[{"id":"16E","src":"cf","name":"Fish","rating":1900,"from":"curated"},{"id":"1753C","src":"cf","name":"Wish I Knew How to Sort","rating":2000,"from":"curated"},{"id":"1265E","src":"cf","name":"Beautiful Mirrors","rating":2100,"from":"curated"},{"id":"1778D","src":"cf","name":"Flexible String Revisit","rating":2100,"from":"curated"},{"id":"1097D","src":"cf","name":"Makoto and a Blackboard","rating":2200,"from":"curated"},{"id":"908D","src":"cf","name":"New Year and Arbitrary Arrangement","rating":2200,"from":"curated"},{"id":"1139D","src":"cf","name":"Steps to One","rating":2300,"from":"curated"},{"id":"1874C","src":"cf","name":"Jellyfish and EVA","rating":2300,"from":"curated"},{"id":"1854C","src":"cf","name":"Expected Destruction","rating":2500,"from":"curated"}]},{"id":"prob-randomized","name":"Randomized algorithms","tier":2200,"order":4,"prereq":["prob-basics"],"summary":"Use randomness to get algorithms that are correct with high probability: pick random elements that likely belong to the answer, random sampling in interactive problems, random hashing, and randomized checks. Requires a good RNG (mt19937).","learn":["If the answer is supported by ≥ half the elements, a random element is in it with probability ≥ 1/2; repeat ~20-30 times.","Random candidate + full check (Monte Carlo / Las Vegas); estimate failure probability (1-p)^k.","Interactive search: random queries to find a large starting point before a deterministic walk.","Use mt19937 seeded with chrono time; never rand() (small range on Windows, hackable).","Majority/frequency queries on ranges by sampling random positions.","Randomly shuffle input to defeat adversarial worst cases (treaps, hashing, incremental algorithms)."],"resources":[{"title":"USACO Guide: Randomness","url":"https://usaco.guide/adv/random","kind":"usaco","where":"USACO Guide Advanced","minutes":30},{"title":"CPH: Randomized algorithms","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 24.5 (p. 231)","minutes":10},{"title":"Don't use rand(): a guide to random number generators in C++","url":"https://codeforces.com/blog/entry/61587","kind":"cf-blog","where":"Codeforces blog","minutes":15}],"problems":[{"id":"843B","src":"cf","name":"Interactive LowerBound","rating":2000,"from":"curated"},{"id":"1114E","src":"cf","name":"Arithmetic Progression","rating":2200,"from":"curated"},{"id":"444B","src":"cf","name":"DZY Loves FFT","rating":2300,"from":"usaco-guide"},{"id":"1523D","src":"cf","name":"Love-Hate","rating":2400,"from":"curated"},{"id":"1305F","src":"cf","name":"Kuroni and the Punishment","rating":2500,"from":"curated"},{"id":"840D","src":"cf","name":"Destiny","rating":2500,"from":"usaco-guide"},{"id":"364D","src":"cf","name":"Ghd","rating":2900,"from":"usaco-guide"}]}]},{"id":"game-theory","name":"Game Theory","cfTags":["games"],"subtopics":[{"id":"game-basics","name":"Game analysis: parity, symmetry & mirroring","tier":800,"order":1,"prereq":["math-arith-basics"],"summary":"Two-player 'who wins with optimal play' problems where the answer follows from a parity count, a symmetric (mirroring) strategy, or a small invariant. Usually solved by playing small cases by hand and spotting the pattern.","learn":["Brute-force tiny cases to find the pattern, then prove it with a strategy.","Mirroring: the second player copies the first player's move on the symmetric position.","Parity: if every move changes the state by a fixed amount, the winner depends on the parity of the total number of moves.","Strategy stealing: the first player can win if an extra free move cannot hurt.","Focus on terminal positions: who is forced to make the last move?","Tree games: the degree of the special vertex and parity of n often decide the winner."],"resources":[{"title":"CPH: Game states","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 25.1 (p. 235)","minutes":10},{"title":"cp-algorithms: Games on arbitrary graphs","url":"https://cp-algorithms.com/game_theory/games_on_graphs.html","kind":"cpalgo","where":"cp-algorithms","minutes":15}],"problems":[{"id":"cses-2208","src":"cses","name":"Another Game","from":"curated"},{"id":"1899A","src":"cf","name":"Game with Integers","rating":800,"from":"curated"},{"id":"1919A","src":"cf","name":"Wallet Exchange","rating":800,"from":"curated"},{"id":"1373B","src":"cf","name":"01 Game","rating":900,"from":"curated"},{"id":"1527B1","src":"cf","name":"Palindrome Game (easy version)","rating":1200,"from":"curated"},{"id":"1747C","src":"cf","name":"Swap Game","rating":1200,"from":"curated"},{"id":"1943A","src":"cf","name":"MEX Game 1","rating":1300,"from":"curated"},{"id":"1370C","src":"cf","name":"Number Game","rating":1400,"from":"curated"},{"id":"1363C","src":"cf","name":"Game On Leaves","rating":1600,"from":"curated"},{"id":"1537D","src":"cf","name":"Deleting Divisors","rating":1700,"from":"curated"},{"id":"1396B","src":"cf","name":"Stoned Game","rating":1800,"from":"curated"},{"id":"1527B2","src":"cf","name":"Palindrome Game (hard version)","rating":1900,"from":"curated"},{"id":"1404B","src":"cf","name":"Tree Tag","rating":1900,"from":"curated"}]},{"id":"game-states-dp","name":"Winning/losing positions & game DP","tier":1200,"order":2,"prereq":["game-basics","@dp-intro"],"summary":"A position is winning iff some move leads to a losing position; losing iff all moves lead to winning positions. Computing this by DP (or retrograde BFS on graphs with cycles) solves games with small state spaces and minimax score games.","learn":["W/L rule: lose if no move exists (normal play); win iff exists a move to a losing state.","Compute in topological order (by remaining stones, positions sorted by value, interval length).","Score games (maximize own minus opponent's): dp[l][r] = max(a_l - dp[l+1][r], a_r - dp[l][r-1]).","Games on DAGs with two tokens: dp over (pos1, pos2, last letter, turn).","Graphs with cycles: retrograde analysis from terminal states with counters (draws remain undetermined).","Look for periodicity in W/L tables (1-2-k game: period 3, or period k+1 when k is divisible by 3)."],"resources":[{"title":"CPH: Game states","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 25.1 (p. 235)","minutes":10},{"title":"USACO Guide: Game Theory","url":"https://usaco.guide/adv/game-theory","kind":"usaco","where":"USACO Guide Advanced","minutes":30},{"title":"cp-algorithms: Games on arbitrary graphs","url":"https://cp-algorithms.com/game_theory/games_on_graphs.html","kind":"cpalgo","where":"cp-algorithms","minutes":15}],"problems":[{"id":"cses-1729","src":"cses","name":"Stick Game","from":"curated"},{"id":"1860C","src":"cf","name":"Game on Permutation","rating":1400,"from":"curated"},{"id":"1738C","src":"cf","name":"Even Number Addicts","rating":1500,"from":"curated"},{"id":"1033C","src":"cf","name":"Permutation Game","rating":1600,"from":"curated"},{"id":"917B","src":"cf","name":"MADMAX","rating":1700,"from":"curated"},{"id":"1194D","src":"cf","name":"1-2-K Game","rating":1700,"from":"curated"},{"id":"1728D","src":"cf","name":"Letter Picking","rating":1800,"from":"curated"},{"id":"1987D","src":"cf","name":"World is Mine","rating":1800,"from":"curated"},{"id":"1628D1","src":"cf","name":"Game on Sum (Easy Version)","rating":2100,"from":"curated"},{"id":"2005E1","src":"cf","name":"Subtangle Game (Easy Version)","rating":2100,"from":"curated"}]},{"id":"game-nim","name":"Nim & XOR-sum games","tier":1700,"order":3,"prereq":["game-states-dp"],"summary":"In Nim, the first player wins iff the XOR of pile sizes is non-zero. Many games are disguised Nim: staircase Nim (only odd-indexed steps matter), games where only the first non-trivial pile matters, and Nim with randomised piles.","learn":["Nim: losing iff a1 ^ a2 ^ ... ^ an == 0; the winning move makes the XOR zero.","Misère Nim: same as Nim unless all piles are size 1 (then parity decides).","Staircase Nim: only piles on odd steps matter — it is Nim on those piles.","Sequential Nim (must take from the first non-empty pile): the player who first meets a pile >1 wins.","Removing the same amount from all piles: only the sorted distinct sizes/gaps matter.","XOR of ranges of consecutive integers has an O(1) formula (pattern by n mod 4)."],"resources":[{"title":"CPH: Nim game","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 25.2 (p. 237)","minutes":10},{"title":"USACO Guide: Game Theory (Nim)","url":"https://usaco.guide/adv/game-theory","kind":"usaco","where":"USACO Guide Advanced","minutes":30},{"title":"cp-algorithms: Sprague-Grundy theorem. Nim","url":"https://cp-algorithms.com/game_theory/sprague-grundy-nim.html","kind":"cpalgo","where":"cp-algorithms","minutes":30}],"problems":[{"id":"cses-1730","src":"cses","name":"Nim Game I","from":"usaco-guide"},{"id":"cses-1098","src":"cses","name":"Nim Game II","from":"curated"},{"id":"cses-1099","src":"cses","name":"Stair Game","from":"curated"},{"id":"1382B","src":"cf","name":"Sequential Nim","rating":1100,"from":"curated"},{"id":"2239A","src":"cf","name":"Nim Game Is XOR Game","rating":1300,"from":"curated"},{"id":"1965A","src":"cf","name":"Everything Nim","rating":1400,"from":"curated"},{"id":"1147C","src":"cf","name":"Thanos Nim","rating":2000,"from":"curated"},{"id":"15C","src":"cf","name":"Industrial Nim","rating":2000,"from":"curated"},{"id":"1451F","src":"cf","name":"Nullify The Matrix","rating":2700,"from":"curated"},{"id":"2043F","src":"cf","name":"Nim","rating":2700,"from":"curated"}]},{"id":"game-sprague-grundy","name":"Sprague–Grundy theorem","tier":2000,"order":4,"prereq":["game-nim"],"summary":"Every impartial game position has a Grundy value = mex of the values of positions reachable in one move; a sum of independent games is losing iff the XOR of Grundy values is 0. Compute Grundy numbers by brute force, then find a pattern or periodicity.","learn":["g(position) = mex{ g(next) }; g = 0 ⇔ losing.","Sum of games: XOR the Grundy values of independent components (piles, subtrees, rows).","Splitting moves (one pile into two) contribute g(a) ^ g(b) to the mex set.","Print the Grundy table for small inputs to find periodicity or a closed form (e.g. based on smallest prime factor).","State compression: Grundy values over bitmasks of used moves (Game of Stones) or of exponent sets.","Trees: Green Hackenbush value of a rooted tree is XOR over children of (child value + 1)."],"resources":[{"title":"CPH: Sprague–Grundy theorem","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 25.3 (p. 238)","minutes":15},{"title":"USACO Guide: Game Theory (Sprague-Grundy)","url":"https://usaco.guide/adv/game-theory","kind":"usaco","where":"USACO Guide Advanced","minutes":30},{"title":"cp-algorithms: Sprague-Grundy theorem. Nim","url":"https://cp-algorithms.com/game_theory/sprague-grundy-nim.html","kind":"cpalgo","where":"cp-algorithms","minutes":30}],"problems":[{"id":"cses-2207","src":"cses","name":"Grundy's Game","from":"curated"},{"id":"2004E","src":"cf","name":"Not a Nim Problem","rating":2100,"from":"curated"},{"id":"768E","src":"cf","name":"Game of Stones","rating":2100,"from":"usaco-guide"},{"id":"603C","src":"cf","name":"Lieges of Legendre","rating":2200,"from":"curated"},{"id":"850C","src":"cf","name":"Arpa and a game with Mojtaba","rating":2200,"from":"usaco-guide"},{"id":"812E","src":"cf","name":"Sagheer and Apple Tree","rating":2300,"from":"usaco-guide"},{"id":"1312F","src":"cf","name":"Attack on Red Kingdom","rating":2500,"from":"curated"},{"id":"1498F","src":"cf","name":"Christmas Game","rating":2500,"from":"curated"},{"id":"1823E","src":"cf","name":"Removing Graph","rating":2500,"from":"curated"}]}]},{"id":"matrices","name":"Matrices & Linear Algebra","cfTags":["matrices","math"],"subtopics":[{"id":"mat-expo","name":"Matrix exponentiation for linear recurrences","tier":1900,"order":1,"prereq":["nt-binary-exponentiation","@dp-intro"],"summary":"A linear recurrence f_n = Σ c_i f_{n-i} (+const) is a vector times a k×k transition matrix; raising the matrix to the n-th power with binary exponentiation computes f_n in O(k^3 log n) for n up to 10^18.","learn":["Fibonacci: [[1,1],[1,0]]^n; extend the state vector with constants or prefix sums to handle +c or Σ terms.","DP with a fixed transition and huge length (counting strings/arrays of length 10^18 with local constraints) is matrix power.","Cost O(k^3 log n): keep k ≤ ~100; reduce state by symmetry or by digit residues.","Matrix products in a segment tree support range updates of recurrences (Fibonacci on ranges).","Exponents of multiplicative recurrences are reduced mod p-1 and powered as matrices.","Use unsigned long long accumulation and a single mod per entry to speed up the inner loop.","Fibonacci facts: gcd(F_m, F_n) = F_gcd(m,n); F_n mod k is periodic (Pisano period ≤ 6k); fast doubling computes F_n without matrices.","Advanced: Berlekamp–Massey finds the shortest linear recurrence from the first 2k terms; Kitamasa / polynomial mod computes the n-th term in O(k^2 log n)."],"resources":[{"title":"USACO Guide: Matrix Exponentiation","url":"https://usaco.guide/plat/matrix-expo","kind":"usaco","where":"USACO Guide Platinum","minutes":30},{"title":"CPH: Linear recurrences","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 23.2 (p. 220)","minutes":10},{"title":"CPH: Matrix operations","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 23.1 (p. 217)","minutes":10},{"title":"cp-algorithms: Fibonacci Numbers","url":"https://cp-algorithms.com/algebra/fibonacci-numbers.html","kind":"cpalgo","where":"cp-algorithms","minutes":15}],"problems":[{"id":"cses-1722","src":"cses","name":"Fibonacci Numbers","from":"usaco-guide"},{"id":"cses-1096","src":"cses","name":"Throwing Dice","from":"curated"},{"id":"691E","src":"cf","name":"Xor-sequences","rating":1900,"from":"usaco-guide"},{"id":"222E","src":"cf","name":"Decoding Genome","rating":1900,"from":"curated"},{"id":"621E","src":"cf","name":"Wet Shark and Blocks","rating":2000,"from":"curated"},{"id":"1970E2","src":"cf","name":"Trails (Medium)","rating":2000,"from":"curated"},{"id":"852B","src":"cf","name":"Neural Network country","rating":2000,"from":"curated"},{"id":"1117D","src":"cf","name":"Magic Gems","rating":2100,"from":"curated"},{"id":"551D","src":"cf","name":"GukiZ and Binary Operations","rating":2100,"from":"curated"},{"id":"514E","src":"cf","name":"Darth Vader and Tree","rating":2200,"from":"curated"},{"id":"718C","src":"cf","name":"Sasha and Array","rating":2300,"from":"usaco-guide"}]},{"id":"mat-graph-paths","name":"Walk counting, (min,+) products & matrices in segment trees","tier":2100,"order":2,"prereq":["mat-expo","@ds-segtree-combine"],"summary":"The (i,j) entry of A^k counts walks of length exactly k between i and j. Replacing (+,×) with (min,+) gives shortest walks with exactly k edges, and binary lifting on matrices answers 'smallest k with property' questions.","learn":["Walk counting: (A^k)[i][j] = number of walks of length k from i to j.","Min-plus product: C[i][j] = min_k A[i][k] + B[k][j]; it is associative so fast exponentiation still works.","Shortest path with exactly k edges via min-plus power; with at most k by adding self-loops of cost 0.","Binary lifting over powers A^{2^j} to find the minimal length with a property (e.g. a positive cycle).","Boolean matrix powers with bitsets for reachability after k steps.","Edges unlocked over time: process time segments and multiply reachability matrices.","A DP whose transition is a small (min,+) or (max,+) matrix per position can be stored in a segment tree: each node keeps the product of its range, giving O(k^3 log n) range queries and point updates.","Aho–Corasick automaton states + (max,+) matrix power maximize a score over texts of length up to 10^14."],"resources":[{"title":"CPH: Graphs and matrices","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 23.3 (p. 222)","minutes":10},{"title":"USACO Guide: Matrix Exponentiation","url":"https://usaco.guide/plat/matrix-expo","kind":"usaco","where":"USACO Guide Platinum","minutes":30},{"title":"cp-algorithms: Number of paths of fixed length / Shortest paths of fixed length","url":"https://cp-algorithms.com/graph/fixed_length_paths.html","kind":"cpalgo","where":"cp-algorithms","minutes":15}],"problems":[{"id":"cses-1723","src":"cses","name":"Graph Paths I","from":"usaco-guide"},{"id":"cses-1724","src":"cses","name":"Graph Paths II","from":"usaco-guide"},{"id":"1970E3","src":"cf","name":"Trails (Hard)","rating":2200,"from":"curated"},{"id":"1814E","src":"cf","name":"Chain Chips","rating":2300,"from":"curated"},{"id":"780F","src":"cf","name":"Axel and Marston in Bitland","rating":2400,"from":"curated"},{"id":"147B","src":"cf","name":"Smile House","rating":2500,"from":"curated"},{"id":"696D","src":"cf","name":"Legen...","rating":2500,"from":"curated"},{"id":"1681E","src":"cf","name":"Labyrinth Adventures","rating":2600,"from":"curated"},{"id":"750E","src":"cf","name":"New Year and Old Subsequence","rating":2600,"from":"curated"},{"id":"576D","src":"cf","name":"Flights for Regular Customers","rating":2700,"from":"curated"}]},{"id":"mat-gauss","name":"Gaussian elimination (systems, rank, determinant)","tier":2300,"order":3,"prereq":["nt-modular-inverse"],"summary":"Gauss–Jordan elimination solves n linear equations in O(n^3), computes rank, inverse and determinant, over reals or modulo a prime. Used for expected-value systems with cycles, linear systems mod p, and counting spanning trees.","learn":["Pick a pivot (largest absolute value for doubles; any non-zero mod p), normalise the row, eliminate the column elsewhere.","Number of solutions: 0 if inconsistent, unique if rank=n, otherwise p^{n-rank} (mod p) or infinite.","Determinant = product of pivots with sign flips for row swaps.","Banded/tridiagonal systems (grid rows) solve in O(n) per row instead of O(n^3).","Expected values on graphs with cycles: one equation per state, then eliminate.","Over GF(2) use bitsets for O(n^3/64).","Recover a polynomial of degree k from k+1 sample values mod p by solving the Vandermonde system (or by Lagrange interpolation)."],"resources":[{"title":"cp-algorithms: Gauss method for solving system of linear equations","url":"https://cp-algorithms.com/linear_algebra/linear-system-gauss.html","kind":"cpalgo","where":"cp-algorithms","minutes":25},{"title":"cp-algorithms: Calculating the determinant using Gauss","url":"https://cp-algorithms.com/linear_algebra/determinant-gauss.html","kind":"cpalgo","where":"cp-algorithms","minutes":10},{"title":"cp-algorithms: Finding the rank of a matrix","url":"https://cp-algorithms.com/linear_algebra/rank-matrix.html","kind":"cpalgo","where":"cp-algorithms","minutes":10},{"title":"CPH: Matrices: operations","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 23.1 (p. 217)","minutes":10}],"problems":[{"id":"cses-3154","src":"cses","name":"System of Linear Equations","from":"curated"},{"id":"1155E","src":"cf","name":"Guess the Root","rating":2200,"from":"curated"},{"id":"24D","src":"cf","name":"Broken robot","rating":2400,"from":"curated"},{"id":"832E","src":"cf","name":"Vasya and Shifts","rating":2600,"from":"curated"},{"id":"1411G","src":"cf","name":"No Game No Life","rating":2700,"from":"curated"},{"id":"446D","src":"cf","name":"DZY Loves Games","rating":2800,"from":"curated"},{"id":"963E","src":"cf","name":"Circles of Waiting","rating":3100,"from":"curated"}]}]},{"id":"xor-linear-algebra","name":"Linear Algebra mod 2 (XOR basis)","cfTags":["matrices","bitmasks","math"],"subtopics":[{"id":"xor-basis","name":"XOR basis (linear basis over GF(2))","tier":2100,"order":1,"prereq":["@bit-xor"],"summary":"Treat numbers as vectors over GF(2); a basis of at most 60 vectors spans every XOR of a subset. Supports: max subset XOR, is x representable, number of distinct subset XORs (2^rank), and counting subsets with a given XOR (2^{n-rank}).","learn":["Insert: for bits high→low, if the bit is set and basis[bit] exists XOR it out, else store as basis[bit].","Max XOR: greedily XOR basis vectors from the highest bit if it increases the value.","x is representable iff it reduces to 0; number of subsets with XOR x is 2^{n-rank} if representable.","Segments partition with no zero-XOR subset of segments: answer is the rank of prefix XORs.","Cycle space of a graph: XOR of a path between u,v can be changed by any cycle XOR; reduce with the basis of cycle XORs.","Square-free parity vectors (exponents mod 2) turn 'product is a perfect square' into a GF(2) rank problem."],"resources":[{"title":"USACO Guide: XOR Basis","url":"https://usaco.guide/adv/xor-basis","kind":"usaco","where":"USACO Guide Advanced","minutes":30},{"title":"A Beautiful Technique for Some XOR Related Problems","url":"https://codeforces.com/blog/entry/68953","kind":"cf-blog","where":"Codeforces blog","minutes":30}],"problems":[{"id":"cses-3191","src":"cses","name":"Maximum Xor Subset","from":"curated"},{"id":"cses-3211","src":"cses","name":"Number of Subset Xors","from":"curated"},{"id":"cses-3192","src":"cses","name":"K Subset Xors","from":"curated"},{"id":"895C","src":"cf","name":"Square Subsets","rating":2000,"from":"curated"},{"id":"1101G","src":"cf","name":"(Zero XOR Subset)-less","rating":2300,"from":"usaco-guide"},{"id":"845G","src":"cf","name":"Shortest Path Problem?","rating":2300,"from":"curated"},{"id":"959F","src":"cf","name":"Mahmoud and Ehab and yet another xor task","rating":2400,"from":"curated"},{"id":"1163E","src":"cf","name":"Magical Permutation","rating":2400,"from":"curated"},{"id":"662A","src":"cf","name":"Gambling Nim","rating":2400,"from":"curated"},{"id":"1427E","src":"cf","name":"Xum","rating":2500,"from":"usaco-guide"}]},{"id":"xor-basis-advanced","name":"Prefix/range linear bases & bases on trees","tier":2400,"order":2,"prereq":["xor-basis"],"summary":"Extensions of the XOR basis: keep the most recent index per pivot to answer 'max XOR in a[l..r]' offline or online, merge bases along tree paths (with LCA/divide & conquer), and count with basis-based combinatorics.","learn":["Prefix basis keeping the largest index for each pivot answers max XOR on [l,r] using only vectors with index ≥ l.","Merging two bases costs O(log^2 C); combine with binary lifting, centroid or divide & conquer for tree paths.","Subtree/rerooting: bases of subtrees via Euler tour + prefix bases.","Graph cycle bases with dynamic components combine DSU and basis merging.","Counting subsets by popcount of XOR: enumerate the span when rank is small, otherwise use the orthogonal complement.","Rank changes at most log C times when adding vectors: amortised arguments."],"resources":[{"title":"USACO Guide: XOR Basis","url":"https://usaco.guide/adv/xor-basis","kind":"usaco","where":"USACO Guide Advanced","minutes":30},{"title":"A Beautiful Technique for Some XOR Related Problems","url":"https://codeforces.com/blog/entry/68953","kind":"cf-blog","where":"Codeforces blog","minutes":30}],"problems":[{"id":"1902F","src":"cf","name":"Trees and XOR Queries Again","rating":2400,"from":"usaco-guide"},{"id":"1100F","src":"cf","name":"Ivan and Burgers","rating":2500,"from":"usaco-guide"},{"id":"1778E","src":"cf","name":"The Tree Has Fallen!","rating":2500,"from":"usaco-guide"},{"id":"724G","src":"cf","name":"Xor-matic Number of the Graph","rating":2600,"from":"curated"},{"id":"1336E1","src":"cf","name":"Chiori and Doll Picking (easy version)","rating":2700,"from":"usaco-guide"},{"id":"1299D","src":"cf","name":"Around the World","rating":3000,"from":"usaco-guide"}]}]},{"id":"fft","name":"FFT & Polynomial Methods","cfTags":["fft","math"],"subtopics":[{"id":"fft-convolution","name":"FFT & polynomial multiplication","tier":2300,"order":1,"prereq":["nt-binary-exponentiation","math-sums-formulas"],"summary":"The Fast Fourier Transform multiplies two polynomials of degree n in O(n log n). Any count of the form c[k] = Σ_{i+j=k} a[i]·b[j] (sums of pairs, matching with shifts, wildcard string matching) is a convolution.","learn":["Convolution: c[k] = Σ_{i+j=k} a_i b_j; reverse one array to get correlations Σ a_i b_{i+k} (shift matching).","Use complex FFT with doubles for counts up to ~10^15 result precision; round results.","Wildcard/mismatch string matching: one convolution per alphabet letter, or Σ (a-b)^2 a b trick.","Count pairs (i,j) with a_i + a_j = s for all s using a frequency polynomial squared.","Repeated self-convolution (k items) via fast exponentiation of the polynomial with truncation.","Prefix-sum counts ('how many subarrays have exactly k elements less than x') become convolutions of count arrays."],"resources":[{"title":"USACO Guide: Introduction to Fast Fourier Transform","url":"https://usaco.guide/adv/fft","kind":"usaco","where":"USACO Guide Advanced","minutes":45},{"title":"cp-algorithms: Fast Fourier transform","url":"https://cp-algorithms.com/algebra/fft.html","kind":"cpalgo","where":"cp-algorithms","minutes":45}],"problems":[{"id":"cses-2111","src":"cses","name":"Apples and Bananas","from":"curated"},{"id":"cses-2112","src":"cses","name":"One Bit Positions","from":"curated"},{"id":"cses-2113","src":"cses","name":"Signal Processing","from":"curated"},{"id":"954I","src":"cf","name":"Yet Another String Matching Problem","rating":2200,"from":"curated"},{"id":"993E","src":"cf","name":"Nikita and Order Statistics","rating":2300,"from":"curated"},{"id":"632E","src":"cf","name":"Thief in a Shop","rating":2400,"from":"curated"},{"id":"528D","src":"cf","name":"Fuzzy Search","rating":2500,"from":"curated"},{"id":"1398G","src":"cf","name":"Running Competition","rating":2600,"from":"curated"},{"id":"827E","src":"cf","name":"Rusty String","rating":2700,"from":"curated"},{"id":"286E","src":"cf","name":"Ladies' Shop","rating":2800,"from":"curated"}]},{"id":"fft-ntt","name":"NTT & polynomial operations mod 998244353","tier":2400,"order":2,"prereq":["fft-convolution","nt-modular-inverse"],"summary":"The Number Theoretic Transform performs exact convolution modulo primes like 998244353 = 119·2^23+1 using a primitive root (3). Together with divide-and-conquer multiplication, polynomial inverse/log/exp, it solves most counting problems with generating functions.","learn":["NTT replaces complex roots of unity with g^{(p-1)/n} mod p; works when n divides p-1.","Arbitrary modulus (10^9+7): three NTT primes + CRT, or split-FFT with doubles.","Product of many polynomials: divide & conquer (or a priority queue by degree) in O(n log^2 n).","Polynomial inverse by Newton iteration: B ← B(2 - AB) doubling the precision.","log/exp/power of power series allow 'k-fold product' and set-partition counts.","Watch sizes: pad to a power of two ≥ deg A + deg B + 1."],"resources":[{"title":"USACO Guide: Introduction to Fast Fourier Transform (Convolution Mod)","url":"https://usaco.guide/adv/fft","kind":"usaco","where":"USACO Guide Advanced","minutes":45},{"title":"USACO Guide: More Complex Operations Using FFT","url":"https://usaco.guide/adv/fft-ext","kind":"usaco","where":"USACO Guide Advanced","minutes":30},{"title":"cp-algorithms: Fast Fourier transform (NTT section)","url":"https://cp-algorithms.com/algebra/fft.html","kind":"cpalgo","where":"cp-algorithms","minutes":45},{"title":"cp-algorithms: Operations on polynomials and series","url":"https://cp-algorithms.com/algebra/polynomial.html","kind":"cpalgo","where":"cp-algorithms","minutes":40}],"problems":[{"id":"1096G","src":"cf","name":"Lucky Tickets","rating":2400,"from":"curated"},{"id":"1251F","src":"cf","name":"Red-White Fence","rating":2500,"from":"curated"},{"id":"1218E","src":"cf","name":"Product Tuples","rating":2500,"from":"curated"},{"id":"958F3","src":"cf","name":"Lightsabers (hard)","rating":2600,"from":"curated"},{"id":"1257G","src":"cf","name":"Divisor Set","rating":2600,"from":"curated"},{"id":"1613F","src":"cf","name":"Tree Coloring","rating":2600,"from":"curated"},{"id":"960G","src":"cf","name":"Bandit Blues","rating":2900,"from":"curated"}]},{"id":"fft-walsh-hadamard","name":"Walsh–Hadamard transform (XOR/AND/OR convolution)","tier":2600,"order":3,"prereq":["fft-convolution","@dp-sos"],"summary":"Bitwise convolutions c[k] = Σ_{i⊕j=k} a_i b_j (XOR), and the AND/OR versions (zeta/Möbius transforms over subsets) run in O(n·2^n). They appear when combining masks, row/column flips and counting subsets by AND.","learn":["FWHT for XOR: butterfly (u,v) → (u+v, u-v); inverse divides by 2^n.","OR convolution = subset-sum (zeta) transform, multiply pointwise, then Möbius transform.","AND convolution uses superset sums; counting subsets whose AND is 0 via PIE on superset counts.","Model 'flip some rows to minimise ones per column' as XOR convolution of column-mask counts with a cost function.","Combine with Fibonacci/linear transforms pointwise in the transformed domain.","Work modulo a prime with the inverse of 2^n."],"resources":[{"title":"Fast Walsh Hadamard Transforms and its inner workings","url":"https://codeforces.com/blog/entry/71899","kind":"cf-blog","where":"Codeforces blog","minutes":40},{"title":"USACO Guide: Sum over Subsets DP","url":"https://usaco.guide/plat/dp-sos","kind":"usaco","where":"USACO Guide Platinum","minutes":30}],"problems":[{"id":"449D","src":"cf","name":"Jzzhu and Numbers","rating":2400,"from":"usaco-guide"},{"id":"1218D","src":"cf","name":"Xor Spanning Tree","rating":2400,"from":"curated"},{"id":"662C","src":"cf","name":"Binary Table","rating":2600,"from":"curated"},{"id":"914G","src":"cf","name":"Sum the Fibonacci","rating":2600,"from":"curated"},{"id":"1119H","src":"cf","name":"Triple","rating":3200,"from":"curated"}]},{"id":"poly-interpolation","name":"Polynomial interpolation & sums of powers","tier":2400,"order":4,"prereq":["nt-modular-inverse","math-sums-formulas"],"summary":"A polynomial of degree d is determined by d+1 values. When an answer is provably a polynomial in n of small degree (sums of k-th powers, DP values as a function of a huge parameter), compute it for d+1 small n and evaluate at the real n by Lagrange interpolation in O(d) or O(d^2).","learn":["Lagrange: P(x) = Σ_i y_i ∏_{j≠i} (x - x_j)/(x_i - x_j); with x_i = 0..d use prefix/suffix products and factorials for O(d).","Σ_{i=1}^{n} i^k is a polynomial in n of degree k+1 (Faulhaber), so k+2 sample points suffice.","If dp[n][x] is a polynomial in x of degree ≤ n (e.g. salaries up to D with tree constraints), compute it for x = 0..n and interpolate at x = D.","Finite differences: the (d+1)-th difference of a degree-d polynomial is 0; shifting x by s changes the coefficient of x^{d-1} by d·s·a_d.","Recover all coefficients by Gaussian elimination on a Vandermonde system when d is tiny (≤ 10) and you can query values.","Everything is modulo a prime: precompute inverses of 1..d and handle x equal to a sample point separately."],"resources":[{"title":"Wikipedia: Lagrange polynomial","url":"https://en.wikipedia.org/wiki/Lagrange_polynomial","kind":"other","where":"Wikipedia","minutes":15},{"title":"cp-algorithms: Operations on polynomials and series (interpolation)","url":"https://cp-algorithms.com/algebra/polynomial.html","kind":"cpalgo","where":"cp-algorithms","minutes":40},{"title":"cp-algorithms: Gauss method for solving system of linear equations","url":"https://cp-algorithms.com/linear_algebra/linear-system-gauss.html","kind":"cpalgo","where":"cp-algorithms","minutes":25}],"problems":[{"id":"1155E","src":"cf","name":"Guess the Root","rating":2200,"from":"curated"},{"id":"1817C","src":"cf","name":"Similar Polynomials","rating":2400,"from":"curated"},{"id":"622F","src":"cf","name":"The Sum of the k-th Powers","rating":2600,"from":"curated"},{"id":"995F","src":"cf","name":"Cowmpany Cowmpensation","rating":2700,"from":"curated"}]}]}]},{"area":"dp","topics":[{"id":"dp","name":"Dynamic Programming","cfTags":["dp","bitmasks","trees","probabilities","games","matrices","combinatorics","divide and conquer"],"subtopics":[{"id":"dp-intro","name":"DP fundamentals (1D)","tier":1100,"order":1,"prereq":[],"summary":"Dynamic programming = solve a problem by combining answers of smaller overlapping subproblems stored in a table. The very first DP problems are 1D: dp[i] depends on a few earlier dp[j] (stairs/Fibonacci style, 'take or skip element i'). Recognise it when brute-force recursion recomputes the same states and the answer for a prefix only depends on a small summary of that prefix.","learn":["Define the state in words first (dp[i] = best answer for the first i elements / for value i), then the transition, base cases and answer cell","Top-down memoisation (recursion + cache) vs bottom-up iteration: same complexity, bottom-up avoids stack overflow","Complexity = number of states x cost of one transition; check it against n before coding","Classic shapes: dp[i] = f(dp[i-1], dp[i-2]) (stairs), take/skip element i (house robber, Boredom), jump lengths (Long Jumps)","Counting DP: add the ways of all predecessors and reduce mod 1e9+7 at every step","Reconstructing the optimal solution: store the argmax/parent choice and walk back from the answer cell","Pitfalls: wrong base case, off-by-one between 0- and 1-indexed prefixes, using int where sums overflow","Push (forward: dp[i] updates dp[i+k]) vs pull (backward: dp[i] reads dp[i-k]) formulations - pick whichever makes the transition easier"],"resources":[{"title":"Introduction to DP","url":"https://usaco.guide/gold/intro-dp","kind":"usaco","where":"USACO Guide Gold","minutes":40},{"title":"CPH 7 Dynamic programming (intro) / 7.1 Coin problem","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 7 (p. 65)","minutes":25},{"title":"Introduction to Dynamic Programming","url":"https://cp-algorithms.com/dynamic_programming/intro-to-dp.html","kind":"cpalgo","where":"cp-algorithms","minutes":20},{"title":"AtCoder Educational DP Contest (26 classic DP tasks)","url":"https://atcoder.jp/contests/dp/tasks","kind":"other","where":"AtCoder DP contest","minutes":60}],"problems":[{"id":"1472C","src":"cf","name":"Long Jumps","rating":1100,"from":"curated"},{"id":"1195C","src":"cf","name":"Basketball Exercise","rating":1400,"from":"curated"},{"id":"698A","src":"cf","name":"Vacations","rating":1400,"from":"curated"},{"id":"1245C","src":"cf","name":"Constanze's Machine","rating":1400,"from":"curated"},{"id":"455A","src":"cf","name":"Boredom","rating":1500,"from":"curated"},{"id":"545C","src":"cf","name":"Woodcutters","rating":1500,"from":"curated"},{"id":"1272D","src":"cf","name":"Remove One Element","rating":1500,"from":"curated"},{"id":"166E","src":"cf","name":"Tetrahedron","rating":1500,"from":"curated"},{"id":"1418C","src":"cf","name":"Mortal Kombat Tower","rating":1500,"from":"usaco-guide"},{"id":"cses-1633","src":"cses","name":"Dice Combinations","from":"usaco-guide"},{"id":"cses-1637","src":"cses","name":"Removing Digits","from":"curated"}]},{"id":"dp-grid","name":"Paths on grids","tier":1300,"order":2,"prereq":["dp-intro"],"summary":"Count or optimise paths in a 2D grid that only move right/down (or similar monotone moves): dp[i][j] from dp[i-1][j] and dp[i][j-1]. Also covers 2 x n / few-row grids handled column by column. Recognise it by a grid with monotone moves or a 2-row board.","learn":["dp[i][j] = cost(i,j) + best(dp[i-1][j], dp[i][j-1]); obstacles set dp to 0 / INF","Count paths mod p; minimal / lexicographically smallest path via layer-by-layer BFS on anti-diagonals","Two paths at once (meeting / crossing): dp from all four corners, or dp on (step, row1, row2)","2 x n boards: state = which cells of the current column are used, process column by column","Range of reachable sums (min and max) is enough when every intermediate value is reachable (Zero Path)","Step-count DP on grids: dp[k][i][j] = best walk of exactly k steps","Counting monotone paths that avoid k obstacles: sort the obstacles and dp[i] = paths to obstacle i avoiding earlier ones (binomials + inclusion-exclusion), O(k^2)"],"resources":[{"title":"Paths on Grids","url":"https://usaco.guide/gold/paths-grids","kind":"usaco","where":"USACO Guide Gold","minutes":35},{"title":"CPH 7.3 Paths in a grid","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 7.3 (p. 71)","minutes":10},{"title":"Finding the largest zero submatrix","url":"https://cp-algorithms.com/dynamic_programming/zero_matrix.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"1766C","src":"cf","name":"Hamiltonian Wall","rating":1300,"from":"curated"},{"id":"1234C","src":"cf","name":"Pipes","rating":1500,"from":"curated"},{"id":"429B","src":"cf","name":"Working out","rating":1600,"from":"curated"},{"id":"1695C","src":"cf","name":"Zero Path","rating":1700,"from":"curated"},{"id":"1517D","src":"cf","name":"Explorer Space","rating":1800,"from":"curated"},{"id":"1680E","src":"cf","name":"Moving Chips","rating":2000,"from":"curated"},{"id":"559C","src":"cf","name":"Gerald and Giant Chess","rating":2200,"from":"curated"},{"id":"1739E","src":"cf","name":"Cleaning Robot","rating":2400,"from":"curated"},{"id":"cses-1638","src":"cses","name":"Grid Paths","from":"usaco-guide"},{"id":"cses-3359","src":"cses","name":"Minimal Grid Path","from":"usaco-guide"},{"id":"cses-1078","src":"cses","name":"Grid Paths II","from":"curated"}]},{"id":"dp-coin-unbounded","name":"Coin problems & unbounded knapsack","tier":1300,"order":3,"prereq":["dp-intro"],"summary":"Coin problems ask for the minimum number of coins / number of ways to form a sum when each coin can be used any number of times. Counting ordered sequences (compositions) and unordered multisets needs different loop orders. Recognise it when items are reusable and the target is a sum/length.","learn":["Minimum coins: dp[x] = min over coins c of dp[x-c] + 1; greedy is wrong for arbitrary coin sets","Ordered ways (sequences): outer loop over x, inner over coins","Unordered ways (combinations): outer loop over coins, inner over x ascending - each multiset counted once","Unbounded knapsack: iterate capacity ascending so an item can be reused","Unreachable states: initialise with INF / -INF and guard transitions","Recognise disguised coins: cut a ribbon into pieces of length a, b, c; write n as a sum of palindromes / 2020s and 2021s"],"resources":[{"title":"Knapsack DP","url":"https://usaco.guide/gold/knapsack","kind":"usaco","where":"USACO Guide Gold","minutes":45},{"title":"CPH 7.1 Coin problem","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 7.1 (p. 65)","minutes":25},{"title":"Knapsack Problem (complete knapsack section)","url":"https://cp-algorithms.com/dynamic_programming/knapsack.html","kind":"cpalgo","where":"cp-algorithms","minutes":25}],"problems":[{"id":"1475B","src":"cf","name":"New Year's Number","rating":900,"from":"curated"},{"id":"1934B","src":"cf","name":"Yet Another Coin Problem","rating":1200,"from":"curated"},{"id":"189A","src":"cf","name":"Cut Ribbon","rating":1300,"from":"curated"},{"id":"1673C","src":"cf","name":"Palindrome Basis","rating":1500,"from":"curated"},{"id":"283C","src":"cf","name":"Coin Troubles","rating":2100,"from":"curated"},{"id":"cses-1634","src":"cses","name":"Minimizing Coins","from":"usaco-guide"},{"id":"cses-1635","src":"cses","name":"Coin Combinations I","from":"usaco-guide"},{"id":"cses-1636","src":"cses","name":"Coin Combinations II","from":"usaco-guide"}]},{"id":"dp-multistate","name":"Extra state dimensions (last choice, flags, counts)","tier":1500,"order":4,"prereq":["dp-intro"],"summary":"Many problems need more than dp[i]: you add a dimension for the last action taken, how many operations were used, a remainder, or a boolean flag ('already started/finished the special segment'). Recognise it when the best choice at i depends on something about the past that a single number cannot summarise but that has few possible values.","learn":["Ask 'what do I need to remember about the prefix to decide the next step?' - each such fact becomes a dimension","Finite-state machine DP: states like before/inside/after a chosen segment (e.g. multiply one subarray by x, Kadane with phases)","dp[i][last] for colouring / no-two-equal-adjacent constraints; dp[i][k] for 'used k operations so far'","Remainder dimension: dp[i][r] with r = sum mod m","Memory: roll arrays (keep only dp[i-1]) when the state space is n x big","Keep the number of states x transitions under ~1e8","Circular arrays: fix the state of the first element (try each option) and force the last element to be consistent, or double the array"],"resources":[{"title":"Introduction to DP","url":"https://usaco.guide/gold/intro-dp","kind":"usaco","where":"USACO Guide Gold","minutes":40},{"title":"CPH 7.1 Coin problem (state design)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 7.1 (p. 65)","minutes":15},{"title":"AtCoder Educational DP Contest (26 classic DP tasks)","url":"https://atcoder.jp/contests/dp/tasks","kind":"other","where":"AtCoder DP contest","minutes":60}],"problems":[{"id":"1105C","src":"cf","name":"Ayoub and Lost Array","rating":1500,"from":"curated"},{"id":"1498C","src":"cf","name":"Planar Reflections","rating":1600,"from":"curated"},{"id":"1476C","src":"cf","name":"Longest Simple Cycle","rating":1600,"from":"curated"},{"id":"1324E","src":"cf","name":"Sleeping Schedule","rating":1700,"from":"curated"},{"id":"1392D","src":"cf","name":"Omkar and Bed Wars","rating":1700,"from":"curated"},{"id":"1286A","src":"cf","name":"Garland","rating":1800,"from":"curated"},{"id":"1221D","src":"cf","name":"Make The Fence Great Again","rating":1800,"from":"curated"},{"id":"1155D","src":"cf","name":"Beautiful Array","rating":1900,"from":"curated"},{"id":"1197D","src":"cf","name":"Yet Another Subarray Problem","rating":1900,"from":"curated"},{"id":"1799D1","src":"cf","name":"Hot Start Up (easy version)","rating":1900,"from":"curated"},{"id":"1012C","src":"cf","name":"Hills","rating":1900,"from":"curated"},{"id":"1077F1","src":"cf","name":"Pictures with Kittens (easy version)","rating":1900,"from":"curated"},{"id":"1433F","src":"cf","name":"Zero Remainder Sum","rating":2100,"from":"curated"},{"id":"cses-1746","src":"cses","name":"Array Description","from":"usaco-guide"},{"id":"cses-2413","src":"cses","name":"Counting Towers","from":"curated"}]},{"id":"dp-lis","name":"Longest increasing subsequence","tier":1500,"order":5,"prereq":["dp-intro","@bs-sorted"],"summary":"LIS: the longest strictly increasing subsequence. O(n^2) dp[i] = 1 + max dp[j] (j<i, a_j<a_i), or O(n log n) by keeping the smallest tail for each length with binary search (or a BIT over values). Many problems reduce to LIS after sorting or transforming (Dilworth: minimum number of non-increasing chains = LIS).","learn":["O(n^2) definition first; then tails[] + lower_bound for O(n log n)","Strict vs non-decreasing: lower_bound vs upper_bound","BIT / segment tree over compressed values gives LIS ending at each i and counts of LIS","Which elements belong to some / every LIS: combine LIS ending at i and starting at i","2D LIS (envelopes): sort by first key asc and second desc, then LIS on the second","Dilworth: partition into fewest decreasing sequences = length of longest increasing one","Minimum changes to make an array increasing: transform a_i - i and use non-decreasing LIS"],"resources":[{"title":"Longest Increasing Subsequence","url":"https://usaco.guide/gold/lis","kind":"usaco","where":"USACO Guide Gold","minutes":35},{"title":"CPH 7.2 Longest increasing subsequence","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 7.2 (p. 70)","minutes":10},{"title":"Longest increasing subsequence","url":"https://cp-algorithms.com/sequences/longest_increasing_subsequence.html","kind":"cpalgo","where":"cp-algorithms","minutes":25}],"problems":[{"id":"340D","src":"cf","name":"Bubble Sort Graph","rating":1500,"from":"curated"},{"id":"977F","src":"cf","name":"Consecutive Subsequence","rating":1700,"from":"usaco-guide"},{"id":"1582F1","src":"cf","name":"Korney Korneevich and XOR (easy version)","rating":1800,"from":"usaco-guide"},{"id":"1296E2","src":"cf","name":"String Coloring (hard version)","rating":2000,"from":"curated"},{"id":"486E","src":"cf","name":"LIS of Sequence","rating":2200,"from":"curated"},{"id":"1437E","src":"cf","name":"Make It Increasing","rating":2200,"from":"curated"},{"id":"650D","src":"cf","name":"Zip-line","rating":2600,"from":"curated"},{"id":"cses-1145","src":"cses","name":"Increasing Subsequence","from":"usaco-guide"}]},{"id":"dp-lcs-edit","name":"LCS, edit distance & two-sequence DP","tier":1500,"order":6,"prereq":["dp-grid"],"summary":"DP over two (or three) sequences with state dp[i][j] = answer for prefixes a[0..i), b[0..j). Longest common subsequence, edit (Levenshtein) distance, interleaving of strings, shortest common supersequence. Recognise it when two strings/arrays are aligned or merged.","learn":["LCS: dp[i][j] = dp[i-1][j-1]+1 if a_i=b_j else max(dp[i-1][j], dp[i][j-1])","Edit distance: insert / delete / replace transitions, dp[i][0]=i, dp[0][j]=j","Interleaving / merging two strings into a third: dp[i][j] over used prefixes","Variants: maximise 4*LCS - |c| - |d| over substrings (reset to 0 like Kadane)","Extra dimension for bracket balance (shortest regular supersequence) or for a lucky substring automaton","LCS of permutations reduces to DAG longest path / LIS","Precompute next-occurrence tables nxt[i][c] for subsequence matching against several patterns"],"resources":[{"title":"Paths on Grids (LCS section)","url":"https://usaco.guide/gold/paths-grids","kind":"usaco","where":"USACO Guide Gold","minutes":35},{"title":"CPH 7.5 Edit distance","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 7.5 (p. 74)","minutes":10},{"title":"AtCoder Educational DP Contest (26 classic DP tasks)","url":"https://atcoder.jp/contests/dp/tasks","kind":"other","where":"AtCoder DP contest","minutes":60}],"problems":[{"id":"2050E","src":"cf","name":"Three Strings","rating":1500,"from":"curated"},{"id":"1446B","src":"cf","name":"Catching Cheaters","rating":1800,"from":"curated"},{"id":"463D","src":"cf","name":"Gargari and Permutations","rating":1900,"from":"curated"},{"id":"346B","src":"cf","name":"Lucky Common Subsequence","rating":2000,"from":"curated"},{"id":"1272F","src":"cf","name":"Two Bracket Sequences","rating":2200,"from":"curated"},{"id":"1303E","src":"cf","name":"Erase Subsequences","rating":2200,"from":"curated"},{"id":"1149B","src":"cf","name":"Three Religions","rating":2200,"from":"curated"},{"id":"10D","src":"cf","name":"LCIS","rating":2800,"from":"usaco-guide"},{"id":"cses-1639","src":"cses","name":"Edit Distance","from":"usaco-guide"},{"id":"cses-3403","src":"cses","name":"Longest Common Subsequence","from":"curated"}]},{"id":"dp-strings","name":"DP on strings & subsequence counting","tier":1500,"order":7,"prereq":["dp-lcs-edit"],"summary":"Counting or optimising over subsequences/substrings of one string: count occurrences of a pattern as a subsequence, count distinct subsequences, choose characters to change so a pattern appears, or match against a KMP automaton. Recognise it by 'subsequence', 'number of ways the string can contain ...', or replacement characters like '?'.","learn":["Count pattern 'abc' as a subsequence: dp over prefix length of the pattern matched so far","'?' characters: multiply by alphabet choices (3^k) and keep counts per matched prefix","Distinct subsequences: subtract the contribution of the previous occurrence of the same character","Automaton DP: state = KMP / Aho prefix-function state; dp[i][state] counts strings avoiding / containing a pattern","Partition a string into pieces with costs (compress with repeated substrings via LCP table)","Add characters to the front or back: interval-like dp over the matched window"],"resources":[{"title":"Introduction to DP","url":"https://usaco.guide/gold/intro-dp","kind":"usaco","where":"USACO Guide Gold","minutes":30},{"title":"Prefix function (building the automaton)","url":"https://cp-algorithms.com/string/prefix-function.html","kind":"cpalgo","where":"cp-algorithms","minutes":30},{"title":"CPH 26 String algorithms","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 26 (p. 243)","minutes":20}],"problems":[{"id":"1178B","src":"cf","name":"WOW Factor","rating":1300,"from":"curated"},{"id":"1084C","src":"cf","name":"The Fair Nut and String","rating":1500,"from":"curated"},{"id":"2005C","src":"cf","name":"Lazy Narek","rating":1800,"from":"curated"},{"id":"1096D","src":"cf","name":"Easy Problem","rating":1800,"from":"curated"},{"id":"1183H","src":"cf","name":"Subsequences (hard version)","rating":1900,"from":"curated"},{"id":"1426F","src":"cf","name":"Number of Subsequences","rating":2000,"from":"curated"},{"id":"1409F","src":"cf","name":"Subsequences of Length Two","rating":2100,"from":"curated"},{"id":"1163D","src":"cf","name":"Mysterious Code","rating":2100,"from":"curated"},{"id":"1120C","src":"cf","name":"Compress String","rating":2100,"from":"curated"},{"id":"1336C","src":"cf","name":"Kaavi and Magic Spell","rating":2200,"from":"curated"},{"id":"1015F","src":"cf","name":"Bracket Substring","rating":2300,"from":"curated"}]},{"id":"dp-partition","name":"Partition into segments","tier":1500,"order":8,"prereq":["dp-intro"],"summary":"Split an array (or string) into consecutive segments, each with a cost or validity condition: dp[i] = best over the last segment's start j of dp[j] + cost(j, i). The core of many 'divide into groups/blocks' problems; later optimised with prefix structures, deques, CHT or divide & conquer.","learn":["dp[i] over prefixes; transition enumerates the last segment [j, i)","Block given by its first element (length = a_j): forward transitions dp[j] -> dp[j + a_j + 1]","Sort first so groups are contiguous (teams with bounded difference), then partition","Limit on the number of segments: dp[k][i] - O(k n^2) baseline before optimisation","Delete segments with equal endpoints: keep best dp value per value of a_j","Know the follow-up optimisations: prefix max, monotone queue, segment tree, CHT, D&C, Aliens"],"resources":[{"title":"Introduction to DP","url":"https://usaco.guide/gold/intro-dp","kind":"usaco","where":"USACO Guide Gold","minutes":30},{"title":"Dynamic Programming Optimizations (overview table)","url":"https://codeforces.com/blog/entry/8219","kind":"cf-blog","where":"Codeforces blog","minutes":20},{"title":"AtCoder Educational DP Contest (26 classic DP tasks)","url":"https://atcoder.jp/contests/dp/tasks","kind":"other","where":"AtCoder DP contest","minutes":60}],"problems":[{"id":"1842C","src":"cf","name":"Tenzing and Balls","rating":1500,"from":"usaco-guide"},{"id":"1881E","src":"cf","name":"Block Sequence","rating":1500,"from":"curated"},{"id":"1741E","src":"cf","name":"Sending a Sequence Over the Network","rating":1600,"from":"curated"},{"id":"1625C","src":"cf","name":"Road Optimization","rating":1700,"from":"curated"},{"id":"1133E","src":"cf","name":"K Balanced Teams","rating":1800,"from":"curated"},{"id":"1256E","src":"cf","name":"Yet Another Division Into Teams","rating":2000,"from":"curated"},{"id":"1699D","src":"cf","name":"Almost Triple Deletions","rating":2300,"from":"curated"}]},{"id":"dp-knapsack-01","name":"0-1 knapsack","tier":1600,"order":9,"prereq":["dp-coin-unbounded"],"summary":"Choose a subset of items, each used at most once, to maximise value under a capacity. dp[w] = best value with total weight w, iterating w downwards so each item is used once. Recognise it whenever you pick a subset subject to a sum constraint and n x capacity is small.","learn":["dp[i][w] = best using the first i items with weight w; 1D version iterates w from high to low","Swap value and weight when weights are huge but values are small (dp[v] = min weight to get value v)","Extra dimensions: count of chosen items, two resources (2D knapsack), sum mod m","Pre-process each item first (e.g. cost of turning 1 into b_i by BFS/DP) then knapsack over the results","Restrict the useful capacity (e.g. answer bounded by sum of something small, pigeonhole mod m)","Recover the chosen set with parent pointers or a boolean take[i][w] table","Order trick: when items must be taken in time order with money that accumulates (Money Buys Happiness), dp over value with min cost is the right dimension"],"resources":[{"title":"Knapsack DP","url":"https://usaco.guide/gold/knapsack","kind":"usaco","where":"USACO Guide Gold","minutes":45},{"title":"CPH 7.4 Knapsack problems","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 7.4 (p. 72)","minutes":20},{"title":"Knapsack Problem","url":"https://cp-algorithms.com/dynamic_programming/knapsack.html","kind":"cpalgo","where":"cp-algorithms","minutes":25},{"title":"AtCoder Educational DP Contest (26 classic DP tasks)","url":"https://atcoder.jp/contests/dp/tasks","kind":"other","where":"AtCoder DP contest","minutes":60}],"problems":[{"id":"1633D","src":"cf","name":"Make Them Equal","rating":1600,"from":"curated"},{"id":"1974E","src":"cf","name":"Money Buys Happiness","rating":1800,"from":"curated"},{"id":"366C","src":"cf","name":"Dima and Salad","rating":1900,"from":"curated"},{"id":"19B","src":"cf","name":"Checkout Assistant","rating":1900,"from":"curated"},{"id":"730J","src":"cf","name":"Bottles","rating":1900,"from":"curated"},{"id":"1458B","src":"cf","name":"Glass Half Spilled","rating":2000,"from":"usaco-guide"},{"id":"837D","src":"cf","name":"Round Subset","rating":2100,"from":"usaco-guide"},{"id":"cses-1158","src":"cses","name":"Book Shop","from":"usaco-guide"}]},{"id":"dp-subset-sum","name":"Subset sum & partition into two sets","tier":1600,"order":10,"prereq":["dp-knapsack-01"],"summary":"Boolean knapsack: which sums are reachable using a subset of the items, or in how many ways. Used to split a set into two equal halves, check feasibility of a target sum, or decide which values a structure can produce. Recognise it when only reachability of sums matters, not value.","learn":["reach[s] |= reach[s - a_i], iterating s downward; counting version adds ways","Equal partition: total must be even and total/2 reachable","Merge of permutations / decomposition into blocks often reduces to subset sum of block lengths","Counting partitions into two equal sets: divide by 2 (or fix the first element)","Sum bound S makes it O(n S); with sqrt distinct values or bitsets it becomes faster (see bitset & bounded knapsack)","Removing one element to break a perfect partition: use parity / gcd arguments together with the DP","Counting knapsack is reversible: to remove item w from a ways[] table run ways[s] -= ways[s-w] for s ascending (Destroy the Colony)"],"resources":[{"title":"Knapsack DP","url":"https://usaco.guide/gold/knapsack","kind":"usaco","where":"USACO Guide Gold","minutes":45},{"title":"CPH 7.4 Knapsack problems (possible sums)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 7.4 (p. 72)","minutes":20}],"problems":[{"id":"1516C","src":"cf","name":"Baby Ehab Partitions Again","rating":1700,"from":"curated"},{"id":"1381B","src":"cf","name":"Unmerge","rating":1800,"from":"curated"},{"id":"1856E1","src":"cf","name":"PermuTree (easy version)","rating":1800,"from":"curated"},{"id":"577B","src":"cf","name":"Modulo Sum","rating":1900,"from":"curated"},{"id":"687C","src":"cf","name":"The Values You Can Make","rating":1900,"from":"usaco-guide"},{"id":"1032E","src":"cf","name":"The Unbearable Lightness of Weights","rating":2100,"from":"curated"},{"id":"1111D","src":"cf","name":"Destroy the Colony","rating":2600,"from":"curated"},{"id":"cses-1745","src":"cses","name":"Money Sums","from":"usaco-guide"},{"id":"cses-1093","src":"cses","name":"Two Sets II","from":"usaco-guide"}]},{"id":"dp-dag","name":"DP on DAGs & graphs","tier":1600,"order":11,"prereq":["dp-intro","@dag-toposort"],"summary":"Every DP is a DAG of states; explicit graph problems on a DAG (longest path, number of paths, best path value) are solved by processing vertices in topological order. Graphs with cycles need SCC condensation or a Dijkstra-like order. Recognise it by directed acyclic structure, 'number of routes', or relaxations in a fixed order.","learn":["Topological order (Kahn / DFS) then dp[v] from predecessors; memoised DFS also works","Longest path, number of shortest paths, min/max path weight on DAGs","State = (vertex, extra info): (vertex, letter) for most frequent letter on a path, (vertex, used k edges)","Detect cycles: if a cycle is reachable the answer may be infinite","Shortest-path DAG: dp along the order of Dijkstra/BFS distances","Cycles: condense SCCs first, then DP on the condensation DAG"],"resources":[{"title":"CPH 16.2 Directed graphs - Dynamic programming","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 16.2 (p. 151)","minutes":15},{"title":"Topological Sort (DP section)","url":"https://usaco.guide/gold/toposort","kind":"usaco","where":"USACO Guide Gold","minutes":35}],"problems":[{"id":"919D","src":"cf","name":"Substring","rating":1700,"from":"usaco-guide"},{"id":"721C","src":"cf","name":"Journey","rating":1800,"from":"curated"},{"id":"1674G","src":"cf","name":"Remove Directed Edges","rating":2000,"from":"curated"},{"id":"1472G","src":"cf","name":"Moving to the Capital","rating":2100,"from":"usaco-guide"},{"id":"1137C","src":"cf","name":"Museums Tour","rating":2500,"from":"curated"},{"id":"cses-1680","src":"cses","name":"Longest Flight Route","from":"usaco-guide"},{"id":"cses-1681","src":"cses","name":"Game Routes","from":"usaco-guide"},{"id":"cses-1202","src":"cses","name":"Investigation","from":"usaco-guide"}]},{"id":"dp-games","name":"Game DP (win/lose states, minimax)","tier":1500,"order":12,"prereq":["dp-intro","dp-dag"],"summary":"Two-player perfect-information games solved by DP over positions: a state is winning if some move leads to a losing state; scores use minimax (max of my gain minus the opponent's best). Recognise it by 'both play optimally' with a small number of positions; for sums of independent games use Sprague-Grundy.","learn":["Winning/losing positions computed in reverse topological order of the game graph","Minimax for scores: dp[state] = max over moves of (gain - dp[next]) (Removal Game)","Interval game states dp[l][r] when players take from the ends","Games on DAG / permutations: process positions in decreasing value order","Grundy numbers and the mex rule for sums of games; find patterns by brute force on small cases","Bitmask of already-used moves when a pile cannot repeat a move size"],"resources":[{"title":"CPH 25 Game theory (game states, Nim, Sprague-Grundy)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 25 (p. 235)","minutes":30},{"title":"Game Theory","url":"https://usaco.guide/adv/game-theory","kind":"usaco","where":"USACO Guide Advanced","minutes":40},{"title":"Games on arbitrary graphs","url":"https://cp-algorithms.com/game_theory/games_on_graphs.html","kind":"cpalgo","where":"cp-algorithms","minutes":20},{"title":"Sprague-Grundy theorem. Nim","url":"https://cp-algorithms.com/game_theory/sprague-grundy-nim.html","kind":"cpalgo","where":"cp-algorithms","minutes":30}],"problems":[{"id":"1382B","src":"cf","name":"Sequential Nim","rating":1100,"from":"curated"},{"id":"1738C","src":"cf","name":"Even Number Addicts","rating":1500,"from":"curated"},{"id":"1033C","src":"cf","name":"Permutation Game","rating":1600,"from":"curated"},{"id":"917B","src":"cf","name":"MADMAX","rating":1700,"from":"curated"},{"id":"1728D","src":"cf","name":"Letter Picking","rating":1800,"from":"curated"},{"id":"1987D","src":"cf","name":"World is Mine","rating":1800,"from":"curated"},{"id":"768E","src":"cf","name":"Game of Stones","rating":2100,"from":"usaco-guide"},{"id":"1628D1","src":"cf","name":"Game on Sum (Easy Version)","rating":2100,"from":"curated"},{"id":"2005E1","src":"cf","name":"Subtangle Game (Easy Version)","rating":2100,"from":"curated"},{"id":"850C","src":"cf","name":"Arpa and a game with Mojtaba","rating":2200,"from":"usaco-guide"},{"id":"cses-1729","src":"cses","name":"Stick Game","from":"curated"},{"id":"cses-1097","src":"cses","name":"Removal Game","from":"curated"},{"id":"cses-1730","src":"cses","name":"Nim Game I","from":"usaco-guide"}]},{"id":"dp-trees","name":"DP on trees","tier":1600,"order":13,"prereq":["dp-intro","@trees-traversal"],"summary":"Root the tree and compute dp[v] from the dp values of v's children in a post-order DFS: maximum matching, independent set, best path through v, counting colourings. Recognise it by a tree where the answer for a subtree only depends on a small summary of each child subtree.","learn":["dp[v][0/1] = v taken / not taken (independent set, matching, vertex cover)","Best path through v = top two child values combined (diameter-like)","Counting: multiply child contributions; use dp[v][state] with a small state set","Leaves vs internal nodes in min/max games on trees (Serval and Rooted Tree)","Process children with sizes for O(n) total; avoid recursion depth issues (iterative DFS for n=2e5)","Depth-indexed DP (dp over levels) when moves go between consecutive depths"],"resources":[{"title":"DP on Trees - Introduction","url":"https://usaco.guide/gold/dp-trees","kind":"usaco","where":"USACO Guide Gold","minutes":40},{"title":"DP on Trees Tutorial","url":"https://codeforces.com/blog/entry/20935","kind":"cf-blog","where":"Codeforces blog","minutes":30},{"title":"CPH 14 Tree algorithms (14.2 diameter, 14.3 all longest paths)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 14 (p. 133)","minutes":25}],"problems":[{"id":"982C","src":"cf","name":"Cut 'em all!","rating":1500,"from":"curated"},{"id":"1689C","src":"cf","name":"Infected Tree","rating":1600,"from":"usaco-guide"},{"id":"1528A","src":"cf","name":"Parsa's Humongous Tree","rating":1600,"from":"usaco-guide"},{"id":"2070D","src":"cf","name":"Tree Jumps","rating":1600,"from":"curated"},{"id":"1693B","src":"cf","name":"Fake Plastic Trees","rating":1700,"from":"curated"},{"id":"1083A","src":"cf","name":"The Fair Nut and the Best Path","rating":1800,"from":"curated"},{"id":"161D","src":"cf","name":"Distance in Tree","rating":1800,"from":"usaco-guide"},{"id":"1929D","src":"cf","name":"Sasha and a Walk in the City","rating":1900,"from":"curated"},{"id":"1153D","src":"cf","name":"Serval and Rooted Tree","rating":1900,"from":"curated"},{"id":"1988D","src":"cf","name":"The Omnipotent Monster Killer","rating":2000,"from":"curated"},{"id":"1249F","src":"cf","name":"Maximum Weight Subset","rating":2200,"from":"curated"},{"id":"1032F","src":"cf","name":"Vasya and Maximum Matching","rating":2400,"from":"curated"},{"id":"cses-1674","src":"cses","name":"Subordinates","from":"usaco-guide"},{"id":"cses-1130","src":"cses","name":"Tree Matching","from":"usaco-guide"}]},{"id":"dp-counting","name":"Counting DP (combinatorial)","tier":1600,"order":14,"prereq":["dp-multistate","@nt-modular-arithmetic"],"summary":"Count arrays, strings, permutations or structures with constraints by DP over positions/values, modulo a prime. Often combined with combinatorics (binomials) or the observation that the structure is determined by few parameters. Recognise it by 'count the number of ... modulo 998244353'.","learn":["Choose the order of construction that makes constraints local (by position, by value, by length)","Count good subsequences: dp over values with divisor transitions (Multiplicity)","Use 'dp[i] = number of ways to finish' when the first element determines a block length","Fibonacci-like structure hidden in grids/strings (Ivan the Fool)","Combine dp with binomial coefficients for independent parts; avoid double counting with canonical forms","Mod arithmetic: add with mod each step, subtract with +mod"],"resources":[{"title":"Combinatorics","url":"https://usaco.guide/gold/combo","kind":"usaco","where":"USACO Guide Gold","minutes":40},{"title":"CPH 22 Combinatorics","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 22 (p. 207)","minutes":30}],"problems":[{"id":"1452D","src":"cf","name":"Radio Towers","rating":1600,"from":"curated"},{"id":"1288C","src":"cf","name":"Two Arrays","rating":1600,"from":"curated"},{"id":"1239A","src":"cf","name":"Ivan the Fool and the Probability Theory","rating":1700,"from":"curated"},{"id":"1061C","src":"cf","name":"Multiplicity","rating":1700,"from":"curated"},{"id":"1528B","src":"cf","name":"Kavi on Pairing Duty","rating":1700,"from":"curated"},{"id":"1000D","src":"cf","name":"Yet Another Problem On a Subsequence","rating":1900,"from":"curated"},{"id":"1606E","src":"cf","name":"Arena","rating":2100,"from":"usaco-guide"},{"id":"1027E","src":"cf","name":"Inverse Coloring","rating":2100,"from":"curated"},{"id":"1767C","src":"cf","name":"Count Binary Strings","rating":2100,"from":"curated"},{"id":"1920E","src":"cf","name":"Counting Binary Strings","rating":2100,"from":"curated"}]},{"id":"dp-probability","name":"Probability & expected value DP","tier":1700,"order":15,"prereq":["dp-intro","@prob-basics","@nt-modular-inverse"],"summary":"dp over states holding a probability, or an expected value computed backwards (E[state] = cost + sum p * E[next]). Uses linearity of expectation to split a complicated quantity into simple indicator sums. Recognise it by 'probability', 'expected number of', and answers modulo a prime (use modular inverses).","learn":["Forward DP of probabilities: dp[t][state] = probability of being in state after t steps","Backward DP of expectations from terminal states; self-loops solved algebraically (E = (1 + sum others)/(1-p))","Linearity of expectation: E[sum] = sum of E[indicator]; contribution technique","Expected squares / quadratic terms: keep E[len] and E[len^2] together (Let's Play Osu!)","Output p/q mod 998244353 via modular inverse (Fermat)","Markov chains: matrix of transition probabilities; Gaussian elimination for general cycles"],"resources":[{"title":"CPH 24 Probability (24.3 random variables, 24.4 Markov chains)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 24 (p. 225)","minutes":30},{"title":"Sums and Expected Value - part 1","url":"https://codeforces.com/blog/entry/62690","kind":"cf-blog","where":"Codeforces blog","minutes":25},{"title":"Sums and Expected Value - part 2","url":"https://codeforces.com/blog/entry/62792","kind":"cf-blog","where":"Codeforces blog","minutes":25}],"problems":[{"id":"839C","src":"cf","name":"Journey","rating":1500,"from":"usaco-guide"},{"id":"518D","src":"cf","name":"Ilya and Escalator","rating":1700,"from":"curated"},{"id":"148D","src":"cf","name":"Bag of mice","rating":1800,"from":"curated"},{"id":"540D","src":"cf","name":"Bad Luck Island","rating":1900,"from":"curated"},{"id":"235B","src":"cf","name":"Let's Play Osu!","rating":2000,"from":"curated"},{"id":"1753C","src":"cf","name":"Wish I Knew How to Sort","rating":2000,"from":"curated"},{"id":"1265E","src":"cf","name":"Beautiful Mirrors","rating":2100,"from":"curated"},{"id":"1778D","src":"cf","name":"Flexible String Revisit","rating":2100,"from":"curated"},{"id":"1097D","src":"cf","name":"Makoto and a Blackboard","rating":2200,"from":"curated"},{"id":"1139D","src":"cf","name":"Steps to One","rating":2300,"from":"curated"},{"id":"1540B","src":"cf","name":"Tree Array","rating":2300,"from":"curated"},{"id":"cses-1725","src":"cses","name":"Dice Probability","from":"curated"},{"id":"cses-1726","src":"cses","name":"Moving Robots","from":"curated"}]},{"id":"dp-interval","name":"Interval (range) DP","tier":1800,"order":16,"prereq":["dp-intro"],"summary":"dp[l][r] = answer for the subarray/substring a[l..r], computed from smaller intervals, usually by choosing a split point or what happens to the endpoints. Matrix-chain, removing/merging adjacent elements, palindromes, bracket colouring. Recognise it when operations merge or delete contiguous blocks and n is about 500 or less.","learn":["Iterate by increasing length (or l from n-1 down to 0, r from l up)","Split transition dp[l][r] = min over k of dp[l][k] + dp[k+1][r] + cost -> O(n^3)","Endpoint transition: the first element is removed alone or together with some equal element k","Extra dimension for 'how many equal characters are glued to the left' (Vasya and Binary String)","Compress equal adjacent elements first (Flood Fill)","Bracket sequences: interval over the matching pair, with colours of endpoints as extra state","2D cutting problems (rectangle cutting) generalise the split idea","Nested-segment selection: compress coordinates, dp over [l, r] using only the segments inside it"],"resources":[{"title":"Range DP","url":"https://usaco.guide/gold/dp-ranges","kind":"usaco","where":"USACO Guide Gold","minutes":40},{"title":"AtCoder Educational DP Contest (26 classic DP tasks)","url":"https://atcoder.jp/contests/dp/tasks","kind":"other","where":"AtCoder DP contest","minutes":60}],"problems":[{"id":"245H","src":"cf","name":"Queries for Number of Palindromes","rating":1800,"from":"usaco-guide"},{"id":"1509C","src":"cf","name":"The Sports Festival","rating":1800,"from":"usaco-guide"},{"id":"1114D","src":"cf","name":"Flood Fill","rating":1900,"from":"usaco-guide"},{"id":"607B","src":"cf","name":"Zuma","rating":1900,"from":"usaco-guide"},{"id":"149D","src":"cf","name":"Coloring Brackets","rating":1900,"from":"curated"},{"id":"1132F","src":"cf","name":"Clear the String","rating":2000,"from":"curated"},{"id":"1025D","src":"cf","name":"Recovering BST","rating":2100,"from":"curated"},{"id":"1312E","src":"cf","name":"Array Shrinking","rating":2100,"from":"curated"},{"id":"1399F","src":"cf","name":"Yet Another Segments Subset","rating":2300,"from":"curated"},{"id":"1107E","src":"cf","name":"Vasya and Binary String","rating":2400,"from":"curated"},{"id":"cses-1080","src":"cses","name":"Empty String","from":"usaco-guide"},{"id":"cses-1744","src":"cses","name":"Rectangle Cutting","from":"curated"}]},{"id":"dp-rerooting","name":"Rerooting (all roots DP)","tier":1800,"order":17,"prereq":["dp-trees"],"summary":"Compute a tree DP for every vertex as the root in O(n): first a down pass (subtree answers), then an up pass that passes each child the answer of 'the rest of the tree'. Recognise it when the question asks the answer for each vertex as root/center, or the best root.","learn":["Down pass: sub[v] from children; up pass: up[c] from up[v] and siblings","Moving the root across edge (v,c) changes the answer by an O(1) formula (Tree with Maximum Cost: res(c) = res(v) + total - 2*size(c))","Non-invertible combine (max): prefix and suffix maxima of children","Sum of distances to all vertices, eccentricity / farthest vertex for every node","Edge direction costs (Choosing Capital): count reversed edges on the root path"],"resources":[{"title":"DP on Trees - Solving For All Roots","url":"https://usaco.guide/gold/all-roots","kind":"usaco","where":"USACO Guide Gold","minutes":35},{"title":"CPH 14.3 All longest paths","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 14.3 (p. 137)","minutes":10},{"title":"Problems related to rerooting","url":"https://codeforces.com/blog/entry/68142","kind":"cf-blog","where":"Codeforces blog","minutes":15}],"problems":[{"id":"219D","src":"cf","name":"Choosing Capital for Treeland","rating":1700,"from":"curated"},{"id":"1822F","src":"cf","name":"Gardening Friends","rating":1700,"from":"curated"},{"id":"1324F","src":"cf","name":"Maximum White Subtree","rating":1800,"from":"curated"},{"id":"1092F","src":"cf","name":"Tree with Maximum Cost","rating":1900,"from":"curated"},{"id":"1882D","src":"cf","name":"Tree XOR","rating":1900,"from":"curated"},{"id":"337D","src":"cf","name":"Book of Evil","rating":2000,"from":"curated"},{"id":"1187E","src":"cf","name":"Tree Painting","rating":2100,"from":"usaco-guide"},{"id":"543D","src":"cf","name":"Road Improvement","rating":2300,"from":"curated"},{"id":"cses-1132","src":"cses","name":"Tree Distances I","from":"usaco-guide"},{"id":"cses-1133","src":"cses","name":"Tree Distances II","from":"usaco-guide"}]},{"id":"dp-bitmask","name":"Bitmask DP","tier":1800,"order":18,"prereq":["dp-intro","@bit-basics"],"summary":"When n <= ~20, a subset of items can be the DP state stored as a bitmask: dp[mask] or dp[mask][last]. Travelling salesman / Hamiltonian paths, assignment, packing into bins, choosing a subset of roles. Recognise it by tiny n (n <= 20, or k <= 20 'types') and a set-dependent cost.","learn":["dp[mask][v] = best path visiting exactly mask and ending at v -> O(2^n n^2)","Assignment / ordering: dp[mask] where popcount(mask) = position being filled","Packing into bins (Elevator Rides): store (rides, current load) as a pair in dp[mask]","Enumerate submasks with s = (s-1) & mask; all masks + submasks is O(3^n)","Bitmask over small primes / parity vectors (Square Subsets)","Bitmask over characters / roles combined with sorting (Team Building)","Counting cycles: fix the lowest vertex as start to avoid double counting"],"resources":[{"title":"Bitmask DP","url":"https://usaco.guide/gold/dp-bitmasks","kind":"usaco","where":"USACO Guide Gold","minutes":40},{"title":"CPH 10.5 Bit manipulation - Dynamic programming","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 10.5 (p. 102)","minutes":15},{"title":"Submask enumeration","url":"https://cp-algorithms.com/algebra/all-submasks.html","kind":"cpalgo","where":"cp-algorithms","minutes":10}],"problems":[{"id":"580D","src":"cf","name":"Kefa and Dishes","rating":1800,"from":"curated"},{"id":"16E","src":"cf","name":"Fish","rating":1900,"from":"curated"},{"id":"453B","src":"cf","name":"Little Pony and Harmony Chest","rating":2000,"from":"curated"},{"id":"895C","src":"cf","name":"Square Subsets","rating":2000,"from":"curated"},{"id":"1185G1","src":"cf","name":"Playlist for Polycarp (easy version)","rating":2100,"from":"curated"},{"id":"11D","src":"cf","name":"A Simple Task","rating":2200,"from":"curated"},{"id":"1238E","src":"cf","name":"Keyboard Purchase","rating":2200,"from":"curated"},{"id":"1215E","src":"cf","name":"Marbles","rating":2200,"from":"curated"},{"id":"1316E","src":"cf","name":"Team Building","rating":2300,"from":"usaco-guide"},{"id":"1550E","src":"cf","name":"Stringforces","rating":2500,"from":"curated"},{"id":"cses-1690","src":"cses","name":"Hamiltonian Flights","from":"usaco-guide"},{"id":"cses-1653","src":"cses","name":"Elevator Rides","from":"usaco-guide"}]},{"id":"dp-prefix-opt","name":"Prefix-sum / prefix-max optimisation","tier":1900,"order":19,"prereq":["dp-partition"],"summary":"When a transition sums or maximises dp over a contiguous range of previous states (dp[i] = sum_{j in [l_i, r_i]} dp_prev[j]), keep prefix sums or prefix maxima of the previous layer to make each transition O(1). Recognise it by an O(n^3) or O(n^2 k) DP whose inner loop runs over a range.","learn":["Range-sum transitions: maintain pref[] of the previous layer, dp[i] = pref[r] - pref[l-1]","Range-max transitions with a monotone left bound: prefix max array","Process layers one at a time; reuse arrays","Difference arrays for 'add dp[j] to a range of next states' (forward transitions)","Harmonic-sum loops: jumps of length k, k+1, ... give O(n sqrt n)","Typical: lift/elevator moves, chip jumps with increasing step, values in a range"],"resources":[{"title":"Dynamic Programming Optimizations (overview table)","url":"https://codeforces.com/blog/entry/8219","kind":"cf-blog","where":"Codeforces blog","minutes":20},{"title":"CPH 9.1 Static array queries (prefix sums)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 9.1 (p. 84)","minutes":10},{"title":"Knapsack DP","url":"https://usaco.guide/gold/knapsack","kind":"usaco","where":"USACO Guide Gold","minutes":20}],"problems":[{"id":"474D","src":"cf","name":"Flowers","rating":1700,"from":"curated"},{"id":"479E","src":"cf","name":"Riding in a Lift","rating":1900,"from":"curated"},{"id":"1067A","src":"cf","name":"Array Without Local Maximums","rating":1900,"from":"curated"},{"id":"1427C","src":"cf","name":"The Hard Work of Paparazzi","rating":2000,"from":"curated"},{"id":"1716D","src":"cf","name":"Chip Move","rating":2000,"from":"curated"}]},{"id":"dp-knapsack-bounded","name":"Bounded knapsack (limited copies)","tier":1900,"order":20,"prereq":["dp-knapsack-01"],"summary":"Each item type i may be taken up to k_i times. Naive is O(W sum k_i); binary splitting turns it into O(W sum log k_i) 0-1 items, and a monotone deque per residue gives O(nW). Also the sqrt trick: a multiset with total S has only O(sqrt S) distinct values.","learn":["Binary splitting: split k into 1,2,4,...,rest so every count 0..k is representable","Monotone queue optimisation: for each remainder mod w_i, take a sliding-window max","Distinct values in a multiset with sum S are at most ~sqrt(2S) - group equal values","Bounded subset-sum reachability: track 'minimum copies used' per sum in O(nW)","Huge weights with few distinct values: scale by lcm / greedily fix most copies, then DP the rest"],"resources":[{"title":"Knapsack DP","url":"https://usaco.guide/gold/knapsack","kind":"usaco","where":"USACO Guide Gold","minutes":45},{"title":"Knapsack Problem (multiple knapsack)","url":"https://cp-algorithms.com/dynamic_programming/knapsack.html","kind":"cpalgo","where":"cp-algorithms","minutes":25},{"title":"CPH 7.4 Knapsack problems","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 7.4 (p. 72)","minutes":15}],"problems":[{"id":"106C","src":"cf","name":"Buns","rating":1700,"from":"curated"},{"id":"1132E","src":"cf","name":"Knapsack","rating":2300,"from":"curated"},{"id":"95E","src":"cf","name":"Lucky Country","rating":2500,"from":"curated"},{"id":"755F","src":"cf","name":"PolandBall and Gifts","rating":2600,"from":"curated"},{"id":"1856E2","src":"cf","name":"PermuTree (hard version)","rating":2700,"from":"curated"},{"id":"cses-1159","src":"cses","name":"Book Shop II","from":"curated"}]},{"id":"dp-digit","name":"Digit DP","tier":1900,"order":21,"prereq":["dp-intro"],"summary":"Count (or sum over) numbers in [L, R] whose decimal/binary digits satisfy a property by building the number digit by digit with a 'tight' flag (still equal to the bound's prefix). Answer = f(R) - f(L-1). Recognise it by huge ranges (1e18) and a digit-based condition.","learn":["State: position, tight flag, started (leading zeros) flag, plus property info (sum, count, remainder, last digit)","Count f(N) for numbers <= N, then f(R) - f(L-1)","Memoise only the non-tight states so they are reused across bounds","Remainder modulo lcm of digits (Beautiful Numbers: mod 2520)","Binary digit DP for bitwise constraints (XOR/AND with limits), possibly with several tight flags","Return pairs (count, sum) to compute sums of numbers instead of counts"],"resources":[{"title":"Digit DP","url":"https://usaco.guide/gold/digit-dp","kind":"usaco","where":"USACO Guide Gold","minutes":40},{"title":"Digit DP","url":"https://codeforces.com/blog/entry/53960","kind":"cf-blog","where":"Codeforces blog","minutes":20}],"problems":[{"id":"914C","src":"cf","name":"Travelling Salesman and Special Numbers","rating":1800,"from":"curated"},{"id":"1036C","src":"cf","name":"Classy Numbers","rating":1900,"from":"curated"},{"id":"628D","src":"cf","name":"Magic Numbers","rating":2200,"from":"usaco-guide"},{"id":"1073E","src":"cf","name":"Segment Sum","rating":2300,"from":"curated"},{"id":"1670F","src":"cf","name":"Jee, You See?","rating":2400,"from":"curated"},{"id":"55D","src":"cf","name":"Beautiful numbers","rating":2500,"from":"curated"},{"id":"cses-2220","src":"cses","name":"Counting Numbers","from":"usaco-guide"}]},{"id":"dp-matrix-expo","name":"Matrix exponentiation for linear DP","tier":1900,"order":22,"prereq":["dp-intro","@nt-binary-exponentiation"],"summary":"A DP whose transition is linear and identical at every step (dp_{t+1} = M dp_t) can be advanced T steps in O(k^3 log T) with fast matrix power. Also counts walks of length T in a graph and works in (min,+) semiring for shortest walks of exact length. Recognise it by T up to 1e18 and a small state count.","learn":["Write the transition as a k x k matrix; answer = M^T * initial vector","Fibonacci / linear recurrences of order k, sums of recurrences (augment with an accumulator row)","Number of walks of length T = (adjacency)^T; shortest walk with exactly T edges via (min,+) product","Exponent recurrences (product-oriented) - work modulo p-1 for exponents","Piecewise constant transitions: exponentiate each segment separately (Okabe)","Segment tree of matrices for range updates of linear recurrences"],"resources":[{"title":"Matrix Exponentiation","url":"https://usaco.guide/plat/matrix-expo","kind":"usaco","where":"USACO Guide Platinum","minutes":40},{"title":"CPH 23.2 Linear recurrences","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 23.2 (p. 220)","minutes":15},{"title":"CPH 23.3 Graphs and matrices","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 23.3 (p. 222)","minutes":10},{"title":"Number of paths of fixed length / shortest paths of fixed length","url":"https://cp-algorithms.com/graph/fixed_length_paths.html","kind":"cpalgo","where":"cp-algorithms","minutes":15}],"problems":[{"id":"691E","src":"cf","name":"Xor-sequences","rating":1900,"from":"usaco-guide"},{"id":"222E","src":"cf","name":"Decoding Genome","rating":1900,"from":"curated"},{"id":"1970E2","src":"cf","name":"Trails (Medium)","rating":2000,"from":"curated"},{"id":"1117D","src":"cf","name":"Magic Gems","rating":2100,"from":"curated"},{"id":"821E","src":"cf","name":"Okabe and El Psy Kongroo","rating":2100,"from":"curated"},{"id":"1970E3","src":"cf","name":"Trails (Hard)","rating":2200,"from":"curated"},{"id":"1182E","src":"cf","name":"Product Oriented Recurrence","rating":2300,"from":"curated"},{"id":"718C","src":"cf","name":"Sasha and Array","rating":2300,"from":"usaco-guide"},{"id":"576D","src":"cf","name":"Flights for Regular Customers","rating":2700,"from":"curated"},{"id":"cses-1722","src":"cses","name":"Fibonacci Numbers","from":"usaco-guide"},{"id":"cses-1096","src":"cses","name":"Throwing Dice","from":"curated"},{"id":"cses-1723","src":"cses","name":"Graph Paths I","from":"usaco-guide"},{"id":"cses-1724","src":"cses","name":"Graph Paths II","from":"usaco-guide"}]},{"id":"dp-data-structures","name":"DP with segment tree / BIT","tier":1900,"order":23,"prereq":["dp-partition","@ds-segtree-basic","@ds-fenwick"],"summary":"Transitions that take max/sum of dp over a set of previous states defined by value ranges or arbitrary ranges are answered with a Fenwick tree or segment tree (point update, range query), and range-add lazy trees when the cost of the last segment changes as i moves. Recognise it by an O(n^2) DP whose inner loop is 'best dp[j] with key in a range'.","learn":["Index the tree by value (compressed) for 'increasing' constraints: dp[i] = 1 + max query(< a_i)","Counting increasing subsequences of length k with k BITs","Segment tree over j with lazy range-add when cost(j, i) changes by +1 on a range as i advances (distinct counts with last occurrence)","Sweep over intervals sorted by endpoint, query best dp before the start","Matrix / small-state DP stored in segment tree nodes for point updates","Prefix sums of a as keys: dp over prefix sums with BIT over compressed sums","Weighted interval scheduling: sort by end, dp[i] = max(dp[i-1], w_i + dp[last interval ending before l_i]) with binary search or a BIT over coordinates"],"resources":[{"title":"CPH 9.2 Binary indexed tree","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 9.2 (p. 86)","minutes":15},{"title":"CPH 9.3 Segment tree","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 9.3 (p. 89)","minutes":20},{"title":"Dynamic Programming Optimizations (overview table)","url":"https://codeforces.com/blog/entry/8219","kind":"cf-blog","where":"Codeforces blog","minutes":20}],"problems":[{"id":"597C","src":"cf","name":"Subsequences","rating":1900,"from":"curated"},{"id":"1932F","src":"cf","name":"Feed Cats","rating":1900,"from":"curated"},{"id":"1216F","src":"cf","name":"Wi-Fi","rating":2100,"from":"curated"},{"id":"1667B","src":"cf","name":"Optimal Partition","rating":2100,"from":"curated"},{"id":"1482E","src":"cf","name":"Skyline Photo","rating":2100,"from":"curated"},{"id":"1106E","src":"cf","name":"Lunar New Year and Red Envelopes","rating":2100,"from":"curated"},{"id":"1799D2","src":"cf","name":"Hot Start Up (hard version)","rating":2100,"from":"curated"},{"id":"1557D","src":"cf","name":"Ezzat and Grid","rating":2200,"from":"curated"},{"id":"1788E","src":"cf","name":"Sum Over Zero","rating":2200,"from":"curated"},{"id":"1304F1","src":"cf","name":"Animal Observation (easy version)","rating":2300,"from":"curated"},{"id":"1609E","src":"cf","name":"William The Oblivious","rating":2400,"from":"curated"},{"id":"cses-1748","src":"cses","name":"Increasing Subsequence II","from":"usaco-guide"},{"id":"cses-1140","src":"cses","name":"Projects","from":"curated"}]},{"id":"dp-monotonic","name":"Monotonic queue / stack optimisation","tier":2000,"order":24,"prereq":["dp-prefix-opt","@ds-monotonic-deque","@ds-monotonic-stack"],"summary":"dp[i] = max over a sliding window j in [i-k, i-1] of dp[j] + f(i): keep a monotone deque of candidates for O(n). Monotonic stacks handle transitions to the previous greater/smaller element. Recognise it by window-bounded transitions or 'jump only to positions where all between are lower/higher'.","learn":["Sliding window maximum deque: push back after popping worse elements, pop front when out of window","Layered DP (choose k items with gap constraints): one deque per layer -> O(nk)","Window size depends on time difference (Watching Fireworks: window = d * dt)","Monotonic stack keeps candidate predecessors for 'previous smaller' transitions","Two-pointer + deque for 'segment max - min <= s' validity in partition DP","Bounded knapsack in O(nW): group capacities by residue mod w_i and run a sliding-window max over each residue class"],"resources":[{"title":"Sliding Window","url":"https://usaco.guide/gold/sliding-window","kind":"usaco","where":"USACO Guide Gold","minutes":30},{"title":"CPH 8.3 Sliding window minimum","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 8.3 (p. 81)","minutes":10},{"title":"CPH 8.2 Nearest smaller elements","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 8.2 (p. 79)","minutes":10}],"problems":[{"id":"1313C2","src":"cf","name":"Skyscrapers (hard version)","rating":1900,"from":"curated"},{"id":"940E","src":"cf","name":"Cashback","rating":2000,"from":"curated"},{"id":"487B","src":"cf","name":"Strip","rating":2000,"from":"curated"},{"id":"1077F2","src":"cf","name":"Pictures with Kittens (hard version)","rating":2100,"from":"curated"},{"id":"372C","src":"cf","name":"Watching Fireworks is Fun","rating":2100,"from":"curated"},{"id":"1407D","src":"cf","name":"Discrete Centrifugal Jumps","rating":2200,"from":"curated"},{"id":"cses-3314","src":"cses","name":"Mountain Range","from":"curated"}]},{"id":"dp-exchange","name":"Exchange argument + DP","tier":2000,"order":25,"prereq":["dp-knapsack-01","@greedy-exchange"],"summary":"When the order in which chosen items are processed matters, an exchange argument fixes a canonical order (by deadline, by a_i + b_i, by size), and a knapsack-like DP then picks the subset. Recognise it by 'choose a subset and an order' with deadlines, thresholds, or pairwise comparisons.","learn":["Prove the order: swap adjacent items and compare the cost; sort by the derived key","After sorting, run 0-1 knapsack over items in that order (deadline as capacity)","Split items into 'always good' (greedy) and 'risky' (DP) groups","Sort by size descending so pairing/assignment becomes a prefix DP","Rating changes / contest problems: sort by gain, DP over count and total"],"resources":[{"title":"CPH 6.3 Tasks and deadlines","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 6.3 (p. 60)","minutes":10},{"title":"CPH 7.4 Knapsack problems","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 7.4 (p. 72)","minutes":10},{"title":"[Tutorial] Non-trivial DP Tricks and Techniques (zscoder)","url":"https://codeforces.com/blog/entry/47764","kind":"cf-blog","where":"Codeforces blog","minutes":45}],"problems":[{"id":"1398D","src":"cf","name":"Colored Rectangles","rating":1800,"from":"curated"},{"id":"864E","src":"cf","name":"Fire","rating":2000,"from":"curated"},{"id":"1154F","src":"cf","name":"Shovels Shop","rating":2100,"from":"curated"},{"id":"1203F2","src":"cf","name":"Complete the Projects (hard version)","rating":2300,"from":"curated"},{"id":"1056F","src":"cf","name":"Write The Contest","rating":2500,"from":"curated"}]},{"id":"dp-tree-knapsack","name":"Tree knapsack & subtree merging","tier":2100,"order":26,"prereq":["dp-trees","dp-knapsack-01"],"summary":"dp[v][k] = best value in v's subtree using k chosen vertices/cuts, merged child by child like a knapsack. Bounding loops by subtree sizes makes the total O(n^2) (or O(nk)), not O(n^3). Recognise it by 'choose exactly k vertices/edges in a tree' or 'cut the tree into parts of size k'.","learn":["Merge child into parent: new[i+j] = combine(dp[v][i], dp[c][j]) for i <= size(v), j <= size(c)","The size-bounded loop is O(n^2) total - every pair of vertices is merged once at their LCA","With a cap k: loop to min(size, k) for O(nk)","Extra state 'is v's parent edge kept / is v chosen' (coupon dependencies, Karen and Supermarket)","Subset sum of child subtree sizes at each node (PermuTree)","Depth-indexed dp merged by small-to-large / long-path decomposition is the next step (see @trees-small-to-large, e.g. 1009F Dominant Indices)"],"resources":[{"title":"DP on Trees - Combining Subtrees","url":"https://usaco.guide/adv/comb-sub","kind":"usaco","where":"USACO Guide Advanced","minutes":30},{"title":"DP on Trees - Introduction","url":"https://usaco.guide/gold/dp-trees","kind":"usaco","where":"USACO Guide Gold","minutes":40},{"title":"DP on Trees Tutorial","url":"https://codeforces.com/blog/entry/20935","kind":"cf-blog","where":"Codeforces blog","minutes":30}],"problems":[{"id":"440D","src":"cf","name":"Berland Federalization","rating":2200,"from":"usaco-guide"},{"id":"815C","src":"cf","name":"Karen and Supermarket","rating":2400,"from":"usaco-guide"},{"id":"1499F","src":"cf","name":"Diameter Cuts","rating":2400,"from":"curated"},{"id":"735E","src":"cf","name":"Ostap and Tree","rating":2500,"from":"usaco-guide"},{"id":"1280D","src":"cf","name":"Miss Punyverse","rating":2500,"from":"usaco-guide"}]},{"id":"dp-broken-profile","name":"Broken profile / row-mask DP","tier":2100,"order":27,"prereq":["dp-bitmask","dp-grid"],"summary":"Grid DP for narrow boards (one dimension <= ~10): the state is a bitmask describing the boundary ('profile') between processed and unprocessed cells. Tilings with dominoes, placing pieces under row constraints. Processing cell by cell (broken profile) gives O(nm 2^m).","learn":["Row-by-row: dp[row][mask] with transitions over compatible next masks (precompute)","Cell-by-cell broken profile: mask stores which of the next m cells are already covered","Count tilings with dominoes (2 x n, n x m)","If n is big but the narrow side has 2-3 rows, transitions are tiny; if both are big there is often a pattern (505: n >= 4 impossible)","Transpose the grid so the narrow side is the mask"],"resources":[{"title":"Broken Profile DP","url":"https://usaco.guide/adv/dp-broken-profile","kind":"usaco","where":"USACO Guide Advanced","minutes":40},{"title":"CPH 7.6 Counting tilings","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 7.6 (p. 75)","minutes":10},{"title":"DP on Broken Profile","url":"https://cp-algorithms.com/dynamic_programming/profile-dynamics.html","kind":"cpalgo","where":"cp-algorithms","minutes":15}],"problems":[{"id":"1051D","src":"cf","name":"Bicolorings","rating":1700,"from":"curated"},{"id":"1391D","src":"cf","name":"505","rating":2000,"from":"curated"},{"id":"342D","src":"cf","name":"Xenia and Dominoes","rating":2100,"from":"curated"},{"id":"77D","src":"cf","name":"Domino Carpet","rating":2300,"from":"curated"},{"id":"845F","src":"cf","name":"Guards In The Storehouse","rating":2500,"from":"usaco-guide"},{"id":"cses-2181","src":"cses","name":"Counting Tilings","from":"usaco-guide"}]},{"id":"dp-open-close","name":"Open-close intervals, insertion & connected-component DP","tier":2200,"order":28,"prereq":["dp-counting"],"summary":"Insert elements in sorted order and track how many 'open groups' (unfinished intervals or connected components) exist: each new element opens a group, closes one, extends one or merges two. Counts permutations/partitions where the cost depends on max - min of groups or on adjacent comparisons. Recognise it by permutations with neighbour constraints or group imbalance limits.","learn":["Sort values; state = (processed, open groups, accumulated cost)","Cost of all open groups grows by (gap to next value) x (number of open groups) - makes total imbalance additive","Connected-component DP: new element creates a component, attaches to an end, or merges two components","Account for fixed endpoints (first/last element) separately","Typical: permutations where |p_i - p_{i+1}| != 1, building sequences with turn-on rules","Relative-order (insertion) DP for permutations with given </> pattern: dp[i][j] = last element is the j-th smallest of the first i, transitions are prefix/suffix sums of dp[i-1]","Interval nesting/opening counts (Increase Sequence): state = number of currently open segments, each position opens/closes at most one"],"resources":[{"title":"Additional DP Optimizations and Techniques (connected-component DP)","url":"https://usaco.guide/adv/dp-more","kind":"usaco","where":"USACO Guide Advanced","minutes":40},{"title":"DP with connected components, a simple way to understand it","url":"https://codeforces.com/blog/entry/92602","kind":"cf-blog","where":"Codeforces blog","minutes":25},{"title":"[Tutorial] Non-trivial DP Tricks and Techniques (zscoder)","url":"https://codeforces.com/blog/entry/47764","kind":"cf-blog","where":"Codeforces blog","minutes":45},{"title":"AtCoder Educational DP Contest - T Permutation (relative-order DP)","url":"https://atcoder.jp/contests/dp/tasks/dp_t","kind":"other","where":"AtCoder DP contest task T","minutes":30}],"problems":[{"id":"466D","src":"cf","name":"Increase Sequence","rating":2100,"from":"curated"},{"id":"1515E","src":"cf","name":"Phoenix and Computers","rating":2200,"from":"usaco-guide"},{"id":"626F","src":"cf","name":"Group Projects","rating":2400,"from":"usaco-guide"},{"id":"704B","src":"cf","name":"Ant Man","rating":2500,"from":"usaco-guide"},{"id":"367E","src":"cf","name":"Sereja and Intervals","rating":2700,"from":"curated"},{"id":"cses-1665","src":"cses","name":"Coding Company","from":"usaco-guide"},{"id":"cses-1075","src":"cses","name":"Permutations II","from":"usaco-guide"}]},{"id":"dp-sos","name":"SOS DP (sum over subsets)","tier":2200,"order":29,"prereq":["dp-bitmask"],"summary":"Compute F[mask] = sum (or max/min/OR) of A[sub] over all submasks of mask for all 2^n masks in O(n 2^n) by processing one bit at a time. Its inverse (Mobius) and superset version are used for counting pairs with AND/OR conditions. Recognise it by 'for every mask, aggregate over its submasks/supermasks' on values up to 2^20-2^22.","learn":["for bit in 0..n-1: for mask: if mask has bit, F[mask] += F[mask ^ (1<<bit)]","Superset sums: flip the condition (mask lacks bit)","Mobius inversion = subtract instead of add; with inclusion-exclusion gives exact AND counts","Keep top-2 indices per mask for 'max over pairs with i < j' (Bits and Pieces)","Compatibility (a & b = 0): query the submasks of ~a","Complexity O(n 2^n) memory 2^n ints - fits for n <= 22","Digit-wise generalisation: SOS over decimal digits (sum over all numbers whose every digit is >= ...), as in Varying Kibibits"],"resources":[{"title":"Sum over Subsets DP","url":"https://usaco.guide/plat/dp-sos","kind":"usaco","where":"USACO Guide Platinum","minutes":35},{"title":"SOS Dynamic Programming [Tutorial]","url":"https://codeforces.com/blog/entry/45223","kind":"cf-blog","where":"Codeforces blog","minutes":30}],"problems":[{"id":"165E","src":"cf","name":"Compatible Numbers","rating":2200,"from":"usaco-guide"},{"id":"1234F","src":"cf","name":"Yet Another Substring Reverse","rating":2200,"from":"curated"},{"id":"449D","src":"cf","name":"Jzzhu and Numbers","rating":2400,"from":"usaco-guide"},{"id":"1620G","src":"cf","name":"Subsequences Galore","rating":2400,"from":"curated"},{"id":"1208F","src":"cf","name":"Bits And Pieces","rating":2600,"from":"usaco-guide"},{"id":"383E","src":"cf","name":"Vowels","rating":2700,"from":"usaco-guide"},{"id":"772D","src":"cf","name":"Varying Kibibits","rating":2700,"from":"curated"},{"id":"1326F2","src":"cf","name":"Wise Men (Hard Version)","rating":3200,"from":"usaco-guide"},{"id":"cses-1654","src":"cses","name":"Bit Problem","from":"usaco-guide"}]},{"id":"dp-bitset","name":"Bitset optimisation","tier":2200,"order":30,"prereq":["dp-subset-sum","dp-knapsack-bounded","@bitset-basics"],"summary":"Boolean DPs whose transition is a shift-and-OR (subset sum reach |= reach << w) run 64x faster with std::bitset: O(nW/64). Combine with grouping equal values (sqrt distinct sizes) for O(W sqrt W / 64). Recognise it by a boolean DP that is slightly too slow at around 1e10 bit-operations.","learn":["reach |= reach << w for each item; template-size trick to choose bitset size at runtime","Group equal item sizes and binary-split their counts before shifting","Cycle lengths of a permutation -> subset sum over few distinct lengths","Bitset for 'earn or unlock' style reachability where values double as resources","Also speeds up transitive closure / reachability counting (Reachable Nodes)","Offline divide and conquer over a segment tree + bitset knapsack to answer which maxima are reachable (Addition on Segments)"],"resources":[{"title":"Bitsets","url":"https://usaco.guide/plat/bitsets","kind":"usaco","where":"USACO Guide Platinum","minutes":35},{"title":"CPH 10.4 Bit optimizations","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 10.4 (p. 100)","minutes":10}],"problems":[{"id":"1854B","src":"cf","name":"Earn or Unlock","rating":2200,"from":"curated"},{"id":"981E","src":"cf","name":"Addition on Segments","rating":2200,"from":"curated"},{"id":"755F","src":"cf","name":"PolandBall and Gifts","rating":2600,"from":"curated"},{"id":"1856E2","src":"cf","name":"PermuTree (hard version)","rating":2700,"from":"curated"},{"id":"356D","src":"cf","name":"Bags and Coins","rating":2700,"from":"curated"},{"id":"1444D","src":"cf","name":"Rectangular Polyline","rating":2900,"from":"usaco-guide"},{"id":"cses-1706","src":"cses","name":"School Excursion","from":"usaco-guide"}]},{"id":"dp-cht","name":"Convex hull trick & Li Chao tree","tier":2200,"order":31,"prereq":["dp-partition"],"summary":"Transitions of the form dp[i] = min_j (m_j x_i + b_j) + c_i (lines indexed by j, queried at x_i) are answered with a convex hull of lines (monotone slopes: deque, O(n)) or a Li Chao segment tree / line container (arbitrary order, O(n log n)). Recognise it by a cost that expands into a product of a j-term and an i-term.","learn":["Expand the cost: (s_i - s_j)^2 = s_i^2 - 2 s_i s_j + s_j^2 -> line with slope -2s_j, intercept dp_j + s_j^2","Monotone slopes and queries: pointer walk on a deque (O(n))","Monotone slopes, arbitrary queries: binary search on the hull","Arbitrary slopes: Li Chao tree or KACTL LineContainer (multiset with intersection points)","Overflow: compare intersections with __int128 or long double","Li Chao merging on trees (small-to-large) for subtree queries"],"resources":[{"title":"Convex Hull Trick","url":"https://usaco.guide/plat/convex-hull-trick","kind":"usaco","where":"USACO Guide Platinum","minutes":40},{"title":"LineContainer","url":"https://usaco.guide/adv/line-container","kind":"usaco","where":"USACO Guide Advanced","minutes":25},{"title":"Convex hull trick and Li Chao tree","url":"https://cp-algorithms.com/geometry/convex_hull_trick.html","kind":"cpalgo","where":"cp-algorithms","minutes":25},{"title":"Dynamic Programming Optimizations (overview table)","url":"https://codeforces.com/blog/entry/8219","kind":"cf-blog","where":"Codeforces blog","minutes":20}],"problems":[{"id":"319C","src":"cf","name":"Kalila and Dimna in the Logging Industry","rating":2100,"from":"curated"},{"id":"311B","src":"cf","name":"Cats Transport","rating":2400,"from":"curated"},{"id":"1083E","src":"cf","name":"The Fair Nut and Rectangles","rating":2400,"from":"usaco-guide"},{"id":"1715E","src":"cf","name":"Long Way Home","rating":2400,"from":"curated"},{"id":"660F","src":"cf","name":"Bear and Bowling 4","rating":2500,"from":"usaco-guide"},{"id":"631E","src":"cf","name":"Product Sum","rating":2600,"from":"curated"},{"id":"1179D","src":"cf","name":"Fedor Runs for President","rating":2700,"from":"curated"},{"id":"932F","src":"cf","name":"Escape Through Leaf","rating":2700,"from":"usaco-guide"},{"id":"cses-2084","src":"cses","name":"Monster Game I","from":"curated"},{"id":"cses-2085","src":"cses","name":"Monster Game II","from":"curated"}]},{"id":"dp-dnc-opt","name":"Divide & conquer optimisation","tier":2300,"order":32,"prereq":["dp-partition"],"summary":"For layered DPs dp[k][i] = min_{j<i} dp[k-1][j] + C(j, i) where the optimal j is monotone in i (C satisfies the quadrangle inequality), compute each layer by recursion on the middle i with a restricted j range: O(k n log n). Recognise it by 'split into k groups' with a cost like sum of squares or number of distinct elements.","learn":["Check opt(i) <= opt(i+1) (quadrangle inequality / intuition: later endpoints never want earlier splits)","compute(l, r, optl, optr): solve mid, recurse left with [optl, opt(mid)], right with [opt(mid), optr]","Cost C(j, i) in O(1) via prefix sums, or amortised with a Mo-like moving window (distinct counts)","Total O(k n log n); combine with Aliens trick to remove the k factor","Segment tree with lazy add is an alternative for 'distinct elements' costs (The Bakery)","Expected-cost or number-theoretic costs (Levels and Regions, Artistic Partition) still work as long as C(j, i) is O(1) after precomputation and opt is monotone"],"resources":[{"title":"Divide & Conquer - DP","url":"https://usaco.guide/plat/DC-DP","kind":"usaco","where":"USACO Guide Platinum","minutes":35},{"title":"Divide and Conquer DP","url":"https://cp-algorithms.com/dynamic_programming/divide-and-conquer-dp.html","kind":"cpalgo","where":"cp-algorithms","minutes":20},{"title":"Dynamic Programming Optimizations (overview table)","url":"https://codeforces.com/blog/entry/8219","kind":"cf-blog","where":"Codeforces blog","minutes":20}],"problems":[{"id":"833B","src":"cf","name":"The Bakery","rating":2200,"from":"curated"},{"id":"643C","src":"cf","name":"Levels and Regions","rating":2400,"from":"curated"},{"id":"1527E","src":"cf","name":"Partition Game","rating":2500,"from":"curated"},{"id":"868F","src":"cf","name":"Yet Another Minimization Problem","rating":2500,"from":"usaco-guide"},{"id":"321E","src":"cf","name":"Ciel and Gondolas","rating":2600,"from":"usaco-guide"},{"id":"1603D","src":"cf","name":"Artistic Partition","rating":3000,"from":"curated"},{"id":"cses-2086","src":"cses","name":"Subarray Squares","from":"curated"},{"id":"cses-2087","src":"cses","name":"Houses and Schools","from":"usaco-guide"}]},{"id":"dp-knuth","name":"Knuth optimisation","tier":2400,"order":33,"prereq":["dp-interval","dp-dnc-opt"],"summary":"For interval DPs dp[l][r] = min_{l<=k<r} dp[l][k] + dp[k+1][r] + C(l, r) where opt[l][r-1] <= opt[l][r] <= opt[l+1][r], restricting k to that range makes the total O(n^2) instead of O(n^3). Classic: optimal merging of adjacent piles, optimal BST, splitting a stick.","learn":["Store opt[l][r]; iterate k only in [opt[l][r-1], opt[l+1][r]]","Sufficient: C is monotone on inclusion and satisfies the quadrangle inequality","Amortised sum over each diagonal telescopes to O(n) -> O(n^2) total","Also applies to some layered DPs dp[k][i] with opt[k-1][i] <= opt[k][i] <= opt[k][i+1]","When unsure, verify monotonicity of opt empirically with a brute force","Layered form: dp[k][i] = min_j dp[k-1][j] + C(j, i) with opt[k-1][i] <= opt[k][i] <= opt[k][i+1] gives O(n^2) total instead of O(k n log n) (Ciel and Gondolas)"],"resources":[{"title":"Additional DP Optimizations and Techniques (Knuth's optimization)","url":"https://usaco.guide/adv/dp-more","kind":"usaco","where":"USACO Guide Advanced","minutes":30},{"title":"Knuth's Optimization","url":"https://cp-algorithms.com/dynamic_programming/knuth-optimization.html","kind":"cpalgo","where":"cp-algorithms","minutes":20},{"title":"Dynamic Programming Optimizations (overview table)","url":"https://codeforces.com/blog/entry/8219","kind":"cf-blog","where":"Codeforces blog","minutes":20}],"problems":[{"id":"1101F","src":"cf","name":"Trucks and Cities","rating":2400,"from":"usaco-guide"},{"id":"321E","src":"cf","name":"Ciel and Gondolas","rating":2600,"from":"usaco-guide"},{"id":"cses-2088","src":"cses","name":"Knuth Division","from":"curated"}]},{"id":"dp-slope-trick","name":"Slope trick","tier":2400,"order":34,"prereq":["dp-multistate","@ds-priority-queue"],"summary":"When dp_i(x) as a function of the value x is convex and piecewise linear, store only the points where its slope changes (in priority queues) instead of the whole array. Operations like 'add |x - a|' or 'prefix min' become O(log n) heap updates. Classic: make an array non-decreasing with minimum total change.","learn":["Represent a convex piecewise-linear function by multisets of breakpoints left/right of the minimum","Add |x - a|: push a to both heaps, move the top across if needed, update the minimum value","Prefix minimum (non-decreasing constraint): clear the right heap","Make strictly increasing: replace a_i with a_i - i","Lazy shifts for 'x can move by up to d' transitions","Original O(n^2) version: dp over compressed values with prefix minima - learn it first","Buy Low Sell High pattern: a min-heap with re-insertion is slope trick on the profit function (also a regret greedy)"],"resources":[{"title":"Slope Trick","url":"https://usaco.guide/adv/slope-trick","kind":"usaco","where":"USACO Guide Advanced","minutes":40},{"title":"[Tutorial] Slope Trick","url":"https://codeforces.com/blog/entry/47821","kind":"cf-blog","where":"Codeforces blog","minutes":30},{"title":"Slope trick explained","url":"https://codeforces.com/blog/entry/77298","kind":"cf-blog","where":"Codeforces blog","minutes":30}],"problems":[{"id":"13C","src":"cf","name":"Sequence","rating":2200,"from":"curated"},{"id":"713C","src":"cf","name":"Sonya and Problem Wihtout a Legend","rating":2300,"from":"curated"},{"id":"865D","src":"cf","name":"Buy Low Sell High","rating":2400,"from":"usaco-guide"},{"id":"1534G","src":"cf","name":"A New Beginning","rating":3300,"from":"curated"},{"id":"1209H","src":"cf","name":"Moving Walkways","rating":3300,"from":"usaco-guide"},{"id":"cses-2132","src":"cses","name":"Increasing Array II","from":"usaco-guide"}]},{"id":"dp-aliens","name":"Aliens trick (Lagrangian relaxation)","tier":2500,"order":35,"prereq":["dp-dnc-opt","@bs-answer"],"summary":"If the best answer with exactly k items/segments, f(k), is convex in k, remove the k dimension: add a penalty lambda per item, solve the unconstrained DP (tracking the count used), and binary search lambda until the count is k; answer = g(lambda) + lambda k. Turns O(nk) into O(n log C).","learn":["Prove or believe convexity of f(k) (often from a flow / exchange argument)","DP returns (value, count); break ties consistently (min count) to handle collinear points","Binary search integer lambda; final answer uses k, not the returned count","Combine with CHT / monotone structures for the inner unconstrained DP","Recognise: 'exactly k segments / operations', k up to n, and O(nk) too slow"],"resources":[{"title":"Lagrangian Relaxation","url":"https://usaco.guide/adv/lagrange","kind":"usaco","where":"USACO Guide Advanced","minutes":35},{"title":"Incredibly beautiful DP optimization from N^3 to N log^2 N","url":"https://codeforces.com/blog/entry/49691","kind":"cf-blog","where":"Codeforces blog","minutes":30}],"problems":[{"id":"958E2","src":"cf","name":"Guard Duty (medium)","rating":2200,"from":"curated"},{"id":"643C","src":"cf","name":"Levels and Regions","rating":2400,"from":"curated"},{"id":"1661F","src":"cf","name":"Teleporters","rating":2600,"from":"usaco-guide"},{"id":"1279F","src":"cf","name":"New Year and Handle Change","rating":2800,"from":"usaco-guide"},{"id":"739E","src":"cf","name":"Gosha is hunting","rating":3000,"from":"curated"}]}]}]},{"area":"graphs","topics":[{"id":"graph-fundamentals","name":"Graph Fundamentals & Traversal","cfTags":["graphs","dfs and similar"],"subtopics":[{"id":"graph-representation","name":"Graph basics & representation","tier":800,"order":1,"prereq":[],"summary":"Vertices, edges, degrees, directed vs undirected, weighted graphs, trees, and how to store them (adjacency list, adjacency matrix, edge list). Many easy CF problems are pure reasoning about degrees, edge counts and simple structure once you model the input as a graph.","learn":["Terminology: path, cycle, simple graph, connected, tree (n-1 edges, connected, acyclic), forest, complete graph, DAG","Handshake lemma: sum of degrees = 2m; number of odd-degree vertices is even","Adjacency list (vector<vector<int>>) is the default: O(n+m) memory; matrix only when n <= ~5000 or you need O(1) edge lookup","Edge list (u,v,w) is what Kruskal / Bellman-Ford iterate over; store edge indices when you must mark edges as used","Read input carefully: 1-indexed vs 0-indexed, multi-edges and self-loops, multiple test cases (reset adjacency lists, sum of n bounded)","Model hidden graphs: grid cells, numbers connected by an operation, permutations (i -> p_i) are all graphs"],"resources":[{"title":"CPH 11.1 Graph terminology","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 11.1 (p. 109)","minutes":20},{"title":"CPH 11.2 Graph representation","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 11.2 (p. 113)","minutes":15},{"title":"USACO Guide: Introduction to Graphs","url":"https://usaco.guide/bronze/intro-graphs","kind":"usaco","where":"USACO Guide Bronze","minutes":30}],"problems":[{"id":"1944A","src":"cf","name":"Destroying Bridges","rating":800,"from":"curated"},{"id":"1255B","src":"cf","name":"Fridge Lockers","rating":1100,"from":"curated"},{"id":"1559C","src":"cf","name":"Mocha and Hiking","rating":1200,"from":"curated"},{"id":"1581B","src":"cf","name":"Diameter of Graph","rating":1200,"from":"curated"},{"id":"1711B","src":"cf","name":"Party","rating":1300,"from":"curated"},{"id":"1829F","src":"cf","name":"Forever Winter","rating":1300,"from":"curated"},{"id":"1065B","src":"cf","name":"Vasya and Isolated Vertices","rating":1300,"from":"curated"},{"id":"1548A","src":"cf","name":"Web of Lies","rating":1400,"from":"curated"}]},{"id":"graph-dfs-bfs","name":"DFS & BFS traversal","tier":1100,"order":2,"prereq":["graph-representation"],"summary":"Depth-first and breadth-first search visit every vertex reachable from a source in O(n+m). They are the building block of nearly every other graph algorithm: reachability, components, trees, orderings, and layered distances.","learn":["Recursive DFS with a visited array; iterative DFS with an explicit stack when depth can reach 1e5-1e6 (stack overflow risk)","BFS with a queue processes vertices in non-decreasing distance order (layers)","DFS on trees: pass parent instead of visited; compute subtree sizes, depths, entry/exit times on the way","Peeling / layered BFS from leaves (Kahn-style) answers \"remove all leaves k times\" problems","Reachability on directed graphs: DFS from s in G and in the reversed graph","Always reset per-test-case arrays only for the n vertices used (sum of n constraints)"],"resources":[{"title":"CPH 12.1 Depth-first search","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 12.1 (p. 117)","minutes":15},{"title":"CPH 12.2 Breadth-first search","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 12.2 (p. 119)","minutes":15},{"title":"CPH 12.3 Applications","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 12.3 (p. 121)","minutes":10},{"title":"USACO Guide: Graph Traversal","url":"https://usaco.guide/silver/graph-traversal","kind":"usaco","where":"USACO Guide Silver","minutes":45},{"title":"cp-algorithms: Depth First Search","url":"https://cp-algorithms.com/graph/depth-first-search.html","kind":"cpalgo","where":"cp-algorithms","minutes":20},{"title":"cp-algorithms: Breadth First Search","url":"https://cp-algorithms.com/graph/breadth-first-search.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"1676G","src":"cf","name":"White-Black Balanced Subtrees","rating":1300,"from":"curated"},{"id":"1675D","src":"cf","name":"Vertical Paths","rating":1300,"from":"curated"},{"id":"1830A","src":"cf","name":"Copil Copac Draws Trees","rating":1400,"from":"curated"},{"id":"1106D","src":"cf","name":"Lunar New Year and a Wander","rating":1500,"from":"curated"},{"id":"1593E","src":"cf","name":"Gardener and Tree","rating":1600,"from":"curated"},{"id":"1037D","src":"cf","name":"Valid BFS?","rating":1700,"from":"curated"},{"id":"1760G","src":"cf","name":"SlavicG's Favorite Problem","rating":1700,"from":"curated"},{"id":"1328E","src":"cf","name":"Tree Queries","rating":1900,"from":"curated"},{"id":"cses-1682","src":"cses","name":"Flight Routes Check","from":"usaco-guide"}]},{"id":"graph-components","name":"Connected components","tier":1100,"order":3,"prereq":["graph-dfs-bfs"],"summary":"Split an undirected graph into maximal connected pieces with DFS/BFS (or DSU). Problems ask for the number/size of components, the minimum number of edges to connect everything (components - 1), or a per-component aggregate.","learn":["Label each vertex with a component id via repeated DFS; count sizes in the same pass","Edges needed to connect c components = c - 1","Per-component aggregates (min, max, sum, min/max index) solve many greedy problems","Components of an \"equivalence\" relation (same letter, same group) -> graph or DSU","Build the graph implicitly (e.g. via shared letters/values using extra nodes) to avoid O(n^2) edges","DSU is an alternative when edges arrive online","Planar graphs: Euler's formula V - E + F = 1 + C counts regions/faces (USACO Guide Advanced: Euler's Formula)"],"resources":[{"title":"CPH 12.3 Applications - connectivity check","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 12.3 (p. 121)","minutes":10},{"title":"USACO Guide: Graph Traversal - connected components","url":"https://usaco.guide/silver/graph-traversal","kind":"usaco","where":"USACO Guide Silver","minutes":45},{"title":"cp-algorithms: Search for connected components","url":"https://cp-algorithms.com/graph/search-for-connected-components.html","kind":"cpalgo","where":"cp-algorithms","minutes":20},{"title":"USACO Guide: Euler's Formula","url":"https://usaco.guide/adv/eulers-formula","kind":"usaco","where":"USACO Guide Advanced","minutes":30}],"problems":[{"id":"1534C","src":"cf","name":"Little Alawn's Puzzle","rating":1300,"from":"curated"},{"id":"1167C","src":"cf","name":"News Distribution","rating":1400,"from":"curated"},{"id":"1559D1","src":"cf","name":"Mocha and Diana (Easy Version)","rating":1400,"from":"curated"},{"id":"1263D","src":"cf","name":"Secret Passwords","rating":1500,"from":"curated"},{"id":"2060E","src":"cf","name":"Graph Composition","rating":1500,"from":"usaco-guide"},{"id":"731C","src":"cf","name":"Socks","rating":1600,"from":"curated"},{"id":"500B","src":"cf","name":"New Year Permutation","rating":1600,"from":"curated"},{"id":"1833E","src":"cf","name":"Round Dance","rating":1600,"from":"usaco-guide"},{"id":"1253D","src":"cf","name":"Harmonious Graph","rating":1700,"from":"curated"},{"id":"cses-1666","src":"cses","name":"Building Roads","from":"usaco-guide"}]},{"id":"graph-flood-fill","name":"Flood fill on grids","tier":1100,"order":4,"prereq":["graph-dfs-bfs"],"summary":"Treat each grid cell as a vertex adjacent to its 4 (or 8) neighbours and run DFS/BFS to find regions. Typical tasks: count rooms/lakes, region sizes, whether a cell can reach the border, or blocking cells to separate regions.","learn":["Use dx/dy arrays and a bounds check helper; mark visited when pushing, not when popping","Iterative BFS/stack avoids recursion depth issues on 1e6-cell grids","Regions touching the border are special (e.g. lakes vs ocean): start a flood fill from all border cells first","Pre-compute region id + size for each cell to answer \"what if I open this cell\" in O(4) per query","Greedy blocking: surround bad cells with walls, then verify with one flood fill"],"resources":[{"title":"USACO Guide: Flood Fill","url":"https://usaco.guide/silver/flood-fill","kind":"usaco","where":"USACO Guide Silver","minutes":30},{"title":"CPH 12.3 Applications","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 12.3 (p. 121)","minutes":10}],"problems":[{"id":"1829E","src":"cf","name":"The Lakes","rating":1100,"from":"curated"},{"id":"2034C","src":"cf","name":"Trapped in the Witch's Labyrinth","rating":1400,"from":"curated"},{"id":"377A","src":"cf","name":"Maze","rating":1600,"from":"curated"},{"id":"616C","src":"cf","name":"The Labyrinth","rating":1600,"from":"curated"},{"id":"723D","src":"cf","name":"Lakes in Berland","rating":1600,"from":"curated"},{"id":"1365D","src":"cf","name":"Solve The Maze","rating":1700,"from":"usaco-guide"},{"id":"1985H1","src":"cf","name":"Maximize the Largest Component (Easy Version)","rating":1700,"from":"curated"},{"id":"598D","src":"cf","name":"Igor In the Museum","rating":1700,"from":"curated"},{"id":"cses-1192","src":"cses","name":"Counting Rooms","from":"usaco-guide"}]},{"id":"graph-bipartite","name":"Bipartite check / 2-colouring","tier":1300,"order":5,"prereq":["graph-dfs-bfs"],"summary":"A graph is bipartite iff it has no odd cycle iff its vertices can be 2-coloured so every edge joins different colours. Recognise it in problems about splitting into two teams/sets with \"must differ\" constraints, or orienting edges so no path has length 2.","learn":["BFS/DFS colouring: colour[v] = colour[u] ^ 1; conflict => odd cycle => not bipartite","Each connected component can be flipped independently -> choose the smaller side, or count 2^(components) colourings","Trees are always bipartite (colour by depth parity)","Odd cycle certificate: reconstruct from the conflict edge using parent pointers","Max number of edges you can add while staying bipartite = |L|*|R| - m (tree case)","Parity constraints (x_u xor x_v = c) generalise this -> weighted DSU / 2-SAT"],"resources":[{"title":"USACO Guide: Graph Traversal - graph two-coloring","url":"https://usaco.guide/silver/graph-traversal","kind":"usaco","where":"USACO Guide Silver","minutes":45},{"title":"CPH 12.3 Applications - bipartiteness check","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 12.3 (p. 121)","minutes":10},{"title":"cp-algorithms: Check whether a graph is bipartite","url":"https://cp-algorithms.com/graph/bipartite-check.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"862B","src":"cf","name":"Mahmoud and Ehab and the bipartiteness","rating":1300,"from":"usaco-guide"},{"id":"687A","src":"cf","name":"NP-Hard Problem","rating":1500,"from":"curated"},{"id":"1702E","src":"cf","name":"Split Into Two Sets","rating":1600,"from":"usaco-guide"},{"id":"1093D","src":"cf","name":"Beautiful Graph","rating":1700,"from":"curated"},{"id":"1144F","src":"cf","name":"Graph Without Long Directed Paths","rating":1700,"from":"curated"},{"id":"1176E","src":"cf","name":"Cover it!","rating":1700,"from":"usaco-guide"},{"id":"1949I","src":"cf","name":"Disks","rating":1800,"from":"curated"},{"id":"1991E","src":"cf","name":"Coloring Game","rating":1900,"from":"usaco-guide"},{"id":"2154D","src":"cf","name":"Catshock","rating":1900,"from":"usaco-guide"},{"id":"1354E","src":"cf","name":"Graph Coloring","rating":2100,"from":"curated"},{"id":"cses-1668","src":"cses","name":"Building Teams","from":"usaco-guide"}]},{"id":"graph-cycle-detection","name":"Cycle detection & finding","tier":1500,"order":6,"prereq":["graph-dfs-bfs"],"summary":"Detect and output a cycle in an undirected graph (a back edge to a non-parent) or a directed graph (an edge to a vertex currently on the recursion stack, 3-colour DFS). Shows up in \"is it a tree/cactus\", \"find any cycle\", and unicyclic-graph problems.","learn":["Undirected: DFS, an edge to a visited vertex other than the parent closes a cycle (careful with multi-edges)","Directed: colours white/grey/black; an edge into a grey vertex = cycle; recover it with parent pointers","Connected + n edges = exactly one cycle (unicyclic / pseudotree); trees hanging off the cycle","A component is a simple cycle iff every vertex has degree 2","Shortest cycle (girth) in unweighted graphs: BFS from every vertex, O(nm)","DSU detects the first edge that creates a cycle in an undirected graph"],"resources":[{"title":"cp-algorithms: Checking a graph for acyclicity and finding a cycle","url":"https://cp-algorithms.com/graph/finding-cycle.html","kind":"cpalgo","where":"cp-algorithms","minutes":20},{"title":"CPH 16.4 Cycle detection","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 16.4 (p. 155)","minutes":10},{"title":"CPH 12.3 Applications - cycle detection","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 12.3 (p. 121)","minutes":10}],"problems":[{"id":"103B","src":"cf","name":"Cthulhu","rating":1500,"from":"curated"},{"id":"977E","src":"cf","name":"Cyclic Components","rating":1500,"from":"curated"},{"id":"1411C","src":"cf","name":"Peaceful Rooks","rating":1700,"from":"curated"},{"id":"1873H","src":"cf","name":"Mad City","rating":1700,"from":"curated"},{"id":"1817B","src":"cf","name":"Fish Graph","rating":1900,"from":"curated"},{"id":"1454E","src":"cf","name":"Number of Simple Paths","rating":2000,"from":"curated"},{"id":"cses-1669","src":"cses","name":"Round Trip","from":"curated"},{"id":"cses-1678","src":"cses","name":"Round Trip II","from":"usaco-guide"},{"id":"cses-1707","src":"cses","name":"Graph Girth","from":"usaco-guide"}]},{"id":"graph-dfs-tree","name":"DFS tree, back edges & constructive DFS","tier":1900,"order":7,"prereq":["graph-cycle-detection"],"summary":"In an undirected DFS every non-tree edge is a back edge connecting a vertex to its ancestor. This structure gives short proofs for \"find a long path or a big independent set / short cycle\" constructive problems and is the foundation for bridges and articulation points.","learn":["Undirected DFS has no cross edges: non-tree edges always go ancestor <-> descendant","Long path in the DFS tree (depth >= k) or many back edges => long cycle; otherwise a deep-level independent set","Use depth[] of endpoints of back edges to measure cycle lengths","Spanning-tree + back-edge view is how low-link values (bridges, cut vertices) are derived","Pick the vertex with the deepest back edge to find a cycle of bounded length","Ramsey/pigeonhole style arguments (\"either A or B exists\") are typical for this pattern"],"resources":[{"title":"[Tutorial] The DFS tree and its applications (Radewoosh)","url":"https://codeforces.com/blog/entry/68138","kind":"cf-blog","where":"Codeforces blog","minutes":40},{"title":"cp-algorithms: Depth First Search - classification of edges","url":"https://cp-algorithms.com/graph/depth-first-search.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"263D","src":"cf","name":"Cycle in Graph","rating":1800,"from":"curated"},{"id":"1364D","src":"cf","name":"Ehab's Last Corollary","rating":2100,"from":"curated"},{"id":"858F","src":"cf","name":"Wizard's Tour","rating":2300,"from":"curated"},{"id":"1325F","src":"cf","name":"Ehab's Last Theorem","rating":2500,"from":"curated"},{"id":"1391E","src":"cf","name":"Pairs of Pairs","rating":2600,"from":"curated"},{"id":"1103C","src":"cf","name":"Johnny Solving","rating":2700,"from":"curated"}]}]},{"id":"shortest-paths","name":"Shortest Paths","cfTags":["shortest paths","graphs"],"subtopics":[{"id":"sp-bfs","name":"BFS shortest paths (unweighted)","tier":1300,"order":1,"prereq":["graph-dfs-bfs"],"summary":"In an unweighted graph BFS gives the distance from a source to every vertex in O(n+m). Recognise it whenever moves have equal cost: grid mazes, button presses, transforming numbers/states by operations.","learn":["dist[] initialised to -1/INF; set dist when pushing to the queue","Path reconstruction: store parent[] and walk back from the target","Distances from both endpoints (dist_s, dist_t) let you test whether an edge/vertex lies on some shortest path: ds[u]+1+dt[v]==ds[t]","Shortest-path DAG: edges with dist[v]==dist[u]+1; count shortest paths with DP in BFS order","Implicit graphs: states are numbers/strings; generate neighbours on the fly","Graph girth / shortest cycle with BFS from each vertex"],"resources":[{"title":"USACO Guide: Unweighted Shortest Paths","url":"https://usaco.guide/gold/unweighted-shortest-paths","kind":"usaco","where":"USACO Guide Gold","minutes":35},{"title":"CPH 12.2 Breadth-first search","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 12.2 (p. 119)","minutes":15},{"title":"cp-algorithms: Breadth First Search","url":"https://cp-algorithms.com/graph/breadth-first-search.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"1661B","src":"cf","name":"Getting Zero","rating":1300,"from":"curated"},{"id":"520B","src":"cf","name":"Two Buttons","rating":1400,"from":"curated"},{"id":"954D","src":"cf","name":"Fight Against Traffic","rating":1600,"from":"curated"},{"id":"1320B","src":"cf","name":"Navigation System","rating":1700,"from":"curated"},{"id":"1307D","src":"cf","name":"Cow and Fields","rating":1900,"from":"curated"},{"id":"2109D","src":"cf","name":"D/D/D","rating":1900,"from":"usaco-guide"},{"id":"1343E","src":"cf","name":"Weights Distributing","rating":2100,"from":"curated"},{"id":"877D","src":"cf","name":"Olya and Energy Drinks","rating":2100,"from":"curated"},{"id":"1650G","src":"cf","name":"Counting Shortcuts","rating":2100,"from":"curated"},{"id":"cses-1667","src":"cses","name":"Message Route","from":"usaco-guide"},{"id":"cses-1193","src":"cses","name":"Labyrinth","from":"usaco-guide"}]},{"id":"sp-multisource-bfs","name":"Multi-source BFS","tier":1600,"order":2,"prereq":["sp-bfs"],"summary":"Push all sources into the queue at distance 0 to get, for every vertex, the distance to the nearest source. Used for spreading/infection processes, \"distance to nearest X\", and races between two groups (monsters vs player).","learn":["Initialise the queue with every source; BFS layers = simultaneous spreading time","Reverse the edges to compute \"distance from each vertex to the nearest vertex with property P\"","Race problems: BFS from enemies first, then BFS for the player only through cells reached strictly earlier","Tag each vertex with which source reached it (Voronoi regions) to find nearest pairs between groups","Multi-player expansion with speeds: process players round by round, each with its own queue"],"resources":[{"title":"USACO Guide: Unweighted Shortest Paths - multi-source","url":"https://usaco.guide/gold/unweighted-shortest-paths","kind":"usaco","where":"USACO Guide Gold","minutes":35},{"title":"cp-algorithms: Breadth First Search","url":"https://cp-algorithms.com/graph/breadth-first-search.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"986A","src":"cf","name":"Fair","rating":1600,"from":"curated"},{"id":"1611E1","src":"cf","name":"Escape The Maze (easy version)","rating":1700,"from":"curated"},{"id":"1579F","src":"cf","name":"Array Stabilization (AND version)","rating":1700,"from":"curated"},{"id":"1283D","src":"cf","name":"Christmas Trees","rating":1800,"from":"curated"},{"id":"1272E","src":"cf","name":"Nearest Opposite Parity","rating":1900,"from":"curated"},{"id":"1105D","src":"cf","name":"Kilani and the Game","rating":1900,"from":"curated"},{"id":"1651D","src":"cf","name":"Nearest Excluded Points","rating":1900,"from":"curated"},{"id":"1611E2","src":"cf","name":"Escape The Maze (hard version)","rating":1900,"from":"curated"},{"id":"1349C","src":"cf","name":"Orac and Game of Life","rating":2000,"from":"curated"},{"id":"1227E","src":"cf","name":"Arson In Berland Forest","rating":2200,"from":"curated"},{"id":"cses-1194","src":"cses","name":"Monsters","from":"usaco-guide"}]},{"id":"sp-01-bfs","name":"0-1 BFS","tier":1800,"order":3,"prereq":["sp-bfs"],"summary":"When edge weights are only 0 or 1, a deque replaces Dijkstra: push 0-edges to the front and 1-edges to the back, giving O(n+m). Typical: grids where moving in some directions or through some cells is free, or \"minimum number of changes/walls to break\".","learn":["Deque: relax 0-edge -> push_front, 1-edge -> push_back; a vertex may be popped more than once, skip stale entries","Generalises to weights 0..k with k+1 buckets (Dial's algorithm)","Model \"cost = number of turns/changes/opened walls\" as 0/1 edges","Multiple sources with 0-1 BFS: compute distance from each of a few groups and combine at a meeting cell","Layered states (time mod g, direction) + 0-1 BFS for harder grid tasks"],"resources":[{"title":"cp-algorithms: 0-1 BFS","url":"https://cp-algorithms.com/graph/01_bfs.html","kind":"cpalgo","where":"cp-algorithms","minutes":20},{"title":"0-1 BFS [Tutorial]","url":"https://codeforces.com/blog/entry/22276","kind":"cf-blog","where":"Codeforces blog","minutes":15},{"title":"USACO Guide: Unweighted Shortest Paths - 0/1 BFS","url":"https://usaco.guide/gold/unweighted-shortest-paths","kind":"usaco","where":"USACO Guide Gold","minutes":35}],"problems":[{"id":"793B","src":"cf","name":"Igor and his way to work","rating":1600,"from":"curated"},{"id":"1063B","src":"cf","name":"Labyrinth","rating":1800,"from":"curated"},{"id":"173B","src":"cf","name":"Chamber of Secrets","rating":1800,"from":"curated"},{"id":"590C","src":"cf","name":"Three States","rating":2200,"from":"curated"},{"id":"821D","src":"cf","name":"Okabe and City","rating":2200,"from":"curated"},{"id":"1340C","src":"cf","name":"Nastya and Unexpected Guest","rating":2400,"from":"curated"}]},{"id":"sp-dijkstra","name":"Dijkstra's algorithm","tier":1600,"order":4,"prereq":["sp-bfs"],"summary":"Single-source shortest paths with non-negative weights in O((n+m) log n) using a priority queue. Recognise weighted distances, \"minimum time/cost to reach\", shortest path trees and counting shortest paths.","learn":["priority_queue of (dist, v) with greater<>; skip entries where d != dist[v]","Use long long distances and an INF like 1e18; never use Dijkstra with negative edges","Shortest-path tree / DAG: keep parent edges; count paths, min/max edges among shortest paths with DP in Dijkstra order (CSES Investigation)","Run from s and t (or reversed graph) to decide which edges lie on a shortest path","O(n^2) Dijkstra without a heap for dense graphs","K-th shortest walks: allow each vertex to be popped k times"],"resources":[{"title":"USACO Guide: Shortest Paths with Non-Negative Edge Weights","url":"https://usaco.guide/gold/shortest-paths","kind":"usaco","where":"USACO Guide Gold","minutes":45},{"title":"CPH 13.2 Dijkstra's algorithm","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 13.2 (p. 126)","minutes":20},{"title":"cp-algorithms: Dijkstra on sparse graphs","url":"https://cp-algorithms.com/graph/dijkstra_sparse.html","kind":"cpalgo","where":"cp-algorithms","minutes":20},{"title":"cp-algorithms: Dijkstra Algorithm","url":"https://cp-algorithms.com/graph/dijkstra.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"229B","src":"cf","name":"Planets","rating":1700,"from":"curated"},{"id":"2023B","src":"cf","name":"Skipping","rating":1700,"from":"curated"},{"id":"1076D","src":"cf","name":"Edge Deletion","rating":1800,"from":"curated"},{"id":"20C","src":"cf","name":"Dijkstra?","rating":1900,"from":"curated"},{"id":"144D","src":"cf","name":"Missile Silos","rating":1900,"from":"curated"},{"id":"1887B","src":"cf","name":"Time Travel","rating":1900,"from":"curated"},{"id":"545E","src":"cf","name":"Paths and Trees","rating":2000,"from":"curated"},{"id":"449B","src":"cf","name":"Jzzhu and Cities","rating":2000,"from":"curated"},{"id":"938D","src":"cf","name":"Buy a Ticket","rating":2000,"from":"curated"},{"id":"1433G","src":"cf","name":"Reducing Delivery Cost","rating":2100,"from":"curated"},{"id":"2000G","src":"cf","name":"Call During the Journey","rating":2100,"from":"curated"},{"id":"715B","src":"cf","name":"Complete The Graph","rating":2300,"from":"curated"},{"id":"cses-1671","src":"cses","name":"Shortest Routes I","from":"usaco-guide"},{"id":"cses-1202","src":"cses","name":"Investigation","from":"usaco-guide"},{"id":"cses-1196","src":"cses","name":"Flight Routes","from":"usaco-guide"}]},{"id":"sp-bellman-ford","name":"Bellman-Ford, negative cycles & difference constraints","tier":1900,"order":5,"prereq":["sp-dijkstra"],"summary":"Bellman-Ford relaxes all edges n-1 times, handling negative weights in O(nm); a relaxation in round n proves a negative cycle. Systems of inequalities x_v - x_u <= w become shortest paths (difference constraints).","learn":["n-1 rounds of relaxing every edge; early exit when nothing changes","Negative cycle detection: any update in round n; to output it, walk parent pointers n steps then loop","Only cycles reachable from the source (and that reach the target) matter for \"arbitrarily large score\" questions (CSES High Score)","Difference constraints: x_v <= x_u + w => edge u->v with weight w; infeasible iff negative cycle","SPFA is a queue-based heuristic; worst case is still O(nm) and can be hacked","Johnson's re-weighting lets Dijkstra run after one Bellman-Ford pass"],"resources":[{"title":"CPH 13.1 Bellman-Ford algorithm","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 13.1 (p. 123)","minutes":20},{"title":"USACO Guide: Shortest Paths with Negative Edge Weights","url":"https://usaco.guide/adv/sp-neg","kind":"usaco","where":"USACO Guide Advanced","minutes":45},{"title":"cp-algorithms: Bellman-Ford Algorithm","url":"https://cp-algorithms.com/graph/bellman_ford.html","kind":"cpalgo","where":"cp-algorithms","minutes":20},{"title":"cp-algorithms: Finding a negative cycle in the graph","url":"https://cp-algorithms.com/graph/finding-negative-cycle-in-graph.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"241E","src":"cf","name":"Flights","rating":2600,"from":"curated"},{"id":"1450E","src":"cf","name":"Capitalism","rating":2700,"from":"curated"},{"id":"cses-1673","src":"cses","name":"High Score","from":"curated"},{"id":"cses-1197","src":"cses","name":"Cycle Finding","from":"usaco-guide"}]},{"id":"sp-floyd-warshall","name":"Floyd-Warshall (all pairs)","tier":1700,"order":6,"prereq":["sp-dijkstra"],"summary":"All-pairs shortest paths in O(n^3) with the k-i-j triple loop; fine for n <= ~500. Also handles transitive closure, minimax paths, incremental edge additions and reversed vertex-insertion orders.","learn":["dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]) with k as the OUTER loop","Adding one edge (a,b,w) updates all pairs in O(n^2): dist[i][j] = min(dist[i][a]+w+dist[b][j], ...)","Insert vertices in reverse deletion order and sum distances among inserted vertices only (Greg and Graph)","Transitive closure with bitsets: reach[i] |= reach[k] if reach[i][k]","Minimum-weight cycle: undirected - before using k as an intermediate, try dist[i][j] + w(j,k) + w(k,i) for all i,j < k; directed - run Floyd and take min dist[i][i] (initialise dist[i][i] = INF)","Negative cycle exists iff some dist[i][i] < 0 at the end"],"resources":[{"title":"CPH 13.3 Floyd-Warshall algorithm","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 13.3 (p. 129)","minutes":15},{"title":"USACO Guide: Shortest Paths - Floyd-Warshall","url":"https://usaco.guide/gold/shortest-paths","kind":"usaco","where":"USACO Guide Gold","minutes":45},{"title":"cp-algorithms: Floyd-Warshall Algorithm","url":"https://cp-algorithms.com/graph/all-pair-shortest-path-floyd-warshall.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"505B","src":"cf","name":"Mr. Kitayuta's Colorful Graph","rating":1400,"from":"curated"},{"id":"295B","src":"cf","name":"Greg and Graph","rating":1700,"from":"curated"},{"id":"1204C","src":"cf","name":"Anna, Svyatoslav and Maps","rating":1700,"from":"curated"},{"id":"33B","src":"cf","name":"String Problem","rating":1800,"from":"curated"},{"id":"25C","src":"cf","name":"Roads in Berland","rating":1900,"from":"curated"},{"id":"1205B","src":"cf","name":"Shortest Cycle","rating":1900,"from":"curated"},{"id":"2057E1","src":"cf","name":"Another Exercise on Graphs (Easy Version)","rating":2300,"from":"usaco-guide"},{"id":"21D","src":"cf","name":"Traveling Graph","rating":2400,"from":"curated"},{"id":"cses-1672","src":"cses","name":"Shortest Routes II","from":"usaco-guide"}]}]},{"id":"dag","name":"Topological Sort & DAGs","cfTags":["graphs","dfs and similar","dp"],"subtopics":[{"id":"dag-toposort","name":"Topological sort","tier":1500,"order":1,"prereq":["graph-dfs-bfs","graph-cycle-detection"],"summary":"Order the vertices of a directed acyclic graph so every edge goes forward, using Kahn's algorithm (repeatedly remove in-degree 0) or reversed DFS finishing times. Appears in dependency/ordering problems (\"A must come before B\") and as the first step of any DAG DP.","learn":["Kahn's BFS: queue of in-degree-0 vertices; if fewer than n vertices are output there is a cycle","DFS post-order reversed is also a topological order","Lexicographically smallest order: use a min-heap instead of a queue; \"smallest label first\" variants may need reversing the graph (Minimal Labels)","Derive the constraint graph from input (adjacent words, screenshots, comparisons) then toposort","Orient undirected edges along a topological order of the directed ones to keep the graph acyclic","Equalities + inequalities: merge equal items with DSU, then toposort the quotient graph"],"resources":[{"title":"CPH 16.1 Topological sorting","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 16.1 (p. 149)","minutes":15},{"title":"USACO Guide: Topological Sort","url":"https://usaco.guide/gold/toposort","kind":"usaco","where":"USACO Guide Gold","minutes":40},{"title":"cp-algorithms: Topological Sorting","url":"https://cp-algorithms.com/graph/topological-sort.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"510C","src":"cf","name":"Fox And Names","rating":1600,"from":"usaco-guide"},{"id":"1931F","src":"cf","name":"Chat Screenshots","rating":1700,"from":"curated"},{"id":"645D","src":"cf","name":"Robot Rapping Results Report","rating":1800,"from":"curated"},{"id":"909E","src":"cf","name":"Coprocessor","rating":1900,"from":"curated"},{"id":"1385E","src":"cf","name":"Directing Edges","rating":2000,"from":"usaco-guide"},{"id":"1131D","src":"cf","name":"Gourmet choice","rating":2000,"from":"curated"},{"id":"1100E","src":"cf","name":"Andrew and Taxi","rating":2200,"from":"curated"},{"id":"1765H","src":"cf","name":"Hospital Queue","rating":2200,"from":"curated"},{"id":"825E","src":"cf","name":"Minimal Labels","rating":2300,"from":"curated"},{"id":"1476E","src":"cf","name":"Pattern Matching","rating":2300,"from":"usaco-guide"},{"id":"cses-1679","src":"cses","name":"Course Schedule","from":"usaco-guide"},{"id":"cses-1757","src":"cses","name":"Course Schedule II","from":"usaco-guide"}]},{"id":"dag-dp","name":"DP on DAGs","tier":1700,"order":2,"prereq":["dag-toposort","@dp-intro"],"summary":"Any DP whose dependency graph is acyclic can be evaluated in topological order: longest/shortest path, number of paths, best path value. Recognise it when states have a directed \"move\" relation without cycles, or when a problem's graph is explicitly a DAG.","learn":["Process vertices in topological order (or memoised DFS) and relax dp[v] from dp[u] over edges u->v","Longest path in a DAG is easy (unlike general graphs); count paths mod p the same way","Combine with binary search on the answer (check \"path of length k using values <= X\" on the sub-DAG)","Detect cycle => answer infinite / -1 before doing DP","Memoised DFS with an \"in progress\" state doubles as cycle detection","For graphs with cycles, condense SCCs first (see scc-condensation)","The same pattern is studied from the DP side in @dp-dag; here the focus is building the graph and the topological order"],"resources":[{"title":"CPH 16.2 Dynamic programming on DAGs","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 16.2 (p. 151)","minutes":20},{"title":"USACO Guide: Topological Sort - dynamic programming","url":"https://usaco.guide/gold/toposort","kind":"usaco","where":"USACO Guide Gold","minutes":40}],"problems":[{"id":"1851E","src":"cf","name":"Nastya and Potions","rating":1500,"from":"curated"},{"id":"919D","src":"cf","name":"Substring","rating":1700,"from":"usaco-guide"},{"id":"721C","src":"cf","name":"Journey","rating":1800,"from":"curated"},{"id":"1572A","src":"cf","name":"Book","rating":1800,"from":"curated"},{"id":"1679D","src":"cf","name":"Toss a Coin to Your Graph...","rating":1900,"from":"curated"},{"id":"1472G","src":"cf","name":"Moving to the Capital","rating":2100,"from":"usaco-guide"},{"id":"2003D2","src":"cf","name":"Turtle and a MEX Problem (Hard Version)","rating":2100,"from":"curated"},{"id":"1627E","src":"cf","name":"Not Escaping","rating":2200,"from":"usaco-guide"},{"id":"cses-1680","src":"cses","name":"Longest Flight Route","from":"usaco-guide"},{"id":"cses-1681","src":"cses","name":"Game Routes","from":"usaco-guide"}]},{"id":"graph-games","name":"Games on graphs (retrograde analysis)","tier":2000,"order":3,"prereq":["dag-dp","sp-multisource-bfs","@game-states-dp"],"summary":"Two players move a token along the edges of a (state) graph. On a DAG, win/lose is a DP in reverse topological order; with cycles, positions can be draws, and the right tool is retrograde analysis: a BFS backwards from terminal positions that fixes a state as soon as its result is forced. Recognise 'who wins with optimal play, or does the game last forever' on a graph or on (position, whose turn) states.","learn":["State = (vertex, player to move, extra info); losing terminal states seed the queue","Retrograde BFS: a state is WIN if some move reaches a LOSE state; LOSE once all its moves (count down an out-degree counter) reach WIN states; states never fixed are DRAW","On a DAG simple memoised DFS / reverse topological DP suffices (no draws)","Parity games (who makes the last move, odd/even path length): state (v, parity) and BFS/DFS on the doubled graph; a reachable cycle gives a draw (Sleepy Game)","Grid variant: force a robot to a target by marking cells with at most one free non-forced neighbour, BFS outward from the target (Crazy Robot)","Detect infinite play: a cycle reachable among undecided states; longest game length via DP on the decided DAG part","Impartial games that split into independent parts need Sprague-Grundy instead (see @game-sprague-grundy)"],"resources":[{"title":"CPH 25.1 Game states","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 25.1 (p. 235)","minutes":20},{"title":"cp-algorithms: Games on arbitrary graphs","url":"https://cp-algorithms.com/game_theory/games_on_graphs.html","kind":"cpalgo","where":"cp-algorithms","minutes":25},{"title":"USACO Guide: Game Theory","url":"https://usaco.guide/adv/game-theory","kind":"usaco","where":"USACO Guide Advanced","minutes":40}],"problems":[{"id":"1613E","src":"cf","name":"Crazy Robot","rating":2000,"from":"curated"},{"id":"786A","src":"cf","name":"Berzerk","rating":2000,"from":"curated"},{"id":"936B","src":"cf","name":"Sleepy Game","rating":2100,"from":"curated"},{"id":"48E","src":"cf","name":"Ivan the Fool VS Gorynych the Dragon","rating":2100,"from":"curated"},{"id":"2137G","src":"cf","name":"Cry Me a River","rating":2200,"from":"curated"},{"id":"919F","src":"cf","name":"A Game With Numbers","rating":2600,"from":"curated"}]}]},{"id":"dsu","name":"Disjoint Set Union","cfTags":["dsu"],"subtopics":[{"id":"dsu-basics","name":"DSU: union by size & path compression","tier":1300,"order":1,"prereq":["graph-components"],"summary":"Union-find maintains a partition of elements under merges with near-constant time find/union. Use it whenever components only grow: dynamic connectivity with edge additions, grouping equivalent items, checking whether an edge closes a cycle.","learn":["find with path compression + union by size/rank -> O(alpha(n)) amortised","Keep extra per-root data (size, min, max, sum, count of edges) and merge it in unite()","unite returns false if already connected -> cycle detection / redundant edge","Number of components = n - successful unions","Small-to-large merging of sets/maps stored at roots for richer per-component info","Iterative find avoids deep recursion"],"resources":[{"title":"CPH 15.2 Union-find structure","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 15.2 (p. 145)","minutes":20},{"title":"USACO Guide: Disjoint Set Union","url":"https://usaco.guide/gold/dsu","kind":"usaco","where":"USACO Guide Gold","minutes":35},{"title":"cp-algorithms: Disjoint Set Union","url":"https://cp-algorithms.com/data_structures/disjoint_set_union.html","kind":"cpalgo","where":"cp-algorithms","minutes":20},{"title":"Codeforces EDU: Disjoint Sets Union (steps 1-2)","url":"https://codeforces.com/edu/course/2/lesson/7","kind":"cf-edu","where":"Codeforces EDU course 2, lesson 7","minutes":90}],"problems":[{"id":"1638C","src":"cf","name":"Inversion Graph","rating":1300,"from":"curated"},{"id":"1139C","src":"cf","name":"Edgy Trees","rating":1500,"from":"curated"},{"id":"1800E2","src":"cf","name":"Unforgivable Curse (hard version)","rating":1500,"from":"curated"},{"id":"1609D","src":"cf","name":"Social Network","rating":1600,"from":"curated"},{"id":"1383A","src":"cf","name":"String Transformation 1","rating":1700,"from":"curated"},{"id":"1971G","src":"cf","name":"XOUR","rating":1700,"from":"curated"},{"id":"691D","src":"cf","name":"Swaps in Permutation","rating":1700,"from":"curated"},{"id":"2020D","src":"cf","name":"Connect the Dots","rating":1800,"from":"curated"},{"id":"25D","src":"cf","name":"Roads not only in Berland","rating":1900,"from":"curated"},{"id":"1027F","src":"cf","name":"Session in BSU","rating":2400,"from":"curated"},{"id":"cses-1676","src":"cses","name":"Road Construction","from":"usaco-guide"}]},{"id":"dsu-offline","name":"DSU offline tricks (reverse deletions, sorted processing)","tier":1700,"order":2,"prereq":["dsu-basics"],"summary":"DSU cannot delete, so process deletions in reverse as insertions, or sort edges/queries by weight and answer queries while merging. Also the \"next free pointer\" DSU skips already-processed cells in O(alpha).","learn":["Reverse time: removals become unions; record answers backwards","Sort edges by weight and queries by threshold; answer \"connected using edges <= w\" offline","Count pairs inside merged components: when merging sizes a and b, add a*b","DSU \"next pointer\": parent[i] = i+1 after painting i to jump over finished positions","Bitwise greedy with DSU: try to keep bit k off, test connectivity using only allowed edges","Value-replacement queries (replace all x by y): DSU on values/positions"],"resources":[{"title":"Codeforces EDU: Disjoint Sets Union (steps 1-2)","url":"https://codeforces.com/edu/course/2/lesson/7","kind":"cf-edu","where":"Codeforces EDU course 2, lesson 7","minutes":90},{"title":"USACO Guide: Disjoint Set Union","url":"https://usaco.guide/gold/dsu","kind":"usaco","where":"USACO Guide Gold","minutes":35},{"title":"cp-algorithms: Disjoint Set Union - applications","url":"https://cp-algorithms.com/data_structures/disjoint_set_union.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"722C","src":"cf","name":"Destroying Array","rating":1600,"from":"curated"},{"id":"1131F","src":"cf","name":"Asya And Kittens","rating":1700,"from":"curated"},{"id":"1213G","src":"cf","name":"Path Queries","rating":1800,"from":"curated"},{"id":"1081D","src":"cf","name":"Maximum Distance","rating":1800,"from":"curated"},{"id":"1620E","src":"cf","name":"Replace the Numbers","rating":1900,"from":"usaco-guide"},{"id":"1851G","src":"cf","name":"Vlad and the Mountains","rating":2000,"from":"curated"},{"id":"cses-2101","src":"cses","name":"New Roads Queries","from":"usaco-guide"}]},{"id":"dsu-weighted","name":"Weighted / parity DSU","tier":1800,"order":3,"prereq":["dsu-basics","graph-bipartite"],"summary":"Store at each node its offset (potential, parity, xor) relative to its root, so relations like x_u - x_v = d or x_u xor x_v = c can be merged and checked for contradictions online. Used for liar/truth-teller puzzles, relative positions, and bipartiteness with merges.","learn":["find returns (root, offset to root); update offsets during path compression","When merging u,v with required relation d, set offset[ru] so the relation holds; contradiction if already same root with different value","Parity DSU (2n nodes: x and not-x) is equivalent and easier to code","Per component, keep counts of each parity to choose the better colouring (min/max)","xor-constraints on tree paths reduce to parity DSU on prefix xors"],"resources":[{"title":"Codeforces EDU: Disjoint Sets Union (steps 1-2)","url":"https://codeforces.com/edu/course/2/lesson/7","kind":"cf-edu","where":"Codeforces EDU course 2, lesson 7","minutes":90},{"title":"cp-algorithms: DSU - support the parity of the path length / distance to representative","url":"https://cp-algorithms.com/data_structures/disjoint_set_union.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"1850H","src":"cf","name":"The Third Letter","rating":1700,"from":"curated"},{"id":"1594D","src":"cf","name":"The Number of Imposters","rating":1700,"from":"curated"},{"id":"766D","src":"cf","name":"Mahmoud and a Dictionary","rating":2000,"from":"curated"},{"id":"1387A","src":"cf","name":"Graph","rating":2100,"from":"usaco-guide"},{"id":"1615D","src":"cf","name":"X(or)-mas Tree","rating":2200,"from":"curated"},{"id":"1290C","src":"cf","name":"Prefix Enlightenment","rating":2400,"from":"curated"}]},{"id":"dsu-rollback","name":"DSU with rollbacks & offline dynamic connectivity","tier":2300,"order":4,"prereq":["dsu-offline"],"summary":"Union by size without path compression has O(log n) finds and every union can be undone from a stack. Combined with a segment tree over time (each edge alive on an interval), this solves offline add/remove-edge connectivity and bipartiteness queries in O(q log q log n).","learn":["No path compression; push (child root, old size) on a stack, pop to undo","Segment tree over query time: insert each edge into O(log q) nodes covering its lifetime, DFS the tree applying/undoing unions","Parity DSU with rollback answers dynamic bipartiteness","Grouping edges by weight then testing each query's edges with rollback (Envy)","Divide and conquer on queries + rollback replaces deletions"],"resources":[{"title":"USACO Guide: Offline Deletion","url":"https://usaco.guide/adv/offline-del","kind":"usaco","where":"USACO Guide Advanced","minutes":45},{"title":"cp-algorithms: Deleting from a data structure in O(T(n) log n)","url":"https://cp-algorithms.com/data_structures/deleting_in_log_n.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"891C","src":"cf","name":"Envy","rating":2300,"from":"usaco-guide"},{"id":"813F","src":"cf","name":"Bipartite Checking","rating":2500,"from":"curated"},{"id":"1140F","src":"cf","name":"Extending Set of Points","rating":2600,"from":"usaco-guide"},{"id":"1217F","src":"cf","name":"Forced Online Queries Problem","rating":2600,"from":"usaco-guide"},{"id":"1386C","src":"cf","name":"Joker","rating":2800,"from":"usaco-guide"},{"id":"cses-2133","src":"cses","name":"Dynamic Connectivity","from":"curated"}]}]},{"id":"mst","name":"Minimum Spanning Trees","cfTags":["graphs","dsu","greedy","trees"],"subtopics":[{"id":"mst-kruskal-prim","name":"MST: Kruskal & Prim","tier":1600,"order":1,"prereq":["dsu-basics"],"summary":"A minimum spanning tree connects all vertices with minimum total weight. Kruskal sorts edges and adds those joining different DSU components; Prim grows one tree with a priority queue (O(n^2) version for dense/complete graphs).","learn":["Kruskal: sort edges, unite if find(u)!=find(v); O(m log m)","Prim with a heap for sparse graphs; O(n^2) array Prim for complete graphs with implicit weights","Virtual source vertex: \"build a station at v for c_v\" = edge (0,v,c_v)","Reduce candidate edges: in special graphs only O(n) edges can be in the MST (e.g. connect to the global min)","Maximum spanning tree / minimax path: sort descending","Bitwise objectives (OR/AND of weights): greedy bit by bit with connectivity checks"],"resources":[{"title":"CPH 15.1 Kruskal's algorithm","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 15.1 (p. 142)","minutes":20},{"title":"CPH 15.3 Prim's algorithm","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 15.3 (p. 147)","minutes":10},{"title":"USACO Guide: Minimum Spanning Trees","url":"https://usaco.guide/gold/mst","kind":"usaco","where":"USACO Guide Gold","minutes":40},{"title":"cp-algorithms: Kruskal with DSU","url":"https://cp-algorithms.com/graph/mst_kruskal_with_dsu.html","kind":"cpalgo","where":"cp-algorithms","minutes":20},{"title":"cp-algorithms: Prim's Algorithm","url":"https://cp-algorithms.com/graph/mst_prim.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"1468J","src":"cf","name":"Road Reform","rating":1800,"from":"curated"},{"id":"1095F","src":"cf","name":"Make It Connected","rating":1900,"from":"curated"},{"id":"1245D","src":"cf","name":"Shichikuji and Power Grid","rating":1900,"from":"curated"},{"id":"472D","src":"cf","name":"Design Tutorial: Inverse the Problem","rating":1900,"from":"usaco-guide"},{"id":"2117G","src":"cf","name":"Omg Graph","rating":1900,"from":"curated"},{"id":"1624G","src":"cf","name":"MinOr Tree","rating":1900,"from":"curated"},{"id":"1927F","src":"cf","name":"Microcycle","rating":1900,"from":"curated"},{"id":"cses-1675","src":"cses","name":"Road Reparation","from":"usaco-guide"}]},{"id":"mst-properties","name":"MST properties: cut/cycle, uniqueness, per-edge MST","tier":2000,"order":2,"prereq":["mst-kruskal-prim","@trees-lca"],"summary":"Cut property: the lightest edge across any cut is in some MST; cycle property: the heaviest edge on a cycle is in none. These answer whether an edge is in all/some/no MSTs, the MST forced to contain an edge, making the MST unique, and second-best MST.","learn":["Process equal-weight groups together in Kruskal to classify edges as \"any\", \"at least one\", \"none\"","MST containing edge (u,v,w) = MST - max edge on the tree path u..v + w (binary lifting max / LCA)","Second-best MST via the same max-on-path query","Unique MST iff no non-tree edge has weight equal to the max on its tree path","Bridges inside a weight group (on the component graph) identify edges in every MST"],"resources":[{"title":"cp-algorithms: Second Best Minimum Spanning Tree","url":"https://cp-algorithms.com/graph/second_best_mst.html","kind":"cpalgo","where":"cp-algorithms","minutes":20},{"title":"cp-algorithms: Minimum spanning tree - Kruskal","url":"https://cp-algorithms.com/graph/mst_kruskal.html","kind":"cpalgo","where":"cp-algorithms","minutes":20},{"title":"USACO Guide: Minimum Spanning Trees","url":"https://usaco.guide/gold/mst","kind":"usaco","where":"USACO Guide Gold","minutes":40}],"problems":[{"id":"1857G","src":"cf","name":"Counting Graphs","rating":2000,"from":"curated"},{"id":"1108F","src":"cf","name":"MST Unification","rating":2100,"from":"usaco-guide"},{"id":"609E","src":"cf","name":"Minimum spanning tree for each edge","rating":2100,"from":"usaco-guide"},{"id":"76A","src":"cf","name":"Gift","rating":2200,"from":"curated"},{"id":"160D","src":"cf","name":"Edges in MST","rating":2300,"from":"curated"},{"id":"1707C","src":"cf","name":"DFS Trees","rating":2400,"from":"curated"},{"id":"1023F","src":"cf","name":"Mobile Phone Network","rating":2600,"from":"curated"},{"id":"827D","src":"cf","name":"Best Edge Weight","rating":2700,"from":"curated"}]},{"id":"mst-special","name":"Special MSTs: Boruvka, implicit & complete graphs","tier":2300,"order":3,"prereq":["mst-kruskal-prim"],"summary":"When the graph is complete or defined implicitly (weights from xor, gcd, distances), you cannot list all edges. Boruvka's algorithm (each component picks its cheapest outgoing edge per round, log n rounds) plus a data structure (trie, segment tree) finds those edges fast.","learn":["Boruvka: O(log n) rounds; in each, find for every component its min outgoing edge","Xor-MST: divide and conquer on a binary trie, merging subtrees with the min xor pair","Complement graphs: unlisted edges have weight 0/1 -> BFS over the complement with a set of unvisited vertices","Cheapest outgoing edge often = nearest value in a sorted set excluding own component","Prove only O(n) or O(n log n) candidate edges matter, then run Kruskal"],"resources":[{"title":"USACO Guide: Minimum Spanning Trees","url":"https://usaco.guide/gold/mst","kind":"usaco","where":"USACO Guide Gold","minutes":40},{"title":"cp-algorithms: Prim - dense graphs","url":"https://cp-algorithms.com/graph/mst_prim.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"1513D","src":"cf","name":"GCD and MST","rating":2000,"from":"usaco-guide"},{"id":"888G","src":"cf","name":"Xor-MST","rating":2300,"from":"usaco-guide"},{"id":"1633E","src":"cf","name":"Spanning Tree Queries","rating":2400,"from":"curated"},{"id":"125E","src":"cf","name":"MST Company","rating":2400,"from":"curated"},{"id":"1508C","src":"cf","name":"Complete the MST","rating":2500,"from":"curated"},{"id":"1120D","src":"cf","name":"Power Tree","rating":2500,"from":"curated"},{"id":"1550F","src":"cf","name":"Jumping Around","rating":2700,"from":"curated"}]},{"id":"mst-kruskal-tree","name":"Kruskal reconstruction tree (DSU tree)","tier":2300,"order":4,"prereq":["mst-kruskal-prim","@trees-lca"],"summary":"While running Kruskal, create a new node for each union whose children are the two merged roots and whose value is the edge weight. Then \"the minimal max-edge on a path between u and v\" is the value at their LCA, and \"vertices reachable using edges <= x\" is a subtree.","learn":["Each union creates node n+k with weight w; leaves are original vertices; tree has 2n-1 nodes","Bottleneck (minimax) distance between u,v = weight(LCA(u,v))","Reachable set under threshold x = subtree of the highest ancestor with weight <= x (binary lifting), contiguous in Euler tour","Combine with segment tree on Euler tour for \"max value in reachable set\" queries","For a range of vertices [l,r], answer = LCA of all, i.e. LCA of the dfs-order min and max"],"resources":[{"title":"USACO Guide: Kruskal Reconstruction Tree","url":"https://usaco.guide/plat/kruskal-tree","kind":"usaco","where":"USACO Guide Platinum","minutes":35},{"title":"[Tutorial] Reachability Tree / DSU-tree","url":"https://codeforces.com/blog/entry/85714","kind":"cf-blog","where":"Codeforces blog","minutes":30}],"problems":[{"id":"1706E","src":"cf","name":"Qpwoeirut and Vertices","rating":2300,"from":"usaco-guide"},{"id":"1253F","src":"cf","name":"Cheap Robot","rating":2500,"from":"curated"},{"id":"1416D","src":"cf","name":"Graph and Queries","rating":2600,"from":"usaco-guide"},{"id":"1797F","src":"cf","name":"Li Hua and Path","rating":3000,"from":"curated"},{"id":"1628E","src":"cf","name":"Groceries in Meteor Town","rating":3100,"from":"usaco-guide"}]}]},{"id":"connectivity","name":"Connectivity: SCC, Bridges, BCC, 2-SAT","cfTags":["dfs and similar","graphs","2-sat"],"subtopics":[{"id":"scc","name":"Strongly connected components (Kosaraju / Tarjan)","tier":1900,"order":1,"prereq":["dag-toposort"],"summary":"An SCC is a maximal set of vertices mutually reachable in a directed graph. Kosaraju (DFS order, then DFS on the reversed graph) or Tarjan (low-link) find all SCCs in O(n+m). Appears when cycles in a directed graph make vertices equivalent.","learn":["Kosaraju: DFS to get finish order, then DFS on reversed graph in decreasing finish time","Tarjan: tin/low with a stack; a root of an SCC has low == tin","Kosaraju outputs SCCs in topological order of the condensation","Min cost to cover all SCCs = per-SCC minimum (Checkposts); counts multiply","Edges to add to make the graph strongly connected = max(#sources, #sinks) in the condensation (if >1 SCC)","Number of SCCs with in-degree 0 = vertices needed to reach everything"],"resources":[{"title":"CPH 17.1 Kosaraju's algorithm","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 17.1 (p. 158)","minutes":20},{"title":"USACO Guide: Strongly Connected Components","url":"https://usaco.guide/adv/SCC","kind":"usaco","where":"USACO Guide Advanced","minutes":45},{"title":"cp-algorithms: Strongly connected components and condensation graph","url":"https://cp-algorithms.com/graph/strongly-connected-components.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"427C","src":"cf","name":"Checkposts","rating":1700,"from":"curated"},{"id":"949C","src":"cf","name":"Data Center Maintenance","rating":1900,"from":"curated"},{"id":"999E","src":"cf","name":"Reachability from the Capital","rating":2000,"from":"curated"},{"id":"22E","src":"cf","name":"Scheme","rating":2300,"from":"curated"},{"id":"1239D","src":"cf","name":"Catowice City","rating":2400,"from":"usaco-guide"},{"id":"cses-1683","src":"cses","name":"Planets and Kingdoms","from":"usaco-guide"},{"id":"cses-1685","src":"cses","name":"New Flight Routes","from":"usaco-guide"}]},{"id":"scc-condensation","name":"Condensation graph & DP over SCCs","tier":2100,"order":2,"prereq":["scc","dag-dp"],"summary":"Contract each SCC to a single node to get a DAG (the condensation), then run DAG DP: maximum collectable value, reachability counts, longest path where a whole cycle can be taken for free. Recognise \"walk anywhere, revisits allowed, collect values\".","learn":["Weight of a condensed node = sum/aggregate of its vertices (or of its internal edges, e.g. repeated mushroom collection)","DP in topological order of the condensation (Kosaraju already gives it)","Infinite answers: any SCC with a cycle reachable on the path","Layered state graphs (vertex, day mod d) can be condensed too","Count \"number of paths\" classes: 0, 1, many, infinite via DP on the condensation"],"resources":[{"title":"USACO Guide: Strongly Connected Components","url":"https://usaco.guide/adv/SCC","kind":"usaco","where":"USACO Guide Advanced","minutes":45},{"title":"cp-algorithms: Condensation graph","url":"https://cp-algorithms.com/graph/strongly-connected-components.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"894E","src":"cf","name":"Ralph and Mushrooms","rating":2100,"from":"usaco-guide"},{"id":"1547G","src":"cf","name":"How Many Paths?","rating":2100,"from":"curated"},{"id":"1900E","src":"cf","name":"Transitive Graph","rating":2100,"from":"curated"},{"id":"1213F","src":"cf","name":"Unstable String Sort","rating":2100,"from":"curated"},{"id":"1137C","src":"cf","name":"Museums Tour","rating":2500,"from":"curated"},{"id":"1534F2","src":"cf","name":"Falling Sand (Hard Version)","rating":3000,"from":"usaco-guide"},{"id":"cses-1686","src":"cses","name":"Coin Collector","from":"usaco-guide"}]},{"id":"bridges-articulation","name":"Bridges & articulation points","tier":2000,"order":3,"prereq":["graph-dfs-tree"],"summary":"A bridge is an edge whose removal disconnects the graph; an articulation (cut) vertex is a vertex whose removal does. Both are found with tin/low values in one DFS. Use them for \"critical roads/cities\", minimising pairs separated by deleting one edge, and strong orientations.","learn":["low[v] = min(tin[v], tin of back-edge targets, low of children)","Edge (p,v) is a bridge iff low[v] > tin[p]; vertex p is a cut vertex iff low[v] >= tin[p] for some child (root: >= 2 children)","Handle multi-edges by skipping the parent EDGE id, not the parent vertex","A graph without bridges can be oriented to be strongly connected (orient tree edges down, back edges up)","Removing a bridge splits into sizes s and n-s: pairs separated = s*(n-s)"],"resources":[{"title":"cp-algorithms: Finding bridges in a graph in O(N+M)","url":"https://cp-algorithms.com/graph/bridge-searching.html","kind":"cpalgo","where":"cp-algorithms","minutes":20},{"title":"cp-algorithms: Finding articulation points in a graph in O(N+M)","url":"https://cp-algorithms.com/graph/cutpoints.html","kind":"cpalgo","where":"cp-algorithms","minutes":20},{"title":"USACO Guide: Biconnected Components","url":"https://usaco.guide/adv/BCC-2CC","kind":"usaco","where":"USACO Guide Advanced","minutes":45},{"title":"[Tutorial] The DFS tree and its applications","url":"https://codeforces.com/blog/entry/68138","kind":"cf-blog","where":"Codeforces blog","minutes":40}],"problems":[{"id":"1986F","src":"cf","name":"Non-academic Problem","rating":1900,"from":"curated"},{"id":"118E","src":"cf","name":"Bertown roads","rating":2000,"from":"curated"},{"id":"1000E","src":"cf","name":"We Need More Bosses","rating":2100,"from":"curated"},{"id":"732F","src":"cf","name":"Tourist Reform","rating":2300,"from":"curated"},{"id":"700C","src":"cf","name":"Break Up","rating":2600,"from":"curated"},{"id":"cses-2076","src":"cses","name":"Necessary Roads","from":"curated"},{"id":"cses-2077","src":"cses","name":"Necessary Cities","from":"curated"}]},{"id":"bcc","name":"2-edge-connected & biconnected components, block-cut tree","tier":2300,"order":4,"prereq":["bridges-articulation"],"summary":"Removing all bridges splits the graph into 2-edge-connected components; contracting them gives the bridge tree. Vertex-biconnected components (blocks) form the block-cut tree. Both turn graph questions into tree questions (paths, LCA).","learn":["Bridge tree: contract 2ECCs, remaining edges (bridges) form a tree; longest path in it = max bridges on a path","Biconnected components via an edge stack in Tarjan; each cut vertex belongs to several blocks","Block-cut tree: nodes for blocks and cut vertices; \"must pass through vertex x\" queries become tree path queries","Cactus graphs: every edge in at most one cycle; contract cycles into nodes","A block with #edges == #vertices is a simple cycle"],"resources":[{"title":"USACO Guide: Biconnected Components","url":"https://usaco.guide/adv/BCC-2CC","kind":"usaco","where":"USACO Guide Advanced","minutes":45},{"title":"cp-algorithms: Strong Orientation","url":"https://cp-algorithms.com/graph/strong-orientation.html","kind":"cpalgo","where":"cp-algorithms","minutes":20},{"title":"cp-algorithms: Articulation points","url":"https://cp-algorithms.com/graph/cutpoints.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"231E","src":"cf","name":"Cactus","rating":2100,"from":"curated"},{"id":"652E","src":"cf","name":"Pursuit For Artifacts","rating":2300,"from":"curated"},{"id":"962F","src":"cf","name":"Simple Cycles Edges","rating":2400,"from":"curated"},{"id":"1763F","src":"cf","name":"Edge Queries","rating":3000,"from":"curated"},{"id":"487E","src":"cf","name":"Tourists","rating":3200,"from":"curated"},{"id":"cses-2177","src":"cses","name":"Strongly Connected Edges","from":"usaco-guide"},{"id":"cses-1705","src":"cses","name":"Forbidden Cities","from":"usaco-guide"}]},{"id":"two-sat","name":"2-SAT","tier":2000,"order":5,"prereq":["scc"],"summary":"Satisfy a conjunction of clauses (a or b) over boolean variables by building the implication graph (not a -> b, not b -> a) and computing SCCs: unsatisfiable iff x and not x share an SCC. Recognise binary choices per item with pairwise conflicts (flip or not, swap or not, side A or B).","learn":["2n nodes: x and not x; each clause adds two implications","Unsat iff comp[x]==comp[not x]; assignment: x = true iff comp[x] comes after comp[not x] in topological order (Tarjan: comp[x] < comp[not x])","Encode \"exactly one\", \"equal\", \"different\", forced values (x -> not x)","Binary search on an answer + 2-SAT feasibility check","Prefix/suffix auxiliary variables encode \"at most one of a group\" in O(n) clauses","Parity-only constraints are easier with DSU; use 2-SAT when there are genuine ORs"],"resources":[{"title":"CPH 17.2 2SAT problem","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 17.2 (p. 160)","minutes":20},{"title":"cp-algorithms: 2-SAT","url":"https://cp-algorithms.com/graph/2SAT.html","kind":"cpalgo","where":"cp-algorithms","minutes":20},{"title":"USACO Guide: Strongly Connected Components - 2-SAT","url":"https://usaco.guide/adv/SCC","kind":"usaco","where":"USACO Guide Advanced","minutes":45}],"problems":[{"id":"1475F","src":"cf","name":"Unusual Matrix","rating":1900,"from":"usaco-guide"},{"id":"228E","src":"cf","name":"The Road to Berland is Paved With Good Intentions","rating":1900,"from":"curated"},{"id":"780D","src":"cf","name":"Innokenty and a Football League","rating":1900,"from":"curated"},{"id":"776D","src":"cf","name":"The Door Problem","rating":2000,"from":"usaco-guide"},{"id":"468B","src":"cf","name":"Two Sets","rating":2000,"from":"usaco-guide"},{"id":"875C","src":"cf","name":"National Property","rating":2100,"from":"curated"},{"id":"1971H","src":"cf","name":"±1","rating":2100,"from":"curated"},{"id":"27D","src":"cf","name":"Ring Road 2","rating":2200,"from":"curated"},{"id":"1385G","src":"cf","name":"Columns Swaps","rating":2300,"from":"curated"},{"id":"1903F","src":"cf","name":"Babysitting","rating":2500,"from":"usaco-guide"},{"id":"1657F","src":"cf","name":"Words on Tree","rating":2600,"from":"curated"},{"id":"1215F","src":"cf","name":"Radio Stations","rating":2700,"from":"curated"},{"id":"cses-1684","src":"cses","name":"Giant Pizza","from":"usaco-guide"}]}]},{"id":"euler-paths","name":"Euler Paths & Circuits","cfTags":["graphs","dfs and similar"],"subtopics":[{"id":"euler-tours","name":"Eulerian paths & circuits (Hierholzer)","tier":2000,"order":1,"prereq":["graph-components"],"summary":"An Eulerian path uses every edge exactly once. Existence is a degree condition plus connectivity; Hierholzer's algorithm builds it in O(n+m). Recognise \"use every edge/pair/domino exactly once\" or strings built from overlapping pieces (De Bruijn).","learn":["Undirected: circuit iff all degrees even; path iff exactly 0 or 2 odd vertices (all non-isolated vertices connected)","Directed: in==out everywhere for a circuit; one +1 start and one -1 end for a path","Hierholzer: iterative DFS with an edge pointer per vertex, append vertex on backtrack, reverse at the end","Mark used edges by id (undirected edges appear in two lists)","Model pieces as edges between \"states\" (overlaps of length k-1, value pairs) -> De Bruijn style","Hamiltonian paths (every vertex once) are NP-hard in general: bitmask DP (see @dp-bitmask)"],"resources":[{"title":"CPH 19.1 Eulerian paths","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 19.1 (p. 173)","minutes":20},{"title":"CPH 19.3 De Bruijn sequences","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 19.3 (p. 178)","minutes":10},{"title":"USACO Guide: Eulerian Tours","url":"https://usaco.guide/adv/eulerian-tours","kind":"usaco","where":"USACO Guide Advanced","minutes":40},{"title":"cp-algorithms: Finding the Eulerian path in O(M)","url":"https://cp-algorithms.com/graph/euler_path.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"1334D","src":"cf","name":"Minimum Euler Cycle","rating":1800,"from":"curated"},{"id":"788B","src":"cf","name":"Weird journey","rating":2100,"from":"curated"},{"id":"2110E","src":"cf","name":"Melody","rating":2300,"from":"curated"},{"id":"1152E","src":"cf","name":"Neko and Flashback","rating":2400,"from":"curated"},{"id":"1981D","src":"cf","name":"Turtle and Multiplication","rating":2400,"from":"usaco-guide"},{"id":"508D","src":"cf","name":"Tanya and Password","rating":2500,"from":"usaco-guide"},{"id":"1361C","src":"cf","name":"Johnny and Megan's Necklace","rating":2500,"from":"usaco-guide"},{"id":"cses-1691","src":"cses","name":"Mail Delivery","from":"usaco-guide"},{"id":"cses-1693","src":"cses","name":"Teleporters Path","from":"usaco-guide"},{"id":"cses-1692","src":"cses","name":"De Bruijn Sequence","from":"usaco-guide"}]},{"id":"euler-applications","name":"Euler tours for orientation & balancing","tier":2300,"order":2,"prereq":["euler-tours"],"summary":"Adding a dummy vertex joined to all odd-degree vertices makes every degree even; an Euler circuit then orients edges so in/out degrees differ by at most 1, or alternately colours edges to balance counts. Used in constructive problems about directing roads or splitting edges evenly.","learn":["Pair odd-degree vertices through a virtual node, take an Euler circuit, orient edges along it","Alternating colours along an Euler circuit splits each vertex's edges almost evenly","Bipartite graphs (rows/columns, values/positions) + Euler circuit give balanced assignments","Delete every second edge along an Euler tour to halve degrees (rounding up)","Adding edges to make degrees even = (#odd vertices)/2 extra edges"],"resources":[{"title":"USACO Guide: Eulerian Tours","url":"https://usaco.guide/adv/eulerian-tours","kind":"usaco","where":"USACO Guide Advanced","minutes":40},{"title":"cp-algorithms: Finding the Eulerian path in O(M)","url":"https://cp-algorithms.com/graph/euler_path.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"723E","src":"cf","name":"One-Way Reform","rating":2200,"from":"curated"},{"id":"1634E","src":"cf","name":"Fair Share","rating":2400,"from":"curated"},{"id":"1186F","src":"cf","name":"Vus the Cossack and a Graph","rating":2400,"from":"curated"},{"id":"527E","src":"cf","name":"Data Center Drama","rating":2600,"from":"curated"}]}]},{"id":"functional-graphs","name":"Functional / Successor Graphs","cfTags":["graphs","dfs and similar"],"subtopics":[{"id":"func-graph-cycles","name":"Functional graphs & permutation cycles","tier":1300,"order":1,"prereq":["graph-dfs-bfs"],"summary":"Every vertex has exactly one outgoing edge (i -> a_i): each component is one cycle with trees hanging into it. Permutations are the special case of disjoint cycles. Recognise arrays where \"i points to a_i\", repeated application of a function, or swaps that sort a permutation.","learn":["Find cycles with 3-colour iteration from every unvisited vertex; O(n)","Floyd's tortoise-and-hare finds a cycle with O(1) memory","Permutation: minimum swaps to sort = n - #cycles; cycle-dependent answers per element","Pick one vertex per cycle (e.g. minimum cost) for \"must cut each cycle\" questions","Tree parts hanging into cycles can be processed in Kahn order (in-degree peeling)","Distances to cycle and cycle lengths per vertex answer \"where am I after k steps\" for one query"],"resources":[{"title":"USACO Guide: Functional Graphs","url":"https://usaco.guide/silver/func-graphs","kind":"usaco","where":"USACO Guide Silver","minutes":35},{"title":"CPH 16.3 Successor paths","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 16.3 (p. 154)","minutes":10},{"title":"CPH 16.4 Cycle detection","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 16.4 (p. 155)","minutes":10},{"title":"cp-algorithms: Floyd's Linked List Cycle Finding Algorithm","url":"https://cp-algorithms.com/others/tortoise_and_hare.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"1020B","src":"cf","name":"Badge","rating":1000,"from":"usaco-guide"},{"id":"2008D","src":"cf","name":"Sakurako's Hobby","rating":1100,"from":"curated"},{"id":"1249B2","src":"cf","name":"Books Exchange (hard version)","rating":1300,"from":"curated"},{"id":"1027D","src":"cf","name":"Mouse Hunt","rating":1700,"from":"curated"},{"id":"2044G1","src":"cf","name":"Medium Demon Problem (easy version)","rating":1700,"from":"usaco-guide"},{"id":"1768D","src":"cf","name":"Lucky Permutation","rating":1800,"from":"curated"},{"id":"1867D","src":"cf","name":"Cyclic Operations","rating":1800,"from":"curated"},{"id":"1872F","src":"cf","name":"Selling a Menagerie","rating":1800,"from":"curated"},{"id":"2044G2","src":"cf","name":"Medium Demon Problem (hard version)","rating":1900,"from":"usaco-guide"},{"id":"1607F","src":"cf","name":"Robot on the Board 2","rating":2300,"from":"curated"},{"id":"1137D","src":"cf","name":"Cooperative Game","rating":2400,"from":"usaco-guide"},{"id":"cses-1751","src":"cses","name":"Planets Cycles","from":"usaco-guide"}]},{"id":"func-graph-lifting","name":"Binary lifting on successor graphs","tier":1900,"order":2,"prereq":["func-graph-cycles"],"summary":"Precompute up[j][v] = vertex after 2^j steps (plus aggregated sums/mins) to answer \"where am I after k steps\" and path aggregates in O(log k) per query. Also used to compute the distance between two vertices in a functional graph via cycle positions.","learn":["up[0][v] = f(v); up[j][v] = up[j-1][up[j-1][v]]; memory n*log(k)","Carry sums/mins alongside jumps (sum[j][v], mn[j][v])","Decompose k into binary and jump; for k up to 1e18 use 60 levels","Distance u -> v: v on the tail path of u, or both reach the same cycle and positions on the cycle differ","Same idea on trees = LCA via binary lifting"],"resources":[{"title":"CPH 16.3 Successor paths","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 16.3 (p. 154)","minutes":10},{"title":"USACO Guide: Functional Graphs","url":"https://usaco.guide/silver/func-graphs","kind":"usaco","where":"USACO Guide Silver","minutes":35},{"title":"cp-algorithms: LCA - binary lifting (same jump table idea)","url":"https://cp-algorithms.com/graph/lca_binary_lifting.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"702E","src":"cf","name":"Analysis of Pathes in Functional Graph","rating":2100,"from":"curated"},{"id":"1516D","src":"cf","name":"Cut","rating":2100,"from":"curated"},{"id":"1175E","src":"cf","name":"Minimal Segment Cover","rating":2200,"from":"curated"},{"id":"1335F","src":"cf","name":"Robots on a Grid","rating":2200,"from":"curated"},{"id":"cses-1750","src":"cses","name":"Planets Queries I","from":"usaco-guide"},{"id":"cses-1160","src":"cses","name":"Planets Queries II","from":"usaco-guide"},{"id":"cses-1191","src":"cses","name":"Cyclic Array","from":"usaco-guide"}]}]},{"id":"flows","name":"Flows & Matchings","cfTags":["flows","graph matchings"],"subtopics":[{"id":"flow-matching","name":"Bipartite matching, Konig & path covers","tier":1900,"order":1,"prereq":["graph-bipartite"],"summary":"Maximum bipartite matching pairs left and right vertices along edges. Kuhn's augmenting paths run in O(VE), Hopcroft-Karp in O(E sqrt V). Konig's theorem: max matching = min vertex cover in bipartite graphs; min path cover in a DAG = n - matching.","learn":["Kuhn: for each left vertex try to find an augmenting path with a visited array; greedy initial matching speeds it up","Hopcroft-Karp or Dinic on a unit network for 1e5 edges","Konig: min vertex cover = max matching; max independent set = n - max matching (bipartite only)","Minimum path cover of a DAG (vertex-disjoint) = n - max matching on split graph; with transitive closure for non-disjoint","Binary search on the answer + matching feasibility (Valuable Paper)","Incremental matching: add left vertices in order and augment from each (Maximize Mex)","Hall's theorem for proving greedy matchings exist"],"resources":[{"title":"CPH 20.3 Maximum matchings","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 20.3 (p. 187)","minutes":20},{"title":"CPH 20.4 Path covers","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 20.4 (p. 190)","minutes":10},{"title":"cp-algorithms: Kuhn's Algorithm for Maximum Bipartite Matching","url":"https://cp-algorithms.com/graph/kuhn_maximum_bipartite_matching.html","kind":"cpalgo","where":"cp-algorithms","minutes":20},{"title":"USACO Guide: Maximum Flow - bipartite matching","url":"https://usaco.guide/adv/max-flow","kind":"usaco","where":"USACO Guide Advanced","minutes":45}],"problems":[{"id":"1423B","src":"cf","name":"Valuable Paper","rating":1900,"from":"curated"},{"id":"498C","src":"cf","name":"Array and Operations","rating":2100,"from":"curated"},{"id":"852D","src":"cf","name":"Exploration plan","rating":2100,"from":"curated"},{"id":"387D","src":"cf","name":"George and Interesting Graph","rating":2200,"from":"curated"},{"id":"1139E","src":"cf","name":"Maximize Mex","rating":2400,"from":"curated"},{"id":"1783F","src":"cf","name":"Double Sort II","rating":2500,"from":"curated"},{"id":"cses-1696","src":"cses","name":"School Dance","from":"usaco-guide"}]},{"id":"flow-maxflow","name":"Maximum flow (Ford-Fulkerson, Edmonds-Karp, Dinic)","tier":2100,"order":2,"prereq":["flow-matching"],"summary":"Push as much flow as possible from s to t respecting edge capacities using augmenting paths in the residual graph. Dinic's algorithm (BFS levels + blocking flow DFS) is the contest standard. Recognise distribution/assignment problems with capacities and the modeling pattern source -> items -> resources -> sink.","learn":["Residual graph with paired reverse edges (store edge index, e and e^1)","Dinic: BFS level graph, DFS with current-arc pointers; O(V^2 E) in general, much faster in practice; O(E sqrt V) for bipartite matching (unit-capacity networks)","Split a vertex into in/out with capacity c to limit flow through a vertex","Edge-disjoint paths = max flow with unit capacities; reconstruct paths by following saturated edges","Binary search on time/capacity + max flow feasibility","Reconstructing per-edge flows from residual capacities gives the actual assignment"],"resources":[{"title":"CPH 20.1 Ford-Fulkerson algorithm","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 20.1 (p. 182)","minutes":25},{"title":"CPH 20.2 Disjoint paths","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 20.2 (p. 186)","minutes":10},{"title":"USACO Guide: Maximum Flow","url":"https://usaco.guide/adv/max-flow","kind":"usaco","where":"USACO Guide Advanced","minutes":50},{"title":"cp-algorithms: Maximum flow - Ford-Fulkerson and Edmonds-Karp","url":"https://cp-algorithms.com/graph/edmonds_karp.html","kind":"cpalgo","where":"cp-algorithms","minutes":20},{"title":"cp-algorithms: Maximum flow - Dinic's algorithm","url":"https://cp-algorithms.com/graph/dinic.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"1214D","src":"cf","name":"Treasure Island","rating":1900,"from":"curated"},{"id":"546E","src":"cf","name":"Soldier and Traveling","rating":2100,"from":"curated"},{"id":"269C","src":"cf","name":"Flawed Flow","rating":2100,"from":"curated"},{"id":"653D","src":"cf","name":"Delivery Bears","rating":2200,"from":"curated"},{"id":"510E","src":"cf","name":"Fox And Dinner","rating":2300,"from":"curated"},{"id":"1717F","src":"cf","name":"Madoka and The First Session","rating":2500,"from":"curated"},{"id":"cses-1694","src":"cses","name":"Download Speed","from":"usaco-guide"},{"id":"cses-1711","src":"cses","name":"Distinct Routes","from":"usaco-guide"}]},{"id":"flow-mincut","name":"Minimum cut & project selection","tier":2300,"order":3,"prereq":["flow-maxflow"],"summary":"Max-flow equals min s-t cut. Many optimisation problems (\"choose a subset maximising profit with dependencies/conflicts\") become min cut: the maximum closure / project selection pattern, where taking an item that requires another is an infinite edge.","learn":["Min cut edges: from vertices reachable from s in the final residual graph to unreachable ones","Project selection: profit p>0 -> edge s->v cap p; cost c -> edge v->t cap c; dependency u needs v -> u->v cap INF; answer = sum positive - maxflow","Separating two sets of vertices with min vertex/edge removals","Each variable with two choices + pairwise penalties = cut in a graph with s/t sides","Konig and min cut are the same idea in bipartite graphs"],"resources":[{"title":"USACO Guide: Minimum Cut","url":"https://usaco.guide/adv/min-cut","kind":"usaco","where":"USACO Guide Advanced","minutes":45},{"title":"CPH 20.1 Ford-Fulkerson algorithm - minimum cuts","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 20.1 (p. 182)","minutes":10},{"title":"cp-algorithms: Maximum flow - Dinic's algorithm","url":"https://cp-algorithms.com/graph/dinic.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"965D","src":"cf","name":"Single-use Stones","rating":1900,"from":"curated"},{"id":"311E","src":"cf","name":"Biologist","rating":2300,"from":"curated"},{"id":"1082G","src":"cf","name":"Petya and Graph","rating":2400,"from":"curated"},{"id":"808F","src":"cf","name":"Card Game","rating":2400,"from":"usaco-guide"},{"id":"1404E","src":"cf","name":"Bricks","rating":2800,"from":"usaco-guide"},{"id":"724E","src":"cf","name":"Goods transportation","rating":2900,"from":"usaco-guide"},{"id":"cses-1695","src":"cses","name":"Police Chase","from":"usaco-guide"}]},{"id":"flow-matching-theory","name":"Konig, Hall & Dilworth (matching theory)","tier":2400,"order":4,"prereq":["flow-matching","flow-mincut"],"summary":"Theorems that turn matching sizes into answers for other questions: Konig (bipartite min vertex cover = max matching, max independent set = n - matching), Hall's marriage condition (a perfect matching on the left exists iff every subset S has |N(S)| >= |S|), and Dilworth/minimum path cover (minimum chains covering a poset = maximum antichain = n - matching on the split graph). Recognise them when n is too large for an explicit flow but the condition can be checked with prefix sums, bitmasks or a segment tree.","learn":["Konig: in a bipartite graph min vertex cover = max matching; recover the cover from the residual graph (left side unreachable + right side reachable from s)","Max independent set in a bipartite graph = |V| - max matching; max weighted closure/independent set via min cut","Hall's theorem: left side saturable iff |N(S)| >= |S| for every subset S; often only 'interval' or 'mask' subsets need checking (2^k groups when the right side has k types)","Use Hall as a feasibility test inside a greedy: fix choices one by one and re-check Hall on bitmask counts (Allowed Letters)","Hall + binary search: on a line/circle the condition reduces to a max over windows (Round Marriage)","Dilworth: minimum chain cover of a DAG/poset = maximum antichain; vertex-disjoint path cover = n - matching on (out-copy, in-copy) split graph; non-disjoint paths need the transitive closure first","Grid row/column covering problems (cover all marked cells with lines) are min vertex cover = Konig","Tutte/general-graph matching (Blossom) is rarely needed; first check whether the graph is bipartite"],"resources":[{"title":"CPH 20.3 Maximum matchings (Hall, Konig)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 20.3 (p. 187)","minutes":25},{"title":"CPH 20.4 Path covers (Dilworth)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 20.4 (p. 190)","minutes":20},{"title":"cp-algorithms: Kuhn's algorithm for bipartite matching","url":"https://cp-algorithms.com/graph/kuhn_maximum_bipartite_matching.html","kind":"cpalgo","where":"cp-algorithms","minutes":25},{"title":"USACO Guide: Maximum Flow (matching & cuts)","url":"https://usaco.guide/adv/max-flow","kind":"usaco","where":"USACO Guide Advanced","minutes":45}],"problems":[{"id":"1009G","src":"cf","name":"Allowed Letters","rating":2400,"from":"curated"},{"id":"2026E","src":"cf","name":"Best Subsequence","rating":2500,"from":"curated"},{"id":"981F","src":"cf","name":"Round Marriage","rating":2500,"from":"curated"},{"id":"1198E","src":"cf","name":"Rectangle Painting 2","rating":2500,"from":"curated"},{"id":"1510B","src":"cf","name":"Button Lock","rating":2600,"from":"curated"},{"id":"1519F","src":"cf","name":"Chests and Keys","rating":3200,"from":"curated"},{"id":"1630F","src":"cf","name":"Making It Bipartite","rating":3400,"from":"curated"},{"id":"cses-1709","src":"cses","name":"Coin Grid","from":"usaco-guide"}]},{"id":"flow-mincost","name":"Min-cost max-flow & assignment","tier":2300,"order":5,"prereq":["flow-maxflow","sp-bellman-ford"],"summary":"Among maximum flows find one of minimum total cost by repeatedly augmenting along the cheapest residual path (Bellman-Ford/SPFA, or Dijkstra with potentials). Used for weighted assignment, choosing k disjoint paths of min cost, and convex costs (one unit edge per marginal cost).","learn":["Successive shortest paths with SPFA; switch to Dijkstra + Johnson potentials for speed","Reverse edges have cost -c","Convex cost per unit: add parallel unit edges with increasing costs (e.g. (2k-1) for squares)","Hungarian algorithm for dense n x n assignment in O(n^3)","Maximising profit: negate costs; stop augmenting when the path cost becomes positive if flow amount is free","Flow value limited to k: add a super-source edge with capacity k"],"resources":[{"title":"USACO Guide: Minimum Cost Flow","url":"https://usaco.guide/adv/min-cost-flow","kind":"usaco","where":"USACO Guide Advanced","minutes":45},{"title":"cp-algorithms: Minimum-cost flow - Successive shortest path algorithm","url":"https://cp-algorithms.com/graph/min_cost_flow.html","kind":"cpalgo","where":"cp-algorithms","minutes":20},{"title":"cp-algorithms: Hungarian algorithm for solving the assignment problem","url":"https://cp-algorithms.com/graph/hungarian-algorithm.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"237E","src":"cf","name":"Build String","rating":2000,"from":"usaco-guide"},{"id":"863F","src":"cf","name":"Almost Permutation","rating":2200,"from":"curated"},{"id":"1913E","src":"cf","name":"Matrix Problem","rating":2400,"from":"curated"},{"id":"277E","src":"cf","name":"Binary Tree on Plane","rating":2400,"from":"curated"},{"id":"884F","src":"cf","name":"Anti-Palindromize","rating":2500,"from":"curated"},{"id":"1061E","src":"cf","name":"Politics","rating":2600,"from":"curated"},{"id":"818G","src":"cf","name":"Four Melodies","rating":2600,"from":"usaco-guide"},{"id":"1107F","src":"cf","name":"Vasya and Endless Credits","rating":2600,"from":"usaco-guide"},{"id":"2046D","src":"cf","name":"For the Emperor!","rating":3100,"from":"usaco-guide"},{"id":"cses-2129","src":"cses","name":"Task Assignment","from":"usaco-guide"}]},{"id":"flow-lower-bounds","name":"Flows with demands (lower bounds) & circulations","tier":2700,"order":6,"prereq":["flow-maxflow"],"summary":"When edges must carry at least l units, transform to a circulation problem with a new source/sink and node excesses, then check feasibility with one max flow. Used in balancing/colouring problems with minimum requirements per row/column.","learn":["Replace edge (u,v,[l,r]) with capacity r-l and add excess: demand[v]+=l, demand[u]-=l","Add edge t->s with INF to turn s-t flow into a circulation; feasible iff all super-source edges saturate","Min/max flow with lower bounds: binary search or a second max flow on the residual","Min cost circulation for lower bounds with costs"],"resources":[{"title":"USACO Guide: Flow with Lower Bounds","url":"https://usaco.guide/adv/flow-lb","kind":"usaco","where":"USACO Guide Advanced","minutes":40},{"title":"cp-algorithms: Flows with demands","url":"https://cp-algorithms.com/graph/flow_with_demands.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"708D","src":"cf","name":"Incorrect Flow","rating":2900,"from":"usaco-guide"},{"id":"1288F","src":"cf","name":"Red-Blue Graph","rating":2900,"from":"curated"},{"id":"704D","src":"cf","name":"Captain America","rating":3100,"from":"usaco-guide"},{"id":"1416F","src":"cf","name":"Showing Off","rating":3300,"from":"usaco-guide"}]}]},{"id":"graph-modeling","name":"Graph Construction Tricks","cfTags":["graphs","shortest paths","data structures"],"subtopics":[{"id":"graph-state-space","name":"State graphs & layered graphs","tier":1700,"order":1,"prereq":["sp-dijkstra"],"summary":"When the cost of moving depends on extra information (coupon used, current bike, horse taken, medicines active), make a vertex for each (node, extra state) and run BFS/Dijkstra on the product graph. Recognise small extra parameters: a boolean, k <= 10, a bitmask of <= 10 bits, time mod small number.","learn":["Vertex = (v, s); total states n * |S| must fit in time/memory","Coupon / one discount: two layers, crossing edge with halved cost (CSES Flight Discount)","Speed factor or vehicle: state = best factor so far; prune dominated states","\"Max + min edge removed/added\" objectives: 4 layers for flags (Minimum Path)","Parity / time mod k layers for alternating edges or periodic constraints","Implicit state spaces (permutation of a grid, bitmask) with BFS + hashing"],"resources":[{"title":"USACO Guide: Shortest Paths with Non-Negative Edge Weights","url":"https://usaco.guide/gold/shortest-paths","kind":"usaco","where":"USACO Guide Gold","minutes":45},{"title":"USACO Guide: Unweighted Shortest Paths","url":"https://usaco.guide/gold/unweighted-shortest-paths","kind":"usaco","where":"USACO Guide Gold","minutes":35}],"problems":[{"id":"2041D","src":"cf","name":"Drunken Maze","rating":1700,"from":"curated"},{"id":"1915G","src":"cf","name":"Bicycles","rating":1800,"from":"curated"},{"id":"2014E","src":"cf","name":"Rendez-vous de Marian et Robin","rating":1800,"from":"curated"},{"id":"1601B","src":"cf","name":"Frog Traveler","rating":1900,"from":"curated"},{"id":"1846G","src":"cf","name":"Rudolf and CodeVid-23","rating":1900,"from":"curated"},{"id":"2059D","src":"cf","name":"Graph and Graph","rating":1900,"from":"curated"},{"id":"59E","src":"cf","name":"Shortest Path","rating":2000,"from":"curated"},{"id":"1801D","src":"cf","name":"The way home","rating":2100,"from":"curated"},{"id":"1486E","src":"cf","name":"Paired Payment","rating":2200,"from":"curated"},{"id":"1840F","src":"cf","name":"Railguns","rating":2200,"from":"curated"},{"id":"1473E","src":"cf","name":"Minimum Path","rating":2400,"from":"curated"},{"id":"cses-1195","src":"cses","name":"Flight Discount","from":"usaco-guide"},{"id":"cses-1670","src":"cses","name":"Swap Game","from":"usaco-guide"}]},{"id":"graph-virtual-nodes","name":"Virtual nodes & segment-tree graphs","tier":2000,"order":2,"prereq":["sp-dijkstra","sp-01-bfs"],"summary":"Replace O(n^2) pairwise edges with extra vertices: one node per colour/line/prime connected to its members (all members pairwise reachable through it), or segment-tree nodes so a vertex can connect to a range in O(log n) edges.","learn":["Group node: v -> g cost c, g -> v cost 0 models \"move between any two members for cost c\" with O(n) edges","Divide distances by 2 trick: use weight 1 on both halves and halve the answer","Prime-factor nodes: connect a number to each prime factor (Friendly Spiders)","Segment tree graph: an \"out\" tree (parent->child, 0 cost) and an \"in\" tree (child->parent) for range edges","Digit-split edges into chains of virtual nodes to compare lexicographic costs (Koala and Notebook)","Super source / super sink vertices for multiple starts/targets"],"resources":[{"title":"USACO Guide: Shortest Paths with Non-Negative Edge Weights","url":"https://usaco.guide/gold/shortest-paths","kind":"usaco","where":"USACO Guide Gold","minutes":45},{"title":"cp-algorithms: 0-1 BFS","url":"https://cp-algorithms.com/graph/01_bfs.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"1775D","src":"cf","name":"Friendly Spiders","rating":1800,"from":"usaco-guide"},{"id":"1941G","src":"cf","name":"Rudolf and Subway","rating":2000,"from":"curated"},{"id":"1520G","src":"cf","name":"To Go Or Not To Go?","rating":2200,"from":"curated"},{"id":"786B","src":"cf","name":"Legacy","rating":2300,"from":"curated"},{"id":"1209F","src":"cf","name":"Koala and Notebook","rating":2600,"from":"curated"}]},{"id":"graph-complement","name":"Complement graph traversal","tier":2100,"order":3,"prereq":["graph-components","dsu-basics"],"summary":"When the input lists the edges that are MISSING, BFS on the complement by keeping a set (or linked list) of still-unvisited vertices and scanning it, skipping vertices adjacent in the given graph. Total work O(n + m log n).","learn":["Maintain unvisited vertices in a std::set or a DSU \"next\" structure; erase when visited","For each popped vertex, iterate the unvisited set and skip those in its (sorted/hashed) given adjacency","Each skip charges to a given edge, each visit removes a vertex -> O((n+m) log n)","Components of the complement = components with 0-weight edges for 0-1 MST","Pigeonhole: if m is small, the vertex of minimum given-degree is complement-adjacent to all but deg of the others, so one complement component is huge and only few vertices need explicit handling"],"resources":[{"title":"USACO Guide: Graph Traversal","url":"https://usaco.guide/silver/graph-traversal","kind":"usaco","where":"USACO Guide Silver","minutes":45},{"title":"cp-algorithms: Search for connected components","url":"https://cp-algorithms.com/graph/search-for-connected-components.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"601A","src":"cf","name":"The Two Routes","rating":1600,"from":"curated"},{"id":"1242B","src":"cf","name":"0-1 MST","rating":1900,"from":"curated"},{"id":"920E","src":"cf","name":"Connected Components?","rating":2100,"from":"usaco-guide"},{"id":"190E","src":"cf","name":"Counter Attack","rating":2100,"from":"curated"},{"id":"653E","src":"cf","name":"Bear and Forgotten Tree 2","rating":2400,"from":"usaco-guide"},{"id":"1761E","src":"cf","name":"Make It Connected","rating":2400,"from":"curated"}]}]}]},{"area":"trees","topics":[{"id":"tree-fundamentals","name":"Tree Fundamentals","cfTags":["trees","dfs and similar"],"subtopics":[{"id":"trees-basics","name":"Tree basics: rooting, parent, depth, subtree size","tier":1100,"order":1,"prereq":["@graph-representation"],"summary":"A tree is a connected acyclic graph with n-1 edges. Rooting it with one DFS gives parent, depth and subtree size of every vertex, which is the starting point of almost every tree problem. Recognise it whenever input gives n-1 edges or a parent array p_2..p_n.","learn":["Equivalent definitions: connected + n-1 edges, acyclic + n-1 edges, unique simple path between every pair","Store as adjacency list; root at 1 and DFS passing the parent (dfs(v,p)) instead of a visited array","Compute par[v], dep[v]=dep[par]+1 on the way down and sz[v]=1+sum sz[child] on the way back up","Leaves = non-root vertices of degree 1; count leaves in each subtree bottom-up","Parent-array input (p_i < i) lets you process vertices n..2 in reverse order with no DFS at all","Implicit trees: heap numbering (children 2v, 2v+1, parent v/2) for complete binary trees","Recursion depth up to 2e5 is usually fine in C++ on CF but can overflow in other languages; know the iterative/BFS-order alternative","Classic greedy: value depth[v]-(sz[v]-1) of choosing a vertex (Linova and Kingdom)"],"resources":[{"title":"USACO Guide: Introduction to Tree Algorithms","url":"https://usaco.guide/silver/intro-tree","kind":"usaco","where":"USACO Guide Silver","minutes":30},{"title":"Competitive Programmer's Handbook: Tree algorithms / Tree traversal","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 14 (p. 133), 14.1 (p. 134)","minutes":15},{"title":"cp-algorithms: Depth First Search","url":"https://cp-algorithms.com/graph/depth-first-search.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"1843C","src":"cf","name":"Sum in Binary Tree","rating":800,"from":"curated"},{"id":"1843D","src":"cf","name":"Apple Tree","rating":1200,"from":"curated"},{"id":"1676G","src":"cf","name":"White-Black Balanced Subtrees","rating":1300,"from":"curated"},{"id":"1675D","src":"cf","name":"Vertical Paths","rating":1300,"from":"curated"},{"id":"1900C","src":"cf","name":"Anji's Binary Tree","rating":1300,"from":"curated"},{"id":"755C","src":"cf","name":"PolandBall and Forest","rating":1300,"from":"usaco-guide"},{"id":"1830A","src":"cf","name":"Copil Copac Draws Trees","rating":1400,"from":"curated"},{"id":"839C","src":"cf","name":"Journey","rating":1500,"from":"usaco-guide"},{"id":"580C","src":"cf","name":"Kefa and Park","rating":1500,"from":"curated"},{"id":"1336A","src":"cf","name":"Linova and Kingdom","rating":1600,"from":"curated"},{"id":"1056D","src":"cf","name":"Decorate Apple Tree","rating":1600,"from":"curated"},{"id":"cses-1674","src":"cses","name":"Subordinates","from":"usaco-guide"}]},{"id":"trees-traversal","name":"Traversal orders: DFS/BFS order, pre/post/in-order","tier":1300,"order":2,"prereq":["trees-basics"],"summary":"The order in which DFS or BFS visits vertices carries structure: preorder lists every subtree contiguously, postorder processes children before parents, BFS order is by layer. Problems ask to simulate or check such orders, reconstruct a tree from one, or process vertices layer by layer.","learn":["Preorder (entry time) puts each subtree in a contiguous block of length sz[v]; postorder is a valid bottom-up DP order","BFS from the root gives vertices sorted by depth; processing it in reverse is an iterative replacement for recursive DFS","Visiting children in sorted order makes the DFS order deterministic (Military Problem)","Binary trees: pre/in/post order and rebuilding a tree from preorder + inorder","Multi-source BFS on a tree (from all leaves or several marked vertices) and layer-by-layer leaf peeling","Checking whether a permutation is a valid DFS order: the parent of p[i+1] must be p[i] or an ancestor of p[i] (the current DFS stack), and every subtree must occupy a contiguous block"],"resources":[{"title":"Competitive Programmer's Handbook: Tree traversal / Binary trees","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 14.1 (p. 134), 14.4 (p. 139)","minutes":15},{"title":"USACO Guide: Graph Traversal","url":"https://usaco.guide/silver/graph-traversal","kind":"usaco","where":"USACO Guide Silver","minutes":40},{"title":"cp-algorithms: Breadth First Search","url":"https://cp-algorithms.com/graph/breadth-first-search.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"1741D","src":"cf","name":"Masha and a Beautiful Tree","rating":1300,"from":"curated"},{"id":"1437D","src":"cf","name":"Minimal Height Tree","rating":1600,"from":"curated"},{"id":"1006E","src":"cf","name":"Military Problem","rating":1600,"from":"curated"},{"id":"1593E","src":"cf","name":"Gardener and Tree","rating":1600,"from":"curated"},{"id":"1611E1","src":"cf","name":"Escape The Maze (easy version)","rating":1700,"from":"curated"},{"id":"1535D","src":"cf","name":"Playoff Tournament","rating":1800,"from":"curated"},{"id":"2002D1","src":"cf","name":"DFS Checker (Easy Version)","rating":1900,"from":"curated"},{"id":"cses-1702","src":"cses","name":"Tree Traversals","from":"curated"}]},{"id":"trees-diameter-center","name":"Diameter, centre and eccentricities","tier":1500,"order":3,"prereq":["trees-traversal"],"summary":"The diameter is the longest path in a tree; it is found by two BFS/DFS passes or by a DP that combines the two deepest child chains. The farthest vertex from any v is an endpoint of a diameter, and the centre is the middle of the diameter. Recognise it in \"max distance\", \"farthest vertex\", \"minimise the worst distance\" and chase/tag games.","learn":["Two-pass algorithm: farthest vertex a from any vertex, then farthest b from a; path a-b is a diameter","DP version: best two downward depths per vertex give the longest path through it (works with edge weights >= 0)","ecc(v) = max(dist(v,a), dist(v,b)) for the diameter endpoints a, b: all eccentricities in O(n)","Centre = middle vertex (or edge) of the diameter; minimises max distance; radius = ceil(D/2)","Diameter of a marked subset: same two-pass trick restricted to marked vertices","Merging two trees by an edge: new diameter = max(d1, d2, ceil(d1/2)+ceil(d2/2)+1) (DSU + diameter)","Compress equal-coloured components before taking the diameter (Anton and Tree)"],"resources":[{"title":"Competitive Programmer's Handbook: Diameter / All longest paths","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 14.2 (p. 135), 14.3 (p. 137)","minutes":20},{"title":"USACO Guide: Introduction to Tree Algorithms (diameter)","url":"https://usaco.guide/silver/intro-tree","kind":"usaco","where":"USACO Guide Silver","minutes":20}],"problems":[{"id":"1881F","src":"cf","name":"Minimum Maximum Distance","rating":1700,"from":"curated"},{"id":"1822F","src":"cf","name":"Gardening Friends","rating":1700,"from":"curated"},{"id":"1975D","src":"cf","name":"Paint the Tree","rating":1700,"from":"curated"},{"id":"1805D","src":"cf","name":"A Wide, Wide Graph","rating":1800,"from":"curated"},{"id":"1404B","src":"cf","name":"Tree Tag","rating":1900,"from":"curated"},{"id":"1294F","src":"cf","name":"Three Paths on a Tree","rating":2000,"from":"curated"},{"id":"337D","src":"cf","name":"Book of Evil","rating":2000,"from":"curated"},{"id":"455C","src":"cf","name":"Civilization","rating":2100,"from":"curated"},{"id":"734E","src":"cf","name":"Anton and Tree","rating":2100,"from":"curated"},{"id":"592D","src":"cf","name":"Super M","rating":2200,"from":"curated"},{"id":"cses-1131","src":"cses","name":"Tree Diameter","from":"usaco-guide"},{"id":"cses-1132","src":"cses","name":"Tree Distances I","from":"usaco-guide"}]},{"id":"trees-greedy","name":"Greedy on trees (leaves-first, cutting, covering)","tier":1500,"order":4,"prereq":["trees-basics"],"summary":"Many Div 2 B-E tree problems are greedy: process leaves first, take deepest vertices, cut a subtree as soon as it satisfies a condition, or push surplus up to the parent. Recognise it when the answer depends on simple local structure (degrees, leaves, depth, subtree sums) and a leaf has only one way to be served.","learn":["Leaves-first greedy: a leaf must be handled by its parent, so decide bottom-up (matching, covering, cutting into fixed-size pieces)","Bipartite colouring by depth parity solves many construction/assignment tasks","Degree arguments: a vertex of degree >= 3 or the degree of the special vertex decides many games and MEX constructions","Removing leaves layer by layer (topological peeling) to count rounds","Sorting children by subtree size / depth and taking the top k","Exchange arguments for path covers: each vertex passes the extra count to its best child","Cutting the tree into components with equal xor/sum: greedily cut a subtree as soon as it reaches the target value","Pairing/matching vertices to minimise or maximise total distance: count how many pairs must cross each edge (min(sz, n-sz) / parity of sz)"],"resources":[{"title":"USACO Guide: Introduction to Tree Algorithms","url":"https://usaco.guide/silver/intro-tree","kind":"usaco","where":"USACO Guide Silver","minutes":20},{"title":"Competitive Programmer's Handbook: Tree algorithms","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 14 (p. 133)","minutes":15}],"problems":[{"id":"1627C","src":"cf","name":"Not Assigning","rating":1400,"from":"curated"},{"id":"1665C","src":"cf","name":"Tree Infection","rating":1600,"from":"curated"},{"id":"2018C","src":"cf","name":"Tree Pruning","rating":1700,"from":"curated"},{"id":"1592C","src":"cf","name":"Bakry and Partitioning","rating":1700,"from":"curated"},{"id":"1693B","src":"cf","name":"Fake Plastic Trees","rating":1700,"from":"curated"},{"id":"1388C","src":"cf","name":"Uncle Bogdan and Country Happiness","rating":1800,"from":"curated"},{"id":"1833G","src":"cf","name":"Ksyusha and Chinchilla","rating":1800,"from":"curated"},{"id":"1746D","src":"cf","name":"Paths on the Tree","rating":1900,"from":"curated"},{"id":"1363E","src":"cf","name":"Tree Shuffling","rating":2000,"from":"curated"},{"id":"1387B1","src":"cf","name":"Village (Minimum)","rating":2100,"from":"usaco-guide"},{"id":"1385F","src":"cf","name":"Removing Leaves","rating":2300,"from":"curated"}]},{"id":"trees-games-constructive","name":"Games, constructive & interactive problems on trees","tier":1500,"order":5,"prereq":["trees-basics","trees-diameter-center"],"summary":"Tree games (moving a token, removing leaves, chasing) are decided by degrees, distances, parity of depths or the diameter; constructive tree tasks ask you to assign weights/labels or build a tree with given properties; interactive tasks let you query distances or LCAs. Recognise them by \"who wins\", \"assign values so that every path...\", \"construct a tree\" or \"this is an interactive problem\" on a tree.","learn":["Leaf-removal games: the special vertex being a leaf (degree <= 1) or the parity of n decides the winner (Game On Leaves)","Token-moving games on trees: compute win/lose for each vertex bottom-up (a vertex wins iff some child loses); for many starting vertices, reroot this DP (Game on Tree)","Chase games: compare distances and the diameter with the players' speeds (Tree Tag)","Bipartite colouring by depth parity: path lengths between leaves are even iff leaves share a colour (Edge Weight Assignment); also gives labelings via highest set bits (Treelabeling)","Constructing values/weights from a given order or partial data: process vertices in BFS/given order and set each value from its parent (Weights Assignment, Sum in the tree)","MEX/label constructions: put the small labels on edges around one vertex of degree >= 3 so no path contains all of them","Interactive: ask distances from one vertex, split vertices by depth parity and query the smaller class (<= n/2 queries); pair up leaves using LCA queries (Kuroni and the Celebration)","Sprague-Grundy on trees: staircase-Nim on vertices at alternate depths (Sagheer and Apple Tree)"],"resources":[{"title":"USACO Guide: Game Theory","url":"https://usaco.guide/adv/game-theory","kind":"usaco","where":"USACO Guide Advanced","minutes":40},{"title":"USACO Guide: Interactive and Communication Problems","url":"https://usaco.guide/adv/interactive","kind":"usaco","where":"USACO Guide Advanced","minutes":30},{"title":"Competitive Programmer's Handbook: Game states / Sprague-Grundy theorem","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 25.1 (p. 235), 25.3 (p. 238)","minutes":20},{"title":"USACO Guide: Introduction to Tree Algorithms","url":"https://usaco.guide/silver/intro-tree","kind":"usaco","where":"USACO Guide Silver","minutes":20}],"problems":[{"id":"1970C1","src":"cf","name":"Game on Tree (Easy)","rating":1400,"from":"curated"},{"id":"1611D","src":"cf","name":"Weights Assignment For Tree Edges","rating":1500,"from":"curated"},{"id":"1325C","src":"cf","name":"Ehab and Path-etic MEXs","rating":1500,"from":"curated"},{"id":"1098A","src":"cf","name":"Sum in the tree","rating":1600,"from":"curated"},{"id":"1363C","src":"cf","name":"Game On Leaves","rating":1600,"from":"curated"},{"id":"2006A","src":"cf","name":"Iris and Game on the Tree","rating":1700,"from":"curated"},{"id":"1970C2","src":"cf","name":"Game on Tree (Medium)","rating":1700,"from":"curated"},{"id":"1338B","src":"cf","name":"Edge Weight Assignment","rating":1800,"from":"curated"},{"id":"1534D","src":"cf","name":"Lost Tree","rating":1800,"from":"curated"},{"id":"1305D","src":"cf","name":"Kuroni and the Celebration","rating":1900,"from":"curated"},{"id":"2053E","src":"cf","name":"Resourceful Caterpillar Sequence","rating":1900,"from":"curated"},{"id":"1605D","src":"cf","name":"Treelabeling","rating":2100,"from":"curated"},{"id":"1943C","src":"cf","name":"Tree Compass","rating":2300,"from":"usaco-guide"},{"id":"812E","src":"cf","name":"Sagheer and Apple Tree","rating":2300,"from":"usaco-guide"}]},{"id":"trees-edge-contribution","name":"Counting over all paths: edge/vertex contribution","tier":1700,"order":6,"prereq":["trees-basics"],"summary":"Sums over all pairs of vertices (total distance, number of paths through a vertex, expected values) are computed by counting how many paths use each edge: sz[v]*(n-sz[v]) for the edge above v. Recognise it when the statement sums something over all O(n^2) pairs or paths.","learn":["Edge (v, par v) lies on sz[v]*(n-sz[v]) paths; sum of all distances = sum of w*sz*(n-sz)","Paths through vertex v: combine sizes of its child subtrees and the outside part","Assign the biggest weights to the edges used by most paths (sort contributions)","Edge used by cnt leaves below it: halving weight saves w/2*cnt (priority queue greedy)","Parity tricks: paths of odd length = (#even depth)*(#odd depth)","With probabilities: linearity of expectation over edges with combinatorial counts C(sz,k)","MEX/forbidden-vertex path counts via subtree sizes relative to a fixed root"],"resources":[{"title":"USACO Guide: DP on Trees - Introduction","url":"https://usaco.guide/gold/dp-trees","kind":"usaco","where":"USACO Guide Gold","minutes":30},{"title":"Competitive Programmer's Handbook: Tree traversal (subtree sizes by DP)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 14.1 (p. 134)","minutes":10}],"problems":[{"id":"1401D","src":"cf","name":"Maximum Distributed Tree","rating":1800,"from":"curated"},{"id":"1824B1","src":"cf","name":"LuoTianyi and the Floating Islands (Easy Version)","rating":1800,"from":"curated"},{"id":"1060E","src":"cf","name":"Sergey and Subway","rating":2000,"from":"curated"},{"id":"1399E1","src":"cf","name":"Weights Division (easy version)","rating":2000,"from":"curated"},{"id":"1454E","src":"cf","name":"Number of Simple Paths","rating":2000,"from":"curated"},{"id":"1399E2","src":"cf","name":"Weights Division (hard version)","rating":2200,"from":"curated"},{"id":"1824B2","src":"cf","name":"LuoTianyi and the Floating Islands (Hard Version)","rating":2300,"from":"usaco-guide"},{"id":"1527D","src":"cf","name":"MEX Tree","rating":2400,"from":"curated"},{"id":"1770E","src":"cf","name":"Koxia and Tree","rating":2400,"from":"curated"}]},{"id":"trees-centroid","name":"Centroid of a tree (finding it, properties)","tier":1700,"order":7,"prereq":["trees-basics"],"summary":"A centroid is a vertex whose removal leaves components of size at most n/2; every tree has one or two adjacent centroids. Found by walking from the root toward the heavy child. Appears in constructive problems, \"balanced split\" questions and as the building block of centroid decomposition.","learn":["Definition: max(n - sz[v], max child sz) <= n/2","Find it in O(n): compute sz, then walk from the root into the child with sz > n/2","There are at most two centroids and if two, they are adjacent","The centroid minimises the sum of distances to all vertices","Centroid of every subtree: it lies on the path from the subtree centroid of the heavy child up to v (Kay and Snowflake)","Moving a leaf between the two centroids to make the centroid unique (Link Cut Centroids)","Adding one leaf moves the centroid by at most one edge; track it incrementally with subtree counts (Two Centroids)","Interactive search for a hidden vertex: query the centroid of the remaining candidates to discard at least half each time (O(log n) queries)"],"resources":[{"title":"USACO Guide: Centroid Decomposition (Finding the centroid)","url":"https://usaco.guide/plat/centroid","kind":"usaco","where":"USACO Guide Platinum","minutes":20},{"title":"Hybrid Tutorial: Centroid Decomposition (centroid section)","url":"https://codeforces.com/blog/entry/81661","kind":"cf-blog","where":"Codeforces blog","minutes":15}],"problems":[{"id":"1406C","src":"cf","name":"Link Cut Centroids","rating":1700,"from":"curated"},{"id":"685B","src":"cf","name":"Kay and Snowflake","rating":1900,"from":"curated"},{"id":"708C","src":"cf","name":"Centroids","rating":2300,"from":"curated"},{"id":"2106G2","src":"cf","name":"Baudelaire (hard version)","rating":2500,"from":"curated"},{"id":"1387B2","src":"cf","name":"Village (Maximum)","rating":2500,"from":"usaco-guide"},{"id":"1827D","src":"cf","name":"Two Centroids","rating":2800,"from":"curated"},{"id":"cses-2079","src":"cses","name":"Finding a Centroid","from":"usaco-guide"}]}]},{"id":"tree-dp","name":"DP on Trees","cfTags":["trees","dp"],"subtopics":[{"id":"trees-dp-basics","name":"DP on trees (subtree DP)","tier":1600,"order":1,"prereq":["trees-basics","@dp-trees"],"summary":"Subtree DP stores dp[v][state] computed from the children of v in postorder: matching, independent set, colourings, best path through v, counting subsets. Recognise it when the answer decomposes over subtrees and each vertex has a small state (taken/not taken, colour, distance). Full theory lives in the DP area; here the focus is tree mechanics.","learn":["State dp[v][0/1] (vertex taken or not) and combine children with sum / max / product","Longest/best path through v = best two child values (Fair Nut, diameter-like DPs)","dp[v][d] = number of vertices at distance d in subtree for small k (Distance in Tree)","Counting subsets/components with products over children (Appleman and Tree)","Subtree knapsack merge: merging child tables of size sz is O(n^2) total, not O(n^3)","Min/max game DPs with alternating levels (Serval and Rooted Tree)","Iterate vertices in reverse BFS order to avoid deep recursion","Bigger state spaces (dp[v][k] over k chosen vertices / cut edges) are the tree-knapsack pattern: see @dp-tree-knapsack (Berland Federalization, Karen and Supermarket, Diameter Cuts)"],"resources":[{"title":"USACO Guide: DP on Trees - Introduction","url":"https://usaco.guide/gold/dp-trees","kind":"usaco","where":"USACO Guide Gold","minutes":40},{"title":"DP on Trees Tutorial","url":"https://codeforces.com/blog/entry/20935","kind":"cf-blog","where":"Codeforces blog","minutes":25},{"title":"Competitive Programmer's Handbook: All longest paths","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 14.3 (p. 137)","minutes":10}],"problems":[{"id":"1997D","src":"cf","name":"Maximize the Root","rating":1500,"from":"curated"},{"id":"1528A","src":"cf","name":"Parsa's Humongous Tree","rating":1600,"from":"usaco-guide"},{"id":"1689C","src":"cf","name":"Infected Tree","rating":1600,"from":"usaco-guide"},{"id":"1083A","src":"cf","name":"The Fair Nut and the Best Path","rating":1800,"from":"curated"},{"id":"161D","src":"cf","name":"Distance in Tree","rating":1800,"from":"usaco-guide"},{"id":"1153D","src":"cf","name":"Serval and Rooted Tree","rating":1900,"from":"curated"},{"id":"2050G","src":"cf","name":"Tree Destruction","rating":1900,"from":"curated"},{"id":"1929D","src":"cf","name":"Sasha and a Walk in the City","rating":1900,"from":"curated"},{"id":"461B","src":"cf","name":"Appleman and Tree","rating":2000,"from":"curated"},{"id":"1101D","src":"cf","name":"GCD Counting","rating":2000,"from":"curated"},{"id":"1988D","src":"cf","name":"The Omnipotent Monster Killer","rating":2000,"from":"curated"},{"id":"2014F","src":"cf","name":"Sheriff's Defense","rating":2000,"from":"curated"},{"id":"1249F","src":"cf","name":"Maximum Weight Subset","rating":2200,"from":"curated"},{"id":"1238F","src":"cf","name":"The Maximum Subtree","rating":2200,"from":"curated"},{"id":"cses-1130","src":"cses","name":"Tree Matching","from":"usaco-guide"}]},{"id":"trees-rerooting","name":"Rerooting (DP for all roots)","tier":1800,"order":2,"prereq":["trees-dp-basics","@dp-rerooting"],"summary":"Rerooting computes a rooted DP answer for every possible root in O(n): one DFS computes down[v] for subtrees, a second pushes up[v] (the answer of the part outside v's subtree) from parent to child. Recognise it when the problem asks \"for every vertex as root\" or \"choose the best root\".","learn":["Pass 1: down[v] from children; pass 2: up[child] from up[v] and the down values of the siblings","Excluding one child: prefix/suffix aggregates over children, or best and second best for max","Sum-of-distances rerooting: ans[c] = ans[v] - sz[c] + (n - sz[c])","Moving the root along an edge changes only that edge's orientation (Choosing Capital)","Combine with diameter: farthest distance from each vertex via rerooting or via diameter endpoints","Non-invertible operations (max, gcd) need prefix/suffix, never \"subtract the child\""],"resources":[{"title":"USACO Guide: DP on Trees - Solving For All Roots","url":"https://usaco.guide/gold/all-roots","kind":"usaco","where":"USACO Guide Gold","minutes":40},{"title":"Competitive Programmer's Handbook: All longest paths","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 14.3 (p. 137)","minutes":10}],"problems":[{"id":"219D","src":"cf","name":"Choosing Capital for Treeland","rating":1700,"from":"curated"},{"id":"1822F","src":"cf","name":"Gardening Friends","rating":1700,"from":"curated"},{"id":"1324F","src":"cf","name":"Maximum White Subtree","rating":1800,"from":"curated"},{"id":"1092F","src":"cf","name":"Tree with Maximum Cost","rating":1900,"from":"curated"},{"id":"1882D","src":"cf","name":"Tree XOR","rating":1900,"from":"curated"},{"id":"1970C3","src":"cf","name":"Game on Tree (Hard)","rating":1900,"from":"usaco-guide"},{"id":"337D","src":"cf","name":"Book of Evil","rating":2000,"from":"curated"},{"id":"1187E","src":"cf","name":"Tree Painting","rating":2100,"from":"usaco-guide"},{"id":"543D","src":"cf","name":"Road Improvement","rating":2300,"from":"curated"},{"id":"708C","src":"cf","name":"Centroids","rating":2300,"from":"curated"},{"id":"cses-1132","src":"cses","name":"Tree Distances I","from":"usaco-guide"},{"id":"cses-1133","src":"cses","name":"Tree Distances II","from":"usaco-guide"}]}]},{"id":"tree-queries","name":"Tree Queries & Decompositions","cfTags":["trees","data structures","divide and conquer"],"subtopics":[{"id":"trees-euler-tour","name":"Euler tour / subtree flattening + range queries","tier":1800,"order":1,"prereq":["trees-traversal","@ds-fenwick","@ds-segtree-basic"],"summary":"Recording entry time tin[v] and exit time tout[v] maps every subtree to a contiguous range, so subtree updates/queries become range operations on an array with a BIT or segment tree. Also u is an ancestor of v iff tin[u] <= tin[v] <= tout[u]. Recognise it in \"add to / query the subtree of v\" problems.","learn":["tin/tout from one DFS; subtree of v = positions [tin[v], tin[v]+sz[v]-1]","Ancestor test in O(1) with tin/tout (Tree Queries 1328E)","Subtree sum / point update -> BIT; subtree assign or add -> lazy segment tree","Root-to-v path sums via the trick +x at tin, -x at tout (path queries with BIT)","Vertices of a given depth inside a subtree: list tins per depth and binary search","Distinct values in subtrees: offline with small-to-large or sweep over the flattened array","Bitmask of colours in a segment tree when number of colours <= 60 (New Year Tree)","Offline growing trees: build the final tree first, then replay operations on its Euler order (A Growing Tree)","Advanced: Mo's algorithm on trees uses the 2n-length Euler tour (each vertex at tin and tout) so a path becomes a range (@ds-mo-algorithm); a segment tree over the Euler tour with depth info maintains a dynamic diameter"],"resources":[{"title":"USACO Guide: (Optional) Euler Tour Technique","url":"https://usaco.guide/gold/tree-euler","kind":"usaco","where":"USACO Guide Gold","minutes":40},{"title":"Competitive Programmer's Handbook: Subtrees and paths","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 18.2 (p. 164)","minutes":15}],"problems":[{"id":"1328E","src":"cf","name":"Tree Queries","rating":1900,"from":"curated"},{"id":"1899G","src":"cf","name":"Unusual Entertainment","rating":1900,"from":"curated"},{"id":"383C","src":"cf","name":"Propagating tree","rating":2000,"from":"curated"},{"id":"877E","src":"cf","name":"Danil and a Part-time Job","rating":2000,"from":"curated"},{"id":"1891F","src":"cf","name":"A Growing Tree","rating":2000,"from":"curated"},{"id":"620E","src":"cf","name":"New Year Tree","rating":2100,"from":"curated"},{"id":"343D","src":"cf","name":"Water Tree","rating":2100,"from":"curated"},{"id":"570D","src":"cf","name":"Tree Requests","rating":2200,"from":"curated"},{"id":"1916E","src":"cf","name":"Happy Life in University","rating":2300,"from":"curated"},{"id":"375D","src":"cf","name":"Tree and Queries","rating":2400,"from":"usaco-guide"},{"id":"cses-1137","src":"cses","name":"Subtree Queries","from":"usaco-guide"},{"id":"cses-1138","src":"cses","name":"Path Queries","from":"usaco-guide"},{"id":"cses-1139","src":"cses","name":"Distinct Colors","from":"usaco-guide"}]},{"id":"trees-binary-lifting","name":"Binary lifting (k-th ancestor, jump pointers)","tier":1900,"order":2,"prereq":["trees-basics","@func-graph-lifting"],"summary":"Store up[j][v] = 2^j-th ancestor of v; then any k-th ancestor is reached in O(log n) by its binary representation, and aggregates (min, max, sum) along the jumped edges can be stored alongside. The same idea works on any successor function (functional graphs, \"next\" pointers on arrays). Recognise it when you must jump far up a tree or along next-pointers many times.","learn":["up[0][v]=par[v], up[j][v]=up[j-1][up[j-1][v]]; LOG ~ 18-20 for n <= 2e5/1e6","k-th ancestor: for each set bit j of k jump up[j]","Binary-search on the ancestor chain: highest ancestor satisfying a monotone condition","Store path aggregates mx[j][v] (max edge, sum) together with the jump table","Online-built trees: a new leaf can fill its own table immediately (Tree 932D, Gold Transfer)","Jumping on arrays: next[i] = end of a greedy segment, then count jumps for range queries (Cut, Minimal Segment Cover)","Memory: [LOG][n] layout is cache-friendlier than [n][LOG] for the table build"],"resources":[{"title":"USACO Guide: Binary Jumping","url":"https://usaco.guide/plat/binary-jump","kind":"usaco","where":"USACO Guide Platinum","minutes":40},{"title":"Competitive Programmer's Handbook: Finding ancestors / Successor paths","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 18.1 (p. 163), 16.3 (p. 154)","minutes":15},{"title":"cp-algorithms: LCA - Binary Lifting","url":"https://cp-algorithms.com/graph/lca_binary_lifting.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"739B","src":"cf","name":"Alyona and a tree","rating":1900,"from":"curated"},{"id":"1142B","src":"cf","name":"Lynyrd Skynyrd","rating":2000,"from":"usaco-guide"},{"id":"208E","src":"cf","name":"Blood Cousins","rating":2100,"from":"curated"},{"id":"1516D","src":"cf","name":"Cut","rating":2100,"from":"curated"},{"id":"932D","src":"cf","name":"Tree","rating":2200,"from":"curated"},{"id":"1535E","src":"cf","name":"Gold Transfer","rating":2200,"from":"curated"},{"id":"1175E","src":"cf","name":"Minimal Segment Cover","rating":2200,"from":"curated"},{"id":"2033G","src":"cf","name":"Sakurako and Chefir","rating":2200,"from":"curated"},{"id":"cses-1687","src":"cses","name":"Company Queries I","from":"usaco-guide"},{"id":"cses-1750","src":"cses","name":"Planets Queries I","from":"usaco-guide"},{"id":"cses-1191","src":"cses","name":"Cyclic Array","from":"usaco-guide"}]},{"id":"trees-lca","name":"Lowest common ancestor (binary lifting, Euler + sparse table)","tier":1900,"order":3,"prereq":["trees-binary-lifting","trees-euler-tour","@ds-sparse-table"],"summary":"The LCA of u and v is their deepest common ancestor; it splits the u-v path in two, giving dist(u,v) = dep[u]+dep[v]-2*dep[lca]. Computed with binary lifting (O(log n) per query) or Euler tour + sparse table (O(1) per query). Needed for any path query on a static tree.","learn":["Binary lifting LCA: lift the deeper vertex to equal depth, then lift both while ancestors differ","Euler tour of size 2n-1 + RMQ on depth with a sparse table gives O(1) LCA","dist(u,v) = dep[u]+dep[v]-2*dep[lca(u,v)] (weighted: use root distances)","LCA of a set = LCA of the vertices with min and max tin (Company 1062E)","Checking whether a set of vertices lies on one path (Passable Paths)","LCA under a changed root r = the deepest of lca(u,v), lca(u,r), lca(v,r)","Tarjan offline LCA with DSU when all queries are known"],"resources":[{"title":"USACO Guide: (Optional) LCA with Euler Tour","url":"https://usaco.guide/gold/lca-euler","kind":"usaco","where":"USACO Guide Gold","minutes":30},{"title":"Competitive Programmer's Handbook: Lowest common ancestor","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 18.3 (p. 167)","minutes":20},{"title":"cp-algorithms: LCA with Euler tour + segment tree","url":"https://cp-algorithms.com/graph/lca.html","kind":"cpalgo","where":"cp-algorithms","minutes":20},{"title":"cp-algorithms: Tarjan's offline LCA","url":"https://cp-algorithms.com/graph/lca_tarjan.html","kind":"cpalgo","where":"cp-algorithms","minutes":15}],"problems":[{"id":"1702G1","src":"cf","name":"Passable Paths (easy version)","rating":1900,"from":"curated"},{"id":"832D","src":"cf","name":"Misha, Grisha and Underground","rating":1900,"from":"curated"},{"id":"1702G2","src":"cf","name":"Passable Paths (hard version)","rating":2000,"from":"curated"},{"id":"1304E","src":"cf","name":"1-Trees and Queries","rating":2000,"from":"curated"},{"id":"519E","src":"cf","name":"A and B and Lecture Rooms","rating":2100,"from":"curated"},{"id":"1062E","src":"cf","name":"Company","rating":2300,"from":"curated"},{"id":"916E","src":"cf","name":"Jamie and Tree","rating":2400,"from":"curated"},{"id":"cses-1688","src":"cses","name":"Company Queries II","from":"usaco-guide"},{"id":"cses-1135","src":"cses","name":"Distance Queries","from":"usaco-guide"}]},{"id":"trees-path-queries","name":"Distances & path queries, tree difference arrays","tier":1900,"order":4,"prereq":["trees-lca"],"summary":"Path questions on a static tree are answered by splitting at the LCA: prefix values from the root give path sums, binary lifting gives path max, and \"add x on path u-v\" is done offline with a difference on the tree (+x at u and v, -x at lca and its parent, then subtree sums). Recognise it in many paths/queries with updates applied before the answers are asked.","learn":["Path sum = pre[u]+pre[v]-2*pre[lca]+val[lca] with root prefix sums","Path max/min of edge weights with binary-lifting aggregates (MST for each edge)","Tree difference array for vertex paths: +1 u, +1 v, -1 lca, -1 par(lca); for edges: +1 u, +1 v, -2 lca","Depth-limited subtree updates offline with a difference array indexed by depth during DFS","Root-path stack + binary search for prefix conditions along the current path","Max-subarray-sum on a path needs mergeable segment info stored in lifting tables (Omsk Metro)","Graph with n+k edges: tree + few extra edges -> LCA distance plus Dijkstra from extra endpoints","k-th vertex on the path u-v: if k <= dep[u]-dep[lca] it is the k-th ancestor of u, otherwise an ancestor of v (binary lifting)","Count marked vertices on a path (or on the path to a query root) with an Euler-tour BIT of root-path counts + LCA (Tree 1111E)","Min/max edge on paths over many queries can also be answered with a Kruskal reconstruction tree (@mst-kruskal-tree)"],"resources":[{"title":"Competitive Programmer's Handbook: Subtrees and paths / LCA","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 18.2 (p. 164), 18.3 (p. 167)","minutes":20},{"title":"USACO Guide: Binary Jumping","url":"https://usaco.guide/plat/binary-jump","kind":"usaco","where":"USACO Guide Platinum","minutes":20}],"problems":[{"id":"1714G","src":"cf","name":"Path Prefixes","rating":1700,"from":"curated"},{"id":"1843F1","src":"cf","name":"Omsk Metro (simple version)","rating":1800,"from":"curated"},{"id":"191C","src":"cf","name":"Fools and Roads","rating":1900,"from":"curated"},{"id":"1076E","src":"cf","name":"Vasya and a Tree","rating":1900,"from":"curated"},{"id":"609E","src":"cf","name":"Minimum spanning tree for each edge","rating":2100,"from":"usaco-guide"},{"id":"1843F2","src":"cf","name":"Omsk Metro (hard version)","rating":2300,"from":"usaco-guide"},{"id":"1051F","src":"cf","name":"The Shortest Statement","rating":2400,"from":"usaco-guide"},{"id":"1111E","src":"cf","name":"Tree","rating":2500,"from":"curated"},{"id":"cses-1135","src":"cses","name":"Distance Queries","from":"usaco-guide"},{"id":"cses-1136","src":"cses","name":"Counting Paths","from":"curated"}]},{"id":"trees-small-to-large","name":"Small-to-large merging (DSU on tree / sack)","tier":2100,"order":5,"prereq":["trees-euler-tour"],"summary":"When every subtree needs a set/map of its contents, merge the smaller child structure into the larger: each element moves O(log n) times, giving O(n log n) or O(n log^2 n). The \"sack\" variant keeps the heavy child's data and re-adds light subtrees using the Euler order. Recognise it in per-subtree statistics (distinct colours, most frequent colour, counts per depth).","learn":["Swap so you always insert the smaller container into the bigger one (std::swap of sets/maps is O(1))","Each element moves O(log n) times because the container it lands in at least doubles","Sack: process light children and clear them, process heavy child and keep, then add light subtrees via tin range","Answer offline queries attached to vertices while v's data is \"live\"","Store per-depth maps to answer \"k-th descendants\" queries (Blood Cousins Return, Tree Requests)","Path-xor sets with small-to-large to detect zero-xor paths greedily (XOR Tree)","Same idea outside trees: merging DSU components, merging sorted vectors (@ds-small-to-large)","Depth-indexed arrays: inherit the deepest child's array (long-path decomposition) and merge others by depth for O(n) total (Dominant Indices)"],"resources":[{"title":"USACO Guide: Small-To-Large Merging","url":"https://usaco.guide/plat/merging","kind":"usaco","where":"USACO Guide Platinum","minutes":30},{"title":"[Tutorial] Sack (dsu on tree)","url":"https://codeforces.com/blog/entry/44351","kind":"cf-blog","where":"Codeforces blog","minutes":30},{"title":"Competitive Programmer's Handbook: Offline algorithms (merging data structures)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 18.4 (p. 170)","minutes":15}],"problems":[{"id":"1923E","src":"cf","name":"Count Paths","rating":2000,"from":"usaco-guide"},{"id":"208E","src":"cf","name":"Blood Cousins","rating":2100,"from":"curated"},{"id":"570D","src":"cf","name":"Tree Requests","rating":2200,"from":"curated"},{"id":"600E","src":"cf","name":"Lomsat gelral","rating":2300,"from":"usaco-guide"},{"id":"1009F","src":"cf","name":"Dominant Indices","rating":2300,"from":"curated"},{"id":"246E","src":"cf","name":"Blood Cousins Return","rating":2400,"from":"curated"},{"id":"375D","src":"cf","name":"Tree and Queries","rating":2400,"from":"usaco-guide"},{"id":"1709E","src":"cf","name":"XOR Tree","rating":2400,"from":"curated"},{"id":"741D","src":"cf","name":"Arpa’s letter-marked tree and Mehrdad’s Dokhtar-kosh paths","rating":2900,"from":"curated"},{"id":"cses-1139","src":"cses","name":"Distinct Colors","from":"usaco-guide"}]},{"id":"trees-hld","name":"Heavy-light decomposition","tier":2300,"order":6,"prereq":["trees-lca","@ds-lazy-propagation"],"summary":"HLD splits the tree into heavy chains so that every root-to-vertex path crosses O(log n) chains; laid out contiguously in one array, any path becomes O(log n) segments for a segment tree, giving O(log^2 n) path updates/queries (and subtree queries with the same order). Recognise it when both path updates and path queries are online.","learn":["Heavy child = child with largest subtree; light edges halve the subtree size, so <= log n per path","DFS visiting the heavy child first makes each chain and each subtree contiguous","Path query: while heads differ, jump the deeper head and query [pos[head], pos[v]]","Edge values: store the weight of edge (par v, v) at v and skip the LCA","Combine with lazy segment tree for path assign/add, and with subtree ranges at the same time","Heavy paths also help interactive/structural problems (descend along the heavy path)","Alternatives: binary lifting (static, no updates), Euler tour (subtree only), link-cut tree (dynamic)"],"resources":[{"title":"USACO Guide: Heavy-Light Decomposition","url":"https://usaco.guide/plat/hld","kind":"usaco","where":"USACO Guide Platinum","minutes":45},{"title":"cp-algorithms: Heavy-light decomposition","url":"https://cp-algorithms.com/graph/hld.html","kind":"cpalgo","where":"cp-algorithms","minutes":25},{"title":"Easiest HLD with subtree queries","url":"https://codeforces.com/blog/entry/53170","kind":"cf-blog","where":"Codeforces blog","minutes":20}],"problems":[{"id":"343D","src":"cf","name":"Water Tree","rating":2100,"from":"curated"},{"id":"1174F","src":"cf","name":"Ehab and the Big Finale","rating":2400,"from":"curated"},{"id":"593D","src":"cf","name":"Happy Tree Party","rating":2400,"from":"curated"},{"id":"1254D","src":"cf","name":"Tree Queries","rating":2700,"from":"usaco-guide"},{"id":"487E","src":"cf","name":"Tourists","rating":3200,"from":"curated"},{"id":"1017G","src":"cf","name":"The Tree","rating":3200,"from":"usaco-guide"},{"id":"cses-2134","src":"cses","name":"Path Queries II","from":"usaco-guide"},{"id":"cses-1138","src":"cses","name":"Path Queries","from":"usaco-guide"}]},{"id":"trees-centroid-decomposition","name":"Centroid decomposition","tier":2300,"order":7,"prereq":["trees-centroid","trees-lca"],"summary":"Recursively remove a centroid and recurse into the pieces: the centroid tree has depth O(log n), and every path of the original tree passes through the highest centroid on it. Used to count/optimise over all paths (paths of length k, xor/palindrome paths) and for nearest-marked-vertex queries with updates.","learn":["Build: find centroid of current component, mark removed, recurse; total O(n log n)","Every u-v path goes through the centroid-tree LCA of u and v","Counting paths: for each centroid gather distances from each child subtree, combine with a global counter, subtract same-subtree pairs","Online queries: store best[c] for every centroid ancestor c of v (O(log n) ancestors), dist via LCA or stored depths","Rank assignment by centroid depth gives a valid \"officer rank\" labelling (Ciel the Commander)","Watch constants: reuse arrays, avoid maps when possible, O(n log^2 n) is the usual budget"],"resources":[{"title":"USACO Guide: Centroid Decomposition","url":"https://usaco.guide/plat/centroid","kind":"usaco","where":"USACO Guide Platinum","minutes":45},{"title":"Hybrid Tutorial: Centroid Decomposition","url":"https://codeforces.com/blog/entry/81661","kind":"cf-blog","where":"Codeforces blog","minutes":40}],"problems":[{"id":"161D","src":"cf","name":"Distance in Tree","rating":1800,"from":"usaco-guide"},{"id":"321C","src":"cf","name":"Ciel the Commander","rating":2100,"from":"usaco-guide"},{"id":"342E","src":"cf","name":"Xenia and Tree","rating":2400,"from":"usaco-guide"},{"id":"914E","src":"cf","name":"Palindromes in a Tree","rating":2400,"from":"curated"},{"id":"293E","src":"cf","name":"Close Vertices","rating":2700,"from":"curated"},{"id":"715C","src":"cf","name":"Digit Tree","rating":2700,"from":"usaco-guide"},{"id":"833D","src":"cf","name":"Red-Black Cobweb","rating":2800,"from":"curated"},{"id":"776F","src":"cf","name":"Sherlock's bet to Moriarty","rating":2800,"from":"usaco-guide"},{"id":"cses-2079","src":"cses","name":"Finding a Centroid","from":"usaco-guide"},{"id":"cses-2080","src":"cses","name":"Fixed-Length Paths I","from":"usaco-guide"},{"id":"cses-2081","src":"cses","name":"Fixed-Length Paths II","from":"usaco-guide"}]},{"id":"trees-hashing","name":"Tree isomorphism & tree hashing","tier":2300,"order":8,"prereq":["trees-dp-basics","trees-centroid","@hash-polynomial"],"summary":"Rooted trees are isomorphic iff their canonical forms match: assign each vertex an id from the sorted list of its children's ids (collision-free with a map) or a randomized hash. For unrooted trees root at the centre/centroid(s). Recognise it in symmetry, counting distinct subtrees and \"same shape\" questions.","learn":["AHU canonical form: map sorted vector of child ids -> new id, O(n log n), no collisions","Random hashing: h(v) = f(sum of g(h(child))) with a random/strong mixing function; avoid plain polynomial hashes (hackable)","Unrooted isomorphism: compare rooted forms at the one or two centres (or centroids)","Symmetric trees: at most one child class may occur an odd number of times, and it must itself be symmetric (Symmetree)","Rerooting + hashing to get the hash of the tree rooted at every vertex","Count distinct subtree shapes with a set of ids"],"resources":[{"title":"Hashing root trees","url":"https://codeforces.com/blog/entry/113465","kind":"cf-blog","where":"Codeforces blog","minutes":20},{"title":"USACO Guide: String Hashing (hash function design)","url":"https://usaco.guide/gold/hashing","kind":"usaco","where":"USACO Guide Gold","minutes":30},{"title":"Competitive Programmer's Handbook: String hashing","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 26.3 (p. 245)","minutes":10}],"problems":[{"id":"1800G","src":"cf","name":"Symmetree","rating":2200,"from":"curated"},{"id":"1182D","src":"cf","name":"Complete Mirror","rating":2400,"from":"curated"},{"id":"1252F","src":"cf","name":"Regular Forestation","rating":2400,"from":"curated"},{"id":"1794E","src":"cf","name":"Labeling the Tree with Distances","rating":2400,"from":"curated"},{"id":"763D","src":"cf","name":"Timofey and a flat tree","rating":2900,"from":"curated"},{"id":"718D","src":"cf","name":"Andrew and Chemistry","rating":2900,"from":"curated"},{"id":"cses-1700","src":"cses","name":"Tree Isomorphism I","from":"curated"},{"id":"cses-1701","src":"cses","name":"Tree Isomorphism II","from":"curated"}]},{"id":"trees-virtual-tree","name":"Virtual (auxiliary) trees","tier":2400,"order":9,"prereq":["trees-lca","trees-euler-tour"],"summary":"Given k important vertices, the virtual tree keeps only them and the LCAs of tin-adjacent pairs (at most 2k-1 vertices), with edges compressed into paths. Running a tree DP on it makes the total cost proportional to the sum of k over all queries/colours. Recognise it when many queries each mark a small subset or when you process each colour class separately.","learn":["Sort marked vertices by tin, add LCAs of adjacent pairs, dedupe: <= 2k-1 vertices","Build edges with a stack in tin order (or by sorting again and linking to LCA of consecutive)","Compressed edge length = depth difference, used for distance/weight sums","Per-colour virtual trees: sum over colours of counts is n, so total O(n log n)","Typical DP on it: minimum cut separating marked vertices, counting paths with unique colours","Alternative for some problems: small-to-large or DSU-on-colours","Size of the minimal subtree (Steiner tree) spanning a set = half the sum of dist between cyclically tin-adjacent vertices; maintain it under insert/delete with a std::set ordered by tin (Archaeology)"],"resources":[{"title":"USACO Guide: Virtual Tree","url":"https://usaco.guide/plat/VT","kind":"usaco","where":"USACO Guide Platinum","minutes":40}],"problems":[{"id":"1923E","src":"cf","name":"Count Paths","rating":2000,"from":"usaco-guide"},{"id":"1681F","src":"cf","name":"Unique Occurrences","rating":2300,"from":"curated"},{"id":"1292D","src":"cf","name":"Chaotic V.","rating":2700,"from":"usaco-guide"},{"id":"613D","src":"cf","name":"Kingdom and its Cities","rating":2800,"from":"usaco-guide"},{"id":"1320E","src":"cf","name":"Treeland and Viruses","rating":3000,"from":"curated"},{"id":"176E","src":"cf","name":"Archaeology","rating":3100,"from":"curated"}]}]}]},{"area":"ds","topics":[{"id":"ds-linear","name":"Stacks, Queues, Deques & Linked Lists","cfTags":["data structures","implementation","two pointers"],"subtopics":[{"id":"ds-stack-basics","name":"Stack simulation & bracket matching","tier":1000,"order":1,"prereq":[],"summary":"A stack (LIFO) processes the most recent unfinished item first. It shows up in bracket/parenthesis sequences, undo operations, \"collapse adjacent equal/opposite items\" simulations and expression parsing. Recognise it when an element only interacts with the latest still-open element.","learn":["std::stack / vector push_back+pop_back; check empty() before top()/pop()","Regular bracket sequence: balance never negative and ends at 0; match each \")\" with the stack top","Collapse simulations (remove adjacent pairs, colliding objects) are a stack scan in O(n)","Store indices, not values, on the stack so you can measure lengths/distances (longest valid substring)","Process collisions/annihilations by grouping (e.g. by parity) and matching with a stack","Every element is pushed and popped at most once -> amortised O(n)"],"resources":[{"title":"CPH: Other structures (stack, queue, deque)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 4.5 (p. 41)","minutes":15},{"title":"USACO Guide: Introduction to Data Structures","url":"https://usaco.guide/bronze/intro-ds","kind":"usaco","where":"USACO Guide Bronze","minutes":20},{"title":"USACO Guide: Stacks","url":"https://usaco.guide/gold/stacks","kind":"usaco","where":"USACO Guide Gold","minutes":25}],"problems":[{"id":"1374C","src":"cf","name":"Move Brackets","rating":1000,"from":"curated"},{"id":"26B","src":"cf","name":"Regular Bracket Sequence","rating":1400,"from":"curated"},{"id":"612C","src":"cf","name":"Replace To Make Regular Bracket Sequence","rating":1400,"from":"curated"},{"id":"1279C","src":"cf","name":"Stack of Presents","rating":1400,"from":"curated"},{"id":"81A","src":"cf","name":"Plug-in","rating":1400,"from":"curated"},{"id":"343B","src":"cf","name":"Alternating Current","rating":1600,"from":"curated"},{"id":"1861C","src":"cf","name":"Queries for the Array","rating":1600,"from":"curated"},{"id":"5C","src":"cf","name":"Longest Regular Bracket Sequence","rating":1900,"from":"curated"},{"id":"911E","src":"cf","name":"Stack Sorting","rating":2000,"from":"curated"},{"id":"1525C","src":"cf","name":"Robot Collisions","rating":2000,"from":"curated"},{"id":"1092D1","src":"cf","name":"Great Vova Wall (Version 1)","rating":2200,"from":"curated"}]},{"id":"ds-monotonic-stack","name":"Monotonic stack / nearest smaller values","tier":1500,"order":2,"prereq":["ds-stack-basics"],"summary":"Keep a stack whose values are monotone; when a new element arrives, pop everything it \"beats\". This gives, for every index, the nearest smaller/greater element to the left/right in O(n). It appears in largest-rectangle, \"sum over all subarrays of max/min\", visibility/jump and contribution-counting problems.","learn":["Nearest smaller to the left: pop while top >= a[i]; the remaining top is the answer","Run it left-to-right and right-to-left to get the span [L_i, R_i] where a[i] is the minimum/maximum","Contribution technique: sum of max over all subarrays = sum a[i]*(i-L_i)*(R_i-i); break ties with < on one side and <= on the other","Largest rectangle in histogram and maximal all-ones sub-rectangle (row-by-row histograms)","Stack + DP: dp[i] computed from the element popped / the new top (skyscrapers, skyline, jumps)","Count \"rounds until stable\" style processes (Psychos in a line) with stack-stored step counts","The same stack pass builds the Cartesian tree (parent = the larger of the nearest smaller neighbours) - see the Cartesian tree sub-topic"],"resources":[{"title":"CPH: Nearest smaller elements","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 8.2 (p. 79)","minutes":15},{"title":"USACO Guide: Stacks (nearest smaller values)","url":"https://usaco.guide/gold/stacks","kind":"usaco","where":"USACO Guide Gold","minutes":25},{"title":"cp-algorithms: Minimum stack / Minimum queue","url":"https://cp-algorithms.com/data_structures/stack_queue_modification.html","kind":"cpalgo","where":"cp-algorithms","minutes":15}],"problems":[{"id":"91B","src":"cf","name":"Queue","rating":1500,"from":"curated"},{"id":"1313C1","src":"cf","name":"Skyscrapers (easy version)","rating":1500,"from":"curated"},{"id":"1779D","src":"cf","name":"Boris and His Amazing Haircut","rating":1700,"from":"curated"},{"id":"280B","src":"cf","name":"Maximum Xor Secondary","rating":1800,"from":"curated"},{"id":"547B","src":"cf","name":"Mike and Feet","rating":1900,"from":"usaco-guide"},{"id":"817D","src":"cf","name":"Imbalanced Array","rating":1900,"from":"curated"},{"id":"1313C2","src":"cf","name":"Skyscrapers (hard version)","rating":1900,"from":"curated"},{"id":"319B","src":"cf","name":"Psychos in a Line","rating":1900,"from":"curated"},{"id":"777E","src":"cf","name":"Hanoi Factory","rating":2000,"from":"curated"},{"id":"601B","src":"cf","name":"Lipshitz Sequence","rating":2100,"from":"curated"},{"id":"1482E","src":"cf","name":"Skyline Photo","rating":2100,"from":"curated"},{"id":"1407D","src":"cf","name":"Discrete Centrifugal Jumps","rating":2200,"from":"curated"},{"id":"1092D2","src":"cf","name":"Great Vova Wall (Version 2)","rating":2200,"from":"curated"},{"id":"cses-1645","src":"cses","name":"Nearest Smaller Values","from":"usaco-guide"},{"id":"cses-1142","src":"cses","name":"Advertisement","from":"usaco-guide"},{"id":"cses-1147","src":"cses","name":"Maximum Building I","from":"usaco-guide"},{"id":"cses-1148","src":"cses","name":"Maximum Building II","from":"usaco-guide"}]},{"id":"ds-queue-deque","name":"Queues & deques (simulation)","tier":1000,"order":3,"prereq":[],"summary":"A queue (FIFO) serves items in arrival order; a deque allows push/pop at both ends. They are used for round-based simulations, BFS, rotating sequences and greedy constructions that append to the front or back.","learn":["std::queue for FIFO simulation; std::deque supports push/pop_front/back and random access in O(1)","Rotations: pop_front then push_back simulates a cyclic shift; detect when the process becomes periodic","Greedy deque building: decide per element whether it goes to the front or back","Keep a set/array of \"currently in the queue\" flags to avoid duplicates","Bound the number of simulation steps (or detect cycles) before brute-forcing"],"resources":[{"title":"CPH: Other structures (deque, queue)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 4.5 (p. 41)","minutes":15},{"title":"USACO Guide: Introduction to Data Structures","url":"https://usaco.guide/bronze/intro-ds","kind":"usaco","where":"USACO Guide Bronze","minutes":20}],"problems":[{"id":"1234B1","src":"cf","name":"Social Network (easy version)","rating":1000,"from":"curated"},{"id":"1579E1","src":"cf","name":"Permutation Minimization by Deque","rating":1000,"from":"curated"},{"id":"1234B2","src":"cf","name":"Social Network (hard version)","rating":1300,"from":"curated"},{"id":"546C","src":"cf","name":"Soldier and Cards","rating":1400,"from":"curated"},{"id":"1066C","src":"cf","name":"Books Queries","rating":1400,"from":"curated"},{"id":"1179A","src":"cf","name":"Valeriy and Deque","rating":1500,"from":"curated"},{"id":"1579E2","src":"cf","name":"Array Optimization by Deque","rating":1700,"from":"curated"}]},{"id":"ds-monotonic-deque","name":"Monotonic deque / sliding window min-max","tier":1600,"order":4,"prereq":["ds-queue-deque","ds-monotonic-stack"],"summary":"A deque kept monotone gives the minimum/maximum of every window of a sliding range in amortised O(1). It speeds up DPs of the form dp[i] = min(dp[j]) + cost over j in a window, and two-pointer problems that need the window extreme.","learn":["Push back after popping worse elements from the back; pop front when the index leaves the window","Store indices in the deque, not values","Sliding window DP: dp[i] = min_{i-k<=j<i} dp[j] + c_i in O(n) instead of O(nk)","Two pointers with window max-min <= K: two deques (one for max, one for min)","Min-queue from two min-stacks: push onto the in-stack, pop from the out-stack (refill by moving everything when empty) - works for any associative op, e.g. gcd","Alternative: a queue built from two min-stacks, or a multiset when you also need deletions by value","Sliding median/cost needs two multisets (or order statistics), not a deque"],"resources":[{"title":"CPH: Sliding window minimum","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 8.3 (p. 81)","minutes":10},{"title":"USACO Guide: Sliding Window","url":"https://usaco.guide/gold/sliding-window","kind":"usaco","where":"USACO Guide Gold","minutes":25},{"title":"cp-algorithms: Minimum queue","url":"https://cp-algorithms.com/data_structures/stack_queue_modification.html","kind":"cpalgo","where":"cp-algorithms","minutes":15}],"problems":[{"id":"1941E","src":"cf","name":"Rudolf and k Bridges","rating":1600,"from":"curated"},{"id":"616D","src":"cf","name":"Longest k-Good Segment","rating":1600,"from":"usaco-guide"},{"id":"1918D","src":"cf","name":"Blocking Elements","rating":1900,"from":"curated"},{"id":"1077F1","src":"cf","name":"Pictures with Kittens (easy version)","rating":1900,"from":"curated"},{"id":"940E","src":"cf","name":"Cashback","rating":2000,"from":"curated"},{"id":"487B","src":"cf","name":"Strip","rating":2000,"from":"curated"},{"id":"1905D","src":"cf","name":"Cyclic MEX","rating":2000,"from":"curated"},{"id":"372C","src":"cf","name":"Watching Fireworks is Fun","rating":2100,"from":"curated"},{"id":"1077F2","src":"cf","name":"Pictures with Kittens (hard version)","rating":2100,"from":"curated"},{"id":"cses-1644","src":"cses","name":"Maximum Subarray Sum II","from":"usaco-guide"},{"id":"cses-1141","src":"cses","name":"Playlist","from":"usaco-guide"},{"id":"cses-2428","src":"cses","name":"Subarray Distinct Values","from":"usaco-guide"},{"id":"cses-1076","src":"cses","name":"Sliding Median","from":"usaco-guide"},{"id":"cses-1077","src":"cses","name":"Sliding Cost","from":"usaco-guide"}]},{"id":"ds-linked-list","name":"Linked lists (array-based) & deletions","tier":1600,"order":5,"prereq":["ds-queue-deque"],"summary":"Doubly linked lists stored in prev[]/next[] arrays allow O(1) deletion of an element while keeping neighbours. They are the tool for \"repeatedly delete elements and look at the new neighbours\" simulations, often combined with a set/priority queue of candidates.","learn":["nxt[i], prv[i] arrays; deleting i: nxt[prv[i]] = nxt[i], prv[nxt[i]] = prv[i]","Use sentinels 0 and n+1 to avoid boundary checks","Only the neighbours of deleted elements change -> re-check only them each round (amortised O(n))","Combine with a std::set / priority_queue of \"active\" candidates (largest, closest, ...)","Josephus-type problems: linked list for small n, order-statistics tree/BIT for large n","std::list exists but array-based lists are faster and easier to index"],"resources":[{"title":"CPH: Other structures","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 4.5 (p. 41)","minutes":10},{"title":"USACO Guide: More Operations on Sorted Sets (combine with sets)","url":"https://usaco.guide/gold/intro-sorted-sets","kind":"usaco","where":"USACO Guide Gold","minutes":20}],"problems":[{"id":"670E","src":"cf","name":"Correct Bracket Sequence Editor","rating":1700,"from":"curated"},{"id":"1154E","src":"cf","name":"Two Teams","rating":1800,"from":"curated"},{"id":"1922D","src":"cf","name":"Berserk Monsters","rating":1900,"from":"curated"},{"id":"1482D","src":"cf","name":"Playlist","rating":1900,"from":"curated"},{"id":"899E","src":"cf","name":"Segments Removal","rating":2000,"from":"curated"},{"id":"cses-2162","src":"cses","name":"Josephus Problem I","from":"curated"},{"id":"cses-2163","src":"cses","name":"Josephus Problem II","from":"curated"}]},{"id":"ds-cartesian-tree","name":"Cartesian tree & divide-and-conquer on the maximum","tier":2100,"order":6,"prereq":["ds-monotonic-stack","ds-sparse-table"],"summary":"The Cartesian tree of an array has the maximum (or minimum) at the root and the left/right parts as subtrees; it is built in O(n) with a monotonic stack. Problems that recurse \"split at the maximum, solve both sides\" or count subarrays whose max/min sits at a given index are DP or counting on this tree, often combined with iterating over the smaller side.","learn":["Build with one stack pass: pop smaller elements, the last popped becomes the left child, the new element becomes the right child of the stack top","Node i owns the range (L_i, R_i) between its nearest greater elements; subtree = that range","Recursion f(l, r) = solve(l, m-1) + solve(m+1, r) with m = argmax via sparse table is the same tree, built top-down","Iterate over the smaller of the two sides at each node: total O(n log n) (special segments, max = sum conditions)","Tree DP on the Cartesian tree counts arrays with a given \"position of maximum\" structure","Offline queries on the recursion (f(l, r)) become sums over nearest-greater spans with a BIT sweep"],"resources":[{"title":"cp-algorithms: Solve RMQ by finding LCA (Cartesian tree construction)","url":"https://cp-algorithms.com/graph/rmq_linear.html","kind":"cpalgo","where":"cp-algorithms","minutes":15},{"title":"cp-algorithms: Treap (Cartesian tree), building in O(n)","url":"https://cp-algorithms.com/data_structures/treap.html","kind":"cpalgo","where":"cp-algorithms","minutes":10},{"title":"CPH: Nearest smaller elements","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 8.2 (p. 79)","minutes":10}],"problems":[{"id":"1691D","src":"cf","name":"Max GEQ Sum","rating":1800,"from":"curated"},{"id":"1913D","src":"cf","name":"Array Collapse","rating":2100,"from":"curated"},{"id":"1156E","src":"cf","name":"Special Segments of Permutation","rating":2200,"from":"curated"},{"id":"1748E","src":"cf","name":"Yet Another Array Counting Problem","rating":2300,"from":"curated"},{"id":"1849E","src":"cf","name":"Max to the Right of Min","rating":2300,"from":"curated"},{"id":"1117G","src":"cf","name":"Recursive Queries","rating":2500,"from":"curated"}]}]},{"id":"ds-stl","name":"Heaps, Sets, Maps & Hashing","cfTags":["data structures","greedy","hashing","sortings"],"subtopics":[{"id":"ds-sets-maps","name":"Sets & maps basics (counting, distinct)","tier":900,"order":1,"prereq":[],"summary":"std::set keeps distinct sorted keys, std::map associates a value with each key (frequency counts, last positions, id->name). These solve \"have I seen this?\", \"how many times?\" and \"group equal things\" questions in O(log n).","learn":["set.insert/erase/count/find in O(log n); size() gives the number of distinct elements","map<key,int> cnt; cnt[x]++ for frequencies; iterate in sorted order of keys","Group by a normalised key: pair of reduced ratio, difference a_i - i, sorted string, etc.","Count pairs with equal key: for each element add cnt[key] before inserting","Use map<long long,...> when keys exceed int; beware operator[] inserting default values"],"resources":[{"title":"CPH: Set structures","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 4.2 (p. 37)","minutes":10},{"title":"CPH: Map structures","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 4.3 (p. 38)","minutes":8},{"title":"USACO Guide: Introduction to Sets & Maps","url":"https://usaco.guide/bronze/intro-sets","kind":"usaco","where":"USACO Guide Bronze","minutes":25}],"problems":[{"id":"1722C","src":"cf","name":"Word Game","rating":800,"from":"curated"},{"id":"1703B","src":"cf","name":"ICPC Balloons","rating":800,"from":"curated"},{"id":"2000C","src":"cf","name":"Numeric String Template","rating":1000,"from":"curated"},{"id":"1790D","src":"cf","name":"Matryoshkas","rating":1200,"from":"curated"},{"id":"1800D","src":"cf","name":"Remove Two Letters","rating":1200,"from":"curated"},{"id":"1974C","src":"cf","name":"Beautiful Triple Pairs","rating":1400,"from":"curated"},{"id":"1506D","src":"cf","name":"Epic Transformation","rating":1400,"from":"curated"},{"id":"1296C","src":"cf","name":"Yet Another Walking Robot","rating":1500,"from":"curated"},{"id":"cses-1621","src":"cses","name":"Distinct Numbers","from":"usaco-guide"},{"id":"cses-1640","src":"cses","name":"Sum of Two Values","from":"usaco-guide"}]},{"id":"ds-hashmap","name":"Hash maps & anti-hash tests","tier":1300,"order":2,"prereq":["ds-sets-maps"],"summary":"unordered_map/unordered_set give expected O(1) lookups, but on Codeforces they can be hacked with keys that all collide, giving O(n^2) and TLE. Know when to use them, how to make them safe (custom random hash), or simply fall back to map / sorting.","learn":["Default std::hash for integers is identity -> adversarial inputs (multiples of a bucket prime) blow up unordered_map","Fix: custom hash with splitmix64 + a random seed from chrono; or gp_hash_table with a custom hash","Call reserve() to avoid rehashing; avoid unordered_map for pair keys without a good hash","Often a sorted vector + binary search or coordinate compression is both safer and faster","Typical uses: count equal prefix sums / pairs with given difference (a_i - i), sum of k values (meet in the middle)"],"resources":[{"title":"USACO Guide: (Optional) Hashmaps","url":"https://usaco.guide/gold/hashmaps","kind":"usaco","where":"USACO Guide Gold","minutes":20},{"title":"Blowing up unordered_map, and how to stop getting hacked on it (neal)","url":"https://codeforces.com/blog/entry/62393","kind":"cf-blog","where":"Codeforces blog","minutes":15}],"problems":[{"id":"1520D","src":"cf","name":"Same Differences","rating":1200,"from":"curated"},{"id":"4C","src":"cf","name":"Registration System","rating":1300,"from":"curated"},{"id":"1915E","src":"cf","name":"Romantic Glasses","rating":1300,"from":"curated"},{"id":"650A","src":"cf","name":"Watchmen","rating":1400,"from":"curated"},{"id":"1850G","src":"cf","name":"The Morning Star","rating":1500,"from":"curated"},{"id":"1536C","src":"cf","name":"Diluc and Kaeya","rating":1500,"from":"curated"},{"id":"1748C","src":"cf","name":"Zero-Sum Prefixes","rating":1600,"from":"curated"},{"id":"cses-1642","src":"cses","name":"Sum of Four Values","from":"usaco-guide"},{"id":"cses-1640","src":"cses","name":"Sum of Two Values","from":"usaco-guide"}]},{"id":"ds-priority-queue","name":"Priority queues / heaps","tier":1200,"order":3,"prereq":["ds-sets-maps"],"summary":"A binary heap returns the current largest (or smallest) element in O(log n). It powers greedy algorithms that repeatedly take the best available option, \"regret\" greedies that undo the worst earlier choice, event simulation and Dijkstra.","learn":["priority_queue<T> is a max-heap; use greater<T> or push negatives for a min-heap","Greedy with regret: take everything, and when a constraint breaks pop the worst taken item","Process items sorted by one key while a heap holds the best candidates by another key","Merge k sorted lists / k smallest sums with a heap of frontier states","Lazy deletion: keep a \"deleted\" marker or a second heap instead of erasing from the middle","Marginal-gain greedy: push the improvement of splitting/upgrading an item, always take the largest"],"resources":[{"title":"CPH: Other structures (priority queue)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 4.5 (p. 41)","minutes":10},{"title":"USACO Guide: Priority Queues","url":"https://usaco.guide/silver/priority-queues","kind":"usaco","where":"USACO Guide Silver","minutes":20}],"problems":[{"id":"1800C1","src":"cf","name":"Powering the Hero (easy version)","rating":1000,"from":"curated"},{"id":"1800C2","src":"cf","name":"Powering the Hero (hard version)","rating":1100,"from":"curated"},{"id":"1526C1","src":"cf","name":"Potions (Easy Version)","rating":1500,"from":"curated"},{"id":"1526C2","src":"cf","name":"Potions (Hard Version)","rating":1600,"from":"curated"},{"id":"1140C","src":"cf","name":"Playlist","rating":1600,"from":"curated"},{"id":"1353D","src":"cf","name":"Constructing the Array","rating":1600,"from":"curated"},{"id":"1974G","src":"cf","name":"Money Buys Less Happiness Now","rating":2000,"from":"curated"},{"id":"2085D","src":"cf","name":"Serval and Kaitenzushi Buffet","rating":2000,"from":"usaco-guide"},{"id":"1271D","src":"cf","name":"Portals","rating":2100,"from":"curated"},{"id":"1428E","src":"cf","name":"Carrots for Rabbits","rating":2200,"from":"curated"},{"id":"865D","src":"cf","name":"Buy Low Sell High","rating":2400,"from":"curated"},{"id":"3D","src":"cf","name":"Least Cost Bracket Sequence","rating":2600,"from":"curated"},{"id":"cses-1164","src":"cses","name":"Room Allocation","from":"usaco-guide"},{"id":"cses-1161","src":"cses","name":"Stick Division","from":"usaco-guide"}]},{"id":"ds-ordered-set","name":"Ordered sets & multisets (lower_bound tricks)","tier":1500,"order":4,"prereq":["ds-sets-maps"],"summary":"Sorted containers support \"smallest element >= x\", \"largest element < x\", deleting one copy and iterating neighbours, all in O(log n). They solve matching/assignment greedies, dynamic nearest-neighbour queries and maintaining the max gap or the median.","learn":["s.lower_bound(x) / upper_bound(x); prev(it) for the largest element < x; check it != begin()/end()","Use the member s.lower_bound, never std::lower_bound(s.begin(), s.end()) (that is O(n))","multiset::erase(value) removes ALL copies; erase(s.find(value)) removes one","Maintain gaps between consecutive points: on insert/delete update a multiset of differences","Greedy matching: for each item take the smallest available partner >= need and erase it","Two multisets (low/high halves) keep the median / sum of k smallest under insertions and deletions","map<int,int> of position -> value for sparse arrays and \"next occurrence\" queries"],"resources":[{"title":"CPH: Iterators and ranges","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 4.4 (p. 39)","minutes":10},{"title":"USACO Guide: More Operations on Sorted Sets","url":"https://usaco.guide/gold/intro-sorted-sets","kind":"usaco","where":"USACO Guide Gold","minutes":30},{"title":"USACO Guide: (Optional) Sorted Sets with Custom Comparators","url":"https://usaco.guide/gold/custom-cpp-stl","kind":"usaco","where":"USACO Guide Gold","minutes":15}],"problems":[{"id":"1883D","src":"cf","name":"In Love","rating":1500,"from":"curated"},{"id":"1041C","src":"cf","name":"Coffee Break","rating":1600,"from":"curated"},{"id":"1029C","src":"cf","name":"Maximal Intersection","rating":1600,"from":"curated"},{"id":"1157E","src":"cf","name":"Minimum Array","rating":1700,"from":"curated"},{"id":"1474C","src":"cf","name":"Array Destruction","rating":1700,"from":"usaco-guide"},{"id":"1801B","src":"cf","name":"Buying gifts","rating":1800,"from":"curated"},{"id":"1968F","src":"cf","name":"Equal XOR Segments","rating":1800,"from":"curated"},{"id":"69E","src":"cf","name":"Subsegments","rating":1800,"from":"curated"},{"id":"2009G1","src":"cf","name":"Yunli's Subarray Queries (easy version)","rating":1900,"from":"curated"},{"id":"1902D","src":"cf","name":"Robot Queries","rating":1900,"from":"curated"},{"id":"1862G","src":"cf","name":"The Great Equalizer","rating":2000,"from":"curated"},{"id":"1418D","src":"cf","name":"Trash Problem","rating":2100,"from":"curated"},{"id":"cses-1091","src":"cses","name":"Concert Tickets","from":"usaco-guide"},{"id":"cses-1163","src":"cses","name":"Traffic Lights","from":"usaco-guide"},{"id":"cses-1073","src":"cses","name":"Towers","from":"usaco-guide"},{"id":"cses-1632","src":"cses","name":"Movie Festival II","from":"usaco-guide"},{"id":"cses-1188","src":"cses","name":"Bit Inversions","from":"usaco-guide"}]},{"id":"ds-interval-set","name":"Maintaining disjoint intervals in a set (ODT / Chtholly)","tier":1800,"order":5,"prereq":["ds-ordered-set"],"summary":"Store a partition of the line into maximal segments with the same value in a std::set/map keyed by left endpoint. Range-assign operations split at l and r and merge everything in between, giving amortised O((n+q) log n). Also covers \"skip already-processed positions\" with a set of alive indices.","learn":["split(pos): find the segment containing pos and cut it into [l,pos-1] and [pos,r]; always split(r+1) before split(l)","Assign on [l,r]: split, erase all segments inside, insert one new segment -> number of segments stays amortised small","Chtholly tree (ODT) complexity relies on random/assign-heavy queries; do not use it when there are no assignments","Set of unprocessed indices: repeatedly s.lower_bound(l) and erase until > r -> each index removed once","Combine with a BIT to add contributions per removed/merged segment (colorful operations)"],"resources":[{"title":"USACO Guide: More Operations on Sorted Sets","url":"https://usaco.guide/gold/intro-sorted-sets","kind":"usaco","where":"USACO Guide Gold","minutes":20},{"title":"Codeforces Round #449 editorial (problem 896C, origin of the Chtholly tree / ODT)","url":"https://codeforces.com/blog/entry/56135","kind":"cf-blog","where":"Codeforces blog","minutes":15}],"problems":[{"id":"356A","src":"cf","name":"Knight Tournament","rating":1500,"from":"curated"},{"id":"1791F","src":"cf","name":"Range Update Point Query","rating":1500,"from":"curated"},{"id":"1690G","src":"cf","name":"Count the Trains","rating":2000,"from":"curated"},{"id":"2000H","src":"cf","name":"Ksyusha and the Loaded Set","rating":2200,"from":"curated"},{"id":"915E","src":"cf","name":"Physical Education Lessons","rating":2300,"from":"curated"},{"id":"1638E","src":"cf","name":"Colorful Operations","rating":2400,"from":"curated"},{"id":"896C","src":"cf","name":"Willem, Chtholly and Seniorious","rating":2600,"from":"curated"}]},{"id":"ds-pbds","name":"Order-statistics tree (pb_ds) & inversion counting","tier":1600,"order":6,"prereq":["ds-ordered-set"],"summary":"GNU pb_ds tree with tree_order_statistics_node_update is a set that also answers find_by_order(k) (k-th smallest) and order_of_key(x) (# elements < x) in O(log n). It replaces a BIT in counting inversions, ranks, dynamic medians and Josephus-style deletions.","learn":["#include <ext/pb_ds/assoc_container.hpp>; typedef tree<T, null_type, less<T>, rb_tree_tag, tree_order_statistics_node_update> ordered_set","For a multiset store pair(value, unique id) or use less_equal (but erase is then broken)","Inversions (distinct values): before inserting a_i, the number of earlier elements greater than a_i is (count inserted so far) - order_of_key(a_i + 1)","k-th alive element after deletions (Josephus, list removals)","Same queries can be done with a BIT over compressed values (often faster and safer)"],"resources":[{"title":"CPH: Other structures (policy-based data structures)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 4.5 (p. 41)","minutes":10},{"title":"USACO Guide: Point Update Range Sum (Order Statistic Tree section)","url":"https://usaco.guide/gold/PURS","kind":"usaco","where":"USACO Guide Gold","minutes":20},{"title":"C++ STL: Policy based data structures","url":"https://codeforces.com/blog/entry/11080","kind":"cf-blog","where":"Codeforces blog","minutes":15}],"problems":[{"id":"1676H2","src":"cf","name":"Maximum Crossings (Hard Version)","rating":1500,"from":"curated"},{"id":"1915F","src":"cf","name":"Greetings","rating":1500,"from":"curated"},{"id":"1579E2","src":"cf","name":"Array Optimization by Deque","rating":1700,"from":"curated"},{"id":"459D","src":"cf","name":"Pashmak and Parmida's problem","rating":1800,"from":"curated"},{"id":"1660F2","src":"cf","name":"Promising String (hard version)","rating":2100,"from":"curated"},{"id":"cses-2163","src":"cses","name":"Josephus Problem II","from":"curated"},{"id":"cses-1076","src":"cses","name":"Sliding Median","from":"usaco-guide"},{"id":"cses-1749","src":"cses","name":"List Removals","from":"usaco-guide"}]}]},{"id":"ds-static-range","name":"Static Range Queries","cfTags":["data structures","binary search","two pointers"],"subtopics":[{"id":"ds-prefix-difference","name":"Prefix sums, 2D prefix sums & difference arrays","tier":1100,"order":1,"prereq":["@prefix-1d"],"summary":"Prefix sums answer range-sum queries on a static array in O(1); difference arrays apply many range additions offline in O(1) each and recover the array with one prefix sum. 2D versions handle sub-rectangle sums. Recognise them whenever queries/updates are on ranges and the array does not change between queries.","learn":["pre[i] = pre[i-1] + a[i]; sum(l,r) = pre[r] - pre[l-1]; use long long","Difference array: d[l] += x, d[r+1] -= x, then prefix-sum d","Count operations applied to each operation (difference array on the operations themselves)","2D: P[i][j] = a + P[i-1][j] + P[i][j-1] - P[i-1][j-1]; rectangle by inclusion-exclusion","Prefix sums + hashmap/count to count subarrays with sum k or sum divisible by m","Prefix counts per value/bit (per-letter, per-bit prefix arrays) for frequency-on-range queries"],"resources":[{"title":"CPH: Static array queries (prefix sums)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 9.1 (p. 84)","minutes":10},{"title":"USACO Guide: Introduction to Prefix Sums","url":"https://usaco.guide/silver/prefix-sums","kind":"usaco","where":"USACO Guide Silver","minutes":20},{"title":"USACO Guide: More on Prefix Sums","url":"https://usaco.guide/silver/more-prefix-sums","kind":"usaco","where":"USACO Guide Silver","minutes":25}],"problems":[{"id":"816B","src":"cf","name":"Karen and Coffee","rating":1400,"from":"usaco-guide"},{"id":"295A","src":"cf","name":"Greg and Array","rating":1400,"from":"usaco-guide"},{"id":"276C","src":"cf","name":"Little Girl and Maximum Sum","rating":1500,"from":"usaco-guide"},{"id":"1398C","src":"cf","name":"Good Subarrays","rating":1600,"from":"usaco-guide"},{"id":"1722E","src":"cf","name":"Counting Rectangles","rating":1600,"from":"usaco-guide"},{"id":"466C","src":"cf","name":"Number of Ways","rating":1700,"from":"curated"},{"id":"1343D","src":"cf","name":"Constant Palindrome Sum","rating":1700,"from":"curated"},{"id":"2030D","src":"cf","name":"QED's Favorite Permutation","rating":1700,"from":"usaco-guide"},{"id":"cses-1646","src":"cses","name":"Static Range Sum Queries","from":"curated"},{"id":"cses-1652","src":"cses","name":"Forest Queries","from":"usaco-guide"},{"id":"cses-1662","src":"cses","name":"Subarray Divisibility","from":"usaco-guide"},{"id":"cses-1661","src":"cses","name":"Subarray Sums II","from":"usaco-guide"}]},{"id":"ds-sparse-table","name":"Sparse table / RMQ (idempotent queries)","tier":1600,"order":2,"prereq":["ds-prefix-difference"],"summary":"A sparse table precomputes answers on all power-of-two-length ranges in O(n log n) and answers min/max/gcd/and/or queries in O(1) by overlapping two blocks. Use it for static arrays with many queries, frequently together with binary search or two pointers.","learn":["st[k][i] = op(st[k-1][i], st[k-1][i + 2^(k-1)]); query with k = __lg(r-l+1)","O(1) queries only for idempotent operations (min, max, gcd, and, or); sum needs O(log n) or prefix sums","Binary search on the answer + RMQ: longest subarray with gcd > 1, max - min <= k, etc.","gcd/and/or over subarrays starting at i take only O(log V) distinct values","Disjoint sparse table / divide-and-conquer answers any associative op in O(1) (USACO Plat DC-SRQ)","Memory n log n: use int, and arrange as st[k][i] for cache efficiency"],"resources":[{"title":"CPH: Static array queries (minimum queries)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 9.1 (p. 84)","minutes":10},{"title":"cp-algorithms: Sparse Table","url":"https://cp-algorithms.com/data_structures/sparse-table.html","kind":"cpalgo","where":"cp-algorithms","minutes":15},{"title":"USACO Guide: Divide & Conquer - SRQ","url":"https://usaco.guide/plat/DC-SRQ","kind":"usaco","where":"USACO Guide Platinum","minutes":20},{"title":"cp-algorithms: Range Minimum Query overview","url":"https://cp-algorithms.com/sequences/rmq.html","kind":"cpalgo","where":"cp-algorithms","minutes":5}],"problems":[{"id":"1878E","src":"cf","name":"Iva & Pav","rating":1400,"from":"curated"},{"id":"1709D","src":"cf","name":"Rorororobot","rating":1700,"from":"curated"},{"id":"2050F","src":"cf","name":"Maximum modulo equality","rating":1700,"from":"curated"},{"id":"482B","src":"cf","name":"Interesting Array","rating":1800,"from":"curated"},{"id":"1548B","src":"cf","name":"Integers Have Friends","rating":1800,"from":"curated"},{"id":"1547F","src":"cf","name":"Array Stabilization (GCD version)","rating":1900,"from":"curated"},{"id":"359D","src":"cf","name":"Pair of Numbers","rating":2000,"from":"curated"},{"id":"514D","src":"cf","name":"R2D2 and Droid Army","rating":2000,"from":"curated"},{"id":"475D","src":"cf","name":"CGCDSSQ","rating":2000,"from":"curated"},{"id":"689D","src":"cf","name":"Friends and Subsequences","rating":2100,"from":"curated"},{"id":"1454F","src":"cf","name":"Array Partition","rating":2100,"from":"curated"},{"id":"675E","src":"cf","name":"Trains and Statistic","rating":2300,"from":"curated"},{"id":"cses-1647","src":"cses","name":"Static Range Minimum Queries","from":"usaco-guide"},{"id":"cses-1650","src":"cses","name":"Range Xor Queries","from":"curated"}]}]},{"id":"ds-fenwick","name":"Fenwick Tree (BIT)","cfTags":["data structures","sortings","divide and conquer"],"subtopics":[{"id":"ds-fenwick","name":"Fenwick tree: point update, prefix query, inversions","tier":1600,"order":1,"prereq":["ds-prefix-difference"],"summary":"A binary indexed tree supports adding to a position and querying a prefix sum in O(log n) with ~10 lines of code. With coordinate compression it counts elements less than x seen so far, which solves inversion counting and many \"count pairs i<j with condition\" problems.","learn":["update: for(; i<=n; i += i&-i); query: for(; i>0; i -= i&-i); 1-indexed!","Range sum = query(r) - query(l-1); works for any invertible operation (sum, xor)","Coordinate-compress values first (sort + unique + lower_bound)","Count pairs i<j with a_j < a_i (inversions) / with prefix-sum conditions by sweeping and querying the BIT","Sort by one coordinate and use the BIT for the other (2D dominance counting, nested segments)","Prefix max BIT works only when values only increase"],"resources":[{"title":"CPH: Binary indexed tree","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 9.2 (p. 86)","minutes":15},{"title":"USACO Guide: Point Update Range Sum","url":"https://usaco.guide/gold/PURS","kind":"usaco","where":"USACO Guide Gold","minutes":30},{"title":"cp-algorithms: Fenwick Tree","url":"https://cp-algorithms.com/data_structures/fenwick.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"652D","src":"cf","name":"Nested Segments","rating":1800,"from":"curated"},{"id":"1042D","src":"cf","name":"Petya and Array","rating":1800,"from":"curated"},{"id":"61E","src":"cf","name":"Enemy is weak","rating":1900,"from":"curated"},{"id":"1311F","src":"cf","name":"Moving Points","rating":1900,"from":"curated"},{"id":"1430E","src":"cf","name":"String Reversal","rating":1900,"from":"curated"},{"id":"1167F","src":"cf","name":"Scalar Queries","rating":2300,"from":"curated"},{"id":"cses-1648","src":"cses","name":"Dynamic Range Sum Queries","from":"usaco-guide"},{"id":"cses-1144","src":"cses","name":"Salary Queries","from":"usaco-guide"},{"id":"cses-1748","src":"cses","name":"Increasing Subsequence II","from":"usaco-guide"}]},{"id":"ds-fenwick-range","name":"BIT range updates & binary lifting (k-th element)","tier":1800,"order":2,"prereq":["ds-fenwick"],"summary":"Storing the difference array in a BIT gives range-add / point-query; two BITs give range-add / range-sum. Descending the BIT bit by bit finds the smallest prefix whose sum reaches k in O(log n), i.e. the k-th smallest element of a multiset of values.","learn":["Range add, point query: add(l, x), add(r+1, -x); value = prefix(i)","Range add, range sum: two BITs B1, B2 with sum(i) = B1(i)*i - B2(i)","k-th one / k-th smallest: walk pos from the highest power of two, skipping blocks whose sum < k","Offline sorting of queries + BIT k-th answers \"k-th element among the first m\" queries","Euler tour + range-add BIT gives subtree updates / path-to-root point queries on trees"],"resources":[{"title":"CPH: Additional techniques (range updates)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 9.4 (p. 93)","minutes":10},{"title":"cp-algorithms: Fenwick Tree (range update sections)","url":"https://cp-algorithms.com/data_structures/fenwick.html","kind":"cpalgo","where":"cp-algorithms","minutes":15},{"title":"USACO Guide: Range Update Range Query","url":"https://usaco.guide/plat/RURQ","kind":"usaco","where":"USACO Guide Platinum","minutes":20}],"problems":[{"id":"1791F","src":"cf","name":"Range Update Point Query","rating":1500,"from":"curated"},{"id":"1227D2","src":"cf","name":"Optimal Subsequences (Hard Version)","rating":1800,"from":"curated"},{"id":"1354D","src":"cf","name":"Multiset","rating":1900,"from":"curated"},{"id":"383C","src":"cf","name":"Propagating tree","rating":2000,"from":"curated"},{"id":"1891F","src":"cf","name":"A Growing Tree","rating":2000,"from":"curated"},{"id":"cses-1651","src":"cses","name":"Range Update Queries","from":"usaco-guide"},{"id":"cses-1749","src":"cses","name":"List Removals","from":"usaco-guide"}]},{"id":"ds-2d-bit","name":"2D BIT & 2D offline counting","tier":2100,"order":3,"prereq":["ds-fenwick"],"summary":"A Fenwick tree of Fenwick trees answers point-update / rectangle-sum queries in O(log^2 n) for moderate grids. For large coordinates the standard alternative is offline: sweep one dimension and keep a 1D BIT over the other, or use a BIT of sorted vectors / ordered sets.","learn":["update(x,y): nested loops over x += x&-x and y += y&-y; rectangle by inclusion-exclusion","Memory n*m: only feasible for ~1000x1000 (or with bitsets/xor tricks)","Offline 2D dominance: sort points and queries by x, sweep with a BIT on y","Range-update range-query in 2D needs 4 BITs (xor variants need parity tricks)","Large coordinates online: BIT of sorted vectors (offline-known coordinates) or sqrt decomposition"],"resources":[{"title":"CPH: Two-dimensionality","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 28.4 (p. 264)","minutes":10},{"title":"USACO Guide: 2D Range Queries","url":"https://usaco.guide/plat/2DRQ","kind":"usaco","where":"USACO Guide Platinum","minutes":25},{"title":"cp-algorithms: Fenwick Tree (2D section)","url":"https://cp-algorithms.com/data_structures/fenwick.html","kind":"cpalgo","where":"cp-algorithms","minutes":10}],"problems":[{"id":"1190D","src":"cf","name":"Tokitsukaze and Strange Rectangle","rating":2000,"from":"curated"},{"id":"1194E","src":"cf","name":"Count The Rectangles","rating":2200,"from":"curated"},{"id":"785E","src":"cf","name":"Anton and Permutation","rating":2200,"from":"curated"},{"id":"1093E","src":"cf","name":"Intersection of Permutations","rating":2400,"from":"curated"},{"id":"869E","src":"cf","name":"The Untended Antiquity","rating":2400,"from":"curated"},{"id":"12D","src":"cf","name":"Ball","rating":2400,"from":"curated"},{"id":"341D","src":"cf","name":"Iahub and Xors","rating":2500,"from":"curated"},{"id":"cses-1739","src":"cses","name":"Forest Queries II","from":"usaco-guide"}]}]},{"id":"ds-segment-tree","name":"Segment Trees","cfTags":["data structures","trees","divide and conquer"],"subtopics":[{"id":"ds-segtree-basic","name":"Segment tree: point update, range query","tier":1600,"order":1,"prereq":["ds-fenwick"],"summary":"A segment tree stores an associative aggregate (sum, min, max, gcd, ...) for O(n) canonical segments, so point updates and range queries cost O(log n). It is the general-purpose range-query structure used whenever the array changes between queries or the operation is not invertible.","learn":["Size 4n recursive or 2n iterative (bottom-up) implementation; know both","Node stores the aggregate of its segment; combine children with the associative operation","Store extra info per node: (min, count of min), (gcd, count equal to gcd), bitmask of letters","Alternating operations per level (Xenia) — node operation can depend on depth","Build in O(n); check the identity element for empty ranges (0 for sum, INF for min)","If only prefix sums are needed and values are invertible, a BIT is shorter"],"resources":[{"title":"CPH: Segment tree","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 9.3 (p. 89)","minutes":15},{"title":"USACO Guide: Point Update Range Sum","url":"https://usaco.guide/gold/PURS","kind":"usaco","where":"USACO Guide Gold","minutes":30},{"title":"cp-algorithms: Segment Tree","url":"https://cp-algorithms.com/data_structures/segment_tree.html","kind":"cpalgo","where":"cp-algorithms","minutes":40},{"title":"Codeforces EDU: Segment Tree, part 1","url":"https://codeforces.com/edu/course/2/lesson/4","kind":"cf-edu","where":"ITMO Academy pilot course, lesson 4","minutes":90},{"title":"Efficient and easy segment trees (Al.Cash)","url":"https://codeforces.com/blog/entry/18051","kind":"cf-blog","where":"Codeforces blog","minutes":20}],"problems":[{"id":"1198B","src":"cf","name":"Welfare State","rating":1600,"from":"curated"},{"id":"1234D","src":"cf","name":"Distinct Characters Queries","rating":1600,"from":"curated"},{"id":"339D","src":"cf","name":"Xenia and Bit Operations","rating":1700,"from":"curated"},{"id":"1611F","src":"cf","name":"ATM and Students","rating":1800,"from":"curated"},{"id":"474F","src":"cf","name":"Ant colony","rating":2100,"from":"curated"},{"id":"cses-1649","src":"cses","name":"Dynamic Range Minimum Queries","from":"usaco-guide"},{"id":"cses-1648","src":"cses","name":"Dynamic Range Sum Queries","from":"usaco-guide"},{"id":"cses-1647","src":"cses","name":"Static Range Minimum Queries","from":"usaco-guide"}]},{"id":"ds-segtree-combine","name":"Segment tree with custom node merge","tier":1900,"order":2,"prereq":["ds-segtree-basic"],"summary":"Many problems need nodes that store several values merged non-trivially: max subarray sum (sum, best prefix, best suffix, best), bracket matching (unmatched open/close), sorted runs (prefix/suffix length), or a small DP/matrix whose merge is matrix multiplication. Design the node so that merge(left,right) is associative.","learn":["Max subarray: node = {sum, pref, suf, best}; merge in O(1)","Brackets: node = {matched, open, close}; matched += min(left.open, right.close)","Non-commutative merges: keep order left-then-right; iterative trees need separate left/right accumulators","Counting non-decreasing subarrays: store length, prefix run, suffix run, count","Small DP state per node (e.g. 3x3 or 5x5 automaton matrix) merged by (min,+) matrix product","Write merge once and reuse it for both build/update and query"],"resources":[{"title":"USACO Guide: More Applications of Segment Tree (non-commutative combiners)","url":"https://usaco.guide/plat/segtree-ext","kind":"usaco","where":"USACO Guide Platinum","minutes":30},{"title":"cp-algorithms: Segment Tree (finding subsegments with maximal sum)","url":"https://cp-algorithms.com/data_structures/segment_tree.html","kind":"cpalgo","where":"cp-algorithms","minutes":15},{"title":"Codeforces EDU: Segment Tree, part 1 (step 2)","url":"https://codeforces.com/edu/course/2/lesson/4","kind":"cf-edu","where":"ITMO Academy pilot course, lesson 4","minutes":60}],"problems":[{"id":"380C","src":"cf","name":"Sereja and Brackets","rating":2000,"from":"curated"},{"id":"1514D","src":"cf","name":"Cut and Stick","rating":2000,"from":"curated"},{"id":"1567E","src":"cf","name":"Non-Decreasing Dilemma","rating":2200,"from":"curated"},{"id":"85D","src":"cf","name":"Sum of Medians","rating":2300,"from":"curated"},{"id":"145E","src":"cf","name":"Lucky Queries","rating":2400,"from":"curated"},{"id":"1609E","src":"cf","name":"William The Oblivious","rating":2400,"from":"curated"},{"id":"750E","src":"cf","name":"New Year and Old Subsequence","rating":2600,"from":"curated"},{"id":"1004F","src":"cf","name":"Sonya and Bitwise OR","rating":2600,"from":"curated"},{"id":"1149C","src":"cf","name":"Tree Generator™","rating":2700,"from":"curated"},{"id":"cses-1190","src":"cses","name":"Subarray Sum Queries","from":"usaco-guide"},{"id":"cses-2166","src":"cses","name":"Prefix Sum Queries","from":"usaco-guide"},{"id":"cses-2206","src":"cses","name":"Pizzeria Queries","from":"usaco-guide"}]},{"id":"ds-segtree-walk","name":"Walking / descending on a segment tree","tier":1900,"order":3,"prereq":["ds-segtree-basic"],"summary":"Instead of binary searching outside the tree (O(log^2 n)), descend from the root choosing the child that still contains the answer, in O(log n). This finds the k-th one, the first index with a_i >= x, the first position where a prefix sum exceeds a value, or the leftmost element in [l, r] not divisible by g.","learn":["k-th one: if left.count >= k go left else k -= left.count and go right","First index >= l with a_i >= x: recursive search that skips nodes with max < x","Combine walks with range restrictions by visiting only O(log n) canonical nodes","Find max suffix with positive sum (matching problems like Serge and Dining Room)","Interactive / offline variants: cache node counts to reuse queries"],"resources":[{"title":"USACO Guide: More Applications of Segment Tree (walking)","url":"https://usaco.guide/plat/segtree-ext","kind":"usaco","where":"USACO Guide Platinum","minutes":25},{"title":"cp-algorithms: Segment Tree (searching for the k-th zero / first element greater than x)","url":"https://cp-algorithms.com/data_structures/segment_tree.html","kind":"cpalgo","where":"cp-algorithms","minutes":15},{"title":"Codeforces EDU: Segment Tree, part 1 (step 2-3)","url":"https://codeforces.com/edu/course/2/lesson/4","kind":"cf-edu","where":"ITMO Academy pilot course, lesson 4","minutes":60}],"problems":[{"id":"914D","src":"cf","name":"Bash and a Tough Math Puzzle","rating":1900,"from":"curated"},{"id":"899F","src":"cf","name":"Letters Removing","rating":2100,"from":"curated"},{"id":"1997E","src":"cf","name":"Level Up","rating":2200,"from":"curated"},{"id":"1520F2","src":"cf","name":"Guess the K-th Zero (Hard version)","rating":2200,"from":"curated"},{"id":"1179C","src":"cf","name":"Serge and Dining Room","rating":2200,"from":"usaco-guide"},{"id":"1404C","src":"cf","name":"Fixed Point Removal","rating":2300,"from":"curated"},{"id":"cses-1143","src":"cses","name":"Hotel Queries","from":"usaco-guide"},{"id":"cses-1749","src":"cses","name":"List Removals","from":"usaco-guide"}]},{"id":"ds-lazy-propagation","name":"Lazy propagation (range update, range query)","tier":2000,"order":4,"prereq":["ds-segtree-basic"],"summary":"Lazy propagation postpones range updates by storing a pending tag in each node and pushing it to children only when needed, so both range updates and range queries cost O(log n). Common tags: range add, range assign, range flip/xor per bit, multiply, and combinations of them.","learn":["Each node: aggregate + lazy tag; push(node) before descending; pull(node) after recursing","Compose tags correctly: assign overrides add; (mul, add) composes as an affine map","Range xor / flip: store per-bit counts (count of ones in each of ~20 bits)","Euler tour turns subtree updates on trees into range updates","Range add + range min/max is the most common combo (max overlap of intervals, dp with ranges)","26 lazy trees (one per letter) or counting sort per range for string range-sort problems"],"resources":[{"title":"CPH: Lazy propagation","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 28.1 (p. 258)","minutes":15},{"title":"USACO Guide: Range Update Range Query","url":"https://usaco.guide/plat/RURQ","kind":"usaco","where":"USACO Guide Platinum","minutes":30},{"title":"cp-algorithms: Segment Tree (range updates / lazy propagation)","url":"https://cp-algorithms.com/data_structures/segment_tree.html","kind":"cpalgo","where":"cp-algorithms","minutes":20},{"title":"Codeforces EDU: Segment Tree, part 2","url":"https://codeforces.com/edu/course/2/lesson/5","kind":"cf-edu","where":"ITMO Academy pilot course, lesson 5","minutes":90}],"problems":[{"id":"242E","src":"cf","name":"XOR on Segment","rating":2000,"from":"curated"},{"id":"877E","src":"cf","name":"Danil and a Part-time Job","rating":2000,"from":"curated"},{"id":"1555E","src":"cf","name":"Boring Segments","rating":2100,"from":"curated"},{"id":"343D","src":"cf","name":"Water Tree","rating":2100,"from":"curated"},{"id":"620E","src":"cf","name":"New Year Tree","rating":2100,"from":"curated"},{"id":"52C","src":"cf","name":"Circular RMQ","rating":2200,"from":"curated"},{"id":"1295E","src":"cf","name":"Permutation Separation","rating":2200,"from":"curated"},{"id":"558E","src":"cf","name":"A Simple Task","rating":2300,"from":"curated"},{"id":"718C","src":"cf","name":"Sasha and Array","rating":2300,"from":"curated"},{"id":"1114F","src":"cf","name":"Please, another Queries on Array?","rating":2400,"from":"curated"},{"id":"446C","src":"cf","name":"DZY Loves Fibonacci Numbers","rating":2400,"from":"curated"},{"id":"cses-1735","src":"cses","name":"Range Updates and Sums","from":"usaco-guide"},{"id":"cses-1736","src":"cses","name":"Polynomial Queries","from":"usaco-guide"},{"id":"cses-1651","src":"cses","name":"Range Update Queries","from":"usaco-guide"}]},{"id":"ds-segtree-compress-dynamic","name":"Coordinate compression & dynamic (sparse) segment trees","tier":2000,"order":5,"prereq":["ds-segtree-basic"],"summary":"When indices are huge (up to 1e9) either compress the coordinates offline or create nodes on demand (dynamic segment tree, O(q log C) nodes). A very common pattern is a segment tree indexed by value or prefix-sum, used to speed up DP transitions dp[i] = best over j with some key condition.","learn":["Offline: collect all coordinates/queries, sort+unique, map to 0..m-1","Dynamic tree: children created lazily (pointer or index arrays), root covers [0, C)","Segment tree over values for dp[i] = max over earlier j with key_j < key_i (LIS-like)","Segment tree over prefix sums for dp with sign conditions (sum > 0, sum = 0)","Careful with interval endpoints when compressing ranges (compress l and r+1)"],"resources":[{"title":"USACO Guide: Sparse Segment Trees","url":"https://usaco.guide/plat/sparse-segtree","kind":"usaco","where":"USACO Guide Platinum","minutes":20},{"title":"CPH: Dynamic trees (dynamic segment tree)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 28.2 (p. 261)","minutes":10},{"title":"CPH: Additional techniques (index compression)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 9.4 (p. 93)","minutes":5}],"problems":[{"id":"474E","src":"cf","name":"Pillars","rating":2000,"from":"curated"},{"id":"1667B","src":"cf","name":"Optimal Partition","rating":2100,"from":"curated"},{"id":"1788E","src":"cf","name":"Sum Over Zero","rating":2200,"from":"curated"},{"id":"1557D","src":"cf","name":"Ezzat and Grid","rating":2200,"from":"curated"},{"id":"817F","src":"cf","name":"MEX Queries","rating":2300,"from":"curated"},{"id":"915E","src":"cf","name":"Physical Education Lessons","rating":2300,"from":"curated"},{"id":"cses-1144","src":"cses","name":"Salary Queries","from":"usaco-guide"}]},{"id":"ds-merge-sort-tree","name":"Merge sort tree & wavelet ideas","tier":2100,"order":6,"prereq":["ds-segtree-basic"],"summary":"Each segment-tree node stores the sorted list of its segment (or another structure such as a BIT/set). A query splits into O(log n) nodes and binary searches each, answering \"how many values in a[l..r] are <= x\" in O(log^2 n) online. Wavelet trees and persistent trees are faster alternatives for the same k-th / count queries.","learn":["Build by merging children: O(n log n) memory and time","Count values < x in [l, r]: sum of lower_bound over O(log n) nodes","k-th smallest in range: binary search on the answer with the count query (O(log^3)) or use persistent/wavelet tree","Node can hold any structure (set, BIT, convex hull) -> \"segment tree of X\"","Fractional cascading reduces queries to O(log n) (rarely needed)"],"resources":[{"title":"CPH: Data structures (segment tree nodes containing structures)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 28.3 (p. 263)","minutes":10},{"title":"cp-algorithms: Segment Tree (saving the entire subarrays in each vertex)","url":"https://cp-algorithms.com/data_structures/segment_tree.html","kind":"cpalgo","where":"cp-algorithms","minutes":15},{"title":"USACO Guide: Wavelet Tree","url":"https://usaco.guide/adv/wavelet","kind":"usaco","where":"USACO Guide Advanced","minutes":20}],"problems":[{"id":"961E","src":"cf","name":"Tufurama","rating":1900,"from":"curated"},{"id":"538F","src":"cf","name":"A Heap of Heaps","rating":2200,"from":"curated"},{"id":"813E","src":"cf","name":"Army Creation","rating":2200,"from":"curated"},{"id":"323C","src":"cf","name":"Two permutations","rating":2400,"from":"curated"},{"id":"840D","src":"cf","name":"Destiny","rating":2500,"from":"usaco-guide"},{"id":"1793F","src":"cf","name":"Rebrending","rating":2600,"from":"curated"}]},{"id":"ds-persistent-segtree","name":"Persistent segment tree","tier":2300,"order":7,"prereq":["ds-segtree-basic","ds-segtree-compress-dynamic"],"summary":"A persistent segment tree copies only the O(log n) nodes changed by each update, keeping every past version. Building versions over prefixes of the array answers k-th smallest in a range, distinct values in a range and \"count of x in [l,r] among elements <= v\" online in O(log n).","learn":["Node pool with left/right child indices; update returns a new root","Version i = tree after inserting a_1..a_i; query(l,r) uses root[r] minus root[l-1]","k-th smallest in [l,r]: descend both versions simultaneously comparing count differences","Online distinct-in-range: version r marks only the last occurrence of each value","Memory: each update creates ~log2(n)+1 nodes, so allocate about (n + q) * 20 nodes (20-40 x n) statically","Version trees (undo/rollback queries) can also be handled offline by DFS over the version tree"],"resources":[{"title":"CPH: Dynamic trees (persistent segment tree)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 28.2 (p. 261)","minutes":10},{"title":"USACO Guide: Persistent Data Structures","url":"https://usaco.guide/adv/persistent","kind":"usaco","where":"USACO Guide Advanced","minutes":30},{"title":"cp-algorithms: Segment Tree (persistent segment tree)","url":"https://cp-algorithms.com/data_structures/segment_tree.html","kind":"cpalgo","where":"cp-algorithms","minutes":15}],"problems":[{"id":"707D","src":"cf","name":"Persistent Bookcase","rating":2200,"from":"curated"},{"id":"1000F","src":"cf","name":"One Occurrence","rating":2400,"from":"curated"},{"id":"786C","src":"cf","name":"Till I Collapse","rating":2400,"from":"curated"},{"id":"1080F","src":"cf","name":"Katya and Segments Sets","rating":2400,"from":"curated"},{"id":"323C","src":"cf","name":"Two permutations","rating":2400,"from":"curated"},{"id":"484E","src":"cf","name":"Sign on Fence","rating":2500,"from":"curated"},{"id":"1771F","src":"cf","name":"Hossam and Range Minimum Query","rating":2500,"from":"curated"},{"id":"cses-1737","src":"cses","name":"Range Queries and Copies","from":"usaco-guide"}]},{"id":"ds-segtree-beats","name":"Segment tree beats & amortised segment trees","tier":2400,"order":8,"prereq":["ds-lazy-propagation"],"summary":"Some range updates (a_i %= x, a_i = sqrt(a_i), a_i = min(a_i, x), a_i = d(a_i)) cannot be lazily tagged but each element can change only a few times, or changes collapse values together. Recursing until a node is \"settled\" gives amortised O((n+q) log n) or O(n log^2 n) — the idea behind segment tree beats (Ji driver segtree).","learn":["Range mod / sqrt / divisor-count: skip a node if max < x (or all values <= 2); each element changes O(log) times","Chmin beats: store max, second max and count of max; tag only when second_max < x < max","Potential-function argument: total work bounded by number of value changes","Range assign with color-merging amortisation (segments of equal colour)","Very advanced (beats with history sums) rarely needed below 2600"],"resources":[{"title":"USACO Guide: Segment Tree Beats","url":"https://usaco.guide/adv/segtree-beats","kind":"usaco","where":"USACO Guide Advanced","minutes":30},{"title":"A simple introduction to \"Segment tree beats\" (jiry_2)","url":"https://codeforces.com/blog/entry/57319","kind":"cf-blog","where":"Codeforces blog","minutes":25}],"problems":[{"id":"920F","src":"cf","name":"SUM and REPLACE","rating":2000,"from":"curated"},{"id":"438D","src":"cf","name":"The Child and Sequence","rating":2300,"from":"usaco-guide"},{"id":"444C","src":"cf","name":"DZY Loves Colors","rating":2400,"from":"curated"},{"id":"793F","src":"cf","name":"Julia the snail","rating":3000,"from":"usaco-guide"},{"id":"679E","src":"cf","name":"Bear and Bad Powers of 42","rating":3100,"from":"usaco-guide"},{"id":"855F","src":"cf","name":"Nagini","rating":3100,"from":"usaco-guide"},{"id":"453E","src":"cf","name":"Little Pony and Lord Tirek","rating":3100,"from":"usaco-guide"}]}]},{"id":"ds-offline-sqrt","name":"Offline Queries, Sweep Line & Sqrt Techniques","cfTags":["data structures","sortings","two pointers","brute force","divide and conquer"],"subtopics":[{"id":"ds-offline-sweep","name":"Offline queries & sweep line with BIT/segment tree","tier":1700,"order":1,"prereq":["ds-fenwick","ds-ordered-set","@sort-compress-events"],"summary":"If all queries are known in advance, sort them (by right endpoint, by x-coordinate, by time) and sweep, maintaining a BIT/segment tree/set that answers each query when the sweep reaches it. Classic: distinct values in a range (keep only the last occurrence), counting nested/intersecting segments, events of intervals.","learn":["Event sweep: +1 at l, -1 at r+1, sort events (tie-breaking matters!) to get max overlap/covered points","Distinct in [l,r]: sort queries by r; when a value reappears clear its previous position in the BIT","Count points in rectangles / segments containing points: sort by one coordinate, BIT on the other","Answer queries in reverse (deletions become insertions) when that is easier","Process segments sorted by left endpoint while a set holds open segments (union of intervals, building graphs)"],"resources":[{"title":"CPH: Sweep line algorithms","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 30 (p. 275)","minutes":15},{"title":"USACO Guide: Sweep Line","url":"https://usaco.guide/plat/sweep-line","kind":"usaco","where":"USACO Guide Platinum","minutes":20},{"title":"USACO Guide: Range Queries with Sweep Line","url":"https://usaco.guide/plat/range-sweep","kind":"usaco","where":"USACO Guide Platinum","minutes":20},{"title":"USACO Guide: More Applications of Segment Tree","url":"https://usaco.guide/plat/segtree-ext","kind":"usaco","where":"USACO Guide Platinum","minutes":15}],"problems":[{"id":"1000C","src":"cf","name":"Covered Points Count","rating":1700,"from":"curated"},{"id":"1420D","src":"cf","name":"Rescue Nibel!","rating":1800,"from":"curated"},{"id":"1462F","src":"cf","name":"The Treasure of The Segments","rating":1800,"from":"curated"},{"id":"1278D","src":"cf","name":"Segment Tree","rating":2100,"from":"curated"},{"id":"703D","src":"cf","name":"Mishka and Interesting sum","rating":2100,"from":"curated"},{"id":"369E","src":"cf","name":"Valera and Queries","rating":2200,"from":"curated"},{"id":"1401E","src":"cf","name":"Divide Square","rating":2400,"from":"curated"},{"id":"cses-1619","src":"cses","name":"Restaurant Customers","from":"usaco-guide"},{"id":"cses-1734","src":"cses","name":"Distinct Values Queries","from":"usaco-guide"}]},{"id":"ds-sqrt-decomposition","name":"Sqrt decomposition (blocks, heavy/light, batching)","tier":2000,"order":2,"prereq":["ds-prefix-difference"],"summary":"Split the array into ~sqrt(n) blocks storing aggregates, so updates and queries touch O(sqrt n) blocks/elements. The same idea appears as \"small parameter -> precompute, large parameter -> brute force\" (threshold on step size or set size) and as rebuilding a structure every sqrt(q) queries.","learn":["Blocks of size B ~ sqrt(n): full blocks via aggregate, partial blocks element by element","Threshold trick: for step k <= sqrt(n) precompute answers, for k > sqrt(n) only n/k terms exist","Heavy/light sets: sets larger than sqrt(total) are few, handle them specially","Batching/rebuilding: keep a buffer of recent updates and rebuild every sqrt(q) operations","Tune B empirically; prefer cache-friendly arrays; sqrt solutions often run near the time limit"],"resources":[{"title":"CPH: Square root algorithms","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 27 (p. 251)","minutes":15},{"title":"CPH: Combining algorithms","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 27.1 (p. 252)","minutes":5},{"title":"USACO Guide: Square Root Decomposition","url":"https://usaco.guide/plat/sqrt","kind":"usaco","where":"USACO Guide Platinum","minutes":35},{"title":"cp-algorithms: Sqrt Decomposition","url":"https://cp-algorithms.com/data_structures/sqrt_decomposition.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"1921F","src":"cf","name":"Sum of Progression","rating":1900,"from":"curated"},{"id":"797E","src":"cf","name":"Array Queries","rating":2000,"from":"curated"},{"id":"1207F","src":"cf","name":"Remainder Problem","rating":2100,"from":"curated"},{"id":"103D","src":"cf","name":"Time to Raid Cowavans","rating":2100,"from":"curated"},{"id":"1580C","src":"cf","name":"Train Maintenance","rating":2200,"from":"curated"},{"id":"1806E","src":"cf","name":"Tree Master","rating":2200,"from":"curated"},{"id":"348C","src":"cf","name":"Subset Sums","rating":2500,"from":"curated"},{"id":"455D","src":"cf","name":"Serega and Fun","rating":2700,"from":"curated"},{"id":"13E","src":"cf","name":"Holes","rating":2700,"from":"usaco-guide"}]},{"id":"ds-mo-algorithm","name":"Mo's algorithm","tier":2200,"order":3,"prereq":["ds-sqrt-decomposition"],"summary":"Mo's algorithm answers offline range queries by sorting them in blocks of the left endpoint and moving two pointers, with O(1) or O(log) add/remove operations, for total O((n + q) sqrt n). It is the go-to tool for 'number of distinct / pairs with property / frequency-based value in [l, r]' when no clever sweep exists.","learn":["Sort by (l / B, r), alternating r direction per block (odd-even trick) for speed; B ~ n / sqrt(q)","Implement add(i) and remove(i) that update a global answer and frequency array","Prefix xors turn \"subarrays with xor k\" into pairs of prefix indices inside the range","Mo's on trees: Euler tour (in/out times) to linearise paths or subtrees","Mo's with updates: add a time dimension, block size n^(2/3), complexity O(n^(5/3))","Hilbert-curve ordering is a faster alternative ordering"],"resources":[{"title":"CPH: Mo's algorithm","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 27.3 (p. 255)","minutes":10},{"title":"USACO Guide: Square Root Decomposition (Mo's algorithm)","url":"https://usaco.guide/plat/sqrt","kind":"usaco","where":"USACO Guide Platinum","minutes":20},{"title":"cp-algorithms: Sqrt Decomposition (Mo's algorithm)","url":"https://cp-algorithms.com/data_structures/sqrt_decomposition.html","kind":"cpalgo","where":"cp-algorithms","minutes":15},{"title":"An alternative sorting order for Mo's algorithm (Hilbert order)","url":"https://codeforces.com/blog/entry/61203","kind":"cf-blog","where":"Codeforces blog","minutes":15}],"problems":[{"id":"220B","src":"cf","name":"Little Elephant and Array","rating":1800,"from":"curated"},{"id":"576C","src":"cf","name":"Points on Plane","rating":2100,"from":"usaco-guide"},{"id":"86D","src":"cf","name":"Powerful array","rating":2200,"from":"usaco-guide"},{"id":"617E","src":"cf","name":"XOR and Favorite Number","rating":2200,"from":"curated"},{"id":"877F","src":"cf","name":"Ann and Books","rating":2300,"from":"usaco-guide"},{"id":"375D","src":"cf","name":"Tree and Queries","rating":2400,"from":"usaco-guide"},{"id":"940F","src":"cf","name":"Machine Learning","rating":2600,"from":"curated"},{"id":"cses-1734","src":"cses","name":"Distinct Values Queries","from":"usaco-guide"}]},{"id":"ds-small-to-large","name":"Small-to-large merging (DSU on tree)","tier":2000,"order":4,"prereq":["ds-sets-maps","@trees-traversal"],"summary":"When merging sets/maps, always insert the smaller one into the larger one: each element moves O(log n) times, so total work is O(n log^2 n) with std::set/map. On trees this computes per-subtree statistics (dominant colour, counts per depth) by merging children into the heaviest child.","learn":["swap(a, b) if a.size() < b.size(), then insert b into a (swap of std containers is O(1))","Tree version (sack): keep the heavy child data, re-add light subtrees","Maintain auxiliary aggregates (max frequency, sum of dominant colours) during insertion","Also works for merging DSU components with lists and for merging priority queues","Alternative linear-time approaches: Euler tour + offline sweep, or long-path decomposition for depth-indexed data","Segment-tree merging (merging dynamic segment trees of children in total O(n log n)) is the faster cousin for value-indexed data"],"resources":[{"title":"CPH: Offline algorithms (merging data structures)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 18.4 (p. 170)","minutes":10},{"title":"USACO Guide: Small-To-Large Merging","url":"https://usaco.guide/plat/merging","kind":"usaco","where":"USACO Guide Platinum","minutes":25},{"title":"[Tutorial] Sack (dsu on tree) by Arpa","url":"https://codeforces.com/blog/entry/44351","kind":"cf-blog","where":"Codeforces blog","minutes":20}],"problems":[{"id":"1923E","src":"cf","name":"Count Paths","rating":2000,"from":"usaco-guide"},{"id":"208E","src":"cf","name":"Blood Cousins","rating":2100,"from":"curated"},{"id":"570D","src":"cf","name":"Tree Requests","rating":2200,"from":"curated"},{"id":"600E","src":"cf","name":"Lomsat gelral","rating":2300,"from":"usaco-guide"},{"id":"1009F","src":"cf","name":"Dominant Indices","rating":2300,"from":"curated"},{"id":"246E","src":"cf","name":"Blood Cousins Return","rating":2400,"from":"curated"},{"id":"1709E","src":"cf","name":"XOR Tree","rating":2400,"from":"curated"},{"id":"cses-1139","src":"cses","name":"Distinct Colors","from":"usaco-guide"}]},{"id":"ds-parallel-binsearch","name":"Parallel binary search","tier":2300,"order":5,"prereq":["ds-offline-sweep","@bs-answer","@dsu-basics"],"summary":"When every query needs its own binary search over time (\"first moment when condition holds\"), and each check requires replaying the same sequence of updates, run all binary searches simultaneously: in each of O(log T) rounds sort queries by their midpoint, replay the updates once and check every query as the replay passes its midpoint. Total O((T + Q) log T * cost of update).","learn":["Recognise: answer for each query is monotone in time / in a threshold, and checking one time costs a full replay of updates","Per round: bucket queries by mid = (lo + hi) / 2, reset the structure, apply updates 1..T in order and test queries in bucket t after update t","Usual structures inside: DSU (first time u and v are connected), BIT with range add (meteor-style accumulation), segment tree","O(log T) rounds; reset the structure each round (DSU re-init, BIT clear)","Alternatives to compare: persistent structures, Kruskal reconstruction tree, divide and conquer over time with rollback","Recursive form: solve(lo, hi, queries) applies updates of [lo, mid], splits queries into two lists and recurses (needs undo or careful order)"],"resources":[{"title":"cp-algorithms: Binary search (Parallel Binary Search section)","url":"https://cp-algorithms.com/num_methods/binary_search.html","kind":"cpalgo","where":"cp-algorithms","minutes":15},{"title":"Parallel Binary Search [tutorial]","url":"https://codeforces.com/blog/entry/45578","kind":"cf-blog","where":"Codeforces blog","minutes":20}],"problems":[{"id":"1706E","src":"cf","name":"Qpwoeirut and Vertices","rating":2300,"from":"curated"},{"id":"484E","src":"cf","name":"Sign on Fence","rating":2500,"from":"curated"},{"id":"1920F2","src":"cf","name":"Smooth Sailing (Hard Version)","rating":3000,"from":"curated"},{"id":"cses-2101","src":"cses","name":"New Roads Queries","from":"curated"}]},{"id":"ds-offline-deletion","name":"Offline deletion / segment tree over time","tier":2400,"order":6,"prereq":["ds-segtree-basic","@dsu-rollback"],"summary":"If a structure supports insertions and rollback (undo) but not deletions — like DSU without path compression or a linear basis — place each element on the O(log q) segment-tree nodes covering its lifetime in the query timeline, then DFS the tree applying and undoing insertions. This gives offline dynamic connectivity and similar results in O(q log q * T).","learn":["Each element is alive on a time interval [add, remove); add it to O(log q) canonical nodes","DFS the time segment tree: apply node items on entry, answer leaf queries, roll back on exit","DSU with union by size and no path compression supports O(log n) rollback via a change stack","Works for any \"insert + undo\" structure: DSU, xor basis, knapsack dp array","Divide-and-conquer on queries (CDQ, see @dc-cdq) is the related technique for offline insertions + queries","Knapsack variant: items alive on time intervals, or \"take a whole array except one\" (1442D) - add items to segment-tree nodes and copy the dp array on the way down"],"resources":[{"title":"USACO Guide: Offline Deletion","url":"https://usaco.guide/adv/offline-del","kind":"usaco","where":"USACO Guide Advanced","minutes":30},{"title":"cp-algorithms: Deleting from a data structure in O(T(n) log n)","url":"https://cp-algorithms.com/data_structures/deleting_in_log_n.html","kind":"cpalgo","where":"cp-algorithms","minutes":15}],"problems":[{"id":"891C","src":"cf","name":"Envy","rating":2300,"from":"usaco-guide"},{"id":"813F","src":"cf","name":"Bipartite Checking","rating":2500,"from":"curated"},{"id":"1140F","src":"cf","name":"Extending Set of Points","rating":2600,"from":"usaco-guide"},{"id":"1217F","src":"cf","name":"Forced Online Queries Problem","rating":2600,"from":"usaco-guide"},{"id":"1442D","src":"cf","name":"Sum","rating":2800,"from":"curated"},{"id":"601E","src":"cf","name":"A Museum Robbery","rating":2800,"from":"usaco-guide"},{"id":"938G","src":"cf","name":"Shortest Path Queries","rating":2900,"from":"curated"}]}]},{"id":"ds-bbst","name":"Balanced BSTs (Treaps)","cfTags":["data structures"],"subtopics":[{"id":"ds-treap","name":"Treaps & implicit treaps (split/merge)","tier":2300,"order":1,"prereq":["ds-lazy-propagation","ds-pbds"],"summary":"A treap is a randomised balanced BST supporting split and merge in expected O(log n). Keyed by implicit position, it becomes a dynamic array supporting cut-and-paste of subarrays, reversals (with a lazy flag), insertions in the middle and range aggregates — things a segment tree cannot do.","learn":["Node: key/size, random priority, left/right, aggregate, lazy tags","split(t, k) into first k elements and the rest (implicit key = size of left subtree)","merge(l, r) assumes all of l is before r; choose the root by priority","Cut-and-paste and reversal: split into three parts, modify/flag the middle, merge back","Push lazy tags (reverse, add) before split/merge; recompute size and aggregate after","Alternatives: rope (__gnu_cxx::rope) or sqrt decomposition for some problems"],"resources":[{"title":"USACO Guide: Treaps","url":"https://usaco.guide/adv/treaps","kind":"usaco","where":"USACO Guide Advanced","minutes":30},{"title":"cp-algorithms: Treap (Cartesian tree)","url":"https://cp-algorithms.com/data_structures/treap.html","kind":"cpalgo","where":"cp-algorithms","minutes":25}],"problems":[{"id":"420D","src":"cf","name":"Cup Trick","rating":2200,"from":"curated"},{"id":"85D","src":"cf","name":"Sum of Medians","rating":2300,"from":"curated"},{"id":"38G","src":"cf","name":"Queue","rating":2300,"from":"curated"},{"id":"702F","src":"cf","name":"T-Shirts","rating":2800,"from":"curated"},{"id":"cses-2072","src":"cses","name":"Cut and Paste","from":"usaco-guide"},{"id":"cses-2073","src":"cses","name":"Substring Reversals","from":"usaco-guide"},{"id":"cses-2074","src":"cses","name":"Reversals and Sums","from":"usaco-guide"}]}]}]},{"area":"strings","topics":[{"id":"string-basics","name":"String Basics","cfTags":["strings","implementation","greedy","expression parsing"],"subtopics":[{"id":"str-frequency","name":"Frequency counting & anagrams","tier":800,"order":1,"prereq":[],"summary":"Count occurrences of each character (array of 26 or a map) and reason only about the multiset of letters. Appears whenever order does not matter: anagrams, rearrangements into palindromes, \"can we make the strings equal by swaps\", distinct-character splits.","learn":["Use int cnt[26] (c - 'a') instead of map<char,int> for speed and simplicity","Two strings are anagrams iff their count arrays are equal; rearrangement questions reduce to comparing counts","Prefix/suffix distinct counts let you evaluate every split point in O(n * 26) or O(n)","A multiset can be arranged into a palindrome iff at most one letter has an odd count","Map one string to another (pattern templates) with two maps to enforce a bijection","Pitfall: uppercase/lowercase and digits need separate offsets; reset count arrays between test cases in O(26), not O(maxn)"],"resources":[{"title":"CPH 26.1: String terminology","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 26.1 (p. 243)","minutes":10},{"title":"USACO Guide: Introduction to Sets & Maps","url":"https://usaco.guide/bronze/intro-sets","kind":"usaco","where":"USACO Guide Bronze","minutes":25},{"title":"USACO Guide: Hash Maps","url":"https://usaco.guide/gold/hashmaps","kind":"usaco","where":"USACO Guide Gold","minutes":20}],"problems":[{"id":"1883B","src":"cf","name":"Chemistry","rating":900,"from":"curated"},{"id":"1800B","src":"cf","name":"Count the Number of Pairs","rating":1000,"from":"curated"},{"id":"1223B","src":"cf","name":"Strings Equalization","rating":1000,"from":"curated"},{"id":"1791D","src":"cf","name":"Distinct Split","rating":1000,"from":"curated"},{"id":"2000C","src":"cf","name":"Numeric String Template","rating":1000,"from":"curated"},{"id":"1669E","src":"cf","name":"2-Letter Strings","rating":1200,"from":"curated"},{"id":"1332C","src":"cf","name":"K-Complete Word","rating":1500,"from":"curated"},{"id":"1781C","src":"cf","name":"Equal Frequencies","rating":1600,"from":"curated"},{"id":"cses-1755","src":"cses","name":"Palindrome Reorder","from":"curated"},{"id":"cses-1622","src":"cses","name":"Creating Strings","from":"usaco-guide"}]},{"id":"str-runs","name":"Runs, blocks & binary strings","tier":800,"order":2,"prereq":["str-frequency"],"summary":"Split a string into maximal blocks of equal characters (run-length encoding) and reason about the number of blocks, their lengths and the transitions between them. Very common in 800-1700 problems on binary strings: deleting/merging blocks, counting \"01\"/\"10\" boundaries, cutting a string into pieces, games that remove blocks.","learn":["Run-length encode in one pass: vector of (char, length); the number of blocks = 1 + number of i with s[i] != s[i-1]","Many operations only change block counts by at most 1 or 2: think in terms of boundaries (transitions), not characters","Binary string sortedness: a sorted 0...01...1 string has at most one \"10\" boundary; count \"10\" transitions to measure distance from sorted","Games removing blocks: players greedily take the largest remaining block of 1s (sort block lengths)","Substring counting by the last transition: any substring ending at i whose last two characters differ behaves like the whole prefix (Paranoid String pattern)","Cyclic strings: rotate so the string starts at a block boundary, then merge the first and last block if equal","Greedy with a pointer over blocks: delete from the earliest block of length >= 2 to save operations"],"resources":[{"title":"CPH 26.1: String terminology","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 26.1 (p. 243)","minutes":10},{"title":"USACO Guide: Ad Hoc Problems","url":"https://usaco.guide/bronze/ad-hoc","kind":"usaco","where":"USACO Guide Bronze","minutes":20}],"problems":[{"id":"1303A","src":"cf","name":"Erasing Zeroes","rating":800,"from":"curated"},{"id":"1398B","src":"cf","name":"Substring Removal Game","rating":800,"from":"curated"},{"id":"1566B","src":"cf","name":"MIN-MEX Cut","rating":800,"from":"usaco-guide"},{"id":"1678B1","src":"cf","name":"Tokitsukaze and Good 01-String (easy version)","rating":800,"from":"curated"},{"id":"2192A","src":"cf","name":"String Rotation Game","rating":800,"from":"curated"},{"id":"1837B","src":"cf","name":"Comparison String","rating":900,"from":"curated"},{"id":"1971D","src":"cf","name":"Binary Cut","rating":1100,"from":"curated"},{"id":"1694B","src":"cf","name":"Paranoid String","rating":1200,"from":"curated"},{"id":"1352F","src":"cf","name":"Binary String Reconstruction","rating":1500,"from":"curated"},{"id":"1430D","src":"cf","name":"String Deletion","rating":1700,"from":"curated"},{"id":"1678B2","src":"cf","name":"Tokitsukaze and Good 01-String (hard version)","rating":1800,"from":"curated"}]},{"id":"str-palindromes-basic","name":"Palindromes (basic)","tier":900,"order":3,"prereq":["str-frequency"],"summary":"Recognise and construct palindromes with two pointers from both ends and mirrored positions i and n-1-i. Typical tasks: make a string a palindrome with minimum changes, build the longest palindrome from given pieces, decide if some subsequence/substring is a palindrome.","learn":["Mirror pairs (i, n-1-i) are independent: fix each pair greedily, middle char is free when n is odd","Every palindrome of length >= 2 contains a palindrome of length 2 or 3 (useful for \"no palindromic substring\" tasks)","Palindromic subsequence of length 3 exists iff some value appears twice at distance >= 2","Count-based reasoning: pairs of letters build the two halves, at most one odd letter in the middle","Two-pointer shrink from both ends when you may delete one kind of character","For many substring palindrome queries move on to hashing or Manacher"],"resources":[{"title":"CPH 26.1: String terminology","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 26.1 (p. 243)","minutes":10},{"title":"USACO Guide: Ad Hoc Problems","url":"https://usaco.guide/bronze/ad-hoc","kind":"usaco","where":"USACO Guide Bronze","minutes":20}],"problems":[{"id":"1324B","src":"cf","name":"Yet Another Palindrome Problem","rating":1100,"from":"curated"},{"id":"1304B","src":"cf","name":"Longest Palindrome","rating":1100,"from":"curated"},{"id":"1867B","src":"cf","name":"XOR Palindromes","rating":1100,"from":"curated"},{"id":"1512C","src":"cf","name":"A-B Palindrome","rating":1200,"from":"curated"},{"id":"1251B","src":"cf","name":"Binary Palindromes","rating":1400,"from":"curated"},{"id":"1421C","src":"cf","name":"Palindromifier","rating":1400,"from":"curated"},{"id":"1624D","src":"cf","name":"Palindromes Coloring","rating":1400,"from":"usaco-guide"},{"id":"1822E","src":"cf","name":"Making Anti-Palindromes","rating":1600,"from":"curated"},{"id":"1555D","src":"cf","name":"Say No to Palindromes","rating":1600,"from":"curated"},{"id":"1335E1","src":"cf","name":"Three Blocks Palindrome (easy version)","rating":1700,"from":"curated"},{"id":"2069D","src":"cf","name":"Palindrome Shuffle","rating":1800,"from":"curated"},{"id":"1109B","src":"cf","name":"Sasha and One More Name","rating":1800,"from":"curated"},{"id":"1951E","src":"cf","name":"No Palindromes","rating":2000,"from":"curated"}]},{"id":"str-subsequences","name":"Subsequences & greedy matching","tier":1000,"order":4,"prereq":["str-frequency"],"summary":"Check whether t is a subsequence of s by a single greedy left-to-right scan, and extend this with next-occurrence tables or prefix/suffix match arrays. Shows up in \"remove characters\", \"minimum number of copies of s to form t\", and \"longest removable substring\" problems.","learn":["Greedy matching: take the earliest possible match of each character of t; this is optimal","Precompute nxt[i][c] = next index >= i holding c (O(26n)) or store positions per letter and binary search","pre[i] = position where t[0..i] finishes greedily from the left, suf[i] = from the right; combine them to remove a maximum substring","Counting subsequences such as \"abc\" uses running counts (number of a, number of ab, ...)","Substring vs subsequence: a substring is contiguous; many traps rely on mixing the two","Lexicographically largest subsequence = suffix maxima taken from right to left"],"resources":[{"title":"CPH 26.1: String terminology","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 26.1 (p. 243)","minutes":10},{"title":"USACO Guide: Two Pointers","url":"https://usaco.guide/silver/two-pointers","kind":"usaco","where":"USACO Guide Silver","minutes":30}],"problems":[{"id":"1451B","src":"cf","name":"Non-Substring Subsequence","rating":900,"from":"curated"},{"id":"1999D","src":"cf","name":"Slavic's Exam","rating":1100,"from":"curated"},{"id":"1989B","src":"cf","name":"Substring and Subsequence","rating":1200,"from":"curated"},{"id":"1307C","src":"cf","name":"Cow and Message","rating":1500,"from":"curated"},{"id":"1368B","src":"cf","name":"Codeforces Subsequences","rating":1500,"from":"curated"},{"id":"1924A","src":"cf","name":"Did We Get Everything Covered?","rating":1500,"from":"curated"},{"id":"1553D","src":"cf","name":"Backspace","rating":1500,"from":"curated"},{"id":"1295C","src":"cf","name":"Obtain The String","rating":1600,"from":"curated"},{"id":"1203D2","src":"cf","name":"Remove the Substring (hard version)","rating":1700,"from":"curated"},{"id":"2104E","src":"cf","name":"Unpleasant Strings","rating":1700,"from":"curated"}]},{"id":"str-lexicographic","name":"Lexicographic order tricks","tier":1100,"order":5,"prereq":["str-subsequences","@greedy-lexicographic"],"summary":"Reason about lexicographic comparison to build the smallest/largest possible string greedily: the first differing position decides everything. Appears in \"minimise the string with k operations\", choosing best prefix to repeat, comparing concatenations and MEX-like strings.","learn":["Greedy: make the earliest position as small as possible, then recurse on the rest","A proper prefix is smaller than the longer string; watch this edge case in comparisons","Sort strings by a+b < b+a to minimise a concatenation","The smallest string not occurring as a substring has small length (enumerate all length-1, 2, 3 strings)","Monotonic stack to delete characters for lexicographically smallest/largest result (remove duplicate letters pattern)","For fast comparison of arbitrary substrings use hashing + binary search, Z-function or suffix array (later sub-topics)"],"resources":[{"title":"CPH 26.1: String terminology","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 26.1 (p. 243)","minutes":10},{"title":"USACO Guide: Greedy Algorithms with Sorting","url":"https://usaco.guide/silver/greedy-sorting","kind":"usaco","where":"USACO Guide Silver","minutes":25}],"problems":[{"id":"1536B","src":"cf","name":"Prinzessin der Verurteilung","rating":1200,"from":"curated"},{"id":"1316B","src":"cf","name":"String Modification","rating":1400,"from":"curated"},{"id":"1735C","src":"cf","name":"Phase Shift","rating":1400,"from":"curated"},{"id":"1675E","src":"cf","name":"Replace With the Previous, Minimize","rating":1500,"from":"curated"},{"id":"1742F","src":"cf","name":"Smaller","rating":1500,"from":"curated"},{"id":"1348C","src":"cf","name":"Phoenix and Distribution","rating":1600,"from":"curated"},{"id":"1537E1","src":"cf","name":"Erase and Extend (Easy Version)","rating":1600,"from":"curated"},{"id":"1799C","src":"cf","name":"Double Lexicographically Minimum","rating":1700,"from":"curated"},{"id":"1506G","src":"cf","name":"Maximize the Remaining String","rating":2000,"from":"curated"},{"id":"1616E","src":"cf","name":"Lexicographically Small Enough","rating":2200,"from":"curated"}]},{"id":"str-brackets","name":"Bracket sequences","tier":1200,"order":6,"prereq":["str-frequency","@ds-stack-basics"],"summary":"A regular bracket sequence has balance (opens minus closes) that never goes negative and ends at zero. Problems ask to fix, count, colour or query bracket sequences; recognise them by \"(\", \")\" or any balanced-token structure.","learn":["Prefix balance b[i]: sequence is regular iff min b >= 0 and b[n] = 0","Stack matching gives the partner of each bracket and the longest regular substring","Minimum moves to fix = how far the balance dips below zero","Range \"longest regular subsequence\" queries: segment tree storing (matched, open, close)","Counting regular sequences of length 2n = Catalan number; prefix-balance DP for constrained counts","Bracket sequences also map to trees / paths (+1/-1 walk), useful for constructive tasks"],"resources":[{"title":"cp-algorithms: Balanced bracket sequences","url":"https://cp-algorithms.com/combinatorics/bracket_sequences.html","kind":"cpalgo","where":"cp-algorithms","minutes":20},{"title":"USACO Guide: Stacks","url":"https://usaco.guide/gold/stacks","kind":"usaco","where":"USACO Guide Gold","minutes":20}],"problems":[{"id":"1469A","src":"cf","name":"Regular Bracket Sequence","rating":1000,"from":"curated"},{"id":"1374C","src":"cf","name":"Move Brackets","rating":1000,"from":"curated"},{"id":"1657C","src":"cf","name":"Bracket Sequence Deletion","rating":1200,"from":"curated"},{"id":"1837D","src":"cf","name":"Bracket Coloring","rating":1400,"from":"curated"},{"id":"1503A","src":"cf","name":"Balance the Bits","rating":1600,"from":"curated"},{"id":"1709C","src":"cf","name":"Recover an RBS","rating":1800,"from":"curated"},{"id":"5C","src":"cf","name":"Longest Regular Bracket Sequence","rating":1900,"from":"curated"},{"id":"380C","src":"cf","name":"Sereja and Brackets","rating":2000,"from":"curated"},{"id":"1976D","src":"cf","name":"Invertible Bracket Sequences","rating":2000,"from":"curated"},{"id":"1821E","src":"cf","name":"Rearrange Brackets","rating":2100,"from":"curated"},{"id":"cses-2064","src":"cses","name":"Bracket Sequences I","from":"usaco-guide"}]},{"id":"str-prefix-counts","name":"Prefix counts & parity masks on strings","tier":1400,"order":7,"prereq":["str-frequency","@prefix-1d"],"summary":"Prefix sums over characters (count of each letter, mismatches against a periodic pattern, digit sums) turn substring questions into O(1) differences. The parity-bitmask variant (bit c = parity of letter c in the prefix) counts substrings where every letter appears an even/odd number of times.","learn":["cnt[c][i] = occurrences of c in s[0..i): substring counts are differences","Compare against periodic targets (RGBRGB...) via prefix mismatch counts for every shift","Good-substring counting: transform each char (e.g. digit - 1) and count equal prefix sums with a map","Parity mask: substring has all even counts iff mask[l] == mask[r]; \"at most one odd\" checks the 26 single-bit flips","Use arrays instead of map when the key space is small (2^26 bitset is too big: use hashing/sorting)","Combine with two pointers when constraints are monotone in the window length"],"resources":[{"title":"USACO Guide: Introduction to Prefix Sums","url":"https://usaco.guide/silver/prefix-sums","kind":"usaco","where":"USACO Guide Silver","minutes":25},{"title":"USACO Guide: More on Prefix Sums","url":"https://usaco.guide/silver/more-prefix-sums","kind":"usaco","where":"USACO Guide Silver","minutes":25}],"problems":[{"id":"1535C","src":"cf","name":"Unstable String","rating":1400,"from":"curated"},{"id":"1045I","src":"cf","name":"Palindrome Pairs","rating":1600,"from":"curated"},{"id":"1196D2","src":"cf","name":"RGB Substring (hard version)","rating":1600,"from":"curated"},{"id":"1398C","src":"cf","name":"Good Subarrays","rating":1600,"from":"usaco-guide"},{"id":"1849C","src":"cf","name":"Binary String Copying","rating":1600,"from":"curated"},{"id":"1660F1","src":"cf","name":"Promising String (easy version)","rating":1700,"from":"curated"},{"id":"1800F","src":"cf","name":"Dasha and Nightmares","rating":1900,"from":"curated"},{"id":"1660F2","src":"cf","name":"Promising String (hard version)","rating":2100,"from":"curated"}]},{"id":"str-parsing","name":"Parsing & expression evaluation","tier":1300,"order":8,"prereq":["str-brackets"],"summary":"Read structured text (numbers, words, nested brackets, loops, mini-languages) and evaluate or transform it. Recursive descent or two stacks (operands + operators with precedence) evaluate arithmetic expressions; a stack of open constructs handles nesting such as loops, comments and tags. Recognised by the CF tag \"expression parsing\" and long input formats.","learn":["Tokenise first: split into numbers, identifiers and symbols; be careful with multi-digit numbers and signs","Two-stack (shunting-yard) evaluation: apply higher-or-equal precedence operators before pushing a new one; \"(\" waits for \")\"","Recursive descent: expr -> term {(+|-) term}, term -> factor {(*|/) factor}, factor -> number | ( expr )","Nested constructs (for/end, comments, tags) -> stack of frames holding a multiplier or depth; cap products to avoid overflow","Decode from the right when a marker follows the encoded item (e.g. two digits then 0)","Brute force over where to insert one bracket/operator, then re-evaluate in O(n): typical O(n^2) solutions","Read whole lines with getline and handle trailing spaces / empty tokens carefully"],"resources":[{"title":"cp-algorithms: Expression parsing","url":"https://cp-algorithms.com/string/expression_parsing.html","kind":"cpalgo","where":"cp-algorithms","minutes":25},{"title":"USACO Guide: Stacks","url":"https://usaco.guide/gold/stacks","kind":"usaco","where":"USACO Guide Gold","minutes":20},{"title":"USACO Guide: Simulation","url":"https://usaco.guide/bronze/simulation","kind":"usaco","where":"USACO Guide Bronze","minutes":15}],"problems":[{"id":"32B","src":"cf","name":"Borze","rating":800,"from":"curated"},{"id":"1729B","src":"cf","name":"Decode String","rating":800,"from":"curated"},{"id":"723B","src":"cf","name":"Text Document Analysis","rating":1100,"from":"curated"},{"id":"1175B","src":"cf","name":"Catch Overflow!","rating":1600,"from":"curated"},{"id":"727B","src":"cf","name":"Bill Total Value","rating":1600,"from":"curated"},{"id":"747E","src":"cf","name":"Comments","rating":1700,"from":"curated"},{"id":"778B","src":"cf","name":"Bitwise Formula","rating":1800,"from":"curated"},{"id":"2052E","src":"cf","name":"Expression Correction","rating":1900,"from":"curated"},{"id":"552E","src":"cf","name":"Vanya and Brackets","rating":2100,"from":"curated"},{"id":"7E","src":"cf","name":"Defining Macros","rating":2600,"from":"curated"}]}]},{"id":"hashing","name":"Hashing","cfTags":["hashing","strings"],"subtopics":[{"id":"hash-polynomial","name":"Polynomial rolling hash","tier":1500,"order":1,"prereq":["str-frequency","@nt-modular-arithmetic"],"summary":"Map every prefix to h[i] = s[0]*p^(i-1) + ... + s[i-1] mod M so any substring hash is h[r] - h[l]*p^(r-l) in O(1). Use it whenever you need many substring equality checks: occurrences, distinct substrings, borders, overlaps when merging words.","learn":["Precompute prefix hashes and powers; substring hash = (h[r] - h[l]*pw[r-l]) mod M, keep values non-negative","Choose a large prime modulus (1e9+7 / 998244353, or 2^61-1 with 128-bit multiply) and a RANDOM base chosen at runtime","Double hashing (two moduli) or mod 2^61-1 makes collisions negligible; never use natural overflow mod 2^64 (Thue-Morse anti-hash)","Birthday paradox: comparing ~10^6 hashes pairwise needs a modulus far above 10^12","Distinct substrings of a fixed length: collect hashes in a sorted vector (avoid unordered_map hacks)","Rabin-Karp: compare the pattern hash with every window hash for O(n + m) matching","Pitfall: map characters to 1..26, not 0, so that \"a\" and \"aa\" differ","2D hashing: hash every row, then hash the column of row-hashes with a second base to compare sub-matrices in O(1)"],"resources":[{"title":"CPH 26.3: String hashing","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 26.3 (p. 245)","minutes":20},{"title":"USACO Guide: String Hashing","url":"https://usaco.guide/gold/hashing","kind":"usaco","where":"USACO Guide Gold","minutes":35},{"title":"cp-algorithms: String Hashing","url":"https://cp-algorithms.com/string/string-hashing.html","kind":"cpalgo","where":"cp-algorithms","minutes":25},{"title":"cp-algorithms: Rabin-Karp for String Matching","url":"https://cp-algorithms.com/string/rabin-karp.html","kind":"cpalgo","where":"cp-algorithms","minutes":10},{"title":"Rolling hash and 8 interesting problems (CF blog)","url":"https://codeforces.com/blog/entry/60445","kind":"cf-blog","where":"Codeforces blog","minutes":30}],"problems":[{"id":"1800D","src":"cf","name":"Remove Two Letters","rating":1200,"from":"curated"},{"id":"1326D1","src":"cf","name":"Prefix-Suffix Palindrome (Easy version)","rating":1500,"from":"curated"},{"id":"316G1","src":"cf","name":"Good Substrings","rating":1700,"from":"curated"},{"id":"2010C2","src":"cf","name":"Message Transmission Error (hard version)","rating":1700,"from":"curated"},{"id":"271D","src":"cf","name":"Good Substrings","rating":1800,"from":"curated"},{"id":"1979D","src":"cf","name":"Fixing a Binary String","rating":1800,"from":"curated"},{"id":"113B","src":"cf","name":"Petr#","rating":2000,"from":"curated"},{"id":"1984D","src":"cf","name":"''a'' String Problem","rating":2000,"from":"curated"},{"id":"727E","src":"cf","name":"Games on a CD","rating":2300,"from":"curated"},{"id":"1469E","src":"cf","name":"A Bit Similar","rating":2400,"from":"curated"}]},{"id":"hash-anti-hash","name":"Collisions & anti-hash safety","tier":1700,"order":2,"prereq":["hash-polynomial"],"summary":"Understand why hashes collide and how hackers break fixed bases, overflow (mod 2^64) hashing and unordered_map. Matters in every hackable round (Div 2/3/Educational) where a deterministic hash can be hacked after the contest.","learn":["Probability of a collision for one comparison is about n/M for polynomial hashes; across many comparisons multiply by their number","mod 2^64 hashing is broken by Thue-Morse strings regardless of the base","Fixed base + fixed modulus can be attacked by tree/lattice methods: randomise the base with a time-seeded RNG","Use mod 2^61-1 or a pair of moduli; compare pairs, not sums","unordered_map with default hash can be blown up to O(n^2): use a custom splitmix64 hash or sort + unique","If a solution fails on a random-looking test only after hacks, suspect the hash"],"resources":[{"title":"On the mathematics behind rolling hashes and anti-hash tests","url":"https://codeforces.com/blog/entry/60442","kind":"cf-blog","where":"Codeforces blog","minutes":30},{"title":"Blowing up unordered_map, and how to stop getting hacked on it","url":"https://codeforces.com/blog/entry/62393","kind":"cf-blog","where":"Codeforces blog","minutes":15},{"title":"USACO Guide: Hash Maps (anti-hash tests)","url":"https://usaco.guide/gold/hashmaps","kind":"usaco","where":"USACO Guide Gold","minutes":15},{"title":"USACO Guide: String Hashing (collision section)","url":"https://usaco.guide/gold/hashing","kind":"usaco","where":"USACO Guide Gold","minutes":15}],"problems":[{"id":"514C","src":"cf","name":"Watto and Mechanism","rating":2000,"from":"curated"},{"id":"1056E","src":"cf","name":"Check Transcription","rating":2100,"from":"usaco-guide"},{"id":"898F","src":"cf","name":"Restoring the Expression","rating":2300,"from":"curated"},{"id":"985F","src":"cf","name":"Isomorphic Strings","rating":2300,"from":"curated"},{"id":"533F","src":"cf","name":"Encoding","rating":2400,"from":"curated"},{"id":"1129C","src":"cf","name":"Morse Code","rating":2400,"from":"curated"}]},{"id":"hash-binary-search","name":"Hashing + binary search (LCP, comparisons, palindromes)","tier":1900,"order":3,"prereq":["hash-polynomial","@bs-answer"],"summary":"Binary search the length of the longest common prefix of two substrings using O(1) hash checks, giving O(log n) lexicographic comparison of any two substrings and palindrome radius computation. Used for longest repeated / common substring (binary search on answer), sorting cyclic shifts, palindrome queries with updates.","learn":["LCP(i, j) by binary search on length with hash equality: O(log n)","Compare substrings lexicographically: find LCP, then compare the next character","Hash the reversed string too: s[l..r] is a palindrome iff forward hash == backward hash","Longest substring occurring >= k times / common to two strings: binary search the length, check with a hash set","Hash in a Fenwick/segment tree supports point updates (CSES Palindrome Queries)","Combine with DP when transitions need \"does block A equal block B\" (e.g. word abbreviations)"],"resources":[{"title":"USACO Guide: String Hashing","url":"https://usaco.guide/gold/hashing","kind":"usaco","where":"USACO Guide Gold","minutes":20},{"title":"cp-algorithms: String Hashing: applications","url":"https://cp-algorithms.com/string/string-hashing.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"1326D2","src":"cf","name":"Prefix-Suffix Palindrome (Hard version)","rating":1800,"from":"usaco-guide"},{"id":"7D","src":"cf","name":"Palindrome Degree","rating":2200,"from":"curated"},{"id":"1003F","src":"cf","name":"Abbreviation","rating":2200,"from":"curated"},{"id":"822E","src":"cf","name":"Liar","rating":2400,"from":"usaco-guide"},{"id":"2038I","src":"cf","name":"Polyathlon","rating":2500,"from":"curated"},{"id":"961F","src":"cf","name":"k-substrings","rating":2700,"from":"curated"},{"id":"cses-2420","src":"cses","name":"Palindrome Queries","from":"curated"}]},{"id":"hash-sets-xor","name":"Set / multiset hashing (XOR & sum hashing)","tier":1900,"order":4,"prereq":["hash-polynomial","@bit-xor"],"summary":"Assign each value a random 64-bit number; the XOR (or sum) of a range is then a fingerprint of its set/multiset. Recognise it when you must test \"every value occurs an even number of times\", \"these two ranges are permutations of each other\" or \"this subarray is a permutation\" many times.","learn":["XOR of random labels over a range is 0 (whp) iff every value appears an even number of times","Sum of random labels fingerprints a multiset; compare with the fingerprint of {1..k} to detect permutations","For \"appears exactly k times\" use labels in Z_k (sum modulo k per component) or cumulative counts mod k","Prefix XOR + hash map counts subarrays with the property in O(n)","Use mt19937_64 seeded with time; 64-bit labels make collisions practically impossible","Graph/cycle tasks: give each edge/cycle a random value and XOR along paths (Zobrist hashing)","Hash a vertex by the XOR/sum of its neighbours labels to group vertices with equal neighbourhoods","Rooted-tree hashing / isomorphism is taught in the Trees area (@trees-hashing)"],"resources":[{"title":"XOR Hashing [Tutorial]","url":"https://codeforces.com/blog/entry/85900","kind":"cf-blog","where":"Codeforces blog","minutes":20},{"title":"USACO Guide: String Hashing (XOR hashing section)","url":"https://usaco.guide/gold/hashing","kind":"usaco","where":"USACO Guide Gold","minutes":15}],"problems":[{"id":"2014H","src":"cf","name":"Robin Hood Archery","rating":1900,"from":"curated"},{"id":"1996G","src":"cf","name":"Penacony","rating":2200,"from":"curated"},{"id":"1977D","src":"cf","name":"XORificator","rating":2300,"from":"curated"},{"id":"154C","src":"cf","name":"Double Profiles","rating":2300,"from":"curated"},{"id":"869E","src":"cf","name":"The Untended Antiquity","rating":2400,"from":"curated"},{"id":"1830C","src":"cf","name":"Hyperregular Bracket Strings","rating":2400,"from":"usaco-guide"},{"id":"1175F","src":"cf","name":"The Number of Subpermutations","rating":2500,"from":"curated"},{"id":"1418G","src":"cf","name":"Three Occurrences","rating":2500,"from":"usaco-guide"},{"id":"1746F","src":"cf","name":"Kazaee","rating":2800,"from":"curated"}]}]},{"id":"prefix-function","name":"Prefix Function / KMP","cfTags":["strings","string suffix structures"],"subtopics":[{"id":"kmp-prefix-function","name":"Prefix function & KMP matching","tier":1600,"order":1,"prereq":["str-subsequences"],"summary":"pi[i] is the length of the longest proper border (prefix that is also a suffix) of s[0..i]. Computing it in O(n) and running it on pattern + \"#\" + text gives all occurrences; it is the go-to deterministic tool for borders and pattern matching.","learn":["Compute pi with the \"fall back j = pi[j-1]\" loop; amortised O(n)","Matching: pi of p + \"#\" + t, positions where pi == |p| are occurrences","All borders of s are pi[n-1], pi[pi[n-1]-1], ... (chain of failure links)","Count occurrences of every prefix: cnt[pi[i]]++, then propagate down the failure chain","Number of distinct substrings in O(n^2) by adding characters one at a time","Works on arrays of integers too (e.g. differences of consecutive heights)"],"resources":[{"title":"cp-algorithms: Prefix function - Knuth-Morris-Pratt","url":"https://cp-algorithms.com/string/prefix-function.html","kind":"cpalgo","where":"cp-algorithms","minutes":30},{"title":"USACO Guide: String Searching (KMP)","url":"https://usaco.guide/adv/string-search","kind":"usaco","where":"USACO Guide Advanced","minutes":30}],"problems":[{"id":"625B","src":"cf","name":"War of the Corporations","rating":1200,"from":"curated"},{"id":"1029A","src":"cf","name":"Many Equal Substrings","rating":1300,"from":"curated"},{"id":"1137B","src":"cf","name":"Camp Schedule","rating":1600,"from":"curated"},{"id":"126B","src":"cf","name":"Password","rating":1700,"from":"curated"},{"id":"471D","src":"cf","name":"MUH and Cube Walls","rating":1800,"from":"curated"},{"id":"1200E","src":"cf","name":"Compress Words","rating":2000,"from":"curated"},{"id":"631D","src":"cf","name":"Messenger","rating":2100,"from":"curated"},{"id":"25E","src":"cf","name":"Test","rating":2200,"from":"curated"},{"id":"cses-1753","src":"cses","name":"String Matching","from":"usaco-guide"},{"id":"cses-1732","src":"cses","name":"Finding Borders","from":"usaco-guide"}]},{"id":"kmp-periods","name":"Borders, periods & repetitions","tier":1800,"order":2,"prereq":["kmp-prefix-function"],"summary":"A string has period p iff it has a border of length n - p; the smallest period is n - pi[n-1] and the string is a repetition of a block iff that period divides n. Appears in \"shortest string whose repetition gives s\", LCM/GCD of strings, cyclic shift cycles and necklace problems.","learn":["Minimal period = n - pi[n-1]; s is k-times a block iff n % period == 0","All periods correspond to all borders (walk the failure chain)","Common divisors of two strings: divisors of gcd(|a|,|b|) that are periods of both","Repeated application of a permutation to a string: each cycle returns after its minimal period (lcm of those)","Periodicity lemma: periods p and q with p + q <= n + gcd(p, q) imply period gcd(p, q)","Hashing alternative: check s[0..n-p) == s[p..n) for each candidate p","Tandem repeats (squares ww): O(n^2) by fixing the half-length and counting equal positions at distance L; all repetitions in O(n log n) with Main-Lorentz"],"resources":[{"title":"cp-algorithms: Prefix function: compressing a string","url":"https://cp-algorithms.com/string/prefix-function.html","kind":"cpalgo","where":"cp-algorithms","minutes":15},{"title":"USACO Guide: String Hashing (Finding Periods)","url":"https://usaco.guide/gold/hashing","kind":"usaco","where":"USACO Guide Gold","minutes":10},{"title":"cp-algorithms: Finding repetitions (Main-Lorentz)","url":"https://cp-algorithms.com/string/main_lorentz.html","kind":"cpalgo","where":"cp-algorithms","minutes":25}],"problems":[{"id":"1473B","src":"cf","name":"String LCM","rating":1000,"from":"curated"},{"id":"182D","src":"cf","name":"Common Divisors","rating":1400,"from":"curated"},{"id":"443B","src":"cf","name":"Kolya and Tandem Repeat","rating":1500,"from":"curated"},{"id":"1950E","src":"cf","name":"Nearly Shortest Repeating Substring","rating":1500,"from":"curated"},{"id":"1948D","src":"cf","name":"Tandem Repeats?","rating":1700,"from":"curated"},{"id":"1219C","src":"cf","name":"Periodic integer number","rating":1700,"from":"curated"},{"id":"1690F","src":"cf","name":"Shifting String","rating":1700,"from":"curated"},{"id":"526D","src":"cf","name":"Om Nom and Necklace","rating":2200,"from":"curated"},{"id":"19C","src":"cf","name":"Deletion of Repeats","rating":2200,"from":"curated"},{"id":"cses-1733","src":"cses","name":"Finding Periods","from":"usaco-guide"}]},{"id":"kmp-automaton","name":"KMP automaton & DP over matches","tier":2100,"order":3,"prereq":["kmp-prefix-function","@dp-strings"],"summary":"Turn the prefix function into an automaton aut[state][c] (state = length of the matched prefix) and run DP over (position, automaton state) to count or optimise strings that contain / avoid a pattern. Typical for \"count strings of length n containing s as a substring\" and for LCS-with-forbidden-substring.","learn":["aut[j][c] = j+1 if p[j] == c else aut[pi[j-1]][c]; build in O(m * alphabet)","DP state (i, j): processed i characters, currently matched j characters of the pattern","Counting strings that contain p = total - strings avoiding p (avoid state m)","Multiple patterns: use Aho-Corasick instead (same idea on a trie)","Combine with other DP dimensions (balance of brackets, LCS indices, number of occurrences)","Prefix-function queries on extended strings: memoise automaton transitions for the fixed part"],"resources":[{"title":"cp-algorithms: Prefix function: building an automaton","url":"https://cp-algorithms.com/string/prefix-function.html","kind":"cpalgo","where":"cp-algorithms","minutes":20},{"title":"USACO Guide: String Searching","url":"https://usaco.guide/adv/string-search","kind":"usaco","where":"USACO Guide Advanced","minutes":10}],"problems":[{"id":"346B","src":"cf","name":"Lucky Common Subsequence","rating":2000,"from":"curated"},{"id":"494B","src":"cf","name":"Obsessive String","rating":2000,"from":"curated"},{"id":"1163D","src":"cf","name":"Mysterious Code","rating":2100,"from":"curated"},{"id":"1721E","src":"cf","name":"Prefix Function Queries","rating":2200,"from":"curated"},{"id":"808G","src":"cf","name":"Anthem of Berland","rating":2300,"from":"curated"},{"id":"1015F","src":"cf","name":"Bracket Substring","rating":2300,"from":"curated"},{"id":"cses-1112","src":"cses","name":"Required Substring","from":"curated"}]}]},{"id":"z-function","name":"Z-function","cfTags":["strings","string suffix structures"],"subtopics":[{"id":"z-function","name":"Z-function & applications","tier":1600,"order":1,"prereq":["str-subsequences"],"summary":"z[i] is the length of the longest common prefix of s and s[i..]; it is computed in O(n) with the [l, r) window trick. Use it for matching (pattern + \"$\" + text), checking which prefixes occur where, comparing a string against all its suffixes, and big-number comparisons of substrings.","learn":["Maintain the rightmost segment [l, r) that matches a prefix; reuse z[i - l] inside it","Matching: z of p + \"$\" + t, positions with z == |p|","Prefix of length k is also a suffix iff z[n-k] == k","Number of occurrences of each prefix: count z values then suffix-sum","Compare s[i..] with s lexicographically in O(1) using z[i] and the next character","Z of t + s compares every suffix of s with t; useful for splitting a number into bounded parts (DP)","Z and prefix function are interconvertible; pick whichever is more natural"],"resources":[{"title":"CPH 26.4: Z-algorithm","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 26.4 (p. 247)","minutes":20},{"title":"cp-algorithms: Z-function","url":"https://cp-algorithms.com/string/z-function.html","kind":"cpalgo","where":"cp-algorithms","minutes":25},{"title":"USACO Guide: String Searching (Z)","url":"https://usaco.guide/adv/string-search","kind":"usaco","where":"USACO Guide Advanced","minutes":20}],"problems":[{"id":"535D","src":"cf","name":"Tavas and Malekas","rating":1900,"from":"curated"},{"id":"1968G1","src":"cf","name":"Division + LCP (easy version)","rating":1900,"from":"curated"},{"id":"432D","src":"cf","name":"Prefixes and Suffixes","rating":2000,"from":"usaco-guide"},{"id":"2209E","src":"cf","name":"A Trivial String Problem","rating":2200,"from":"curated"},{"id":"1968G2","src":"cf","name":"Division + LCP (hard version)","rating":2200,"from":"curated"},{"id":"1537E2","src":"cf","name":"Erase and Extend (Hard Version)","rating":2200,"from":"curated"},{"id":"149E","src":"cf","name":"Martian Strings","rating":2300,"from":"curated"},{"id":"1051E","src":"cf","name":"Vasya and Big Integers","rating":2600,"from":"usaco-guide"},{"id":"1313E","src":"cf","name":"Concatenation with intersection","rating":2700,"from":"usaco-guide"},{"id":"cses-2107","src":"cses","name":"String Functions","from":"curated"}]}]},{"id":"tries","name":"Tries","cfTags":["strings","data structures","trees"],"subtopics":[{"id":"trie-basic","name":"Trie (prefix tree)","tier":1600,"order":1,"prereq":["str-frequency"],"summary":"A rooted tree where each edge is a character and each node is a prefix of some inserted string. Use it for many prefix queries, longest common prefix sums over pairs, dictionary DP (split text into words), and games played by appending letters.","learn":["Array-based nodes: int nxt[N][26], cnt[N], end[N]; node count = total length + 1","Sum over pairs of LCP lengths = sum over nodes of C(cnt, 2)","Word-break DP: from each position walk down the trie (O(n * max word length))","Games on prefixes: compute win/lose on the trie bottom-up (can-win and can-lose separately)","Store the minimum/maximum index or count at every node for \"first string with this prefix\" queries","Memory: allocate exactly total length nodes; reset only used nodes between test cases"],"resources":[{"title":"CPH 26.2: Trie structure","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 26.2 (p. 244)","minutes":15},{"title":"USACO Guide: String Searching (Trie)","url":"https://usaco.guide/adv/string-search","kind":"usaco","where":"USACO Guide Advanced","minutes":20}],"problems":[{"id":"1792D","src":"cf","name":"Fixed Prefix Permutations","rating":1700,"from":"curated"},{"id":"455B","src":"cf","name":"A Lot of Games","rating":1900,"from":"curated"},{"id":"1902E","src":"cf","name":"Collapsing Strings","rating":1900,"from":"curated"},{"id":"633C","src":"cf","name":"Spy Syndrome 2","rating":1900,"from":"curated"},{"id":"37C","src":"cf","name":"Old Berland Language","rating":1900,"from":"usaco-guide"},{"id":"965E","src":"cf","name":"Short Code","rating":2200,"from":"usaco-guide"},{"id":"557E","src":"cf","name":"Ann and Half-Palindrome","rating":2300,"from":"curated"},{"id":"2041I","src":"cf","name":"Auto Complete","rating":2300,"from":"curated"},{"id":"cses-1731","src":"cses","name":"Word Combinations","from":"usaco-guide"}]},{"id":"trie-xor","name":"Binary (XOR) trie","tier":1800,"order":2,"prereq":["trie-basic","@bit-xor"],"summary":"Insert numbers bit by bit from the most significant bit; walking greedily to the opposite bit answers max/min XOR with a set of numbers in O(log C). Recognise it from \"maximum XOR of a pair/subarray\", multiset queries with XOR, and counting pairs whose XOR is below k.","learn":["Max XOR with x: at each bit try to go to child (bit of x) ^ 1","Subarray XOR = prefix[r] ^ prefix[l]: insert prefixes as you sweep","Keep a count per node to support deletion (multiset) and counting pairs with XOR < k","Global XOR updates: keep a lazy mask instead of modifying the trie; MEX after XOR walks down full subtrees","Divide-and-conquer on the trie for minimum XOR spanning tree / inversion counts per bit","Store max index per node for \"latest prefix with XOR >= k\" queries; persistent version for range queries"],"resources":[{"title":"USACO Guide: String Searching (Trie: XOR problems)","url":"https://usaco.guide/adv/string-search","kind":"usaco","where":"USACO Guide Advanced","minutes":15},{"title":"CPH 10: Bit manipulation","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 10 (p. 95)","minutes":15}],"problems":[{"id":"706D","src":"cf","name":"Vasiliy's Multiset","rating":1800,"from":"curated"},{"id":"923C","src":"cf","name":"Perfect Security","rating":1800,"from":"curated"},{"id":"1895D","src":"cf","name":"XOR Construction","rating":1900,"from":"curated"},{"id":"2093G","src":"cf","name":"Shorten the Array","rating":1900,"from":"curated"},{"id":"1285D","src":"cf","name":"Dr. Evil Underscores","rating":1900,"from":"curated"},{"id":"817E","src":"cf","name":"Choosing The Commander","rating":2000,"from":"curated"},{"id":"1416C","src":"cf","name":"XOR Inverse","rating":2000,"from":"curated"},{"id":"842D","src":"cf","name":"Vitya and Strange Lesson","rating":2000,"from":"curated"},{"id":"665E","src":"cf","name":"Beautiful Subarrays","rating":2100,"from":"usaco-guide"},{"id":"cses-1655","src":"cses","name":"Maximum Xor Subarray","from":"usaco-guide"}]},{"id":"trie-xor-advanced","name":"Advanced XOR trie (merging, D&C, persistence)","tier":2300,"order":3,"prereq":["trie-xor"],"summary":"Harder tasks build tries over subtrees or prefixes and combine them: divide and conquer over the trie for XOR-MST, tries per parity class, persistent tries for range-restricted maximum XOR, and trie walks with counts for k-th smallest XOR.","learn":["XOR-MST (Boruvka on a trie): split by the highest bit, connect the two halves by one minimum XOR edge","k-th smallest pairwise XOR: walk all n pointers down the trie simultaneously bit by bit","Persistent trie: version r holds prefixes 0..r with latest-index info for max XOR in [l, r]","Separate tries by depth parity / colour when queries depend on that class","Small-to-large merging of tries over subtrees","Binary search on the answer + trie check (count pairs with XOR < mid) for k-th smallest subarray/pair values","Divide and conquer on the position of the maximum, querying a persistent trie on the smaller side"],"resources":[{"title":"USACO Guide: Persistent Data Structures","url":"https://usaco.guide/adv/persistent","kind":"usaco","where":"USACO Guide Advanced","minutes":25},{"title":"USACO Guide: String Searching (Trie)","url":"https://usaco.guide/adv/string-search","kind":"usaco","where":"USACO Guide Advanced","minutes":10}],"problems":[{"id":"1980G","src":"cf","name":"Yasya and the Mysterious Tree","rating":2300,"from":"curated"},{"id":"888G","src":"cf","name":"Xor-MST","rating":2300,"from":"usaco-guide"},{"id":"1625D","src":"cf","name":"Binary Spiders","rating":2300,"from":"curated"},{"id":"1720D2","src":"cf","name":"Xor-Subsequence (hard version)","rating":2400,"from":"curated"},{"id":"1777F","src":"cf","name":"Comfortably Numb","rating":2400,"from":"curated"},{"id":"1983F","src":"cf","name":"array-value","rating":2500,"from":"curated"},{"id":"241B","src":"cf","name":"Friends","rating":2700,"from":"curated"},{"id":"1849F","src":"cf","name":"XOR Partition","rating":2700,"from":"curated"},{"id":"1055F","src":"cf","name":"Tree and XOR","rating":2900,"from":"usaco-guide"}]}]},{"id":"aho-corasick","name":"Aho-Corasick","cfTags":["strings","string suffix structures"],"subtopics":[{"id":"aho-corasick","name":"Aho-Corasick automaton","tier":2200,"order":1,"prereq":["trie-basic","kmp-prefix-function"],"summary":"Build a trie of all patterns plus suffix (failure) links by BFS to match a whole dictionary against a text in O(total length + matches). Use it for \"count occurrences of each pattern in the text\", \"for each position how many patterns end here\", and pattern-set queries.","learn":["Failure link of a node = longest proper suffix that is also a trie node; compute by BFS","Goto transitions go[v][c] turn the trie into a full automaton","Count occurrences of each pattern: add 1 to the visited state, then accumulate along suffix links in reverse BFS order","Patterns ending at a position = sum of terminal counts along the output-link chain (precompute in BFS)","Number of distinct pattern lengths is O(sqrt(total length)) - useful bound","Suffix-link tree + Euler tour + Fenwick handles dynamic pattern sets and online queries","Dynamic insertions: binary-grouping (log n automata) technique"],"resources":[{"title":"cp-algorithms: Aho-Corasick algorithm","url":"https://cp-algorithms.com/string/aho_corasick.html","kind":"cpalgo","where":"cp-algorithms","minutes":35},{"title":"USACO Guide: String Searching (Aho-Corasick)","url":"https://usaco.guide/adv/string-search","kind":"usaco","where":"USACO Guide Advanced","minutes":25},{"title":"Aho-Corasick algorithm. Construction (CF blog)","url":"https://codeforces.com/blog/entry/14854","kind":"cf-blog","where":"Codeforces blog","minutes":15}],"problems":[{"id":"1202E","src":"cf","name":"You Are Given Some Strings...","rating":2400,"from":"usaco-guide"},{"id":"710F","src":"cf","name":"String Set Queries","rating":2400,"from":"curated"},{"id":"963D","src":"cf","name":"Frequency of String","rating":2500,"from":"usaco-guide"},{"id":"1437G","src":"cf","name":"Death DBMS","rating":2600,"from":"curated"},{"id":"1207G","src":"cf","name":"Indie Album","rating":2700,"from":"usaco-guide"},{"id":"547E","src":"cf","name":"Mike and Friends","rating":2800,"from":"usaco-guide"},{"id":"cses-2102","src":"cses","name":"Finding Patterns","from":"usaco-guide"},{"id":"cses-2103","src":"cses","name":"Counting Patterns","from":"curated"},{"id":"cses-2104","src":"cses","name":"Pattern Positions","from":"curated"}]},{"id":"aho-dp","name":"DP on the Aho-Corasick automaton","tier":2400,"order":2,"prereq":["aho-corasick","kmp-automaton","@dp-bitmask","@dp-matrix-expo"],"summary":"Run DP over (length, automaton state [, extra mask]) to count or optimise strings with respect to a set of patterns; with fixed small state count, matrix exponentiation handles huge lengths. Recognise from \"count strings of length n that contain none / all of these words\" or \"maximise happiness from occurring pickup lines\".","learn":["State = node of the automaton; value of a state = sum of terminal values along suffix links","Forbidden patterns: mark nodes whose suffix-link chain contains a terminal as dead","Must contain all patterns: add a bitmask of seen patterns (small number of patterns)","Large n: (max,+) or (+,*) matrix exponentiation over the automaton states","Question marks / wildcards: transition over all letters, combine with bitmask DP on the letters used"],"resources":[{"title":"cp-algorithms: Aho-Corasick: applications","url":"https://cp-algorithms.com/string/aho_corasick.html","kind":"cpalgo","where":"cp-algorithms","minutes":15},{"title":"USACO Guide: Matrix Exponentiation","url":"https://usaco.guide/plat/matrix-expo","kind":"usaco","where":"USACO Guide Platinum","minutes":20}],"problems":[{"id":"86C","src":"cf","name":"Genetic engineering","rating":2500,"from":"curated"},{"id":"696D","src":"cf","name":"Legen...","rating":2500,"from":"curated"},{"id":"1739F","src":"cf","name":"Keyboard Design","rating":2600,"from":"curated"},{"id":"1511F","src":"cf","name":"Chainword","rating":2700,"from":"curated"},{"id":"1400F","src":"cf","name":"x-prime Substrings","rating":2800,"from":"curated"},{"id":"1327G","src":"cf","name":"Letters and Question Marks","rating":2800,"from":"curated"}]}]},{"id":"palindromes","name":"Palindrome Algorithms","cfTags":["strings","string suffix structures"],"subtopics":[{"id":"pal-manacher","name":"Manacher's algorithm","tier":1800,"order":1,"prereq":["str-palindromes-basic"],"summary":"Computes the radius of the longest palindrome centred at every position (odd and even) in O(n) by reusing a mirrored centre inside the rightmost palindrome. Use it for longest palindromic substring, counting palindromic substrings, and \"longest palindromic prefix/suffix\" questions.","learn":["Handle even centres by inserting separators (s = \"#a#b#\") or keep two arrays d1/d2","Rightmost palindrome [l, r]: start from min(r - i, d[l + r - i]) and extend naively","Number of palindromic substrings = sum of radii","Longest palindromic prefix: largest centre whose palindrome touches index 0","Palindromes starting/ending at each index: difference arrays over the radii","Hashing + binary search gives the same radii in O(n log n) when Manacher is awkward","For n <= 5000 the O(n^2) table pal[l][r] (or expand around every centre) is often enough"],"resources":[{"title":"cp-algorithms: Manacher's Algorithm","url":"https://cp-algorithms.com/string/manacher.html","kind":"cpalgo","where":"cp-algorithms","minutes":25},{"title":"USACO Guide: String Searching (Manacher)","url":"https://usaco.guide/adv/string-search","kind":"usaco","where":"USACO Guide Advanced","minutes":15},{"title":"Manacher's algorithm and code readability (CF blog)","url":"https://codeforces.com/blog/entry/12143","kind":"cf-blog","where":"Codeforces blog","minutes":10}],"problems":[{"id":"245H","src":"cf","name":"Queries for Number of Palindromes","rating":1800,"from":"usaco-guide"},{"id":"835D","src":"cf","name":"Palindromic characteristics","rating":1900,"from":"usaco-guide"},{"id":"1943B","src":"cf","name":"Non-Palindromic Substring","rating":2000,"from":"curated"},{"id":"1080E","src":"cf","name":"Sonya and Matrix Beauty","rating":2400,"from":"usaco-guide"},{"id":"1827C","src":"cf","name":"Palindrome Partition","rating":2600,"from":"curated"},{"id":"30E","src":"cf","name":"Tricky and Clever Password","rating":2800,"from":"curated"},{"id":"cses-1111","src":"cses","name":"Longest Palindrome","from":"usaco-guide"}]},{"id":"pal-eertree","name":"Palindromic tree (eertree)","tier":2600,"order":2,"prereq":["pal-manacher","kmp-prefix-function"],"summary":"The eertree stores every distinct palindromic substring as a node (at most n + 2) with suffix links to the longest palindromic suffix. It answers counts of distinct palindromes, occurrences of each palindrome and powers palindromic-factorisation DP via series links.","learn":["Two roots: length -1 (imaginary) and length 0; add characters one by one, at most one new node each","Suffix link = longest proper palindromic suffix; occurrences via reverse-order accumulation","Palindromic factorisation in O(n log n) using diff/series links (lengths form O(log n) arithmetic progressions)","Count palindromes ending at each position = depth in the suffix-link tree","Palindrome pair counting (Palisection) also solvable with Manacher + prefix sums"],"resources":[{"title":"Palindromic tree: behind the scenes (adamant, CF blog)","url":"https://codeforces.com/blog/entry/13959","kind":"cf-blog","where":"Codeforces blog","minutes":30},{"title":"USACO Guide: String Suffix Structures (Palindromic Tree)","url":"https://usaco.guide/adv/string-suffix","kind":"usaco","where":"USACO Guide Advanced","minutes":15}],"problems":[{"id":"17E","src":"cf","name":"Palisection","rating":2900,"from":"usaco-guide"},{"id":"932G","src":"cf","name":"Palindrome Partition","rating":2900,"from":"usaco-guide"},{"id":"906E","src":"cf","name":"Reverses","rating":3300,"from":"curated"},{"id":"1738H","src":"cf","name":"Palindrome Addicts","rating":3300,"from":"curated"},{"id":"1081H","src":"cf","name":"Palindromic Magic","rating":3500,"from":"usaco-guide"}]}]},{"id":"suffix-structures","name":"Suffix Structures","cfTags":["string suffix structures","strings"],"subtopics":[{"id":"suffix-array","name":"Suffix array","tier":2100,"order":1,"prereq":["hash-binary-search","@sort-basics"],"summary":"Sort all suffixes (or cyclic shifts) by prefix doubling in O(n log n) (or O(n log^2 n) with std::sort). Once built, pattern search is a binary search, and sorted order exposes lexicographic structure: k-th substring, minimal shift, BWT.","learn":["Prefix doubling: rank pairs (rank[i], rank[i + 2^k]) and re-sort; counting sort gives O(n log n)","Append a sentinel smaller than all characters (or work with cyclic shifts)","Pattern occurrence = contiguous range of the SA, found by two binary searches: O(m log n)","Concatenate several strings with distinct separators to compare them together","Same doubling idea sorts strings defined by XOR/shift operations","Burrows-Wheeler transform and its inverse are SA applications (CSES String Transform)"],"resources":[{"title":"cp-algorithms: Suffix Array","url":"https://cp-algorithms.com/string/suffix-array.html","kind":"cpalgo","where":"cp-algorithms","minutes":35},{"title":"USACO Guide: Suffix Array","url":"https://usaco.guide/adv/suffix-array","kind":"usaco","where":"USACO Guide Advanced","minutes":35}],"problems":[{"id":"128B","src":"cf","name":"String","rating":2100,"from":"curated"},{"id":"427D","src":"cf","name":"Match & Catch","rating":2200,"from":"curated"},{"id":"873F","src":"cf","name":"Forbidden Indices","rating":2400,"from":"curated"},{"id":"1090J","src":"cf","name":"Two Prefixes","rating":2600,"from":"usaco-guide"},{"id":"1654F","src":"cf","name":"Minimal String Xoration","rating":2800,"from":"curated"},{"id":"232D","src":"cf","name":"Fence","rating":2900,"from":"curated"},{"id":"cses-2108","src":"cses","name":"Substring Order I","from":"curated"},{"id":"cses-1113","src":"cses","name":"String Transform","from":"usaco-guide"}]},{"id":"suffix-lcp","name":"LCP array & applications","tier":2300,"order":2,"prereq":["suffix-array","@ds-sparse-table"],"summary":"Kasai's algorithm builds lcp[i] = LCP of adjacent suffixes in the SA in O(n); with a sparse table, LCP of any two suffixes is a range minimum. Classic uses: number of distinct substrings, longest repeated / common substring, counting substrings occurring k times, sums of LCP over sets of suffixes.","learn":["Kasai: process suffixes in text order, lcp decreases by at most 1 each step","Distinct substrings = n(n+1)/2 - sum(lcp)","LCP(sa_i, sa_j) = min(lcp[i+1..j]): sparse table for O(1) queries","Longest common substring of A and B: adjacent SA entries from different strings in A + \"#\" + B","Sum of pairwise LCPs over a set: sort by SA rank, monotonic stack or DSU merging by decreasing lcp","Substrings occurring >= k times: sliding window minimum over lcp"],"resources":[{"title":"cp-algorithms: Suffix Array: LCP and applications","url":"https://cp-algorithms.com/string/suffix-array.html","kind":"cpalgo","where":"cp-algorithms","minutes":25},{"title":"USACO Guide: Suffix Array (LCP)","url":"https://usaco.guide/adv/suffix-array","kind":"usaco","where":"USACO Guide Advanced","minutes":25}],"problems":[{"id":"123D","src":"cf","name":"String","rating":2300,"from":"curated"},{"id":"316G3","src":"cf","name":"Good Substrings","rating":2400,"from":"curated"},{"id":"452E","src":"cf","name":"Three strings","rating":2400,"from":"curated"},{"id":"1780G","src":"cf","name":"Delicious Dessert","rating":2400,"from":"curated"},{"id":"1073G","src":"cf","name":"Yet Another LCP Problem","rating":2600,"from":"usaco-guide"},{"id":"653F","src":"cf","name":"Paper task","rating":2600,"from":"usaco-guide"},{"id":"204E","src":"cf","name":"Little Elephant and Strings","rating":2800,"from":"curated"},{"id":"cses-2105","src":"cses","name":"Distinct Substrings","from":"curated"},{"id":"cses-2106","src":"cses","name":"Repeating Substring","from":"curated"},{"id":"cses-2110","src":"cses","name":"Substring Distribution","from":"curated"}]},{"id":"suffix-automaton","name":"Suffix automaton & suffix tree","tier":2400,"order":3,"prereq":["suffix-array","aho-corasick"],"summary":"The suffix automaton is the minimal DFA recognising all suffixes (at most 2n states), built online in O(n); its suffix-link tree is the suffix tree of the reversed string. It answers substring membership, number of distinct substrings, occurrences of every substring and k-th lexicographic substring.","learn":["Each state = class of substrings with the same endpos set; len[v] and link[v] determine it","Online extension with cloning; total states <= 2n - 1, transitions <= 3n - 4","Distinct substrings = sum(len[v] - len[link[v]]); occurrences = endpos sizes via the link tree","k-th substring: count paths from each state (DP on DAG) and walk","Generalised SAM for several strings; longest common substring by running the second string through","Suffix tree (Ukkonen or from SA + LCP) is the dual structure; pick whichever you know best"],"resources":[{"title":"cp-algorithms: Suffix Automaton","url":"https://cp-algorithms.com/string/suffix-automaton.html","kind":"cpalgo","where":"cp-algorithms","minutes":45},{"title":"USACO Guide: String Suffix Structures","url":"https://usaco.guide/adv/string-suffix","kind":"usaco","where":"USACO Guide Advanced","minutes":35},{"title":"A short guide to suffix automata (CF blog)","url":"https://codeforces.com/blog/entry/20861","kind":"cf-blog","where":"Codeforces blog","minutes":20},{"title":"cp-algorithms: Suffix Tree (Ukkonen)","url":"https://cp-algorithms.com/string/suffix-tree-ukkonen.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"316G2","src":"cf","name":"Good Substrings","rating":2200,"from":"curated"},{"id":"802G3","src":"cf","name":"Fake News (hard)","rating":2300,"from":"curated"},{"id":"616F","src":"cf","name":"Expensive Strings","rating":2700,"from":"curated"},{"id":"235C","src":"cf","name":"Cyclical Quest","rating":2700,"from":"usaco-guide"},{"id":"666E","src":"cf","name":"Forensic Examination","rating":3100,"from":"curated"},{"id":"1037H","src":"cf","name":"Security","rating":3200,"from":"usaco-guide"},{"id":"1063F","src":"cf","name":"String Journey","rating":3300,"from":"usaco-guide"},{"id":"700E","src":"cf","name":"Cool Slogans","rating":3300,"from":"curated"},{"id":"cses-2109","src":"cses","name":"Substring Order II","from":"curated"}]}]},{"id":"string-advanced","name":"Advanced String Topics","cfTags":["strings","fft","dp","string suffix structures"],"subtopics":[{"id":"str-lcp-dp","name":"DP powered by string tools (LCP table, palindrome table, matching)","tier":1900,"order":1,"prereq":["hash-polynomial","z-function","@dp-lcs-edit","@dp-strings"],"summary":"DP over positions or substrings whose transitions ask string questions: \"are these two blocks equal?\", \"is s[l..r] a palindrome?\", \"which substring is larger?\", \"where does t occur?\". Precompute the answers with an O(n^2) LCP table, a palindrome table, hashing, Z or KMP so each transition is O(1). Classic DP forms (LCS, edit distance, subsequence counting) live in the DP area (@dp-lcs-edit, @dp-strings).","learn":["O(n^2) LCP table: lcp[i][j] = s[i]==s[j] ? lcp[i+1][j+1] + 1 : 0, filled from the back (use short/int16 to save memory)","Compare two substrings of equal length via lcp: equal iff lcp >= len, otherwise compare the first different character","Palindrome table pal[l][r] = s[l]==s[r] && pal[l+1][r-1]; prefix sums of palindromes ending/starting at i count pairs","Splitting into increasing numbers: dp[i][len] with LCP-based comparison of the previous block plus suffix sums","Compression DP: dp[i] = min over j of dp[j] + cost(s[j..i)), where the period of every substring comes from a prefix function started at j","Find all occurrences first (KMP/Z/hash), then DP over occurrences (cover / remove all occurrences with minimum moves and count ways)","Memory: n = 5000 gives 25M cells; reuse rows or store only what transitions need"],"resources":[{"title":"CPH 26.3: String hashing (substring comparison)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 26.3 (p. 245)","minutes":15},{"title":"cp-algorithms: Z-function (LCP with the prefix)","url":"https://cp-algorithms.com/string/z-function.html","kind":"cpalgo","where":"cp-algorithms","minutes":15},{"title":"cp-algorithms: Prefix function: compressing a string","url":"https://cp-algorithms.com/string/prefix-function.html","kind":"cpalgo","where":"cp-algorithms","minutes":15},{"title":"USACO Guide: Introduction to DP","url":"https://usaco.guide/gold/intro-dp","kind":"usaco","where":"USACO Guide Gold","minutes":20}],"problems":[{"id":"159D","src":"cf","name":"Palindrome pairs","rating":1500,"from":"curated"},{"id":"611D","src":"cf","name":"New Year and Ancient Prophecy","rating":2000,"from":"curated"},{"id":"1624E","src":"cf","name":"Masha-forgetful","rating":2000,"from":"curated"},{"id":"1729G","src":"cf","name":"Cut Substrings","rating":2100,"from":"curated"},{"id":"1120C","src":"cf","name":"Compress String","rating":2100,"from":"curated"},{"id":"2045H","src":"cf","name":"Missing Separators","rating":2200,"from":"curated"},{"id":"825F","src":"cf","name":"String Compression","rating":2400,"from":"curated"},{"id":"1562E","src":"cf","name":"Rescue Niwen!","rating":2500,"from":"curated"}]},{"id":"str-min-rotation","name":"Cyclic strings: minimal rotation & Lyndon factorisation","tier":1900,"order":2,"prereq":["kmp-periods","hash-binary-search"],"summary":"Duval's algorithm splits a string into a non-increasing sequence of Lyndon words in O(n); the lexicographically smallest cyclic shift is found with it (or with Booth's algorithm / SA on s+s). Appears in canonical forms of cyclic strings and necklaces, and greedy \"cut and reverse\" tasks.","learn":["Lyndon word: strictly smaller than all its proper rotations","Duval: maintain i, j, k pointers; O(n) time, O(1) memory","Minimal rotation: run Duval on s + s; the answer is the start of the last Lyndon factor that begins before position n","Alternatives: suffix array of s + s, or hashing + binary search comparisons in O(n log n)","Canonical form of a cyclic string = its minimal rotation (compare necklaces by it, count distinct rotations)","Booth's algorithm (failure function on s + s) is an O(n) alternative to Duval"],"resources":[{"title":"cp-algorithms: Lyndon factorization","url":"https://cp-algorithms.com/string/lyndon_factorization.html","kind":"cpalgo","where":"cp-algorithms","minutes":25},{"title":"USACO Guide: String Searching (Minimal Rotation)","url":"https://usaco.guide/adv/string-search","kind":"usaco","where":"USACO Guide Advanced","minutes":10}],"problems":[{"id":"745A","src":"cf","name":"Hongcow Learns the Cyclic Shift","rating":900,"from":"curated"},{"id":"496B","src":"cf","name":"Secret Combination","rating":1500,"from":"curated"},{"id":"524F","src":"cf","name":"And Yet Another Bracket Sequence","rating":2700,"from":"curated"},{"id":"594E","src":"cf","name":"Cutting the Line","rating":3100,"from":"curated"},{"id":"cses-1110","src":"cses","name":"Minimal Rotation","from":"usaco-guide"}]},{"id":"str-fft-matching","name":"Matching with FFT / bitsets (wildcards, mismatches)","tier":2500,"order":3,"prereq":["z-function","@fft-convolution"],"summary":"When the pattern has wildcards or you need, for every alignment, the number of matching characters, encode the comparison as a convolution (sum over (a - b)^2 * a * b with 0 for wildcards) and use FFT; for small alphabets do one convolution per letter. Bitset shift-and gives O(nm/64) substring queries.","learn":["Exact matching with wildcards: sum p_j t_{i+j} (p_j - t_{i+j})^2 = 0 expands into three convolutions","Per-letter indicator convolutions count matches for each shift (alphabet size times FFT)","Approximate matching (within distance k): blur the text indicator first, then convolve","Bitset shift-and: occ &= (pos[c] >> j) for each pattern character; supports point updates","Use NTT or double precision carefully; reverse one of the sequences to turn correlation into convolution"],"resources":[{"title":"cp-algorithms: Fast Fourier transform (string matching section)","url":"https://cp-algorithms.com/algebra/fft.html","kind":"cpalgo","where":"cp-algorithms","minutes":30},{"title":"USACO Guide: Introduction to Fast Fourier Transform","url":"https://usaco.guide/adv/fft","kind":"usaco","where":"USACO Guide Advanced","minutes":30},{"title":"USACO Guide: Bitsets","url":"https://usaco.guide/plat/bitsets","kind":"usaco","where":"USACO Guide Platinum","minutes":15}],"problems":[{"id":"954I","src":"cf","name":"Yet Another String Matching Problem","rating":2200,"from":"curated"},{"id":"528D","src":"cf","name":"Fuzzy Search","rating":2500,"from":"curated"},{"id":"754E","src":"cf","name":"Dasha and cyclic table","rating":2600,"from":"curated"},{"id":"827E","src":"cf","name":"Rusty String","rating":2700,"from":"curated"},{"id":"1334G","src":"cf","name":"Substring Search","rating":2900,"from":"curated"},{"id":"914F","src":"cf","name":"Substrings in a String","rating":3000,"from":"curated"}]}]}]},{"area":"misc","topics":[{"id":"geometry","name":"Geometry","cfTags":["geometry"],"subtopics":[{"id":"geo-points-vectors","name":"Points, vectors & distances","tier":1000,"order":1,"prereq":[],"summary":"Representing points and vectors with integer coordinates, computing Euclidean and squared distances, dot products and basic vector arithmetic. Appears in easy problems about distances, circles around the origin and moving on the plane; recognise it whenever coordinates are given and comparisons of lengths are needed.","learn":["Store points as pair<long long,long long> or a small struct with +, -, scalar * operators (or std::complex as in CPH 29.1)","Compare distances using squared lengths (dx*dx+dy*dy) to stay in exact integer arithmetic; take sqrt only for the final output","Dot product a.x*b.x+a.y*b.y: zero means perpendicular, sign tells acute/obtuse angle","Watch overflow: coordinates up to 1e9 give squared distances up to ~8e18, use long long (or __int128)","Print floating answers with enough digits (setprecision(10)) and use long double when precision matters","Translate the problem so one point is the origin to simplify formulas","Vector identities: ABCD is a parallelogram iff the diagonals share a midpoint (A+C = B+D); a polygon is centrally symmetric iff p_i + p_{i+n/2} is constant","The same tools work in 3D: squared distances and dot products identify cubes, right angles and equal edges"],"resources":[{"title":"Complex numbers / points as vectors","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 29.1 (p. 266)","minutes":20},{"title":"Geometry Primitives","url":"https://usaco.guide/plat/geo-pri","kind":"usaco","where":"USACO Guide Platinum","minutes":40},{"title":"Basic Geometry","url":"https://cp-algorithms.com/geometry/basic-geometry.html","kind":"cpalgo","where":"cp-algorithms","minutes":30}],"problems":[{"id":"1047B","src":"cf","name":"Cover Points","rating":900,"from":"curated"},{"id":"1620B","src":"cf","name":"Triangles on a Rectangle","rating":1000,"from":"curated"},{"id":"1199B","src":"cf","name":"Water Lily","rating":1000,"from":"curated"},{"id":"1886B","src":"cf","name":"Fear of the Dark","rating":1200,"from":"curated"},{"id":"2002C","src":"cf","name":"Black Circles","rating":1200,"from":"curated"},{"id":"1495A","src":"cf","name":"Diamond Miner","rating":1200,"from":"curated"},{"id":"1307B","src":"cf","name":"Cow and Friend","rating":1300,"from":"curated"},{"id":"507B","src":"cf","name":"Amr and Pins","rating":1400,"from":"curated"},{"id":"18A","src":"cf","name":"Triangle","rating":1500,"from":"curated"},{"id":"407A","src":"cf","name":"Triangle","rating":1600,"from":"curated"},{"id":"1299B","src":"cf","name":"Aerodynamic","rating":1800,"from":"curated"},{"id":"660D","src":"cf","name":"Number of Parallelograms","rating":1900,"from":"curated"},{"id":"464B","src":"cf","name":"Restore Cube ","rating":2000,"from":"curated"},{"id":"1477C","src":"cf","name":"Nezzar and Nice Beatmap","rating":2200,"from":"curated"}]},{"id":"geo-rectangles","name":"Rectangle geometry","tier":1000,"order":2,"prereq":["geo-points-vectors"],"summary":"Axis-aligned rectangles: area, intersection, union of two or three rectangles and coverage checks. Very common in Div 3/4 and early Div 2 problems; recognise it when shapes are given by lower-left and upper-right corners.","learn":["Intersection of [x1,x2]x[y1,y2] and [x3,x4]x[y3,y4] is [max(x1,x3),min(x2,x4)] x [max(y1,y3),min(y2,y4)], empty if any side is negative","Area of union of two rectangles = A + B - intersection (inclusion-exclusion)","To test if a rectangle is fully covered, subtract covered parts and check what remains","Prefix/suffix intersections let you drop one rectangle in O(1) (intersection of all but one)","Compress coordinates when many rectangles are involved, then sweep or use 2D difference arrays"],"resources":[{"title":"Rectangle Geometry","url":"https://usaco.guide/bronze/rect-geo","kind":"usaco","where":"USACO Guide Bronze","minutes":30},{"title":"Points and lines (basics)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 29.2 (p. 268)","minutes":15}],"problems":[{"id":"1622A","src":"cf","name":"Construct a Rectangle","rating":800,"from":"curated"},{"id":"2027A","src":"cf","name":"Rectangle Arrangement","rating":800,"from":"curated"},{"id":"1555B","src":"cf","name":"Two Tables","rating":1300,"from":"usaco-guide"},{"id":"1028C","src":"cf","name":"Rectangles","rating":1600,"from":"curated"},{"id":"993A","src":"cf","name":"Two Squares","rating":1600,"from":"curated"},{"id":"135B","src":"cf","name":"Rectangle and Square","rating":1600,"from":"curated"},{"id":"1216C","src":"cf","name":"White Sheet","rating":1700,"from":"usaco-guide"},{"id":"581D","src":"cf","name":"Three Logos","rating":1700,"from":"usaco-guide"},{"id":"14C","src":"cf","name":"Four Segments","rating":1700,"from":"curated"}]},{"id":"geo-manhattan","name":"Manhattan & Chebyshev distance","tier":1500,"order":3,"prereq":["geo-points-vectors"],"summary":"Manhattan distance |dx|+|dy| separates into coordinates and becomes Chebyshev distance after rotating by 45 degrees (u=x+y, v=x-y). Recognise it in grid-walking problems, sums of pairwise distances and farthest-pair queries.","learn":["Sum of |xi-xj| over all pairs: sort and use prefix sums, independently for x and y","Rotation trick: |dx|+|dy| = max(|du|,|dv|) with u=x+y, v=x-y; max Manhattan distance = max over the four sign combinations","Chebyshev distance max(|dx|,|dy|) is king moves on a grid; convert back with the inverse rotation","Manhattan circles are diamonds; diamonds become axis-aligned squares after rotation","Points with equal Manhattan and Euclidean distance share x or y (count with maps and subtract duplicates)","Terms like max(0, p - |x - j|) are tents; the rotation (j+x, j-x) turns \"is every point covered\" into two prefix-max checks","Short Manhattan tours: sort points in vertical strips of width ~sqrt(C), alternating direction (Mo-style ordering)"],"resources":[{"title":"Distance functions","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 29.4 (p. 272)","minutes":15},{"title":"Manhattan Distance","url":"https://cp-algorithms.com/geometry/manhattan-distance.html","kind":"cpalgo","where":"cp-algorithms","minutes":25}],"problems":[{"id":"1450B","src":"cf","name":"Balls of Steel","rating":1000,"from":"curated"},{"id":"1869B","src":"cf","name":"2D Traveling","rating":1100,"from":"curated"},{"id":"1648A","src":"cf","name":"Weird Sum","rating":1400,"from":"curated"},{"id":"1550C","src":"cf","name":"Manhattan Subarrays","rating":1700,"from":"curated"},{"id":"2122C","src":"cf","name":"Manhattan Pairs","rating":1700,"from":"curated"},{"id":"1689D","src":"cf","name":"Lena and Matrix","rating":1900,"from":"curated"},{"id":"1032D","src":"cf","name":"Barcelonian Distance","rating":1900,"from":"curated"},{"id":"1710B","src":"cf","name":"Rain","rating":2100,"from":"curated"},{"id":"576C","src":"cf","name":"Points on Plane","rating":2100,"from":"usaco-guide"},{"id":"1044C","src":"cf","name":"Optimal Polygon Perimeter","rating":2100,"from":"curated"},{"id":"1979E","src":"cf","name":"Manhattan Triangle","rating":2400,"from":"curated"},{"id":"1455E","src":"cf","name":"Four Points","rating":2400,"from":"curated"},{"id":"85E","src":"cf","name":"Guard Towers","rating":2600,"from":"curated"}]},{"id":"geo-cross-product","name":"Cross product & orientation","tier":1600,"order":4,"prereq":["geo-points-vectors"],"summary":"The cross product a.x*b.y-a.y*b.x gives twice the signed area of a triangle and tells whether a turn is left, right or collinear. It is the core primitive of almost all computational geometry; recognise it whenever you must decide on which side of a line a point lies.","learn":["cross(b-a, c-a) > 0: counter-clockwise (left turn), < 0: clockwise, = 0: collinear","Keep everything in integers (long long / __int128) so orientation tests are exact","|cross| / 2 is the triangle area; non-degenerate triangle iff cross != 0","Collinearity of many points: fix one point and normalise direction vectors (divide by gcd, fix sign) to group them","Dot product decides angle type; cross product decides side - combine them to sort or classify","Interactive problems may ask only for orientation signs: build convex order from sign queries"],"resources":[{"title":"Points and lines","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 29.2 (p. 268)","minutes":25},{"title":"Geometry Primitives","url":"https://usaco.guide/plat/geo-pri","kind":"usaco","where":"USACO Guide Platinum","minutes":40},{"title":"Oriented area of a triangle","url":"https://cp-algorithms.com/geometry/oriented-triangle-area.html","kind":"cpalgo","where":"cp-algorithms","minutes":10}],"problems":[{"id":"cses-2189","src":"cses","name":"Point Location Test","from":"usaco-guide"},{"id":"659D","src":"cf","name":"Bicycle Race","rating":1500,"from":"curated"},{"id":"1616C","src":"cf","name":"Representative Edges","rating":1500,"from":"curated"},{"id":"618C","src":"cf","name":"Constellation","rating":1600,"from":"curated"},{"id":"1030D","src":"cf","name":"Vasya and Triangle","rating":1800,"from":"curated"},{"id":"552D","src":"cf","name":"Vanya and Triangles","rating":1900,"from":"curated"},{"id":"961D","src":"cf","name":"Pair Of Lines","rating":2000,"from":"curated"},{"id":"340B","src":"cf","name":"Maximal Area Quadrilateral","rating":2100,"from":"curated"},{"id":"1254C","src":"cf","name":"Point Ordering","rating":2300,"from":"curated"}]},{"id":"geo-lines","name":"Lines: representation & intersection","tier":1800,"order":5,"prereq":["geo-cross-product"],"summary":"Representing lines as ax+by=c or point+direction, normalising them for hashing, checking parallelism and computing intersection points. Recognise it in counting problems about lines through pairs of points or intersection counts.","learn":["Line through p,q: a=q.y-p.y, b=p.x-q.x, c=a*p.x+b*p.y; normalise (divide by gcd, make first non-zero positive) to store in a set/map","Two lines are parallel iff a1*b2-a2*b1=0; intersection uses Cramer's rule with that determinant","Number of intersecting pairs = total pairs minus pairs within each parallel class","Normalised direction vectors (dx/g, dy/g) identify slopes exactly without floating point","Use exact rational comparisons (cross-multiplication) instead of comparing slopes as doubles","Distance from point P to line AB = |cross(B-A, P-A)| / |B-A|; it bounds how far a convex vertex can move before the polygon stops being convex"],"resources":[{"title":"Intersection Point of Lines","url":"https://cp-algorithms.com/geometry/lines-intersection.html","kind":"cpalgo","where":"cp-algorithms","minutes":15},{"title":"Points and lines","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 29.2 (p. 268)","minutes":20},{"title":"Basic Geometry (lines)","url":"https://cp-algorithms.com/geometry/basic-geometry.html","kind":"cpalgo","where":"cp-algorithms","minutes":30}],"problems":[{"id":"1248A","src":"cf","name":"Integer Points","rating":1000,"from":"curated"},{"id":"593B","src":"cf","name":"Anton and Lines","rating":1600,"from":"curated"},{"id":"849B","src":"cf","name":"Tell Your World","rating":1600,"from":"curated"},{"id":"1468F","src":"cf","name":"Full Turn","rating":1700,"from":"curated"},{"id":"772B","src":"cf","name":"Volatile Kite","rating":1800,"from":"curated"},{"id":"1163C1","src":"cf","name":"Power Transmission (Easy Edition)","rating":1900,"from":"curated"},{"id":"1163C2","src":"cf","name":"Power Transmission (Hard Edition)","rating":1900,"from":"curated"},{"id":"1016E","src":"cf","name":"Rest In The Shades","rating":2400,"from":"curated"}]},{"id":"geo-segment-intersection","name":"Segment intersection","tier":1900,"order":6,"prereq":["geo-cross-product"],"summary":"Deciding whether two segments intersect using orientation tests, including collinear-overlap edge cases, and computing the intersection point. Recognise it when segments, fences, chords or paths must not cross.","learn":["Proper intersection: orientations of (a,b,c) and (a,b,d) differ AND orientations of (c,d,a) and (c,d,b) differ","Collinear case: all four orientations are zero, then check overlap of bounding boxes/projections","Point on segment: cross = 0 and the point lies within the bounding box","Chords of a circle intersect iff their endpoints interleave around the circle","Lattice points on a segment: gcd(|dx|,|dy|)+1 (useful for counting covered integer points)","Test edge cases: shared endpoints, zero-length segments, vertical segments"],"resources":[{"title":"Points and lines (segment intersection)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 29.2 (p. 268)","minutes":20},{"title":"Check if two segments intersect","url":"https://cp-algorithms.com/geometry/check-segments-intersection.html","kind":"cpalgo","where":"cp-algorithms","minutes":15},{"title":"Finding intersection of two segments","url":"https://cp-algorithms.com/geometry/segments-intersection.html","kind":"cpalgo","where":"cp-algorithms","minutes":15},{"title":"Geometry Primitives","url":"https://usaco.guide/plat/geo-pri","kind":"usaco","where":"USACO Guide Platinum","minutes":40}],"problems":[{"id":"cses-2190","src":"cses","name":"Line Segment Intersection","from":"usaco-guide"},{"id":"1552C","src":"cf","name":"Maximize the Intersections","rating":1800,"from":"curated"},{"id":"1036E","src":"cf","name":"Covered Points","rating":2400,"from":"curated"},{"id":"1468G","src":"cf","name":"Hobbits","rating":2500,"from":"curated"},{"id":"598F","src":"cf","name":"Cut Length","rating":2900,"from":"usaco-guide"}]},{"id":"geo-polygon-area","name":"Polygon area & point in polygon","tier":1800,"order":7,"prereq":["geo-cross-product"],"summary":"Shoelace formula for the area of a simple polygon and ray casting / winding tests for point-in-polygon, plus O(log n) point-in-convex-polygon by binary search. Recognise it whenever a polygon is given as a vertex list.","learn":["Shoelace: 2*Area = |sum cross(p_i, p_{i+1})|; keep twice the area as an integer","Sign of the sum gives orientation (CCW positive)","Ray casting: count crossings of a horizontal ray; handle points on the boundary separately","Convex polygon: binary search the fan of triangles from vertex 0 for O(log n) queries","Triangulation and area-based DP: split polygon by diagonals, check diagonal validity with cross products","Area of triangle/quadrilateral maximisation: fix a diagonal, take best point on each side","Counting triangles of polygon vertices that contain a point: count the complement (triangles lying in a half-plane through the point) with two pointers"],"resources":[{"title":"Polygon area","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 29.3 (p. 271)","minutes":15},{"title":"Geometry Primitives","url":"https://usaco.guide/plat/geo-pri","kind":"usaco","where":"USACO Guide Platinum","minutes":40},{"title":"Finding area of simple polygon","url":"https://cp-algorithms.com/geometry/area-of-simple-polygon.html","kind":"cpalgo","where":"cp-algorithms","minutes":10},{"title":"Check if point belongs to the convex polygon","url":"https://cp-algorithms.com/geometry/point-in-convex-polygon.html","kind":"cpalgo","where":"cp-algorithms","minutes":15}],"problems":[{"id":"cses-2191","src":"cses","name":"Polygon Area","from":"usaco-guide"},{"id":"cses-2192","src":"cses","name":"Point in Polygon","from":"usaco-guide"},{"id":"559A","src":"cf","name":"Gerald's Hexagon","rating":1600,"from":"curated"},{"id":"166B","src":"cf","name":"Polygons","rating":2100,"from":"curated"},{"id":"55E","src":"cf","name":"Very simple problem","rating":2500,"from":"curated"},{"id":"437E","src":"cf","name":"The Child and Polygon","rating":2500,"from":"curated"},{"id":"13D","src":"cf","name":"Triangles","rating":2600,"from":"curated"}]},{"id":"geo-picks-lattice","name":"Pick's theorem & lattice points","tier":1900,"order":8,"prereq":["geo-polygon-area"],"summary":"Pick's theorem A = i + b/2 - 1 relates area, interior and boundary lattice points of a lattice polygon; boundary points on an edge are gcd(|dx|,|dy|). Recognise it when counting integer points inside/on a polygon or constructing lattice triangles of given area.","learn":["Boundary points b = sum over edges gcd(|dx|,|dy|)","Interior points i = A - b/2 + 1 with A from the shoelace formula (use 2A to stay integer)","Lattice triangle area is always a multiple of 1/2: 2A must be an integer, which gives feasibility conditions","Lattice points inside a circle/annulus: loop over x and compute the y-range with integer sqrt","Lattice points under a line: floor-sum style counting (see number theory area)","Parity tricks: with Pick, the parity of interior points depends only on coordinates mod 4 and gcds mod 4, so classify points into residue classes and count"],"resources":[{"title":"Pick's Theorem","url":"https://cp-algorithms.com/geometry/picks-theorem.html","kind":"cpalgo","where":"cp-algorithms","minutes":10},{"title":"Lattice points inside non-lattice polygon","url":"https://cp-algorithms.com/geometry/lattice-points.html","kind":"cpalgo","where":"cp-algorithms","minutes":20},{"title":"Geometry Primitives (Pick)","url":"https://usaco.guide/plat/geo-pri","kind":"usaco","where":"USACO Guide Platinum","minutes":40}],"problems":[{"id":"cses-2193","src":"cses","name":"Polygon Lattice Points","from":"usaco-guide"},{"id":"1971F","src":"cf","name":"Circle Perimeter","rating":1600,"from":"curated"},{"id":"1030D","src":"cf","name":"Vasya and Triangle","rating":1800,"from":"curated"},{"id":"1548D1","src":"cf","name":"Gregor and the Odd Cows (Easy)","rating":2300,"from":"curated"},{"id":"1036E","src":"cf","name":"Covered Points","rating":2400,"from":"curated"}]},{"id":"geo-precision-circles","name":"Floating point, circles & numeric geometry","tier":1700,"order":9,"prereq":["geo-points-vectors"],"summary":"Problems involving circles, angles, trigonometry and continuous optimisation where answers are real numbers. Recognise them from \"absolute or relative error 1e-6\" outputs; they often combine geometry with binary or ternary search on the answer.","learn":["Use long double, compare with an epsilon, and avoid subtracting nearly equal numbers","acos/asin need arguments clamped to [-1,1]","Circle-circle and circle-line intersections: derive with distances and the cosine rule","Distance from point to segment: project with the dot product, clamp to the segment","Tangent circles: centres of touching circles of radii r1,r2 are r1+r2 apart; solve for the unknown coordinate with Pythagoras","Binary search the answer (radius, time) when a monotone feasibility check exists; ternary search for unimodal functions","Regular polygons: central angle 2*pi/n; inscribed/circumscribed radius formulas"],"resources":[{"title":"Circle-Line Intersection","url":"https://cp-algorithms.com/geometry/circle-line-intersection.html","kind":"cpalgo","where":"cp-algorithms","minutes":15},{"title":"Circle-Circle Intersection","url":"https://cp-algorithms.com/geometry/circle-circle-intersection.html","kind":"cpalgo","where":"cp-algorithms","minutes":10},{"title":"Basic Geometry","url":"https://cp-algorithms.com/geometry/basic-geometry.html","kind":"cpalgo","where":"cp-algorithms","minutes":30},{"title":"Complex numbers (angles, rotation)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 29.1 (p. 266)","minutes":15}],"problems":[{"id":"1354C1","src":"cf","name":"Simple Polygon Embedding","rating":1400,"from":"curated"},{"id":"908C","src":"cf","name":"New Year and Curling","rating":1500,"from":"curated"},{"id":"1096C","src":"cf","name":"Polygon for the Angle","rating":1600,"from":"curated"},{"id":"935C","src":"cf","name":"Fifa and Fafa","rating":1600,"from":"curated"},{"id":"140A","src":"cf","name":"New Year Table","rating":1700,"from":"curated"},{"id":"613A","src":"cf","name":"Peter and Snow Blower","rating":1900,"from":"curated"},{"id":"342C","src":"cf","name":"Cupboard and Balloons","rating":1900,"from":"curated"},{"id":"600D","src":"cf","name":"Area of Two Circles' Intersection","rating":2000,"from":"curated"},{"id":"1354C2","src":"cf","name":"Not So Simple Polygon Embedding","rating":2000,"from":"curated"},{"id":"1C","src":"cf","name":"Ancient Berland Circus","rating":2100,"from":"curated"},{"id":"630P","src":"cf","name":"Area of a Star","rating":2100,"from":"curated"},{"id":"1059D","src":"cf","name":"Nature Reserve","rating":2200,"from":"curated"}]},{"id":"geo-polar-sort","name":"Angular (polar) sort","tier":2000,"order":10,"prereq":["geo-cross-product"],"summary":"Sorting vectors by angle around a point using half-plane classification plus cross product, avoiding atan2 precision issues. Recognise it when you need consecutive directions, angle gaps, rotating sweeps or counting triangles/configurations around a pivot.","learn":["Split vectors into upper half (y>0 or y=0,x>0) and lower half, then compare by cross product inside each half","atan2 with long double works for moderate coordinates but can fail for nearly parallel vectors","Minimum angle between vectors: sort and check adjacent pairs including the wrap-around","Angular sweep around each point gives O(n^2 log n) algorithms for counting triangles/quadrilaterals","Normalised directions (gcd) group identical rays exactly"],"resources":[{"title":"Basic Geometry (angles)","url":"https://cp-algorithms.com/geometry/basic-geometry.html","kind":"cpalgo","where":"cp-algorithms","minutes":30},{"title":"Complex numbers (arg / polar form)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 29.1 (p. 266)","minutes":15},{"title":"Geometry Primitives","url":"https://usaco.guide/plat/geo-pri","kind":"usaco","where":"USACO Guide Platinum","minutes":40}],"problems":[{"id":"257C","src":"cf","name":"View Angle","rating":1800,"from":"curated"},{"id":"598C","src":"cf","name":"Nearest vectors","rating":2300,"from":"curated"},{"id":"1284E","src":"cf","name":"New Year and Castle Construction","rating":2500,"from":"curated"},{"id":"1019D","src":"cf","name":"Large Triangle","rating":2700,"from":"curated"},{"id":"1025F","src":"cf","name":"Disjoint Triangles","rating":2700,"from":"curated"}]},{"id":"geo-convex-hull","name":"Convex hull","tier":2000,"order":11,"prereq":["geo-cross-product","geo-polygon-area"],"summary":"Computing the convex hull of a point set with Andrew's monotone chain (or Graham scan) in O(n log n), and using hull properties for extreme-point queries. Recognise it when only the \"outer\" points matter, when maximising a linear function or when lower/upper envelopes of prefix sums appear.","learn":["Monotone chain: sort by (x,y), build lower and upper hulls with a stack popping non-left turns","Decide whether collinear points on edges are kept (<= vs < in the pop condition)","Lower hull of points (i, prefix_i) gives optimal averages/greedy merges (Water Balance pattern)","Transform the problem (e.g. y -> y - x^2) to turn parabolas into lines and use the upper hull","Farthest pair / largest triangle use the hull plus rotating calipers","Point-in-convex-polygon and tangents by binary search on the hull"],"resources":[{"title":"Convex hull problem","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 30.3 (p. 278)","minutes":15},{"title":"Convex Hull","url":"https://usaco.guide/plat/convex-hull","kind":"usaco","where":"USACO Guide Platinum","minutes":40},{"title":"Convex Hull construction","url":"https://cp-algorithms.com/geometry/convex-hull.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"cses-2195","src":"cses","name":"Convex Hull","from":"curated"},{"id":"166B","src":"cf","name":"Polygons","rating":2100,"from":"curated"},{"id":"1299C","src":"cf","name":"Water Balance","rating":2100,"from":"usaco-guide"},{"id":"1142C","src":"cf","name":"U2","rating":2400,"from":"curated"},{"id":"605C","src":"cf","name":"Freelancer's Dreams","rating":2400,"from":"curated"},{"id":"682E","src":"cf","name":"Alyona and Triangles","rating":2600,"from":"curated"}]},{"id":"geo-sweep-line","name":"Sweep line in geometry","tier":2100,"order":12,"prereq":["geo-rectangles","geo-segment-intersection"],"summary":"Process events (segment endpoints, rectangle edges) sorted by x while maintaining an active set ordered by y in a data structure. Recognise it when counting intersections of horizontal/vertical segments, union area/perimeter of rectangles or covered points.","learn":["Events: (x, type, data); choose the tie-break order of start/end events carefully","Horizontal/vertical segment intersections: add/remove horizontals at endpoints, query a Fenwick tree for verticals","Union area of rectangles: segment tree over compressed y storing cover count and covered length","Pieces of a square cut by segments = 1 + segments spanning full side + intersections (Euler formula)","Use coordinate compression and 64-bit counts"],"resources":[{"title":"Sweep line algorithms: intersection points","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 30.1 (p. 276)","minutes":15},{"title":"Sweep Line","url":"https://usaco.guide/plat/sweep-line","kind":"usaco","where":"USACO Guide Platinum","minutes":40},{"title":"Range Queries with Sweep Line","url":"https://usaco.guide/plat/range-sweep","kind":"usaco","where":"USACO Guide Platinum","minutes":30},{"title":"Search for a pair of intersecting segments","url":"https://cp-algorithms.com/geometry/intersecting_segments.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"cses-1740","src":"cses","name":"Intersection Points","from":"usaco-guide"},{"id":"cses-1742","src":"cses","name":"Robot Path","from":"usaco-guide"},{"id":"1194E","src":"cf","name":"Count The Rectangles","rating":2200,"from":"curated"},{"id":"610D","src":"cf","name":"Vika and Segments","rating":2300,"from":"curated"},{"id":"1401E","src":"cf","name":"Divide Square","rating":2400,"from":"curated"},{"id":"1402B","src":"cf","name":"Roads","rating":2900,"from":"usaco-guide"}]},{"id":"geo-closest-pair","name":"Closest pair of points","tier":2100,"order":13,"prereq":["geo-sweep-line","dc-merge-sort-inversions"],"summary":"Find the two closest points in O(n log n) by sweeping with a set ordered by y (CPH) or by divide and conquer on x. Recognise it when minimising a distance-like expression over pairs, sometimes after rewriting it as a point distance (e.g. prefix sums).","learn":["Sweep: keep points with x within d of the current point in a set ordered by y; only O(1) candidates per point","Divide and conquer: split by median x, merge strips sorted by y, check next ~7 points","Rewrite pair expressions like (i-j)^2 + (pre_i - pre_j)^2 as squared distance between (i, pre_i) points","Keep distances squared in long long; randomised grid hashing is an alternative expected O(n) method"],"resources":[{"title":"Closest pair problem","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 30.2 (p. 277)","minutes":15},{"title":"Finding the nearest pair of points","url":"https://cp-algorithms.com/geometry/nearest_points.html","kind":"cpalgo","where":"cp-algorithms","minutes":20},{"title":"Sweep Line (closest pair)","url":"https://usaco.guide/plat/sweep-line","kind":"usaco","where":"USACO Guide Platinum","minutes":40}],"problems":[{"id":"cses-2194","src":"cses","name":"Minimum Euclidean Distance","from":"curated"},{"id":"120J","src":"cf","name":"Minimum Sum","rating":1900,"from":"curated"},{"id":"429D","src":"cf","name":"Tricky Function","rating":2200,"from":"curated"}]},{"id":"geo-advanced","name":"Minkowski sum, half-planes & rotating calipers","tier":2500,"order":14,"prereq":["geo-convex-hull","geo-polar-sort"],"summary":"Advanced convex geometry: Minkowski sum of convex polygons by merging edges in angular order, half-plane intersection with a deque, and rotating calipers for diameters/widths. Rare below 2400 but standard in harder geometry problems.","learn":["Minkowski sum of convex polygons: start at the lowest point of each and merge edge vectors by polar angle; result has <= n+m vertices","Number of distinct edge directions = number of vertices of a Minkowski sum (Geometers Anonymous)","Half-plane intersection: sort by angle, maintain a deque, pop while the last intersection is outside","Rotating calipers: two pointers on the hull for diameter, width, max-area triangle","Point in Minkowski sum = can be represented as a sum of points from each polygon"],"resources":[{"title":"Minkowski sum of convex polygons","url":"https://cp-algorithms.com/geometry/minkowski.html","kind":"cpalgo","where":"cp-algorithms","minutes":20},{"title":"Half-plane intersection","url":"https://cp-algorithms.com/geometry/halfplane-intersection.html","kind":"cpalgo","where":"cp-algorithms","minutes":30},{"title":"Convex Hull (extensions)","url":"https://usaco.guide/plat/convex-hull","kind":"usaco","where":"USACO Guide Platinum","minutes":40}],"problems":[{"id":"1195F","src":"cf","name":"Geometers Anonymous Club","rating":2500,"from":"usaco-guide"},{"id":"87E","src":"cf","name":"Mogohu-Rea Idol","rating":2600,"from":"curated"},{"id":"682E","src":"cf","name":"Alyona and Triangles","rating":2600,"from":"curated"}]}]},{"id":"randomized","name":"Randomized algorithms & hashing tricks","cfTags":["probabilities"],"subtopics":[{"id":"rand-rng-antihash","name":"Good RNG & hashing custom keys","tier":1400,"order":1,"prereq":["@ds-hashmap"],"summary":"Use mt19937 seeded by time instead of rand(), and protect unordered_map / hashing against anti-hash tests with a randomised custom hash (splitmix64). Turn mathematical objects into canonical keys (reduced fractions, transformed values) so they can be counted in a hash map. Matters on Codeforces because open hacking targets predictable hashes.","learn":["mt19937_64 rng(chrono::steady_clock::now().time_since_epoch().count()); uniform_int_distribution for ranges; shuffle(v.begin(), v.end(), rng)","rand() has RAND_MAX 32767 on some judges and is predictable","unordered_map can be blown up to O(n) per operation by crafted tests; use a splitmix64 hash with a random offset, or map","Polynomial hashing: random base, mod 2^61-1 or two moduli to avoid anti-hash tests","Use canonical keys (normalised fractions with sign fixed, prime-signature vectors) when hashing mathematical objects","Algebraic rewriting into a key: (a+b)(a^2+b^2) = k  <=>  a^4 - k*a = b^4 - k*b (mod p) after multiplying by (a-b)"],"resources":[{"title":"Don't use rand(): a guide to random number generators in C++","url":"https://codeforces.com/blog/entry/61587","kind":"cf-blog","where":"Codeforces blog","minutes":15},{"title":"Blowing up unordered_map, and how to stop getting hacked on it","url":"https://codeforces.com/blog/entry/62393","kind":"cf-blog","where":"Codeforces blog","minutes":15},{"title":"Hash Maps","url":"https://usaco.guide/gold/hashmaps","kind":"usaco","where":"USACO Guide Gold","minutes":25},{"title":"String Hashing","url":"https://usaco.guide/gold/hashing","kind":"usaco","where":"USACO Guide Gold","minutes":35}],"problems":[{"id":"988C","src":"cf","name":"Equal Sums","rating":1400,"from":"curated"},{"id":"1133D","src":"cf","name":"Zero Quantity Maximization","rating":1500,"from":"curated"},{"id":"1225D","src":"cf","name":"Power Products","rating":1800,"from":"usaco-guide"},{"id":"1188B","src":"cf","name":"Count Pairs","rating":2300,"from":"curated"}]},{"id":"rand-random-input","name":"Random input, expected behaviour & birthday paradox","tier":1700,"order":2,"prereq":["rand-rng-antihash"],"summary":"Some problems promise random tests or contain a random process; then the answer has a provable typical shape (first 1 bit appears early, few prefix maxima, small depth) or a pigeonhole/birthday argument bounds the brute force. Recognise statements that say \"tests are generated randomly\", or when values are bounded so a collision must appear quickly.","learn":["Random binary string: the first 1 and the first 0 after it appear within O(log n) positions with high probability, so \"try only a few shifts\" is enough","Random permutations: expected number of prefix maxima is O(log n); a random swap changes inversion parity, so parity identifies the number of swaps","Birthday/pigeonhole: if pair sums lie in [1, 2V], among more than 2V pairs two must collide, so brute force over pairs stops after O(V) steps","Randomised algorithms with expected guarantees: random shuffle before incremental algorithms (min enclosing circle), random pivot in quicksort/quickselect","Random binary trees and random walks have O(log n) / O(sqrt n) typical sizes; exploit them only when the statement guarantees randomness","Always analyse failure probability across all tests (union bound) before relying on luck"],"resources":[{"title":"Randomized algorithms (Monte Carlo / Las Vegas)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 24.5 (p. 231)","minutes":15},{"title":"Randomized Algorithms","url":"https://usaco.guide/adv/random","kind":"usaco","where":"USACO Guide Advanced","minutes":30},{"title":"Randomized Algorithms and Online Judges","url":"https://codeforces.com/blog/entry/84215","kind":"cf-blog","where":"Codeforces blog","minutes":15}],"problems":[{"id":"1743D","src":"cf","name":"Problem with Random Tests","rating":1700,"from":"curated"},{"id":"986B","src":"cf","name":"Petr and Permutations","rating":1800,"from":"curated"},{"id":"1500A","src":"cf","name":"Going Home","rating":1800,"from":"curated"},{"id":"1773B","src":"cf","name":"BinCoin","rating":2200,"from":"curated"}]},{"id":"rand-algorithms","name":"Random sampling (frequent elements, Monte Carlo)","tier":2000,"order":3,"prereq":["rand-rng-antihash","@prob-randomized"],"summary":"Monte Carlo sampling: if the answer is determined by an element that occupies at least a 1/k fraction of the data (majority, half of the array, every friend likes the currency), pick random elements and verify each candidate. Recognise \"at least half / more than a third / at least n/2 elements\" conditions where a deterministic solution looks much harder.","learn":["If an element appears in >= 1/k of positions, ~20-30*k random picks find it with failure probability (1-1/k)^tries","Range majority: sample random positions in [l, r] and count occurrences with binary search on per-value position lists","Ghd / gcd of at least half: a random element is in the optimal half with probability 1/2; test all its divisors","Kuroni-style: with cost <= n, at least half of the elements change by <= 1, so try prime factors of a_i - 1, a_i, a_i + 1 for random i","Love-Hate: fix a random person in the answer and run SOS DP over the <= 15 currencies they like","Deterministic alternatives exist (Boyer-Moore voting on a segment tree, persistent tree); choose by implementation time"],"resources":[{"title":"Randomized algorithms","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 24.5 (p. 231)","minutes":15},{"title":"Randomized Algorithms","url":"https://usaco.guide/adv/random","kind":"usaco","where":"USACO Guide Advanced","minutes":30},{"title":"Randomized algorithms lecture, part 1 & 2","url":"https://codeforces.com/blog/entry/71097","kind":"cf-blog","where":"Codeforces blog","minutes":40}],"problems":[{"id":"1514D","src":"cf","name":"Cut and Stick","rating":2000,"from":"curated"},{"id":"2149G","src":"cf","name":"Buratsuta 3","rating":2100,"from":"curated"},{"id":"1523D","src":"cf","name":"Love-Hate","rating":2400,"from":"curated"},{"id":"1305F","src":"cf","name":"Kuroni and the Punishment","rating":2500,"from":"curated"},{"id":"840D","src":"cf","name":"Destiny","rating":2500,"from":"usaco-guide"},{"id":"364D","src":"cf","name":"Ghd","rating":2900,"from":"usaco-guide"}]},{"id":"rand-interactive","name":"Randomization in interactive problems","tier":2100,"order":4,"prereq":["rand-algorithms","@inter-binary-search"],"summary":"Interactive problems with a query limit often need randomness: random probes to estimate an unknown size, random pivots to sort with comparison-like queries, or random choices to defeat an adaptive-looking interactor. Recognise a query budget like 2n, 40n or 60n where the deterministic worst case is too slow but the expected cost fits.","learn":["Sample random positions to land close to the target, then finish with a deterministic walk or binary search","Random pivots (quicksort-style) give expected O(n log n) queries for sorting/reconstruction problems","Random large jumps estimate an unknown cycle length (max seen label), then baby-step giant-step finishes it","If the interactor answers randomly, repeat queries and use the answers that cannot both be wrong","Shrink a candidate region by querying a random point inside it: expected O(log n) rounds","Use a fixed-seed-free RNG (time-seeded mt19937) so hacks cannot target your choices"],"resources":[{"title":"Randomized Algorithms","url":"https://usaco.guide/adv/random","kind":"usaco","where":"USACO Guide Advanced","minutes":30},{"title":"Randomized algorithms lecture, part 1 & 2","url":"https://codeforces.com/blog/entry/71097","kind":"cf-blog","where":"Codeforces blog","minutes":40},{"title":"Randomized algorithms","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 24.5 (p. 231)","minutes":15}],"problems":[{"id":"2074E","src":"cf","name":"Empty Triangle","rating":1600,"from":"curated"},{"id":"1729E","src":"cf","name":"Guess the Cycle Size","rating":1800,"from":"curated"},{"id":"843B","src":"cf","name":"Interactive LowerBound","rating":2000,"from":"curated"},{"id":"1039B","src":"cf","name":"Subway Pursuit","rating":2100,"from":"curated"},{"id":"1114E","src":"cf","name":"Arithmetic Progression","rating":2200,"from":"curated"},{"id":"1918E","src":"cf","name":"ace5 and Task Order","rating":2200,"from":"curated"},{"id":"1840G1","src":"cf","name":"In Search of Truth (Easy Version)","rating":2200,"from":"curated"},{"id":"1061F","src":"cf","name":"Lost Root","rating":2400,"from":"curated"}]}]},{"id":"bitset","name":"Bitset optimisation","cfTags":["bitmasks"],"subtopics":[{"id":"bitset-basics","name":"Bitset optimisation (graphs, matrices, sets)","tier":1900,"order":1,"prereq":[],"summary":"std::bitset packs booleans into 64-bit words so AND/OR/XOR/shift/popcount run n/64 times faster. Recognise it when an O(n^2) or O(n^3) boolean computation is just slightly too slow (n around 1e4-5e4).","learn":["bitset<N> needs a compile-time N; use the maximum constraint","count(), _Find_first(), _Find_next(i) iterate set bits quickly","Common uses: popcount of intersections (common neighbours, counting corner rectangles), reachability in DAGs (reach[v] |= reach[u])","Complexity becomes O(n^2 / w) or O(n^3 / w) with w = 64","Process DAG reachability in reverse topological order; for memory, process vertices in blocks","Precompute per-element bitsets and answer queries with XOR/AND + count","Pattern matching with wildcards/updates: keep one bitset of positions per letter, AND shifted letter bitsets (shift-and); O(n*m/64)","Pairs/triangles: for each point keep a bitset of points farther than d and test pairs with (a & b).any() while scanning edges in decreasing length"],"resources":[{"title":"Bit optimizations","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 10.4 (p. 100)","minutes":15},{"title":"Bitsets","url":"https://usaco.guide/plat/bitsets","kind":"usaco","where":"USACO Guide Platinum","minutes":30},{"title":"Vectorization in C++","url":"https://usaco.guide/adv/vectorization","kind":"usaco","where":"USACO Guide Advanced","minutes":25}],"problems":[{"id":"cses-2136","src":"cses","name":"Hamming Distance","from":"curated"},{"id":"cses-2137","src":"cses","name":"Corner Subgrid Count","from":"curated"},{"id":"cses-2138","src":"cses","name":"Reachable Nodes","from":"usaco-guide"},{"id":"cses-2143","src":"cses","name":"Reachability Queries","from":"curated"},{"id":"33D","src":"cf","name":"Knights","rating":2000,"from":"curated"},{"id":"981E","src":"cf","name":"Addition on Segments","rating":2200,"from":"curated"},{"id":"1194E","src":"cf","name":"Count The Rectangles","rating":2200,"from":"curated"},{"id":"1097F","src":"cf","name":"Alex and a TV Show","rating":2500,"from":"curated"},{"id":"333E","src":"cf","name":"Summer Earnings","rating":2500,"from":"curated"},{"id":"754E","src":"cf","name":"Dasha and cyclic table","rating":2600,"from":"curated"},{"id":"576D","src":"cf","name":"Flights for Regular Customers","rating":2700,"from":"curated"},{"id":"914F","src":"cf","name":"Substrings in a String","rating":3000,"from":"curated"}]}]},{"id":"divide-and-conquer","name":"Divide and conquer","cfTags":["divide and conquer"],"subtopics":[{"id":"dc-recursion","name":"Divide & conquer basics","tier":1200,"order":1,"prereq":[],"summary":"Solve a problem by splitting the input into halves (or around the minimum/maximum), solving recursively and combining. Recognise it when the structure is self-similar (strings of length 2^k, building a tree from a max, splitting a range at its minimum).","learn":["Write solve(l, r) and identify the combine step and the base case","Split at the maximum/minimum to build Cartesian-tree-like recursions","Recursion depth: halving gives O(log n); splitting at extremes can be O(n), consider an explicit stack","Complexity via the master theorem: T(n)=2T(n/2)+O(n) = O(n log n)","Enumerate all reachable values of a split process with recursion + set"],"resources":[{"title":"Sorting theory (merge sort as divide & conquer)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 3.1 (p. 25)","minutes":15},{"title":"Segment Tree, part 1 (recursive range splitting)","url":"https://codeforces.com/edu/course/2/lesson/4","kind":"cf-edu","where":"Codeforces EDU: Segment Tree, part 1","minutes":30}],"problems":[{"id":"1461D","src":"cf","name":"Divide and Summarize","rating":1600,"from":"curated"},{"id":"768B","src":"cf","name":"Code For 1","rating":1600,"from":"curated"},{"id":"559B","src":"cf","name":"Equivalent Strings","rating":1700,"from":"curated"},{"id":"1111C","src":"cf","name":"Creative Snap","rating":1700,"from":"curated"},{"id":"873D","src":"cf","name":"Merge Sort","rating":1800,"from":"curated"},{"id":"448C","src":"cf","name":"Painting Fence","rating":1900,"from":"curated"},{"id":"1696D","src":"cf","name":"Permutation Graph","rating":1900,"from":"curated"},{"id":"1400E","src":"cf","name":"Clear the Multiset","rating":2200,"from":"curated"}]},{"id":"dc-merge-sort-inversions","name":"Merge sort & counting inversions","tier":1500,"order":2,"prereq":["dc-recursion"],"summary":"Count pairs i<j with a_i > a_j (inversions) in O(n log n) during merge sort or with a Fenwick tree; parity of inversions decides reachability by swaps. Recognise it whenever crossing pairs, adjacent swaps or \"number of pairs with prefix condition\" appear.","learn":["During merge, when taking from the right half add the number of remaining left elements","Minimum adjacent swaps to sort = number of inversions","A swap changes the inversion parity; a permutation's parity = (n - cycles) mod 2","Generalise: count pairs (i<j) with pre_j - pre_i < t by merge-sorting prefix sums","Bitwise variants: count inversions per bit level on a trie / recursive split"],"resources":[{"title":"Sorting theory (inversions, merge sort)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 3.1 (p. 25)","minutes":20},{"title":"Introduction to Sorting","url":"https://usaco.guide/bronze/intro-sorting","kind":"usaco","where":"USACO Guide Bronze","minutes":20},{"title":"Segment tree part 1 (inversions problems)","url":"https://codeforces.com/edu/course/2/lesson/4","kind":"cf-edu","where":"Codeforces EDU: Segment Tree, part 1","minutes":60}],"problems":[{"id":"1918B","src":"cf","name":"Minimize Inversions","rating":900,"from":"curated"},{"id":"1760E","src":"cf","name":"Binary Inversions","rating":1100,"from":"curated"},{"id":"1983D","src":"cf","name":"Swap Dilemma","rating":1700,"from":"curated"},{"id":"911D","src":"cf","name":"Inversion Counting","rating":1800,"from":"curated"},{"id":"986B","src":"cf","name":"Petr and Permutations","rating":1800,"from":"curated"},{"id":"540E","src":"cf","name":"Infinite Inversions","rating":2100,"from":"curated"},{"id":"1917D","src":"cf","name":"Yet Another Inversions Problem","rating":2300,"from":"curated"},{"id":"220E","src":"cf","name":"Little Elephant and Inversions","rating":2400,"from":"curated"}]},{"id":"dc-on-array","name":"D&C over the midpoint (static)","tier":2200,"order":3,"prereq":["dc-recursion","@ds-sparse-table"],"summary":"Answer counting questions over all subarrays by recursing on halves and handling subarrays that cross the midpoint in O(len), or answer offline range queries by splitting at the midpoint (divide-and-conquer static range queries). Recognise it when a property of subarrays is easy to evaluate for those containing a fixed position.","learn":["Count crossing subarrays: precompute suffix info of the left half and prefix info of the right half, combine with two pointers or maps","Static range queries: queries crossing mid are answered with precomputed left/right aggregates; others recurse","Split at the maximum and iterate over the smaller side gives O(n log n) (small-to-large)","Total complexity O(n log n) or O(n log^2 n)","Closest pair is a classic instance"],"resources":[{"title":"Divide & Conquer - SRQ","url":"https://usaco.guide/plat/DC-SRQ","kind":"usaco","where":"USACO Guide Platinum","minutes":30},{"title":"Closest pair problem (D&C alternative)","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 30.2 (p. 277)","minutes":10}],"problems":[{"id":"cses-1647","src":"cses","name":"Static Range Minimum Queries","from":"usaco-guide"},{"id":"1691D","src":"cf","name":"Max GEQ Sum","rating":1800,"from":"curated"},{"id":"1156E","src":"cf","name":"Special Segments of Permutation","rating":2200,"from":"curated"},{"id":"1793F","src":"cf","name":"Rebrending","rating":2600,"from":"curated"},{"id":"1730E","src":"cf","name":"Maximums and Minimums","rating":2700,"from":"curated"},{"id":"549F","src":"cf","name":"Yura and Developers","rating":2800,"from":"curated"}]},{"id":"dc-cdq","name":"CDQ divide & conquer (offline)","tier":2400,"order":4,"prereq":["dc-merge-sort-inversions","@ds-fenwick"],"summary":"CDQ divide and conquer solves offline problems where each update affects later queries (3D partial order, dynamic 2D counting) by recursing on time and letting the left half's updates answer the right half's queries with a sweep + Fenwick tree. Recognise it when a 2D data structure seems necessary but everything is offline.","learn":["Sort by first key, recurse on halves, then contribute left-half updates to right-half queries sorted by the second key with a BIT on the third","Complexity O(n log^2 n) with small memory compared to 2D structures","Works for dynamic point-add / rectangle-query by treating time as a dimension","Clear BIT changes by undoing exactly the updates you did","Alternatives: offline 2D BIT, BIT of sorted vectors, wavelet trees"],"resources":[{"title":"CDQ Divide and Conquer","url":"https://robert1003.github.io/2020/01/31/cdq-divide-and-conquer.html","kind":"other","where":"Article linked from USACO Guide Platinum 2D Range Queries","minutes":30},{"title":"2D Range Queries","url":"https://usaco.guide/plat/2DRQ","kind":"usaco","where":"USACO Guide Platinum","minutes":40}],"problems":[{"id":"cses-1739","src":"cses","name":"Forest Queries II","from":"usaco-guide"},{"id":"641E","src":"cf","name":"Little Artem and Time Machine","rating":2000,"from":"curated"},{"id":"762E","src":"cf","name":"Radio stations","rating":2200,"from":"curated"},{"id":"1045G","src":"cf","name":"AI robots","rating":2200,"from":"curated"},{"id":"1093E","src":"cf","name":"Intersection of Permutations","rating":2400,"from":"curated"},{"id":"848C","src":"cf","name":"Goodbye Souvenir","rating":2600,"from":"curated"}]}]},{"id":"expression-parsing","name":"Expression parsing","cfTags":["expression parsing"],"subtopics":[{"id":"parse-brackets","name":"Stack parsing of nested structures","tier":1400,"order":1,"prereq":["@str-brackets"],"summary":"Check and repair bracket sequences, match nested structures and simulate nesting with a stack (loops, comments, try/catch blocks). Recognise it from nested input formats or anything with opening/closing tokens.","learn":["Balance counter: never negative and ends at 0 for a regular sequence","Stack of positions gives the matching bracket of each closer and the longest regular substring","Multiple bracket types: push the opener, check the type on close","Greedy fixes: count moves/replacements from the minimum prefix balance","Nested multiplications/loops: keep a stack of multipliers and cap values to avoid overflow"],"resources":[{"title":"Stacks","url":"https://usaco.guide/gold/stacks","kind":"usaco","where":"USACO Guide Gold","minutes":25},{"title":"Balanced bracket sequences","url":"https://cp-algorithms.com/combinatorics/bracket_sequences.html","kind":"cpalgo","where":"cp-algorithms","minutes":20}],"problems":[{"id":"1175B","src":"cf","name":"Catch Overflow!","rating":1600,"from":"curated"},{"id":"223A","src":"cf","name":"Bracket Sequence","rating":1700,"from":"curated"},{"id":"1153C","src":"cf","name":"Serval and Parenthesis Sequence","rating":1700,"from":"curated"},{"id":"747E","src":"cf","name":"Comments","rating":1700,"from":"curated"},{"id":"195C","src":"cf","name":"Try and Catch","rating":1800,"from":"curated"}]},{"id":"parse-expressions","name":"Expression parsing & evaluation","tier":1800,"order":2,"prereq":["parse-brackets"],"summary":"Evaluate or transform arithmetic/logical expressions with operator precedence using recursive descent or the shunting-yard (two stacks) algorithm, and build expression trees. Recognise it in problems that give formulas, macro definitions or \"insert brackets/operators\" tasks.","learn":["Recursive descent: expr -> term {(+|-) term}, term -> factor {(*|/) factor}, factor -> number | (expr)","Shunting-yard: operator stack + value stack, pop while top has higher/equal precedence (left-assoc)","Unary minus and right-associative operators need special handling","Build an expression tree to evaluate many assignments or run DP over it","Try all bracket placements only where they matter (around + segments between *)","Parse tokens first (numbers, identifiers, operators) to keep the grammar code simple"],"resources":[{"title":"Expression parsing","url":"https://cp-algorithms.com/string/expression_parsing.html","kind":"cpalgo","where":"cp-algorithms","minutes":25}],"problems":[{"id":"778B","src":"cf","name":"Bitwise Formula","rating":1800,"from":"curated"},{"id":"2052E","src":"cf","name":"Expression Correction","rating":1900,"from":"curated"},{"id":"39A","src":"cf","name":"C*++ Calculations","rating":2000,"from":"curated"},{"id":"552E","src":"cf","name":"Vanya and Brackets","rating":2100,"from":"curated"},{"id":"7E","src":"cf","name":"Defining Macros","rating":2600,"from":"curated"},{"id":"217C","src":"cf","name":"Formurosa","rating":2600,"from":"curated"},{"id":"115D","src":"cf","name":"Unambiguous Arithmetic Expression","rating":2600,"from":"curated"}]}]},{"id":"sqrt-heuristics","name":"Square-root heuristics","cfTags":["brute force","data structures"],"subtopics":[{"id":"sqrt-heuristics","name":"Advanced sqrt heuristics (rebuild, heavy sets, distinct sizes)","tier":2200,"order":1,"prereq":["@ds-sqrt-decomposition"],"summary":"Beyond plain block decomposition: rebuild a static structure every sqrt(q) updates and handle the buffer by brute force, split sets/vertices into heavy (size > sqrt) and light, and use that a total size n gives only O(sqrt n) distinct sizes. Recognise it when two naive approaches are fast in opposite regimes.","learn":["Rebuild every B updates (e.g. multi-source BFS) and answer queries with static data + O(B) buffered updates","Heavy/light sets: at most n/B heavy sets; heavy-heavy and heavy-light pairs are checked differently","Sum of sizes n => at most O(sqrt n) distinct sizes: group equal sizes (binary splitting) for knapsack","Block jump pointers: store where you exit a block and how many steps it takes","Balance B = sqrt(n * cost_a / cost_b); try a few values when constant factors are large","Value thresholds: small values/ratios are enumerated directly, large ones force few candidates (e.g. geometric triples a, ab, ab^2 with b > cube root)"],"resources":[{"title":"Combining algorithms","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 27.1 (p. 252)","minutes":15},{"title":"Integer partitions","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 27.2 (p. 254)","minutes":10},{"title":"Square Root Decomposition","url":"https://usaco.guide/plat/sqrt","kind":"usaco","where":"USACO Guide Platinum","minutes":40},{"title":"Applications of Square Root Decomposition","url":"https://codeforces.com/blog/entry/83248","kind":"cf-blog","where":"Codeforces blog","minutes":30},{"title":"SQRT decomposition for beginners","url":"https://codeforces.com/blog/entry/54133","kind":"cf-blog","where":"Codeforces blog","minutes":20}],"problems":[{"id":"1822G2","src":"cf","name":"Magic Triples (Hard Version)","rating":2200,"from":"curated"},{"id":"1468M","src":"cf","name":"Similar Sets","rating":2300,"from":"curated"},{"id":"342E","src":"cf","name":"Xenia and Tree","rating":2400,"from":"usaco-guide"},{"id":"1619H","src":"cf","name":"Permutation and Queries","rating":2400,"from":"curated"},{"id":"95E","src":"cf","name":"Lucky Country","rating":2500,"from":"curated"},{"id":"455D","src":"cf","name":"Serega and Fun","rating":2700,"from":"curated"}]}]},{"id":"simulation","name":"Simulation & schedules","cfTags":["schedules","implementation"],"subtopics":[{"id":"sim-timeline","name":"Timeline simulation & schedules","tier":1300,"order":1,"prereq":["@impl-simulation","@sort-compress-events"],"summary":"Simulate processes that evolve over time - queues, servers, machines, traffic lights, robots following programs - by jumping from event to event instead of tick by tick, or by finding the period of the process. Recognise it from statements describing who does what at which moment.","learn":["Represent the state at event times only; jump time forward to the next event (next arrival, next finish)","Use a queue for FIFO waiting lines and a priority_queue / set of (finish time, id) for servers","If the state space is small, the process is eventually periodic: detect the repeat and skip k mod period steps","Cyclic schedules (lights, repeated programs): work modulo the cycle length and double the string to handle wrap-around","Binary search on the finishing time when tasks can be redistributed (schedule feasibility check)","Be careful with ties: same-time events must follow the statement order","x -> f(x) mod m processes: find the first hit time t0 and the cycle length c (at most m steps each), then solve t0 + k*c for both processes"],"resources":[{"title":"Simulation","url":"https://usaco.guide/bronze/simulation","kind":"usaco","where":"USACO Guide Bronze","minutes":25},{"title":"Scheduling","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 6.2 (p. 58)","minutes":10},{"title":"Sweep Line (event processing)","url":"https://usaco.guide/plat/sweep-line","kind":"usaco","where":"USACO Guide Platinum","minutes":40}],"problems":[{"id":"1607B","src":"cf","name":"Odd Grasshopper","rating":900,"from":"curated"},{"id":"1059A","src":"cf","name":"Cashier","rating":1000,"from":"curated"},{"id":"1744C","src":"cf","name":"Traffic Light","rating":1000,"from":"curated"},{"id":"2070B","src":"cf","name":"Robot Program","rating":1100,"from":"curated"},{"id":"920B","src":"cf","name":"Tea Queue","rating":1200,"from":"curated"},{"id":"1941D","src":"cf","name":"Rudolf and the Ball Game","rating":1200,"from":"curated"},{"id":"747C","src":"cf","name":"Servers","rating":1300,"from":"curated"},{"id":"982B","src":"cf","name":"Bus of Characters","rating":1300,"from":"curated"},{"id":"1701C","src":"cf","name":"Schedule Management","rating":1400,"from":"curated"},{"id":"1840E","src":"cf","name":"Character Blocking","rating":1600,"from":"curated"},{"id":"547A","src":"cf","name":"Mike and Frog","rating":2200,"from":"curated"}]}]},{"id":"practice-skills","name":"Practice skills (non-graded)","graded":false,"cfTags":["*special"],"subtopics":[{"id":"skill-reading","name":"Reading problems & constraints","tier":800,"order":1,"prereq":["@impl-complexity"],"summary":"Read the whole statement, the constraints and the samples before coding; derive the target complexity from n. Most early wrong answers come from misreading.","learn":["n <= 1e5..2e5: O(n log n); n <= 5000: O(n^2); n <= 20: O(2^n * n); n <= 1e18: O(log n) or formula","Re-read the output format and edge cases (n = 1, all equal, negative values)","Work through the samples by hand and invent a small extra test","Check the sum-of-n guarantee over test cases"],"resources":[{"title":"Estimating efficiency","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 2.3 (p. 21)","minutes":10},{"title":"Expected Knowledge","url":"https://usaco.guide/general/expected-knowledge","kind":"usaco","where":"USACO Guide General","minutes":10}],"problems":[{"id":"546A","src":"cf","name":"Soldier and Bananas","rating":800,"from":"usaco-guide"}]},{"id":"skill-debugging","name":"Debugging techniques","tier":1000,"order":2,"prereq":["skill-reading"],"summary":"A systematic checklist for wrong answers and runtime errors: overflow, uninitialised data, off-by-one, resetting between test cases, and compiler flags/sanitisers.","learn":["Compile with -Wall -Wextra -fsanitize=address,undefined -D_GLIBCXX_DEBUG while testing","Check overflow (int vs long long), array bounds, multitest resets","Print intermediate values with a debug macro that is disabled on submit","Re-derive the algorithm on the failing small case by hand"],"resources":[{"title":"How to Debug","url":"https://usaco.guide/general/debugging-checklist","kind":"usaco","where":"USACO Guide General","minutes":15},{"title":"Debugging C++","url":"https://usaco.guide/general/debugging-cpp","kind":"usaco","where":"USACO Guide General","minutes":25}],"problems":[]},{"id":"skill-stress-testing","name":"Stress testing","tier":1300,"order":3,"prereq":["skill-debugging"],"summary":"Write a brute-force solution and a random test generator, then compare outputs in a loop to find a small failing test. The fastest way out of \"WA on test 2\" when you cannot see the bug.","learn":["Generator with a seed argument and small parameters (n <= 6) so counterexamples are readable","Brute force that is obviously correct (try all subsets/permutations)","Script: loop { gen > in; sol < in > a; brute < in > b; diff a b || break }","Also stress for time limits with maximum-size tests"],"resources":[{"title":"Basic Debugging (stress testing)","url":"https://usaco.guide/general/basic-debugging","kind":"usaco","where":"USACO Guide General","minutes":25}],"problems":[]},{"id":"skill-contest-strategy","name":"Contest strategy & time management","tier":1200,"order":4,"prereq":["skill-reading"],"summary":"How to allocate time in a 2-hour Codeforces round: read the next problem when stuck, check standings, avoid penalty from careless submissions, and upsolve afterwards.","learn":["Solve in order but read one problem ahead; switch if stuck for ~20-30 minutes","Test on samples and an edge case before submitting: each WA costs penalty","Look at the standings to see which problems are being solved","Upsolve 1-2 problems above your level after every contest and read the editorial"],"resources":[{"title":"Contest Strategy","url":"https://usaco.guide/general/contest-strategy","kind":"usaco","where":"USACO Guide General","minutes":15},{"title":"How to Practice","url":"https://usaco.guide/general/practicing","kind":"usaco","where":"USACO Guide General","minutes":20},{"title":"Contests and resources","url":"https://cses.fi/book/book.pdf","kind":"cph","where":"CPH ch. 1.6 (p. 15)","minutes":5}],"problems":[]}]}]}]
